/** @internal */
export const DEVICE_MANAGEMENT_SVC = 'DeviceManagementService';

/**
 * @eventProperty
 */
export enum DeviceManagementEvents {

    /**
     * @eventProperty
     * This RB event is send when the application cannot access the audio/video devices. The user should check the app / browser configuration and access to OS devices
     */
    ON_AUDIO_VIDEO_DEVICE_ACCESS_ERROR = "rainbowonaudiovideodeviceaccesserror",

    /**
     * @eventProperty
     * This RB event is send when the application detects any kind of change in the devices list (audio input / output or video input devices)
     * **Event Data**
     * - **kind**: The kind of the device (audioinput, audiooutput or videoinput)
     * - **action**: Could be added (new device is added) / removed (device is removed) / updated (the id of the device has updated)
     */
     ON_AUDIO_VIDEO_DEVICE_LIST_UPDATE = "rainbowonaudiovideodevicelistupdate",

    /**
     * @eventProperty
     * This RB event is send when a new device is selected to be used
     * **Event Data**
     * - **kind**: The kind of the device (audioinput, audiooutput or videoinput)
     * - **plugIn**: True if the new device is selected after a plug-in
     * - **plugOut**: True if the new device is selected after a plug-out of the current device used
     */
    ON_NEW_AUDIO_VIDEO_DEVICE_SELECTED = "rainbowonnewaudiovideodeviceselected",

    /**
     * @eventProperty
     * This RB event is send when a new secondary device is selected to be used; This is used only for incoming calls / IMs that could be played
     * also on the secondary device, if it's activated in the settings
     */
    ON_NEW_SECONDARY_OUTPUT_DEVICE_SELECTED = "rainbowonnewsecondaryoutputdeviceselected"
}

export interface DeviceManagementService {

    /**
     * Return all available cameras
     */
    getAllCameras(): MediaDeviceInfo[];

    /**
     * Return all available microphones
     */
    getAllMicrophones(): MediaDeviceInfo[];

    /**
     * Return all available speakers
     */
    getAllSpeakers(): MediaDeviceInfo[];

    /**
     * Return the current selected microphone (that's used in all VoIP calls)
     */
    getCurrentMicrophone(): MediaDeviceInfo;

    /**
     * Return the current selected speaker (that's used in all VoIP calls)
     */
    getCurrentSpeaker(): MediaDeviceInfo | null;

    /**
     * Return the current selected camera (that's used in all VoIP calls)
     */
    getCurrentCamera(): MediaDeviceInfo;

    /**
     * This API can be used to modify the current camera. This will result in sending
     * an update event of type ON_NEW_AUDIO_VIDEO_DEVICE_SELECTED
     * @param camera - The new device to be used; Should be of type videoinput
     */
    setCurrentCamera(camera: MediaDeviceInfo): void;

    /**
     * This API can be used to modify the current speaker. This will result in sending
     * an update event of type DeviceManagementEvents.ON_NEW_AUDIO_VIDEO_DEVICE_SELECTED
     * @param speaker - The new device to be used; Should be of type audiooutput
     */
    setCurrentSpeaker(speaker: MediaDeviceInfo): void;

    /**
     * This API can be used to modify the current microphone. This will result in sending
     * an update event of type ON_NEW_AUDIO_VIDEO_DEVICE_SELECTED
     * @param microphone - The new device to be used; Should be of type audioinput
     */
    setCurrentMicrophone(microphone: MediaDeviceInfo): void;

    /**
     * Set the output speaker of the audio element with the given speaker.
     * This method is useful if you're developing an audio application and want to configure
     * the speaker to be used by an audio tag in the same way as Rainbow's audio tags.
     * @param element - The Audio element to whom we want to change the output ID
     * @param speaker - The speaker to be used
     */
    setSpeakerForAudioElement(element: HTMLAudioElement, speaker: MediaDeviceInfo): Promise<void>

    /**
     * Subscribe to updates on the deviceManagement service (all events are of RBEvent type);
     * @param handler - The call-back function that will be subscribed to the RxJS subject
     * @param filterEvent - a list of event names that the user wants to receive when subscribing (used a filter)
     */
    subscribe(handler: (event: RBEvent<DeviceManagementEvents>) => any, eventNames?: DeviceManagementEvents | DeviceManagementEvents[]): Subscription;
}

