    private constructor() { super(); }

    public async start() {
        if (this.started) { return; }
        if (!config.sdk) this.checkDeviceList();

        this.xmppConnectionSubscription = this.xmppService.subscribeToConnectionEvents((event: RBEvent) => {
            try {
                if (event.name === 'ON_XMPP_CONNECTED' && event.data.reason === 'RECONNECTION') {
                    this.logger.info("[DeviceManagementService] XMPP Connection state event : RECONNECTION");
                    this.setGlobalTagSinkId(true);
                }
            }
            catch { }
        });

        if (!config.sdk) this.started = true;
    }

    public async stop() {
        if (this.deviceWatcher) this.deviceWatcher = null;
        if (this.xmppConnectionSubscription) { this.xmppConnectionSubscription.unsubscribe(); this.xmppConnectionSubscription = null; }
        if (navigator.mediaDevices?.ondevicechange) navigator.mediaDevices.ondevicechange = null;
        this.started = false;
    }

    /**
    * Subscribe to updates on the deviceManagement service (all events are of RBEvent type);
    * @param handler - The call-back function that will be subscribed to the RxJS subject
    * @param filterEvent - a list of event names that the user wants to receive when subscribing (used a filter)
    */
    public subscribe(handler: (event: RBEvent<DeviceManagementEvents>) => any, eventNames?: DeviceManagementEvents | DeviceManagementEvents[]): Subscription {
        const observable = eventNames ? this.rxSubject.pipe(filter((event: RBEvent<DeviceManagementEvents>) => {
            if (eventNames instanceof Array) return eventNames.indexOf(event.name) !== -1;
            return event.name === eventNames;
        })) : this.rxSubject;
        return observable.subscribe((event: RBEvent<DeviceManagementEvents>) => { try { handler(event); } catch { } });
    }

    private sendEvent(name: DeviceManagementEvents, data: any = null) {
        this.rxSubject.next(RBEvent.create(name, data));
    }

