    private devicesToIgnore = ["display", "screen", "amd ", "monitor", "écran", "lenovo usb audio", "(hdmi)", " dac(", "PHL 2"];
    private inputDevicesToAcceptEvenWhenNotDefault = ["plantronics", "jabra", "konftel", "sennheiser"];

    private arrayContains(array: any[], textSearched: string) {
        return (array.some(function(element) {
            return (textSearched.indexOf(element) > -1);
        }));
    }

    //example of Hash label : "Speakers (Jabra Speak 710) (0b0e:2475)"
    private getHashFromLabel(label: string): string {
        const first = label.lastIndexOf("(");
        const last = label.lastIndexOf(")");
        let result = "";
        if (first && last) {
            result = label.substring(first + 1, last);
            //check if HASH is correct
            if (result.indexOf(":") === -1) {
                result = "";
            }
        }

        return result;
    }

    private compareHashInLabel(labelA: string, labelB: string): boolean {
        const hashA = this.getHashFromLabel(labelA);
        const hashB = this.getHashFromLabel(labelB);

        return (hashA && hashB && hashA === hashB);
    }

    /**
     * Set the output sinkID of the audio element with the output device given
     * @param element - The Audio element to whom we want to change the output ID
     * @param outputDevice - The output device to be used
     */
    public async setSpeakerForAudioElement(element: HTMLAudioElement, outputDevice: MediaDeviceInfo) {
        if (!element) {
            throw new Error("[DeviceManagementService] setSpeakerForAudioElement -- no HTML Audio Element received !");
        }

        if (!element['setSinkId']) {
            //system does not support setSinkId, ignore and do not add logs here
            return;
        }

        if (!outputDevice) {
            this.logger.debug(`[DeviceManagementService] setSpeakerForAudioElement -- no output device or setSinkId does not exist !`);
            return;
        }

        if (element['sinkId'] === outputDevice.deviceId) {
            return;
        }

        try {
            this.logger.debug(`[DeviceManagementService] -- setSpeakerForAudioElement to new device -- ${outputDevice.deviceId}`);

            await element['setSinkId'](outputDevice.deviceId);

            if (element.load) {
                element.load();
            }
        }
        catch (error) {
            this.logger.error(`[DeviceManagementService] -- setSpeakerForAudioElement error -- ${error}`);
            return;
        }
    }

