    private startDeviceWatcher(): void {
        if (navigator?.mediaDevices && !navigator.mediaDevices.ondevicechange) {
            navigator.mediaDevices.ondevicechange = event => {
                this.logger.info("[DeviceManagementService] ondevicechange detected " + JSON.stringify(event));
                if (!this.deviceWatcher) {
                    this.deviceWatcher = setTimeout(() => {
                        this.checkDeviceList();
                        this.deviceWatcher = null;
                    }, 500);
                }
            };
        }
    }

    public async checkDeviceList(): Promise<void> {
        let tempStream = null;
        if (window.adapter && window.adapter.browserDetails.browser === "firefox") {
            //when we're on Firefox, the labels are not shown automatically, so we need to have an active stream
            //to be able to get the labels
            if (this.getUserMediaForVideoDone || this.getUserMediaForAudioDone) {
                //if we've already done the initial get user media, each time there's device update, we need to have active media stream;
                //in case of error, do nothing, but continue (as perhaps the audio stream is already taken by the application)
                try {
                    tempStream = await navigator.mediaDevices.getUserMedia({ audio: true, video: false });
                }
                catch {
                    //do nothing, but continue
                }
            }
        }
        this.logger.info("[DeviceManagementService] checkDeviceList");
        const devices: MediaDeviceInfo[] = await navigator.mediaDevices.enumerateDevices();
        this.logger.info("[DeviceManagementService] devices brut list " + JSON.stringify(devices));
        const tempAudioInputDevices: MediaDeviceInfo[] = [];
        const tempAudioOutputDevices: MediaDeviceInfo[] = [];
        const tempVideoInputDevices: MediaDeviceInfo[] = [];

        devices.forEach((device: MediaDeviceInfo) => {
            //check whether we need to get the user media or not
            // Note: For security reasons, the label field is always blank unless an active media stream exists
            // or the user has granted persistent permission for media device access.
            // The set of device labels could otherwise be used as
            // part of a fingerprinting mechanism to identify a user.
            if (device.deviceId && device.label) {
                if (device.kind === "audioinput" || device.kind === "audiooutput") { this.getUserMediaForAudioDone = true; }
                if (device.kind === "videoinput") { this.getUserMediaForVideoDone = true; }
            }

            if (device.kind === "audioinput") { tempAudioInputDevices.push(device); }
            if (device.kind === "audiooutput") { tempAudioOutputDevices.push(device); }
            if (device.kind === "videoinput") { tempVideoInputDevices.push(device); }
        });

        if (!this.getUserMediaForAudioDone && !this.getUserMediaForVideoDone && tempAudioInputDevices.length && tempVideoInputDevices.length) {
            //get user media is not done at all (start-up), so ask for all information
            this.testGetUserMedia(tempAudioInputDevices, tempVideoInputDevices);
            return;
        }

        if (!this.getUserMediaForAudioDone && tempAudioInputDevices.length) {
            //get user media and stop here, as we need to get the information for the input / output devices
            this.testGetUserMedia(tempAudioInputDevices, []);
            return;
        }

        if (!this.getUserMediaForVideoDone && tempVideoInputDevices.length) {
            //get user media and stop here, as we need to get the information for the video input devices
            this.testGetUserMedia([], tempVideoInputDevices);
            return;
        }

        this.manualAleDeviceSelection = this.settingsService.getBooleanSetting("manualAleDeviceSelection");

        //start watching device update, as we've given update on the devices
        this.startDeviceWatcher();

        //check for any changes on the audio input devices
        this.updateCurrentAudioInputDevices(tempAudioInputDevices);
        this.updateCurrentAudioOutputDevices(tempAudioOutputDevices);
        this.updateCurrentVideoInputDevices(tempVideoInputDevices);

        if (tempStream) {
            this.webrtcConfigAndUtils.disableMediaStream(tempStream);
        }
    }

