    /**
     *  Get a list of directory entries data (API request to {@link https://api.openrainbow.org/directory/#api-directory-GetDirectoryList Rainbow Company Directory portal - directory - Get a list of directory entries data})
     * @public
     * @description
     *      Get a list of contacts from company's directory
     * @param string - companyId Allows to filter the list of directory entries on the companyIds provided in this option
     * @param page - Allow to specify the page number to retrieve
     * @param pageSize - Allow to specify the number of phone book entries to retrieve
     * @param searchPattern - Allows to filter the list of directory entries by the words provided in this option
     * @param searchBy - Allows to filter the list of directory entries on the number provided in this option.
     * @param format - Allows to retrieve more or less entry details in response. Possible values are:
     *      - small: id, firstName, lastName
     *      - medium: id, companyId, firstName, lastName, workPhoneNumbers
     *      - full: all fields.
     * @returns {Promise<{ contacts: DirectoryContact[]; limit: number; offset: number; total: number }>} object contaning result of search
     * @memberof CompanyDirectoryService
     */
    public async getDirectoryContacts(companyId: string, page?: number, pageSize: number = 1000, searchPattern?: string, searchBy?: 'phoneNumbers' | 'tags' | 'name', format: string = 'full'): Promise<{ contacts: DirectoryContact[]; limit: number; offset: number; total: number }> {
        try {

            // Prepare request url
            const portalURL = config.restServerUrl + "/api/rainbow/directory/v1.0/";
            let url: string = `${portalURL}entries?view=company&type=all&format=${format}&companyId=${companyId}&limit=${pageSize}`;
            if (page) { url += "&offset=" + (pageSize * (page - 1)); }

            if (searchPattern) {
                switch (searchBy) {
                    case "phoneNumbers":
                    case "tags":
                        url += "&" + searchBy + "=" + encodeURIComponent(searchPattern);
                        break;
                    case "name":
                    default:
                        url += "&name=" + encodeURIComponent(searchPattern);
                        break;
                }
            }


            const headers = this.authService.getRequestHeader();
            const response: Response = await fetch(url, { method: 'GET', headers });
            if (!response.ok) { throw (response); }
            const responseData: any = (await response.json());
            this.logger.info("[CompanyDirectoryService] getDirectoryContacts success (found " + responseData.total + " contact(s))");
            const contactsData = responseData.data;
            const contacts: DirectoryContact[] = [];

            contactsData.forEach((contactData) => {
                const contact = DirectoryContact.createFromData(contactData);
                contacts.push(contact);
            });

            return { contacts: contacts, limit: responseData.limit, offset: responseData.offset, total: responseData.total };

        } catch (error) {
            const errorInfo = await this.errorHelperService.getErrorInfo(error, 'getDirectoryContacts');
            this.logger.error(`[CompanyDirectoryService] ${errorInfo.message}`);
            throw errorInfo.error;
        }
    }

    /**
     * This API allows administrators to create an entry in the directory of a company they administrate. (API request to {@link https://api.openrainbow.org/directory/#api-directory-PostDirectory Rainbow Company Directory portal - directory - Create a directory entry})
     * @public
     * @description
     *      Creates a company directory contact
     * @param {DirectoryContact} entry a {@link DirectoryContact} object to create on server
     * @returns {Promise<DirectoryContact>} The created company directory contact
     * @memberof CompanyDirectoryService
     * @fires CompanyDirectoryEvent#ADMIN_DIRECTORY_CHANGE
     */
    public async createDirectoryContact(entry: DirectoryContact): Promise<DirectoryContact> {
        try {
            if (!entry.companyId) {
                throw (new Error("Missing mandatory parameter 'companyId"));
            }
            const portalURL = config.restServerUrl + "/api/rainbow/directory/v1.0/";

            const url: string = `${portalURL}entries`;
            const headers = this.authService.getPostHeader();
            const response: Response = await fetch(url, { method: 'POST', headers, body: JSON.stringify(entry) });
            if (!response.ok) { throw (response); }
            const responseData: any = (await response.json());
            const contact = DirectoryContact.createFromData(responseData.data);
            this.logger.info("[CompanyDirectoryService] createDirectoryContact success");

            this.eventService.publish(CompanyDirectoryEvent.ADMIN_DIRECTORY_CHANGE, contact);

            return contact;
        } catch (error) {
            const errorInfo = await this.errorHelperService.getErrorInfo(error, 'createDirectoryContact');
            this.logger.error(`[CompanyDirectoryService] ${errorInfo.message}`);
            throw errorInfo.error;
        }
    }

