/**
 * @module RainbowSDK
 */
import './strophejs';
import adapter from "webrtc-adapter";
import { SDKPlugin } from './plugins/plugin';
import { AuthService } from './services/core/auth.service';
import { XmppService } from './services/core/xmpp.service';
import { MainService } from './services/core/main.service';
import { EventService } from './services/core/event.service';
import { SettingsService } from './services/core/settings.service';
import { ContactService } from './services/core/contact.service';
import { ConnectionService, ConnectionServiceRB } from './services/core/connection.service';
import { LogLevelEnum, LoggerService } from './services/core/logger.service';
import { PresenceHelperService } from './services/core/presenceHelper.service';
import jquery from 'jquery';
import { UserNetworkService } from './services/core/userNetwork.service';
import { BUBBLE_CONFERENCE_SVC, BubbleConferenceService, ConversationService, DirectorySearchService } from './services';
import { DirectorySearchServiceRB } from './services/core/directorySearch.service';
import { ConnectedUser } from './models';
import { UtilitiesService } from './services/utilities/utilities.service';
import { BubbleService } from './services/bubbles';
import { BUBBLE_SVC } from './services/bubbles/bubble.service';
import { ConversationServiceRB } from 'rainbow-sdk/services/conversation/conversation.service';
import { WEBINAR_SVC, WebinarService } from './services/webinars/webinars.service';
import { CALL_SVC, CallService } from './services/call/call.service';
import { FAVORITES_SVC, FavoritesService } from './services/favorites/favorites.service';
import { CALL_LOG_SVC, CallLogService } from './services/callLog/callLog.service';
import { DATA_CHANNEL_SVC, DataChannelService } from './services/dataChannel';
import { DEVICE_MANAGEMENT_SVC, DeviceManagementService } from './services/deviceManagement/deviceManagement.service';
import { TELEPHONYCONFIG_SVC, TelephonyConfigService } from './services/telephonyConfig';
import { SDKAdminService, SDK_ADMIN_SVC } from './services/admin';
import { BUBBLE_TAG_SVC, BubbleTagService } from './services/bubbles/bubbleTag.service';
import { UserService, UserServiceRB } from './services/users/user.service';
import { DOCUMENTS_SVC, DocumentsService } from './services/documents/documents.service';

export interface RainbowSDKAppConfig {
    /** Rainbow backend server url */
    server?: string

    /** Rainbow application identifier */
    applicationId?: string

    /** Rainbow application secretKey */
    secretKey?: string
}

export interface RainbowSDKConfig {

    /** Application configuration */
    appConfig?: RainbowSDKAppConfig;

    /** List of plugins to use in the application */
    plugins?: SDKPlugin[];

    /** When set to true, the sdk will try to connect with localStorage token information */
    autoLogin?: boolean;

    /** Specify the SDK internal log level */
    logLevel?: LogLevelEnum;

    /** When set to true, sone additional CONNECTING events will be emitted to manage a connection progress bar */
    progressEvents?: boolean;

    /** @internal */
    devMode?: boolean;
}

/**
 * This class is the **Web Rainbow SDK** main entry point
 * It offers :
 * + Lifecycle methods (create, start and stop methods)
 * + A get method to fetch plugin services
 * + Direct accesses to "core" plugins
 */
export class RainbowSDK {

    /**
     * Direct access to core ConnectedUser
     * @returns the ConnectedUser instance
     */
    public get connectedUser(): ConnectedUser | undefined { return this._contactService.userContact; }

    /**
     * Direct access to core ConnectionService
     * @returns the ConnectionService singleton instance
     */
    public get connectionService(): ConnectionService { return this._connectionService; }

    /**
      * Direct access to core ConversationService
      * @returns the ConversationService singleton instance if available
      */
    public get conversationService(): ConversationService { return this._conversationService; }

    /**
     * Direct access to core UserService
     * @returns the UserService singleton instance
     */
    public get userService(): UserService { return this._userService; }

    /**
     * Direct access to core UtilitiesService
     * @returns the UtilitiesService singleton instance
     */
    public get utils(): UtilitiesService { return this._utilitiesService; }

    /**
     * Direct access to core UserNetworkService
     * @returns the UserNetworkService singleton instance
     */
    public get userNetwork(): UserNetworkService { return ContactService.getInstance().userNetwork; }

    /**
     * Direct access to BubbleService
     * @returns the BubbleService singleton instance if available
     */
    public get bubbleService(): BubbleService | undefined { return this.get<BubbleService>(BUBBLE_SVC); }

    /**
     * Direct access to BubbleTagService
     * @returns the BubbleService singleton instance if available
     */
    public get BubbleTagService(): BubbleTagService | undefined { return this.get<BubbleTagService>(BUBBLE_TAG_SVC); }

    /**
     * Direct access to WebinarService
     * @returns the WebinarService singleton instance if available
     */
    public get webinarService(): WebinarService | undefined { return this.get<WebinarService>(WEBINAR_SVC); }

    /**
     * Direct access to DocumentsService
     * @returns the DocumentsService singleton instance if available
     */
    public get documentsService(): DocumentsService | undefined { return this.get<DocumentsService>(DOCUMENTS_SVC); }

    /**
     * Direct access to core DirectoryService
     * @returns the DirectoryService singleton instance
     */
    public get directorySearchService(): DirectorySearchService { return this._directorySearchService; }

    /**
     * Direct access to CallService
     * @returns the CallService singleton instance if available
     */
    public get callService(): CallService | undefined { return this.get<CallService>(CALL_SVC); }

    /**
     * Direct access to FavoritesService
     * @returns the FavoritesService singleton instance if available
     */
    public get favoritesService(): FavoritesService | undefined { return this.get<FavoritesService>(FAVORITES_SVC); }

    /**
     * Direct access to CallLogService
     * @returns the CallLogService singleton instance if available
     */
    public get callLogsService(): CallLogService | undefined { return this.get<CallLogService>(CALL_LOG_SVC); }

    /**
     * Direct access to BubbleConferenceService
     * @returns the BubbleConferenceService singleton instance if available
     */
    public get bubbleConferenceService(): BubbleConferenceService | undefined { return this.get<BubbleConferenceService>(BUBBLE_CONFERENCE_SVC); }

    /**
     * Direct access to DataChannelService
     * @returns the DataChannelService singleton instance if available
     */
    public get dataChannelService(): DataChannelService | undefined { return this.get<DataChannelService>(DATA_CHANNEL_SVC); }

    /**
     * Direct access to DeviceManagementService
     * @returns the DeviceManagementService singleton instance if available
     */
    public get deviceManagementService(): DeviceManagementService | undefined { return this.get<DeviceManagementService>(DEVICE_MANAGEMENT_SVC); }

    /**
     * Direct access to TelephonyConfigService
     * @returns the TelephonyConfigService singleton instance if available
     */
    public get telephonyConfigService(): TelephonyConfigService | undefined { return this.get<TelephonyConfigService>(TELEPHONYCONFIG_SVC); }

    /**
     * Direct access to AdminService
     * @returns the AdminService singleton instance if available
     */
    public get adminService(): SDKAdminService | undefined { return this.get<SDKAdminService>(SDK_ADMIN_SVC); }

    private _contactService: ContactService = ContactService.getInstance();
    private _userService: UserService = UserServiceRB.getInstance();
    private _loggerService: LoggerService = LoggerService.getInstance();
    private _connectionService: ConnectionServiceRB = ConnectionServiceRB.getInstance();
    private _utilitiesService: UtilitiesService = UtilitiesService.getInstance();
    private _conversationService = ConversationServiceRB.getInstance();
    private _directorySearchService: DirectorySearchService;

    /**
     * Static method to reach the RainbowSDK singleton instance
     * @returns The Rainbow singleton instance
     */
    public static getInstance(): RainbowSDK {
        if (!window.rainbow) { window.rainbow = { plugins: {}, rainbowSDK: undefined, services: {} }; }
        if (!window.rainbow.rainbowSDK) window.rainbow.rainbowSDK = new RainbowSDK();
        return window.rainbow.rainbowSDK as RainbowSDK;
    }

    /**
     * Static method to create the RainbowSDK singleton instance
     * @returns The Rainbow singleton instance
     */
    public static create(options?: RainbowSDKConfig): RainbowSDK {

        const rainbowSDK = RainbowSDK.getInstance();
        window.adapter = adapter;
        window.$ = jquery;

        if (options?.appConfig) {
            if (options.appConfig.server) config.xmpp.server = config.webservices.server = options.appConfig.server;
            if (options.appConfig.applicationId) config.rainbowApiClientKey = options.appConfig.applicationId;
            if (options.appConfig.secretKey) config.appModuleKey = options.appConfig.secretKey;
        }

        const authService = AuthService.getInstance();
        authService.getServerApiUrls();
        authService.browserFingerprint = "NoImprint";

        XmppService.getInstance();
        SettingsService.getInstance().configure();
        SettingsService.getInstance().setSetting('apiMode', 'rainbow');

        if (options.devMode === true) {
            SettingsService.getInstance().setSetting('devMode', 'true');
            SettingsService.getInstance().setSetting('showBodyMessage', 'true');
        }

        MainService.getInstance().configure();
        EventService.getInstance().configure();
        PresenceHelperService.getInstance();

        if (options?.plugins) options.plugins.forEach((plugin: SDKPlugin) => { plugin.initialize(); });
        rainbowSDK._directorySearchService = DirectorySearchServiceRB.getInstance();

        if (options?.autoLogin) rainbowSDK._connectionService.autoLogin = options.autoLogin;
        if (options?.progressEvents) rainbowSDK._connectionService.progressEvents = options.progressEvents;
        if (options?.logLevel !== undefined) rainbowSDK._loggerService.logLevel = options.logLevel;

        // Create the globalAudioTag if necessary
        if (!document.getElementById('globalAudioTag')) {
            const audio = document.createElement('audio');
            audio.id = 'globalAudioTag';
            audio.autoplay = true;
            audio.style.display = 'none';
            document.body.appendChild(audio);
        }

        return rainbowSDK;
    }

    private constructor() {
        if (!(window as any).moment) (window as any).moment = null;
        (window as any).moduleIds = [];
        (window as any).version = 'Dev';
        (window as any).config = {
            multiEnvServer: null,
            xmpp: { protocol: 'wss', server: 'demo.openrainbow.org', port: '443', pingInterval: '60000' },
            webservices: { protocol: 'https', server: 'demo.openrainbow.org', port: '443' },
            consoleLog: true,
            sdk: true
        };
    }

    /**
     * Permits to enable console logs
     * @param enable - when set to true logs are displayed on console
     */
    public enableLogs(enable: boolean): void {
        this._loggerService.enableConsoleLog = enable;
    }

    /**
     * Permits to specify logLevel
     * @param logLevel - when set to true logs are displayed on console
     */
    public setLogLevel(logLevel: LogLevelEnum): void {
        this._loggerService.logLevel = logLevel;
    }

    /**
     * Permits to get current logLevel
     * @param logLevel - when set to true logs are displayed on console
     */
    public getLogLevel(): LogLevelEnum {
        return this._loggerService.logLevel;
    }

    /**
     * Permits to start the Rainbow SDK
     * @returns resolve when Rainbow SDK is started
     */
    public async start(): Promise<ConnectedUser> {
        return await this.connectionService.start();
    }

    /**
    * Permits to stop the Rainbow SDK
    * @returns resolve when Rainbow SDK is stopped
    */
    public async stop(): Promise<void> {
        return await this.connectionService.stop();
    }

    /**
    * Get the current Rainbow SDK version
    * @returns the current Rainbow SDK version
    */
    public getVersion(): string {
        return '5.0.36-sts';
    }

    /**
    * Permit to fetch the singleton instance of a named service
    * @returns the singleton instance of a named service
    */
    public get<T = any>(serviceName: string): T | undefined {
        return window.rainbow.services[serviceName];
    }
}
