    /**
     * Attach the xmpp handlers to callbacks
     * @public
     * @returns {void}
     * @memberof TelephonySipWiseEventHandler
     */
    public attachHandlers(): void {
        this.detachHandlers();
        this.messageHandlerRef = this.xmppService.addHandler((stanza) => { this.onCallserviceMessageReceived(stanza); return true; }, TelephonySipWiseEventHandler.CALLSERVICE_NS, "message", null);
        this.overflowUpdatRef = this.xmppService.addHandler((stanza) => { this.onOverflowUpdateMessageReceived(stanza); return true; }, TelephonySipWiseEventHandler.OVERFLOWUPDATE_NS, "message", null);
        this.userConfigurationRef = this.xmppService.addHandler((stanza) => { this.onUserConfigurationMessageReceived(stanza); return true; }, TelephonySipWiseEventHandler.USERCONFIGURATION_NS, "message", null);
        this.welcomeServiceRef = this.xmppService.addHandler((stanza) => { this.onWelcomeServiceMessageReceived(stanza); return true; }, TelephonySipWiseEventHandler.WELCOMESERVICE_NS, "message", null);
        this.huntingGroupUpdateRef = this.xmppService.addHandler((stanza) => { this.onhuntingGroupUpdateMessageReceived(stanza); return true; }, null, "message", "groupchat");
        this.huntingGroupAdminUpdateRef = this.xmppService.addHandler((stanza) => { this.onHGAdminUpdateMessageReceived(stanza); return true; }, TelephonySipWiseEventHandler.HUNTINGGROUPADMINUPDATE_NS, "message", null);
        this.clirUpdatRef = this.xmppService.addHandler((stanza) => { this.onClirMessageReceived(stanza); return true; }, TelephonySipWiseEventHandler.CLIRUPDATE_NS, "message", null); //RQRAINB-10990
    }

    /**
     * Detach the xmpp handlers
     * @public
     * @returns {void}
     * @memberof TelephonySipWiseEventHandler
     */
    public detachHandlers(): void {
        if (this.messageHandlerRef) {
            this.xmppService.deleteHandler(this.messageHandlerRef);
            this.messageHandlerRef = null;
        }
        if (this.overflowUpdatRef) {
            this.xmppService.deleteHandler(this.overflowUpdatRef);
            this.overflowUpdatRef = null;
        }
        if (this.userConfigurationRef) {
            this.xmppService.deleteHandler(this.userConfigurationRef);
            this.userConfigurationRef = null;
        }
        if (this.huntingGroupUpdateRef) {
            this.xmppService.deleteHandler(this.huntingGroupUpdateRef);
            this.huntingGroupUpdateRef = null;
        }
        if (this.huntingGroupAdminUpdateRef) {
            this.xmppService.deleteHandler(this.huntingGroupAdminUpdateRef);
            this.huntingGroupAdminUpdateRef = null;
        }
        if (this.welcomeServiceRef) {
            this.xmppService.deleteHandler(this.welcomeServiceRef);
            this.welcomeServiceRef = null;
        }
        if (this.clirUpdatRef) {
            this.xmppService.deleteHandler(this.clirUpdatRef);
            this.clirUpdatRef = null;
        }
    }


