    /**
     * Main handling callback method for received telephony events
     * @public
     * @param {any} stanza Received telephony event
     * @returns {void}
     * @memberof TelephonySipWiseEventHandler
     */
    public onCallserviceMessageReceived(stanza: any): void {
        try {
            //console.log(stanza);
            const stanzaElem = $(stanza);
            // Extract global payload element
            //sipWise+ : new balise / callservice replaced by telephony
            const actionElem = stanzaElem.find("telephony");
            const forwardUpdatedElem = actionElem.find("forwardUpdated");
            if (forwardUpdatedElem && forwardUpdatedElem.length !== 0) {
                this.onforwardUpdatedMsg(forwardUpdatedElem);
                return;
            }
            //Else check telephony event
            const eventElem = actionElem.find("event");
            const seqNum = eventElem.attr("seqNum");
            if (seqNum) { //seqNum ctrl to be implemented ?
                const ts = eventElem.attr("ts"); //timestamp
                const cause = eventElem.attr("cause"); //cause
                this.logger.info("[TelephonySipWiseEventHandler] onCallserviceMessageReceived -- telephony event received and queued: seqNum = " + seqNum + " cause = " + cause + " ts = " + ts);
            } else {
                this.logger.info("[TelephonySipWiseEventHandler] onCallserviceMessageReceived -- no telephony event received then msg ignored");
                return;
            }
            // Push the telephony event in the message queue
            this.promiseQueue.add(() => { return this.onTelephonyEvent(eventElem, seqNum); });
        } catch (error) {
            this.logger.error("[TelephonySipWiseEventHandler] onCallserviceMessageReceived -- failure -- " + error.message);
        }
    }

