    /**
     * callback method for hunting group events
     * @public
     * @param {any} stanza Received update event
     * @returns {void}
     * @memberof TelephonySipWiseEventHandler
     */
    public onhuntingGroupUpdateMessageReceived(stanza: any): void {
        try {
            const stanzaElem = $(stanza);
            //Extract various global payload element
            const rvcpGroupElt = stanzaElem.find("rvcpgroup");
            const memberData = rvcpGroupElt.find("member");
            const memberStatus = memberData.attr("status");
            if (rvcpGroupElt && rvcpGroupElt.length !== 0) {
                if (rvcpGroupElt.attr("event")) {
                    this.logger.info("[telephonySipWiseEventHandler] onhuntingGroupUpdateMessageReceived -- update HG received -- ");
                    this.logger.info("[telephonySipWiseEventHandler] onhuntingGroupUpdateMessageReceived -- for memberId/role/status: " + memberData.attr("memberId") + "/" + memberData.text() + "/" + memberStatus);
                    this.eventService.publish("ON_SIPWISE_HUNTING_GROUP_UPDATE_EVENT");
                }
            }
            const groupElt = stanzaElem.find("group");
            const roomJID = groupElt.attr("jid");
            const realTimeElt = groupElt.find("realTime");
            const waitingCalls = realTimeElt.find("waitingCalls");
            const activeCalls = realTimeElt.find("activeCalls");
            if (waitingCalls?.length !== 0 && activeCalls?.length !== 0) {
                const realStatObj = { roomJID: roomJID, waitingCallsCount: waitingCalls.attr("count"), waitingCallsOldestDate: waitingCalls.attr("oldestDate"), activeCallsCount: activeCalls.attr("count"), activeCallsOldestDate: activeCalls.attr("oldestDate") };
                this.logger.info("[telephonySipWiseEventHandler] onhuntingGroupUpdateMessageReceived -- realtime statistics -- JID: " + roomJID);
                this.eventService.publish("ON_SIPWISE_HUNTING_GROUP_REALTIME_STATISTICS_EVENT", realStatObj);
            }
        } catch (error) {
            this.logger.error("[TelephonySipWiseEventHandler] onhuntingGroupUpdateMessageReceived -- failure -- " + error.message);
        }
    }//end of onhuntingGroupUpdateMessageReceived

