    /**
     * Method manageLegElem
     * search leg elem in eventElem
     * @private
     * @param {any} legElem [required] leg part
     * @param {any} eventElem [required] xmpp msg, event part
     * @param {string} seqNum [required] messqge sequence number
     * @param {any[]} callsToUpdate [required] list of calls to update
     * @async
     * @returns {Promise<void>} Status promise resolved when the handling is complete
     * @memberof TelephonySipWiseEventHandler
     */

    private async manageLegElem(legElem: any, eventElem: any, seqNum: string, callsToUpdate: any[]): Promise<void> {
        try {
            //collecte all attributes mainly for log
            const legId = legElem.attr("legId"); //required
            const callId = legElem.attr("callId"); //required
            const deviceId = legElem.attr("deviceId");
            const state = legElem.attr("state");
            const op = legElem.attr("op"); //required
            if (!legId) {
                const errorMessage = "manageLegElem -- Anomaly legId missing / seqNum = " + seqNum;
                throw new Error(errorMessage);
            }
            if (!callId) {
                const errorMessage = "manageLegElem -- Anomaly callId missing / seqNum = " + seqNum;
                throw new Error(errorMessage);
            }
            if (!op) {
                const errorMessage = "manageLegElem -- Anomaly op missing / seqNum = " + seqNum;
                throw new Error(errorMessage);
            }
            this.logger.info("[TelephonySipWiseEventHandler] manageLegElem legId = " + legId + " callId = " + callId +
                " deviceId = " + deviceId + " state = " + state + " op = " + op + " / seqNum = " + seqNum);
            switch (op) {
                case "created":
                    if (this.computeCallRelevancy(deviceId, callId)) {
                        this.logger.debug("[TelephonySipWiseEventHandler] manageLegElem / create legId/callId = " + legId + "/" + callId + " relevant");
                        await this.legElemCreate(eventElem);
                        const call = this.getCallFromCallId(callId);
                        call.setConnectionIdSipWise(legId);
                        callsToUpdate[callId] = { trigger: true, info: "leg" + op }; //tag callId as call to be updated
                    } else { //this leg is not to be managed
                        this.logger.info("[TelephonySipWiseEventHandler] manageLegElem / create legId/callId = " + legId + "/" + callId + " not relevant");
                    }
                    break;
                case "updated":
                    if (this.computeCallRelevancy(deviceId, callId)) {
                        this.logger.debug("[TelephonySipWiseEventHandler] manageLegElem / update legId/callId = " + legId + "/" + callId + " relevant");
                        await this.legElemUpdate(eventElem);
                        const call = this.getCallFromCallId(callId);
                        call.setConnectionIdSipWise(legId);
                        callsToUpdate[callId] = { trigger: true, info: "leg" + op }; //tag callId as call to be updated
                    } else { //this leg is not to be managed
                        this.logger.info("[TelephonySipWiseEventHandler] manageLegElem / update legId/callId = " + legId + "/" + callId + " not relevant");
                    }
                    break;
                case "ended":
                    this.logger.info("[TelephonySipWiseEventHandler] manageLegElem / leg end / seqNum = " + seqNum);
                    if (this.computeCallRelevancy(deviceId, callId)) {
                        //call state -> ended to be updated
                        const call = this.getCallFromCallId(callId);
                        if (call) {
                            this.telephonyService.clearCall(this.getCallFromCallId(callId), true); //2nd para true for clearcall without broadcast
                            callsToUpdate[callId] = { trigger: true, info: "leg" + op }; //update op
                        } else {
                            this.logger.info("[TelephonySipWiseEventHandler] manageLegElem : leg ended / call already removed");
                        }
                    } else { //this legs is no more involved in the call but not relevant device
                        this.logger.info("[TelephonySipWiseEventHandler] manageLegElem : leg ended but not relevant");
                    }
                    break;
                default: {
                    this.logger.info("[TelephonySipWiseEventHandler] manageLegElem / invalid op -> " + op + " / seqNum = " + seqNum);
                    const errorMessage = "manageLegElem -- Anomaly invalid op / seqNum = " + seqNum;
                    this.logger.error("[TelephonySipWiseEventHandler] " + errorMessage);
                    throw new Error(errorMessage);
                }
            }
        } catch (error) {
            const errorMessage = "manageCallElem -- " + error.message;
            throw new Error(errorMessage);
        }
    } //end manageLegElem

