    /**
     * Method endPointDevicesMng
     * @private
     * @param {any} endPointElem [required] xmpp msg endPoint part
     * @returns {any []} list of devices
     * @memberof TelephonySipWiseEventHandler
     */
    private endPointDevicesMng(endPointElem: any): any {

        const callId = endPointElem.attr("callId"); //required
        const endpointId = endPointElem.attr("endpointId");
        const deviceList = [];

        if (callId && endpointId) {
            endPointElem.find("device").each((__index: number, endPointDeviceElem: Element) => {
                const endPointDeviceElemIter = $(endPointDeviceElem);
                const deviceType = endPointDeviceElemIter.attr("type");
                const deviceId = endPointDeviceElemIter.attr("deviceId");
                if (deviceType && deviceId) {
                    deviceList.push({ "callId": callId, "endpointId": endpointId, "deviceType": deviceType, "deviceId": deviceId });
                }
            });
        } else {
            const errorMessage = "endPointDevicesMng -- Anomaly no callId or endpointId";
            this.logger.error("[TelephonySipWiseEventHandler] " + errorMessage);
        }
        return deviceList;
    } //end endPointDevicesMng

    /**
     * Method endPointContactFromUserIdMng
     * @private
     * @param {any} endPointElem [required] xmpp msg endPoint part
     * @async
     * @returns {Promise<Contact>} pomise of contact
     * @memberof TelephonySipWiseEventHandler
     */
    private async endPointContactFromUserIdMng(endPointElem: any): Promise<Contact> { //RQRAINB-10966

        const phoneNumber = endPointElem.find("phoneNumber").text();
        const jid = endPointElem.find("jid").text();
        const firstName = endPointElem.find("firstName").text();
        const lastName = endPointElem.find("lastName").text();
        const displayName = endPointElem.find("displayName").text();
        const origin = endPointElem.find("origin").text(); //RQRAINB-10966
        const userId = endPointElem.find("userId").text(); //RQRAINB-10966

        let contact: Contact = null;

        if (origin && userId) { //RQRAINB-10966
            this.logger.info("[TelephonySipWiseEventHandler] endPointContactFromUserIdMng :  origin/userId = " + origin + " / " + userId);
        }

        if (jid) { //rainbow case
            contact = await this.contactService.getOrCreateContact(jid);
            return contact;
        }
        if (userId && origin && origin !== "RAINBOW") { //userId and origin provided
            try {
                switch (origin) {
                    case "O365":
                        contact = await this.office365AdService.getO365ContactFromServer(userId);
                        break;
                    case "PERSONAL_DIRECTORY":
                    case "BUSINESS_DIRECTORY":
                        contact = await this.companyDirectoryService.getDirectoryContactById(userId);
                        break;
                    case "PBX":
                        contact = null; //nothing new to be expected from pbx server search then manage it from PCG included info as the case of no contact found
                        break;
                    default:
                        this.logger.error("[TelephonySipWiseEventHandler] endPointContactFromUserIdMng anomaly directory origin not managed");
                        contact = null;
                        break;
                }
            } catch (error) { //something wrong with server search
                this.logger.error("[TelephonySipWiseEventHandler] endPointContactFromUserIdMng anomaly directory search error : " + error.status);
                contact = null;
            }
            if (!contact) { //no info from previous search then use provided names from pcg
                contact = await this.contactService.getOrCreateContact(jid, phoneNumber);
                if (firstName || lastName) {
                    const updatedFirstname = firstName ? firstName : '';
                    const updatedLastname = lastName ? lastName : '';
                    contact.updateName(updatedFirstname, updatedLastname);
                } else if (displayName) {
                    contact.updateName("", displayName);
                    this.eventService.publish("ON_USER_CONTACT_UPDATED_TELEPHONY_EVENT", contact); ///CRRAINB-31295
                }
            }
            return contact;
        }
        if (phoneNumber) { // manage with the remaining given info
            contact = await this.contactService.getOrCreateContact(null, phoneNumber);
            if (firstName || lastName) {
                const updatedFirstname = firstName ? firstName : '';
                const updatedLastname = lastName ? lastName : '';
                contact.updateName(updatedFirstname, updatedLastname);
            } else if (displayName) { //CRRAINB-26699
                contact.updateName("", displayName);
            }
        }
        return contact;
    } //end endPointContactFromUserIdMng

