export const WEBRTC_CONFIG_UTILS_SVC = 'WebrtcConfigAndUtils';

export interface WebrtcStatisticsNetwork {
    /**
     * Type of interface usedCan be "wifi", "vpn", "ethernet", "unknown", "cellular"
     * From networkType in local-candidate report
     */
    networkType?: string;

    /**
     * Route used by the peer-connectionFormat: <local_address>: [type] (protocol) <-> <remote_address>: [type] (protocol)
     * Computed from statistics in local_candidate and remote_candidate depending on the localCandidateId and remoteCandidateId in the candidate-pair report in use (selectedCandidatePairId in tranport report or selected=true in candidate-pair report
     */
    candidatePair?: string;
}

/**
 * Object containing all stats related to the output-rtp (outflow)
 */
export interface WebrtcStatisticsOutboundAudio {
    /**
     * The total of packets sent from the beginning of this RTP stream.From packetsSent in outbound-rtp report
     */
    totalPacketsSent?: number,

    /**
     * The total of bytes sent from the beginning of this RTP stream.From bytesSent outbound-rtp report
     */
    totalBytesSent?: number,

    /**
     * The delta of the audio KB sent between the current and the last iteration
     */
    deltaAudioKBSent?: number,

    /**
     * The current encoder target in bits per second for this RTP stream.From targetBitrate in outbound-rtp report
     */
    targetBitrate?: number,

    /**
     * Represents the audio level of the media source detected from the input device
     */
    audioInputLevel?: number,

    /**
     * If exist, the value of the media identification-tag negotiated for this RTP streamFrom mid in inbound-rtp or outbound-rtp report
     */
    mid?: number,

    /**
     * Name of the inbound codec used (eg: "opus")
     * Computed from mimeType (remove "audio/") in the codec report associated to this RTP Stream (codecId from the inbound-rtp report)
     */
    codec?: string
}

/**
 * Object containing all stats related to the inbound-rtp (inflow)
 */
export interface WebrtcStatisticsInboundAudio {
    /**
     * The total of packets received from the beginning of this RTP stream.From packetsReceived in inbound-rtp report
     */
    totalPacketsReceived?: number,

    /**
     * The total of packets discarded from the beginning of this RTP stream.From packetsDiscarded in inbound-rtp report
     */
    totalPacketsReceivedDiscarded?: number,

    /**
     * The total of packets lost from the beginning of this RTP stream.From packetsLost in inbound-rtp report
     */
    totalPacketsLost?: number,

    /**
     * The total of bytes received from the beginning of this RTP stream.From bytesReceived inbound-rtp report
     */
    totalBytesReceived?: number,

    /**
     * The number of packets received for this RTP stream from the last measurement. Computed from packetsReceived in inbound-rtp report
     */
    deltaPacketsReceived?: number,

    /**
     * The number of KB received for this RTP stream since the last measurement.
     */
    deltaKBReceived?: number,

    /**
     * Mean of the round trip time during the last interval.Computed from totalRoundTripTime and roundTripTimeMeasurements in remote-outbound-rtp report
     */
    roundTripTimeMs?: number,

    /**
     * Mean of the jitter buffer delay during the last interval.Computed From jitterBufferDelay and jitterBufferEmittedCount in inbound-rtp report
     */
    jitterBufferMs?: number,

    /**
     * Value of the jitter for the current measurement.From jitter in inbound-rtp report
     */
    jitterMs?: number,

    /**
     * Mean for the last interval. Computed from the codec used, the absolute delay computed and the packets lost.
     */
    mos?: number,

    /**
     * Name of the inbound codec used (eg: "opus")
     * Computed from mimeType (remove "audio/") in the codec report associated to this RTP Stream (codecId from the inbound-rtp report)
     */
    codec?: string,

    /**
     * If exist, the value of the media identification-tag negotiated for this RTP streamFrom mid in inbound-rtp or outbound-rtp report
     */
    mid?: number,

    /**
     * The MEAN MOS value for the current session
     */
    meanMOS?: number,

    /**
     * Represents the audio level of the media source seen from the output device
     */
    audioOutputLevel?: number,

    /**
     * Represents the absolute delay computed with: absoluteDelay:number = 20 + RTT/2 + JitterBufferDelay where
     * 20 represents the packetization time (fixed value) in milliseconds
     * RTT as computed in Compute the Round Trip Time in milliseconds
     * JitterBufferDelay in milliseconds
     */
    absDelayMs?: number,

    /**
     * A value indicating the current quality of the incoming audio based on the MOS value; Values are 0, 1, 2; as 0 is bad, 3 is good
     */
    networkQualityValue?: number
}

/**
 * Interface containing all stats related to the audio stats for the sessions output-rtp (outflow) + input-rtp (inflow)
 */
export interface WebrtcStatisticsAudio {
    /**
     * Object containing all stats related to the output-rtp (outflow)
     */
    sent?: WebrtcStatisticsOutboundAudio,

    /**
     * Object containing all stats related to the inbound-rtp (inflow)
     */
    received?: WebrtcStatisticsInboundAudio
}

/**
 * Interface containing all stats related to the OUTBOUND video stats for the sessions
 * NOTE The same interface is also related to the screen sharing, as in terms of WEBRTC it's a VIDEO stream
 */
export interface WebrtcStatisticsOutboundVideo {
    /**
     * The total of packets sent from the beginning of this RTP stream. From packetsSent in outbound-rtp report
     */
    totalPacketsSent?: number,

    /**
     * The total of bytes sent from the beginning of this RTP stream. From bytesSent outbound-rtp report
     */
    totalBytesSent?: number,

    /**
     * The total time for encoding the media from the beginning of this RTP stream. From totalEncodeTime in outbound-rtp report
     */
    totalEncodeTimeSeconds?: number,

    /**
     * The total number of video frames sent from the beginning of this RTP stream. From framesSent in outbound-rtp report
     */
    totalFramesSent?: number,

    /**
     * The number of frames that were successfully encoded from the beginning of this RTP stream.From framesEncoded in outbound-rtp report
     */
    totalFramesEncoded?: number,

    /**
     * The number of key frames that were successfully encoded from the beginning of this RTP stream.From keyFramesEncoded in outbound-rtp report
     */
    totalKeyFramesEncoded?: number,

    /**
     * The number of Picture Loss Indication (PLI) requests sent (receiver) or received (sender) from the beginning of this RTP stream.
     * From pliCount in outbound-rtp report
     */
    totalPliCount?: number,

    /**
     * The number of Negative Acknowledgment (NACK) requests sent from the beginning of this RTP stream. From nackCount in outbound-rtp report
     */
    totalNackCount?: number,

    /**
     * The current encoder target in bits per second for this RTP stream.From targetBitrate in outbound-rtp report
     */
    targetBitrate?: number,

    /**
     * The number of horizontal pixels in a video frame for this RTP stream.From frameWidth in inbound-rtp or outbound-rtp report
     */
    frameWidth?: number,

    /**
     * The number of vertical pixels in a video frame for this RTP stream.From frameHeigh in inbound-rtp or outbound-rtp report
     */
    frameHeight?: number,

    /**
     * The number of individual video frames sent per second at a given time.
     */
    framesPerSecond?: number,

    /**
     * The current reason for limiting the resolution and/or framerate. Acceptable values: bandwidth, cpu, other, none.
     */
    qualityLimitationReason?: string,

    /**
     * Object containing the details about all quality limitations durations during the session
     */
    qualityLimitationDurations?: any,

    /**
     * If exist, the value of the media identification-tag negotiated for this RTP streamFrom mid in inbound-rtp or outbound-rtp report
     */
    mid?: number,

    /**
     * The rate of retransmitted packets sent per second.
     * This metric is useful for evaluating the stability and quality of a WebRTC connection by indicating how many packets needed to be resent to maintain data integrity.
     */
    retransmittedPacketsSent?: number,

    /**
     * The average Quantization Parameter (QP) used for encoding a video stream, normalized by the number of frames encoded.
     * The Quantization Parameter (QP) is a crucial factor in video compression and directly affects the quality and bitrate of the video.
     * The Quantization Parameter (QP) controls the level of compression during video encoding. Lower QP values (e.g., around 10-20) correspond to higher video quality because the encoding process uses more bits to represent each frame.
     * Higher QP values (e.g., 30-50) result in higher compression and lower video quality, as fewer bits are used per frame.
     */
    qpValue?: number,

    /**
     * Name of the codec used (eg: "vp8")Computed from mimeType (remove "audio/") in the codec report associated to this RTP Stream (codecId from the inbound-rtp report)
     */
    codec?: string
}

