    public async createOrUpdateStatisticsForCall(call: CallRB) {
        try {
            if (!call) {
                throw new Error(`[WebrtcConfigAndUtils] createOrUpdateStatisticsForCall -- missing call`);
            }

            if (!call.contact) {
                throw new Error(`[WebrtcConfigAndUtils] createOrUpdateStatisticsForCall -- missing contact for call`);
            }

            const callId = call.id;
            const contactDbId = (call.contact.dbId) ? call.contact.dbId : call.contact.id;

            if (!callId || !contactDbId) {
                throw new Error(`[WebrtcConfigAndUtils] createOrUpdateStatisticsForCall -- missing informations for ${callId} `);
            }

            const metrics = [];

            //check if statistics already exist
            if (this.callsStats[callId]) {
                if (this.callsStats[callId].RainMetrics) { this.callsStats[callId].push(this.callsStats[callId].RainMetrics); }
                metrics.push({ connectionId: callId, stats: this.callsStats[callId] });

                if (this.started) {
                    await this.updateStatisticsForCall(this.callsStats[callId].id, callId, "ended", metrics);
                } else {
                    this.statsWaitingQueue.push({ id: this.callsStats[callId].id, callId: callId, callState: "ended", metrics: metrics });
                }
                return;
            }

            this.logger.info("[WebrtcConfigAndUtils] createOrUpdateStatisticsForCall " + callId);
            this.callsStats[callId] = {};
            metrics.push({ connectionId: callId, stats: this.callsStats[callId] });

            const id = await this.createStatisticsForSession(callId, contactDbId, "pending");
            this.callsStats[callId].id = id;
            this.logger.info("[WebrtcConfigAndUtils] createOrUpdateStatisticsForCall success for session " + callId + " with id " + id);
        }
        catch (error) {
            this.logger.error("[WebrtcConfigAndUtils] createOrUpdateStatisticsForCall error -- " + error.message);
        }
    }

    public async updateStatisticsForCall(id: string, callId: string, callState: string, metrics: any): Promise<void> {
        try {
            if (!id) {
                throw new Error(`[WebrtcConfigAndUtils] updateStatisticsForCall -- missing id ${id}`);
            }

            this.logger.info("[WebrtcConfigAndUtils] updateStatisticsForCall " + callId);
            const portalURL = config.restServerUrl + "/api/rainbow/metrics/v1.0/";

            const response = await fetch(portalURL + "webrtcmetrics/" + id + "/metrics", {
                method: 'POST',
                headers: this.authService.getPostHeader(),
                body: JSON.stringify({
                    metrics: metrics
                })
            });
            if (!response.ok) throw (response);

            this.logger.info("[WebrtcConfigAndUtils] updateStatisticsForCall success");

            if (callState === "ended") {
                this.logger.info("[WebrtcConfigAndUtils] updateStatisticsForCall -- update call state with " + callState);
                const response2 = await fetch(portalURL + "webrtcmetrics/" + id, {
                    method: 'PUT',
                    headers: this.authService.getPostHeader(),
                    body: JSON.stringify({
                        callState: callState
                    })
                });
                if (!response2.ok) throw (response2);
                this.logger.info("[WebrtcConfigAndUtils] updateStatisticsForCall -- update call state success");
            }
        }
        catch (error) {
            this.logger.error("[WebrtcConfigAndUtils] updateStatisticsForCall failure " + error.errorMsg);

            if (!this.started) {
                this.logger.log("No internet connection");
            }
        }
    }

    public async createStatisticsForSession(callId: string, peerId: string, callState: string): Promise<string> {
        try {
            this.logger.info("[WebrtcConfigAndUtils] createStatisticsForSession " + callId);
            const portalURL = config.restServerUrl + "/api/rainbow/metrics/v1.0/webrtcmetrics";

            const response = await fetch(portalURL, {
                method: 'POST',
                headers: this.authService.getPostHeader(),
                body: JSON.stringify({
                    callId: callId,
                    peerId: peerId,
                    callState: callState
                })
            });
            if (!response.ok) throw (response);
            const result = (await response.json()).data;
            const id = result ? result.id : null;

            this.logger.info("[WebrtcConfigAndUtils] createStatisticsForSession success");
            if (id && !this.callsStats[callId]) {
                this.callsStats[callId] = {};
            }

            return id;
        }
        catch (error) {
            this.logger.error("[WebrtcConfigAndUtils] createStatisticsForSession failure " + error.errorMsg);
            throw error;
        }
    }

