/**
 * @internal
 * Call service events send to other services
 * Can listen to it via `CallService.subscribe()` API.
 */
export enum CallServiceEvents {
    /**
     * @eventProperty
     * This RBEvent is sent when a call is accepted
     *
     * **Event Data**
     * - **call**: The call that is accepted
     */
    ON_CALL_ACCEPTED = 'ON_CALL_ACCEPTED',

    /**
     * @eventProperty
     * An audio call only has been requested
     */
    ON_MAKE_AUDIO_CALL = 'ON_MAKE_AUDIO_CALL',

    /**
     * @eventProperty
     * A phone call has been requested
     */
    ON_MAKE_PHONE_CALL = 'ON_MAKE_PHONE_CALL'
}

