    /**
     * Subscribe to updates from the call service, all events are of RBEvent<CallServiceEvents>
     * @param callback - The callback function that will be called when events are received
     * @param eventNames - (optional) array of event to listen
     * @returns Returns RxJS Subscription
     */
    public subscribe(callback: (event: RBEvent<CallServiceEvents>) => any, eventNames?: CallServiceEvents | CallServiceEvents[]): Subscription {
        const observable = eventNames ? this.rxSubject.pipe(filter((event: RBEvent<CallServiceEvents>) => {
            if (eventNames instanceof Array) return eventNames.indexOf(event.name) !== -1;
            return event.name === eventNames;
        })) : this.rxSubject;

        return observable.subscribe((event: RBEvent<CallServiceEvents>) => {
            try { callback(event); }
            catch (error) { this.logger.error(`[ConversationService] subscribe () -- error -- ${error.message}`); }
        });
    }


    public sendEvent(name: CallServiceEvents, data: any = null) {
        this.rxSubject.next(RBEvent.create(name, data));
    }

