    allowAttendeeToTalk(webinar: Webinar, userId: string): Promise<Webinar>;
    disableAttendeeToTalk(webinar: Webinar, userId: string): Promise<Webinar>;
    askForStaging(webinar: Webinar, participantId: string): Promise<any>;
    declineStagingInvitation(webinar: Webinar, participantId: string): Promise<void>;
    lowerHand(webinar: Webinar, userId: string): Promise<Webinar>;
