    public async applyVideoConstraints(webinar: Webinar, streamType: 'audioVideo' | 'sharing', resolution: WebinarConstraintResolution, frameRate: number, maxBitrate: number): Promise<void> {
        try {
            const stream = webinar.session?.localParticipant[`${streamType}Stream`];
            const tranceiverIndex = streamType === 'audioVideo' ? 1 : 0;
            const senderTranceiver = webinar.session?.localParticipant[`${streamType}Session`]?.localTransceivers[tranceiverIndex].sender;

            if (stream && senderTranceiver) {
                const track = stream.getVideoTracks()[0];

                // Compute scaling informations
                const scaleInfo = this.computeScaleFactor(track, resolution, streamType === 'sharing');

                // Compute maxBitRate
                const appliedMaxBitrate = localStorage.getItem('webinarConstantMaxBitRate') === 'true' ? (streamType === 'sharing' ? 1500000 : 1200000) : maxBitrate * 1000;
                const maxBitrateInfo = `${appliedMaxBitrate / 1000}k`;

                // Apply scale factor and maxBitRate
                const params = senderTranceiver.getParameters();
                params.encodings[0].scaleResolutionDownBy = scaleInfo.scaleFactor;
                params.encodings[0].maxBitrate = appliedMaxBitrate;
                senderTranceiver.setParameters(params);

                // Apply frame rate constraints on src track
                if (streamType === 'audioVideo') {
                    const originalStream = webinar.session?.localParticipant.originalAudioVideoStream;
                    const originalTrack = originalStream.getVideoTracks()[0];
                    const constraints = originalTrack.getConstraints();
                    constraints.frameRate = frameRate;
                    await originalTrack.applyConstraints(constraints);
                    this.virtualBackgroundService?.setFramerate(frameRate);
                }
                else {
                    const constraints = track.getConstraints();
                    constraints.frameRate = frameRate;
                    await track.applyConstraints(constraints);
                }

                this.logger.info(`[WebinarServiceConference] applyVideoConstraints (web: ${webinar.id}, type: ${streamType}, ${scaleInfo.scaleInfo}, frameRate: ${frameRate}fps, maxBitRate: ${maxBitrateInfo})`);
            }
        }
        catch (error) { this.logger.error(`[WebinarServiceConference] applyVideoConstraints -- failure -- ${error.message}`); }
    }

