    private computeScaleFactor(track: MediaStreamTrack, resolution: WebinarConstraintResolution, sharing: boolean): any {
        const trackInfo = track.getSettings();
        const width = trackInfo.width;
        const height = trackInfo.height;
        const aspectRatio = trackInfo.aspectRatio;

        let ratio: string;
        switch (aspectRatio) {
            case 16 / 9: ratio = '(16/9)'; break;
            case 16 / 10: ratio = '(16/10)'; break;
            case 4 / 3: ratio = '(4/3)'; break;
            case 5 / 4: ratio = '(5/4)'; break;
            default: ratio = '(unknown)'; break;
        }

        let expectedHeight: number;
        switch (resolution) {
            case 'high': expectedHeight = sharing ? 1080 : 720; break;
            case 'medium': expectedHeight = 360; break;
            case 'low': expectedHeight = 180; break;
            case 'min': expectedHeight = 110; break;
            default: expectedHeight = 360; break;
        }

        const scaleFactor = expectedHeight < height ? height / expectedHeight : 1;
        const srcInfo = `${width}x${height}${ratio}`;
        const resInfo = `${resolution}(${expectedHeight}p)`;
        const destInfo = `${Math.floor(width / scaleFactor)}x${Math.floor(height / scaleFactor)}${ratio}`;
        const scaleInfo = `srcRes:${srcInfo} => expRes "${resInfo}" => scaleFactor:${scaleFactor.toFixed(2)} => compRes:${destInfo}`;
        return { scaleFactor, scaleInfo };
    }

    public disableIncomingStreams(webinar: Webinar, media: 'video' | 'sharing', disabled: boolean): Webinar {
        webinar.incomingStreamsDisabled[media] = disabled;
        webinar.session.speakerParticipants.forEach((participant) => {
            this.pauseVideoStream(webinar, participant, media, disabled, 'global');
        });
        return webinar;
    }

    public async pauseVideoStream(webinar: Webinar, participant: WebinarSessionParticipant, media: 'video' | 'sharing', paused: boolean, origin: string): Promise<Webinar> {
        // Never try to pause localParticipant video
        if (participant.id === webinar.session.localParticipant.id) return webinar;

        const session: JingleSession = participant[media === 'video' ? 'audioVideoSession' : 'sharingSession'];
        const videoStreamAvailable = participant.medias[media === 'video' ? 'video' : 'sharing'];
        if (!videoStreamAvailable) return webinar;
        if (paused) {
            if (!session.onHold) {
                await session.sendHold(true);
                participant.rxSubject.next(RBEvent.create('updateMedia', { type: media }));
                this.logger.info(`[WebinarServiceConference] pauseVideoStream (web: ${webinar.id}, part: ${participant.id}, media: ${media}, paused: ${paused}, origin: ${origin}})`);
            }
        }
        else {
            if (session.onHold && !webinar.incomingStreamsDisabled[media]) {
                await session.sendHold(false);
                participant.rxSubject.next(RBEvent.create('updateMedia', { type: media }));
                this.logger.info(`[WebinarServiceConference] pauseVideoStream (web: ${webinar.id}, part: ${participant.id}, media: ${media}, paused: ${paused}, origin: ${origin}})`);
            }
        }
        return webinar;
    }

