    private startSession(webinar: Webinar): Promise<Webinar> {
        return new Promise<Webinar>(async (resolve: any, reject: any) => {
            if (webinar.session) resolve(webinar);
            try {
                if (webinar.isAttendee) {
                    webinar.session = WebinarSession.create();
                    this.logger.info(`[WebinarServiceConference] startSession (web: ${webinar.id}) -- attendee create a session object`);
                    resolve(webinar);
                }
                else {
                    const startTimeout = setTimeout(() => {
                        if (this.startConferencePromiseResolvers[webinar.id]) {
                            this.startConferencePromiseResolvers[webinar.id] = null;
                            delete this.startConferencePromiseResolvers[webinar.id];
                        }
                        this.logger.info(`[WebinarServiceConference] startSession (web: ${webinar.id}) -- start session timeout`);
                        reject(new Error('Webinar startsession timeout'));
                    }, 8000);

                    this.startConferencePromiseResolvers[webinar.id] = () => {
                        clearTimeout(startTimeout);
                        if (this.startConferencePromiseResolvers[webinar.id]) { delete this.startConferencePromiseResolvers[webinar.id]; }
                        resolve(webinar);
                    };

                    const url = `${config.restServerUrl}/api/rainbow/conference/v1.0/rooms/${webinar.roomId}/start`;
                    const headers = this.authService.getPostHeader();
                    const response = await fetch(url, { method: "POST", headers });
                    if (!response.ok) {
                        const data = await response.json();
                        // For unknown reason, the webinar room is inactive, send initial presence to reactivate it !
                        if (data.errorDetailsCode === 409111 && webinar.room) {
                            this.logger.info(`[WebinarServiceConference] startSession (web: ${webinar.id}) -- webinar room is inactive, send initial presence to reactivate it`);
                            await this.bubbleService.sendInitialRoomPresenceSync(webinar.room as BubbleRB);
                            const response = await fetch(url, { method: "POST", headers });
                            if (!response.ok) throw response;
                        }
                        else throw response;
                    }
                }
                this.logger.info(`[WebinarServiceConference] startSession (web: ${webinar.id}) -- success`);
            }
            catch (error) {
                const errorInfo = await this.errorHelperService.getErrorInfo(error, `startSession -- ${webinar.id}`);
                this.logger.info(`[WebinarServiceConference] startSession (web: ${webinar.id}) -- error -- ${errorInfo.message}`);
                reject(errorInfo.error);
            }
        });
    }

    private async joinSession(webinar: Webinar): Promise<void> {
        try {
            this.subscribeToPublisherPromiseResolvers = {};
            const url = `${config.restServerUrl}/api/rainbow/conference/v1.0/rooms/${webinar.roomId}/join?context=webinar`;
            const headers = this.authService.getPostHeader();
            const resourceId = this.xmppService.getResourceFromJid(this.xmppService.fullJid);
            const codecs = this.manageCodecs();
            const params: any = { resourceId, codecs };
            if (this.profileService.isFeatureEnabled(this.profileService.FeaturesEnum.UNMUTE_REQUEST)) { params['askToUnmute'] = true; }
            const body = JSON.stringify(params);
            const webRequestId = randomString(10);
            this.logger.info(`[WebinarServiceConference] joinSession (web: ${webinar.id}, jid: ${this.xmppService.fullJid}, webRequestId: ${webRequestId})`);
            const response = await fetch(url, { method: 'POST', headers, body });
            if (!response.ok) throw response;
            const data = (await response.json()).data;
            if (webinar.session) webinar.session.jingleJid = data.jingleJid;
            if (data.isAlreadyConnected === true) {
                this.logger.info(`[WebinarServiceConference] joinSession (web: ${webinar.id}, jid: ${this.xmppService.fullJid}) -- already connected to this webinar`);
                throw new Error('alreadyConnected');
            }
            this.logger.info(`[WebinarServiceConference] joinSession (web: ${webinar.id}, jid: ${this.xmppService.fullJid}, webRequestId: ${webRequestId}) -- success`);
        }
        catch (error) {
            const errorInfo = await this.errorHelperService.getErrorInfo(error, `joinSession (web: ${webinar.id}, jid: ${this.xmppService.fullJid})`);
            throw errorInfo.error;
        }
    }

    private manageCodecs(): WebinarCodecs {
        const codecs: WebinarCodecs = {};
        const defaultCodec = localStorage.getItem('enableWebinarSimulcast') !== 'false' ? 'vp8' : 'vp8';
        const storedVideoCodec = localStorage.getItem('webinarVideoCodec') || defaultCodec;
        const storedSharingCodec = localStorage.getItem('webinarSharingCodec') || defaultCodec;
        if (storedVideoCodec) codecs.video = storedVideoCodec;
        if (storedSharingCodec) codecs.sharing = storedSharingCodec;
        return codecs;
    }

    private async stopSession(webinar: Webinar): Promise<Webinar> {
        try {
            webinar.action = 'stopSession';
            const url = `${config.restServerUrl}/api/rainbow/conference/v1.0/rooms/${webinar.roomId}/stop`;
            const headers = this.authService.getPostHeader();
            const body = JSON.stringify({ webinarRoomType: 'practiceRoom' });
            const response = await fetch(url, { method: "DELETE", headers, body });
            if (!response.ok) throw response;
            this.logger.info(`[WebinarServiceConference] stopSession (web: ${webinar.id}) -- success`);
            return webinar;
        }
        catch (error) {
            const errorInfo = await this.errorHelperService.getErrorInfo(error, "stopSession");
            throw errorInfo.error;
        }
    }

    private async disconnectParticipant(webinar: Webinar, participantId: string): Promise<Webinar> {
        try {
            let url = `${config.restServerUrl}/api/rainbow/conference/v1.0/rooms/${webinar.room.dbId}/users/${participantId}`;
            if (this.bubbleService.context === 'webinar') url += '?context=webinar';
            const headers = this.authService.getRequestHeader();
            const response = await fetch(url, { method: "DELETE", headers });
            if (!response.ok) throw response;

            if (webinar.session) {
                if (participantId === this.contactService.userContact.dbId) {
                    this.clearSession(webinar);
                    webinar.session.localParticipant = undefined;
                    webinar.session.speakerParticipants = [];
                }
                else webinar.session.removeParticipant(participantId);
            }
            webinar.rxParticipantsSubject.next(null);

            this.logger.info(`[WebinarServiceConference] disconnectParticipant (web: ${webinar.id}, part: ${participantId}`);
            return webinar;
        }
        catch (error) {
            const errorInfo = await this.errorHelperService.getErrorInfo(error, "disconnectParticipant");
            throw errorInfo.error;
        }
    }

