    public async getErrorInfo(error: any, context: string = null, params: any = null) {
        const errorInfo = new ErrorHelperInfo();
        if (error instanceof Error) {
            errorInfo.message = error.message;
            errorInfo.error = error;
            if (error.message === "Failed to fetch") {
                errorInfo.error.translatedMessage = this.i18n.translate("IceConfigurationFailed");
            }
        }

        if (error instanceof Response) {
            let data;
            try {
                data = await error.json();
            } catch { /* don't care about this error : probably contains an HTML error page */ }
            const status = (data?.errorDetailsCode) ? data.errorDetailsCode : error.status;
            const statusText = this.getStatusText(status, error);
            const errorText = this.getErrorText(data);
            const feature = this.getFeature(data);
            const portal = error.url ? (error.url.match(/api\/rainbow\/(\w+)\//))[1] : undefined;
            const requestId = (error.headers?.get("x-rainbow-request-id")) ? ` (x-rainbow-request-id:${error.headers.get("x-rainbow-request-id")})` : '';

            // Compute error message
            if (context) { errorInfo.message = `${context} -- `; }
            errorInfo.message += `${statusText} -- ${errorText}`;
            if (feature) { errorInfo.message += `-- ${feature}`; }
            if (requestId) { errorInfo.message += requestId; }

            // Create the error
            errorInfo.error = new Error(errorInfo.message);
            errorInfo.error.status = error.status;
            errorInfo.error.statusText = statusText;
            errorInfo.error.fieldErrors = this.getBadRequestFieldErrors(data, error);
            errorInfo.error.errorDetails = this.getTextWithoutIds(errorText);
            errorInfo.error.errorDetailsCode = status;
            errorInfo.error.errorDetailsLabel = this.getErrorCodeLabel(status, portal);
            try {
                errorInfo.error.translatedMessage = this.getTranslatedErrorMessage(errorInfo.error, params, portal);
            } catch (error) {
                //Noop
            }
            errorInfo.error.portal = portal;
            errorInfo.error.feature = feature;
            if (data?.errorDetailsData) errorInfo.error.errorDetailsData = data.errorDetailsData;
            errorInfo.error.fullResponseData = data;
        }
        return errorInfo;
    }

    private getTranslatedErrorMessage(error: any, params: any, portal: string): string {
        let errorMessage = '';
        if (error.errorDetailsCode) {
            errorMessage = this.getLocalizedError(error.errorDetailsCode, params, portal);
            if (!errorMessage) { errorMessage = this.i18n.translate("anErrorOccurred", { errorcode: error.errorDetailsCode }); }
        }
        return errorMessage;
    }

    public getLocalizedError(errorCode: string, params: any, portal: string): string {
        let errorMessage = '';
        const errorLabel = this.getErrorCodeLabel(errorCode, portal);
        if (errorLabel) {
            const translation = this.i18n.translate(errorLabel, params);
            if (translation !== errorLabel) { errorMessage = translation; }
        }
        return errorMessage;
    }

    private getErrorText(data: any): string {
        if (!data) return 'Unknow error - Something goes really wrong';
        let message = '';
        if (data.errorDetails) {
            if (data.errorDetails instanceof Array) { data.errorDetails.forEach((details: any) => { message += details.msg; }); }
            else {
                if (data.errorDetails.msg) { message += JSON.stringify(data.errorDetails.msg); }
                else if (data.errorDetails.details) { message += data.errorDetails.details; }
                else { message += (typeof data.errorDetails === "string" ? data.errorDetails : JSON.stringify(data.errorDetails)); }
            }
        } else if (data.errorMsg) {
            message += data.errorMsg;
        }
        return message;
    }

    private getTextWithoutIds(message: string): string {
        return message?.replace(new RegExp("\\s[\\d]{1}[a-f\\d]{23}", "g"), "");
    }

    private getFeature(data: any): string | undefined {
        if (data?.errorDetails && !(data.errorDetails instanceof Array) && data.errorDetails.feature) {
            return String(data.errorDetails.feature);
        }
        return undefined;
    }


    private getStatusText(status: any, response: Response): string {
        switch (status) {
            case -1: return "Service unavailable"; //TODO not translated !!
            case 400: return "badRequest";
            case 401: return "authorizationFailure";
            case 403: return "accessForbidden";
            case 404: return "resourceNotFound";
            case 413: return "requestEntityTooLarge";
            case 415: return "unsupportedMediaType";
            case 429: return "Too many requests"; //TODO not translated !!
            case 500: return "internalServerError";
            case 403503: return "NotAllowedSelfRegistrationEmail";
            default: return response.statusText ? response.statusText : "unknownError";
        }
    }

    private getBadRequestFieldErrors(data: any, response: Response): any {
        const fieldErrors: any = {};
        const errorDetails = data ? data.errorDetails : null;
        const errorDetailsCode = data ? data.errorDetailsCode : null;
        const errorDetailsData = data ? data.errorDetailsData : null;

        if (response.status === 400) { // Bad request
            if (errorDetails) {
                if (errorDetails instanceof Array) {
                    errorDetails.forEach((details: any) => {
                        if (!fieldErrors[details.param]) { // do not override if already exists
                            fieldErrors[details.param] = { ok: false, message: details.msg, value: details.value };
                        }
                    });
                }
                else if (errorDetails.param) {
                    if (!fieldErrors[errorDetails.param]) { // do not override if already exists
                        fieldErrors[errorDetails.param] = { ok: false, message: errorDetails.msg, value: errorDetails.value };
                    }
                }
            }
            if (errorDetailsCode === 400511) {
                fieldErrors.office365Tenant = { ok: false, message: ErrorHelperService.ERROR_CODE_LABELS["400511"] };
            }
            if (errorDetailsCode === 400601) {
                fieldErrors.outgoingPrefix = { ok: false, message: ErrorHelperService.ERROR_CODE_LABELS["400601"] };
                fieldErrors.numberingPrefix = { ok: false, message: ErrorHelperService.ERROR_CODE_LABELS["400601"] };
            }
        } else if (response.status === 409) { // Conflict
            if (errorDetailsCode === 409000 && errorDetailsData) {
                if (errorDetailsData.loginEmail) {
                    fieldErrors.loginEmail = { ok: false, label: "userAlreadyExist" }; // prefer "label" instead of "message" field
                }
                if (errorDetailsData.authenticationExternalUid) {
                    fieldErrors.authenticationExternalUid = { ok: false, label: "userIdAlreadyUsed" }; // prefer "label" instead of "message" field
                }
            }
        }
        return fieldErrors;
    }

    private getErrorCodeLabel(errorCode: string, portal: string): string {
        if (portal && ErrorHelperService.PORTAL_ERROR_CODE_LABELS[portal] && ErrorHelperService.PORTAL_ERROR_CODE_LABELS[portal][errorCode]) {
            const toto = ErrorHelperService.PORTAL_ERROR_CODE_LABELS[portal][errorCode];
            return toto;
        }
        return ErrorHelperService.ERROR_CODE_LABELS[errorCode];
    }
