    /**
     * Get contact by dbId; If not found, user will be searched on server
     * @param dbId - the dbId of the contact to be found
     * @param force - [optional] if TRUE, this will force an update of the contact from the server
     * @returns Returns contact if found
     */
    public async getContactByDBId(dbId: string, force: boolean = false): Promise<Contact> {
        // Check if the contact already exists
        const existingContact = this.dbContacts[dbId];
        if (!force && existingContact) { return existingContact; }

        // Check if a request for this contact is already lauched
        if (!this.getContactPromises[dbId]) {
            this.getContactPromises[dbId] = new Promise((resolve, reject) => {
                this.getContactByDbIdInner(dbId)
                    .then((contact) => {
                        resolve(contact);
                        delete this.getContactPromises[dbId];
                    })
                    .catch((error) => {
                        reject(error);
                        delete this.getContactPromises[dbId];
                    });
            });

        }
        return this.getContactPromises[dbId];
    }

    /**
     * Get contact by jid or by his phone number; If not found, contact will created and updated from server if possible
     * @param jid - the jid of the contact to be found
     * @param phoneNumber - if user has no jid, it could be found by his phone number
     * @returns Returns contact if found
     */
    public getOrCreateContact(jid: string, phoneNumber: string = null): Promise<Contact> {

        // Try to find an existing contact (Bot contacts should be found here as they do not have a valid JID)
        if (!jid && !phoneNumber) { return Promise.reject(new Error('No jid or no phoneNumber')); }
        const existingContact = jid ? this.getContactFromCacheByJid(jid) : this.getContactFromCacheByPhoneNumber(phoneNumber);
        if (existingContact) { return Promise.resolve(existingContact); }

        // Otherwise compute contactId
        if (jid && jid.indexOf("@") === -1) { return Promise.reject(new Error("Invalid jid " + jid)); }
        const contactId = jid ? jid : phoneNumber;

        // If phoneNumber only contact
        if (!jid) { return Promise.resolve(this.createBasicContact(null, phoneNumber)); }

        // Create promise if not pending
        if (!this.getContactPromises[contactId]) {
            this.getContactPromises[contactId] = new Promise((resolve, reject) => {

                // Create and store contact in contact hashmaps
                const contact = this.createBasicContact(jid, phoneNumber, false);

                this.updateContactFromServer(contact)
                    .then(() => {
                        this.contacts[contact.id] = contact;
                        this.dbContacts[contact.dbId] = contact;
                        this.jtelContacts[contact.jidtel] = contact;
                        delete this.getContactPromises[contactId];

                        resolve(contact);
                    })
                    .catch((error) => {
                        this.logger.error("[contactService] getOrCreateContact -- failure -- " + error.message);
                        delete this.getContactPromises[contactId];
                        reject(error);
                    });
            });
        }
        return this.getContactPromises[contactId];
    }

