    /**
     * @public
     * @async
     * @description Update the user's profile data (name, emails, numbers, etc)
     * @param userProfile the userData to be send to the server for update
     * @param checkProfile when true check if userModification is allowed for this user
     * @returns Returns the updated user if success and an update on the contact RX is received (or undefined, if the user is not allowed to update his profile)
     */
    public async updateUserProfile(userProfile: ConnectedUserProfile, checkProfile: boolean = false): Promise<User> {
        try {
            let responseData = null;
            // Copy input user profile to suit server requirements (data name)
            const userServerProfile: any = JSON.parse(JSON.stringify(userProfile));

            if (checkProfile && this.userContact && !this.userContact.modifyProfileEnabled) {
                this.logger.warn("[contactService] updateUserContactProfileData is not allowed for this contact");
                return undefined;
            }

            // Translation of property names between server and contact/user model
            if (userProfile.hasOwnProperty('initialized')) {
                userServerProfile.isInitialized = userProfile.initialized;
                // Virer initialized
            }
            if (userProfile.hasOwnProperty('guest')) {
                userServerProfile.guestMode = userProfile.guest;
                // Virer initialguestized
            }

            this.logger.info("[contactService] updateUserContact");
            const url = `${config.restServerUrl}/api/rainbow/enduser/v1.0/users/${this.authService.userId}`;
            const headers = this.authService.getPostHeader();
            const response: Response = await fetch(url, { method: 'PUT', headers, body: JSON.stringify(userServerProfile) });
            if (!response.ok) throw (response);
            responseData = (await response.json()).data;
            this.userContact.updateFromUserData(responseData);
            this.authService.loggedInUser = responseData;
            this.logger.info("[contactService] updateUserContact successfully");
            return this.userContact;
        }
        catch (error) {
            const errorInfo = await this.errorHelperService.getErrorInfo(error, 'updateUserContact');
            this.logger.error(errorInfo.message);
            throw errorInfo.error;
        }
    }

