    /**
     * @public
     * @returns The capabilities representing the medias that could be used for a WebRTC Call with the specified remote Rainbow user
     */
    public getConnectedUserWebRTCCallCapabilities(remoteParty: User): WebCallCapabilities {
        let canMakeAudio: boolean = false;
        let canMakeVideo: boolean = false;
        let canMakeSharing: boolean = false;

        // First, check conditions applicable to all types of media
        if (!(remoteParty !== this.userContact && // Called user is not the Connected user
            (remoteParty as Contact)?.capabilities?.webRTC && !(remoteParty as Contact)?.capabilities.addMedia && // Criteria on called user capabilities
            this.userContact?.capabilities?.webRTC)) // Criteria on Connected user capabilities
        {
            return { audio: false, video: false, sharing: false };
        }

        // Second, check webRTC media capability
        // Check audio capability (On both connected + remote users)
        canMakeAudio = this?.userContact.webrtcAudioEnabled && (remoteParty as Contact)?.webrtcAudioEnabled;

        // Check video capability (On both connected + remote users)
        canMakeVideo = this?.userContact.webrtcVideoEnabled && (remoteParty as Contact)?.webrtcVideoEnabled;

        // Check browser validity (connected user only)
        canMakeSharing = this?.userContact?.webrtcSharingEnabled && (window.adapter?.browserDetails.browser !== 'safari');

        return {
            audio: canMakeAudio,
            video: canMakeVideo,
            sharing: canMakeSharing,
        };
    }

    public createWebRTCCapabilitiesObservable(remoteParty: User): Observable<WebCallCapabilities> {
        return new Observable<WebCallCapabilities>((observer) => {
            // Sending new WebRTC call capabilities between the connected user and the specified user
            let remotePartySubscription: Subscription;
            let connectedUserSubscription: Subscription;

            try {
                const emitWebRTCCallCapabilities = () => {
                    const callCapabilities: WebCallCapabilities = this.getConnectedUserWebRTCCallCapabilities(remoteParty);
                    observer.next(callCapabilities);
                };

                // this.logger.debug(`[contactService] createWebRTCCapabilitiesObservable -- Return the 1st Web Call Capabilities values !`);
                emitWebRTCCallCapabilities();

                // Subscription on connected user instance
                connectedUserSubscription = this.userContact.rxSubject.subscribe((event) => {
                    try {
                        this.logger.debug(`[contactService] connectedUserSubscription -- event = ${event?.name}`);
                        emitWebRTCCallCapabilities();
                    }
                    catch (error) {
                        observer.error(error);
                    }
                });

                // Subscription on remote party user instance
                remotePartySubscription = (remoteParty as Contact)?.rxSubject.subscribe((event) => {
                    try {
                        this.logger.debug(`[contactService] remotePartySubscription -- event = ${event?.name}`);
                        emitWebRTCCallCapabilities();
                    }
                    catch (error) {
                        observer.error(error);
                    }
                });
                // throw new Error('[contactService]  Error simulation code to stop it all !');
            }
            catch (error) {
                observer.error(error);
            }

            // Cleaning
            return () => {
                this.logger.error(`[contactService] createWebRTCCapabilitiesObservable -- Clean all subscriptions !`);
                connectedUserSubscription.unsubscribe();
                remotePartySubscription.unsubscribe();
            };
        });
    }

