    /**
     * @public
     * @function getConnecteUserAvailablePresenceStatusList
     * @description
     *    Return a list of status that the user can currently Set (via changeMyPresence API); Values are ["online", "away", "xa", "dnd"]
     *    Online -> user goes to online (or can "exit") any manual state; In case of a call in progress, the user will go to busy state;
     *    Away -> a manual Away state
     *    xa -> "invisble" or "appear offline" manual state
     *    dnd -> Do not disturb manual state
     * @returns {string[]} Returns an array of all available values to be used if the user wants to change his presence
     */
    public getConnectedUserAvailablePresenceStatusList(): string[] {
        let list = [];
        if (this.userContact?.status) {
            this.logger.info("[contactService] getConnecteUserAvailablePresenceStatusList " + this.userContact.status + " " + this.userContact.message);
            if (!this.userContact.changePresenceEnabled) { list = []; }
            else if (this.userContact.status === "offline") { list = ["online"]; }
            // else if (this.userContact.status === "dnd" && this.userContact.message === "presentation") { list = ["dnd"]; }
            else if (this.userContact.canSetInvisiblePresenceCustomisation) { list = ["online", "away", "xa", "dnd"]; }
            else { list = ["online", "away", "dnd"]; }
        }
        return list;
    }

    /**
     * @public
     * @function setConnectUserPresence
     * @description
     *    Change the current user presence status (if allowed); The status list can be get at all time via computeStatusList
     * @param status the presence status that the user wants to set to his user. The status list can be get via computeStatusList API
     */
    public setConnectedUserPresence(presenceStatus: UserPresenceStatus | string): void {
        this.logger.info("[contactService] changeMyPresence " + presenceStatus + " " + this.userContact.message);
        let status: string = presenceStatus;
        if ((status === "dnd" && this.userContact.message === "presentation") || status === "busy") { return; }

        let message = "";
        if (status === "online") { message = "mode=auto"; }

        // If manual away
        if (status === "away") { status = "xa"; message = "away"; }

        // If user is in DND presentation mode, disable the presentation mode
        if (this.presentationModeActive) { this.presentationModeActive = false; }

        if (this.userContact.status === "busy" && (this.userContact.message === "phone" || this.userContact.message === "audioPhone") && (status === "xa" || status === "dnd" || status === "away")) {
            this.eventService.publish('GLOBAL_NOTIFY_MESSAGE_EVENT', "presenceActivatedConfirmation", true);
        }

        this.setUserContactStatus(status, message);

        if (status === "online") {
            setTimeout(() => { this.manualState = false; this.dndStateActivated = false; this.updatePresence(); }, 1000);
        }

        let presence = "online";
        if (status === "xa" && message === "away") { presence = "away"; }
        else if (status === "dnd") { presence = "dnd"; }
        else if (status === "xa") { presence = "invisible"; }
        this.setUserSettings({ "presence": presence });
    }

