    public searchContacts(criteria: string) {
        const contacts = this.getContacts();
        return contacts.filter((contact) => {
            return ((contact.roster || contact.isBot) && !contact.isTerminated && this.contactMatcher(contact, criteria));
        });
    }

    /**
     * @public
     * @description
     * Search users in the Rainbow users network (ie 'My Network') of the connected user by using a specified pattern to filter items.
     * @param {string} searchPattern Pattern to search
     * @param {DirectorySearchOptions} [options] Search options {@link DirectorySearchOptions}
     * @returns {Promise<DirectoryInternalSearchResults[]>} Resolves with an array of contacts and the total number of users matching the criteria.
     * {@link DirectoryInternalSearchResults}
     */
    public searchRainbowUsersNetwork(searchPattern: string, options?: DirectorySearchOptions): DirectoryInternalSearchResults {
        let contacts: Contact[] = this.getContacts();
        contacts = contacts.filter((contact) => {
            return ((contact.roster || contact.isBot) && !contact.isTerminated && this.contactMatcher(contact, searchPattern));
        });
        const nbFoundContacts: number = contacts.length;

        if (options?.limit) {
            contacts = contacts.slice(0, options?.limit);
        }

        return { contacts: contacts, total: nbFoundContacts };
    }

    public contactMatcher(contact: Contact, criteria: string) {
        const displayname = contact.firstname + " " + contact.lastname;
        const queries = criteria.toLowerCase().trim().normalize("NFD").replace(/[\u0300-\u036f]/g, "").split(/[ ]+/);
        const names = displayname.toLowerCase().trim().normalize("NFD").replace(/[\u0300-\u036f]/g, "").split(/[ ]+/);
        return queries.every((query) => {
            return names.some((name, index) => {
                if (name.length && name.indexOf(query) === 0) { names[index] = ""; return true; }
                return false;
            });
        });
    }

    public async getContactsByEmails(emails: string[]): Promise<any> {
        try {
            this.logger.info("[ContactService] getContactsByEmails with [" + emails.join() + "]");
            const url = `${config.restServerUrl}/api/rainbow/enduser/v1.0/users/loginemails`;
            const loginEmail = emails.map((email: string) => { return email.toLowerCase(); });
            const response: Response = await fetch(url, { method: 'POST', headers: this.authService.getPostHeader(), body: JSON.stringify({ loginEmail }) });
            if (!response.ok) { throw (response); }
            const responseData = await response.json();
            const contacts = {};
            const contactsArray = responseData.data.map((userData: any) => {
                let contact = this.dbContacts[userData.id];
                if (!contact) {
                    contact = this.createContact();
                    this.contacts[contact.id] = contact;
                    this.dbContacts[contact.dbId] = contact;
                    this.jtelContacts[contact.jidtel] = contact;
                }
                contact.updateFromUserData(userData);
                contact.createAvatar();
                contacts[contact.loginEmail] = contact;
                loginEmail.splice(loginEmail.indexOf(contact.loginEmail.toLowerCase()), 1);
                return contact;
            });
            return { contacts: contacts, contactsArray: contactsArray, emails: loginEmail };
        }
        catch (error) {
            const errorInfo = await this.errorHelperService.getErrorInfo(error, 'getContactsByEmails');
            this.logger.error(errorInfo.message);
            throw errorInfo.error;
        }
    }

