    public createBasicContact(jid: string, phoneNumber: string = null, append: boolean = true) {
        this.logger.debug(`[ContactService] CreateContact ${jid} ${anonymizer(phoneNumber)}`);

        // Create the contact object
        const contact = this.createContact();

        // Handle case where we have no jid
        if (!jid) {
            contact.id = phoneNumber;
            contact.initials = "?";
            contact.displayName = phoneNumber ? phoneNumber : (this.i18nService.isInitialized ? this.i18nService.translate("accountDeleted") : "Unknown contact");
            contact.lastname = phoneNumber ? phoneNumber : (this.i18nService.isInitialized ? this.i18nService.translate("accountDeleted") : "Unknown contact");
            contact.firstname = "";
            contact.phoneProCan = phoneNumber ? phoneNumber : "";
            contact.phonePro = contact.phoneProCan;
            contact.temp = true;
            if (config.sdk) {
                contact.avatar = { src: "" };
            } else {
                contact.avatar = { src: "/assets/skins/rainbow/images/conversations/unknownUser.jpeg" };
            }
            contact.nameUpdatePrio = Contact.NameUpdatePrio.NO_UPDATE_PRIO;//not yet updated
            return contact;
        }

        // Compute the contact id
        let contactId = jid;
        if (!contactId) { contactId = phoneNumber; contact.phoneProCan = phoneNumber; }
        if (!contactId) { contactId = "anonymous"; }

        // Configure contact
        contact.jid = jid;
        contact.id = contactId;
        contact.ask = "none";
        contact.subscription = "none";
        this.updateContactRichStatus(contact);

        // Append in contact list
        if (append) { this.contacts[contact.id] = contact; }

        return contact;
    }

