    public createContactFromData(userData: any): Contact {
        // Try to find an existing contact
        if (!userData) { return null; }

        const existingContact = this.getContactFromCacheByJid(userData.jid_im);
        if (existingContact) {
            // Add (if necessary) routines properties
            // Routines
            if (!existingContact.personalRoutines && userData.personalRoutines) {
                existingContact.personalRoutines = userData.personalRoutines.map((userDataRoutine: any) => {
                    return PersonalRoutine.createRoutineFromData(userDataRoutine);
                });
            }

            // Add (if necessary) outOfOffice properties
            if (!existingContact.outOfOffice && userData.outOfOffice) {
                existingContact.outOfOffice = userData.outOfOffice;
            }

            // Add (if necessary) forward properties
            // Forwards (Voice Hub system)
            if (!existingContact.forwards && userData.forwards) {
                existingContact.forwards = userData.forwards.map((userDataForward: any) => {
                    return TelephonyForward.createForwardFromVoiceUserData(userDataForward);
                });
            }
            // Forward (Hybrid system)
            if (!existingContact.forwards && userData.forward) {
                existingContact.forwards = [TelephonyForward.createForwardFromHybridData(userData.forward)];
            }
            return existingContact;
        }

        // Create and store contact in contact hashmaps
        const contact = this.createBasicContact(userData.jid_im, undefined, false);

        contact.updateFromUserData(userData);
        this.updateContactRichStatus(contact, this.isUserContactJid(contact.jid));
        contact.createAvatar();
        this.sendContactUpdateEvent(contact, "create");

        this.contacts[contact.id] = contact;
        this.dbContacts[contact.dbId] = contact;
        this.jtelContacts[contact.jidtel] = contact;

        return contact;
    }

    public updateContactPersonalRoutines(contactJidIm: string, personalRoutineData: any): void {
        if (!contactJidIm) return;

        const existingContact = this.getContactFromCacheByJid(contactJidIm);
        if (existingContact) {
            existingContact.personalRoutines = personalRoutineData.map((userDataRoutine: any) => {
                return PersonalRoutine.createRoutineFromData(userDataRoutine);
            });
        }
        return;
    }

