    private async getNetwork() {
        try {
            const url = `${config.restServerUrl}/api/rainbow/enduser/v1.0/users/networks?limit=2000&format=full`;
            const headers = this.authService.getRequestHeader();
            const response: Response = await fetch(url, { method: 'GET', headers });
            if (!response.ok) throw (response);
            const responseData = await response.json();
            this.logger.info(`[ContactService] GetNetwork success -- find ${responseData.data.length} contact(s)`);
            responseData.data.forEach((contactData: any) => {
                const contact: Contact = this.createContact();
                contact.updateFromUserData(contactData);
                if (contactData.showPresence) {
                    contact.subscription = "both";
                }
                contact.status = "offline";
                contact.roster = true;
                this.contacts[contact.id] = contact;
                this.dbContacts[contact.dbId] = contact;
                this.jtelContacts[contact.jidtel] = contact;
                contact.createAvatar();
            });
        }
        catch (error) {
            const errorInfo = await this.errorHelperService.getErrorInfo(error, 'getNetwork');
            this.logger.error(errorInfo.message);
            throw errorInfo.error;
        }
    }

