    /**
     *  Subscribe to updates from the service (all events are of RBEvent type {name: string, data:any});
     *  NB There might be some events that are not documented here, they're send on updates of different properties of the rooms.
     * @param handler - The call-back function that will be subscribed to the RxJS subject
     * @param eventNames - array of event to listen
     */
    public subscribe(handler: (event: RBEvent<BubbleServiceEvents>) => any, eventNames?: BubbleServiceEvents | BubbleServiceEvents[]): Subscription {
        const observable = eventNames ? this.rxSubject.pipe(filter((event: RBEvent<BubbleServiceEvents>) => {
            if (eventNames instanceof Array) return eventNames.indexOf(event.name) !== -1;
            return event.name === eventNames;
        })) : this.rxSubject;

        return observable.subscribe((event: RBEvent<BubbleServiceEvents>) => {
            try { handler(event); }
            catch (error) { this.logger.error(`[ContactService] subscribe () -- error -- ${error.message}`); }
        });
    }

    /**
     * Bubble service events send to other services via sendEvent()
     * Can listen to it via bubbleService.subscribe() API
     * @param name - the name of the event
     * @param data - the data to be send (an object
     */
    public sendEvent(name: BubbleServiceEvents, data: any = null) {
        this.rxSubject.next(RBEvent.create<BubbleServiceEvents, any>(name, data));
    }

    public subscribeToInnerEvents(handler: (event: RBEvent<BubbleServiceInnerEvents>) => any): Subscription {
        return this.innerRxSubject.subscribe(handler);
    }

    public sendInnerEvent(name: BubbleServiceInnerEvents, data: any = null) {
        this.innerRxSubject.next(RBEvent.create<BubbleServiceInnerEvents, any>(name, data));
    }


