    /**
     * Load all room from server in a given status
     * @param status - (values: 'invited', 'accepted','unsubscribed')
     */
    public async getAllServerBubbles(status: string = 'accepted'): Promise<void> {
        if (!this.preload[status]) {
            const startDate = performance.now();
            const limit = this.maxBubblesStartupLoad ? this.maxBubblesStartupLoad : 1000;
            this.logger.info(`[bubbleService] getAllServerBubbles - ${status} - ${limit} - init`);
            let offset = 0;
            const bubblesDataPage = await this.getServerBubblesDataPage(status, offset, limit);
            offset += limit;
            while (offset < bubblesDataPage.total) {
                await this.getServerBubblesDataPage(status, offset, limit);
                offset += limit;
            }
            const endDate = performance.now();
            this.logger.info(`[bubbleService] getAllServerBubbles - ${status} - done - ${Math.round(endDate - startDate)} ms`);
        }
        this.preload[status] = true;
    }

