    /**
     * This API allows the user to "mark as read" an access request and/or remove it from the list
     * @param requestId - the request ID
     * @param ackRead - if the request should be marked as READ, (allows the user to manage a notification center related to updates on his pending request) An access request with the status pending, accepted or rejected can be acknowledged. These acknowledgment can't be undo
     * @param removeFromList - remove the access request from the list. Only an access request with the status accepted or rejected can be removed
     */
    public async updateUserRequestToJoinBubble(requestId: string, ackRead: boolean = false, removeFromList: boolean = false) {
        try {
            // Get rooms data
            if (!requestId || !this.connectedUserPendingRequests[requestId]) { throw new Error("[bubbleService] updateUserRequestToJoinBubble -- request not found"); }

            const data = {
                ack: ackRead,
                hide: removeFromList
            };

            this.logger.info(`[bubbleService] updateUserRequestToJoinBubble - for bubble ${requestId} ackRead ${ackRead} and remove from list ${removeFromList}`);
            const url = `${this.portalURL}rooms/${requestId}/lobbies/users`;
            const headers = this.authService.getPostHeader();
            const body = JSON.stringify(data);
            const response = await fetch(url, { method: 'PUT', headers, body });
            if (!response.ok) { throw (response); }

            if (ackRead && this.connectedUserPendingRequests[requestId]) {
                this.connectedUserPendingRequests[requestId].ackRead = true;
            }

            if (removeFromList) {
                delete this.connectedUserPendingRequests[requestId];
            }

            this.logger.info(`[bubbleService] updateUserRequestToJoinBubble - for bubble ${requestId} -- success`);
        }
        catch (error) {
            const errorInfo = await this.errorHelperService.getErrorInfo(error, `updateUserRequestToJoinBubble`);
            this.logger.error(`[bubbleService] ${errorInfo.message}`);
            throw errorInfo.error;
        }
    }

