    public getRoomsByContainerId(containerId: string): Bubble[] { return this.getBubblesFromCache().filter((room: BubbleRB) => { return room.containerId === containerId; }); }

    /***
    * GET ALL ROOMS ORDER BY DATE OR NAME
    * DEFAULT ORDER IS BY NAME
    */
    public getOrderedRooms(order?: string): Bubble[] {
        const bubbles = this.getBubblesFromCache();
        switch (order) {
            case 'lastActivityDate':
                return bubbles.sort((bubbleA: BubbleRB, bubbleB: BubbleRB) => { return bubbleB.lastActivityDate.getTime() - bubbleA.lastActivityDate.getTime(); });
            case 'creationDate':
                return bubbles.sort((bubbleA: BubbleRB, bubbleB: BubbleRB) => { return bubbleB.creationDate.getTime() - bubbleA.creationDate.getTime(); });
            default:
                return bubbles.sort((bubbleA: BubbleRB, bubbleB: BubbleRB) => { return bubbleA.name.localeCompare(bubbleB.name); });
        }
    }

    /***
    * GET MY ROOMS ORDER BY DATE OR NAME
    * DEFAULT ORDER IS BY NAME
    */
    public getMyOrderedRooms(order: string): Bubble[] {
        const bubbles = this.getMyBubbles();
        switch (order) {
            case 'lastActivityDate':
                return bubbles.sort((bubbleA: BubbleRB, bubbleB: BubbleRB) => { return bubbleB.lastActivityDate.getTime() - bubbleA.lastActivityDate.getTime(); });
            case 'creationDate':
                return bubbles.sort((bubbleA: BubbleRB, bubbleB: BubbleRB) => { return bubbleB.creationDate.getTime() - bubbleA.creationDate.getTime(); });
            default:
                return bubbles.sort((bubbleA: BubbleRB, bubbleB: BubbleRB) => { return bubbleA.name.localeCompare(bubbleB.name); });
        }
    }

