    /*
    * API used to update the room from the server but do not send any presences or events; Only update of the room via RX
    */
    public async updateRoomFromServer(bubble: Bubble): Promise<void> {
        this.logger.info(`[bubbleService] updateRoomFromServer (room: ${bubble.dbId})`);
        try {
            let url = `${this.portalURL}rooms/${bubble.dbId}?format=full&unsubscribed=true`;
            if (this.context === 'webinar') url += '&context=webinar';
            const response = await fetch(url, { headers: this.authService.getRequestHeader() });
            const bubbleData = (await response.json()).data;
            await this.getAllBubblesParticipants([bubbleData]);
            this.updateRoomData(bubble as BubbleRB, bubbleData);
            bubble.sendEvent(BubbleEvents.ON_DATA_UPDATED);
        }
        catch (error) {
            this.logger.error(`[bubbleService] updateRoomFromServer (room: ${bubble.dbId}) -- FAILURE -- ${error.message}`);
        }
    }

    private updateRoomData(bubble: BubbleRB, newRoomData: any): void {
        let sendRoomStatusEvent = false;
        // Update name and description
        bubble.name = newRoomData.name;
        bubble.description = newRoomData.topic; // Warning: topic = field name provided by Server

        // Update conference property data
        bubble.conference = newRoomData.conference; // BIG HACK for RQRAINB-5201

        // Get the previous status of the connected user
        const oldConnectedUserStatus: BubbleUserStatus = bubble.bubbleConnectedUser?.status;

        // Update room participants
        bubble.users = [];
        newRoomData.users.forEach((userData: any) => {
            const contact = this.contactService.getContactFromCacheById(userData.userId);
            if (contact) {
                const newUserBubble: BubbleUser = { user: contact, status: userData.status, date: new Date(userData.additionDate), role: userData.privilege };
                bubble.users.push(newUserBubble);
                // If The current bubble user is the connected user, mandatory to update bubbleConnectedUser !
                if (this.contactService.isUserContact(contact)) {
                    bubble.bubbleConnectedUser = newUserBubble;
                    if (oldConnectedUserStatus !== newUserBubble.status) {
                        sendRoomStatusEvent = true;
                    }
                }
            }
        });
        this.refreshMemberAndOrganizerLists(bubble);

        // Update room avatar
        if (newRoomData.lastAvatarUpdateDate && (newRoomData.lastAvatarUpdateDate !== bubble.lastAvatarUpdate)) {
            bubble.lastAvatarUpdate = newRoomData.lastAvatarUpdateDate;
            const updateToken = MainService.MD5(bubble.lastAvatarUpdate);
            bubble.avatar = `${config.restServerUrl}/api/room-avatar/${bubble.dbId}?size=512&update=${updateToken}`;
        }
        else if (!newRoomData.lastAvatarUpdateDate && bubble.lastAvatarUpdate && bubble.avatar) {
            bubble.lastAvatarUpdate = newRoomData.lastAvatarUpdateDate;
            bubble.avatar = null;
        }
        bubble.updateAvatarInfo();

        // Update room guests
        bubble.guestEmails = newRoomData.guestEmails;
        bubble.guestPhoneNumbers = (newRoomData.conference?.guestPhoneNumbers) ? newRoomData.conference.guestPhoneNumbers : [];

        if (newRoomData["allParticipants"] && !bubble.usersReady.value) {
            bubble.usersReady.next(true);
        }

        //send event if the status in the bubble has changed
        if (sendRoomStatusEvent) {
            const actionEvent: BubbleServiceEvents = this.getEventFromBubbleStatus(bubble.bubbleConnectedUser.status);
            this.sendEvent(actionEvent, { bubble: bubble, bubbleUser: bubble.bubbleConnectedUser });
        }
    }

    public async getServerBubble(roomId: string): Promise<BubbleRB> {
        try {
            this.logger.info(`[bubbleService] getServerBubble(${roomId})`);
            let url = `${this.portalURL}rooms/${roomId}?format=full&unsubscribed=true`;
            if (this.context === 'webinar') url += `&context=webinar`;
            const headers = this.authService.getRequestHeader();
            const response = await fetch(url, { method: 'GET', headers });
            if (!response.ok) { throw (response); }
            const roomData = (await response.json()).data;
            this.logger.info(`[bubbleService] getServerBubble(${roomId}) -- SUCCESS`);
            const roomsData = await this.getAllBubblesParticipants([roomData]);
            return this.createOrUpdateBubbleFromData(roomsData[0]);
        }
        catch (error) {
            const errorInfo = await this.errorHelperService.getErrorInfo(error, 'getServerBubble');
            this.logger.error(`[bubbleService] ${errorInfo.message}`);
            throw errorInfo.error;
        }
    }

    /**
     * Get room data from server then create and store the Room instance
     * @param bubbleJid - the jid of the room to get
     * @param sendPresence - (default : true) When set to false the initial presence is not sent
     * @param nbUsersToKeep - number of user to keep in room data
     */
    private getServerBubbleByJid(bubbleJid: string, sendPresence?: boolean, nbUsersToKeep?: number): Promise<BubbleRB> {
        if (!this.getBubbleByJidPromises[bubbleJid]) {
            this.getBubbleByJidPromises[bubbleJid] = (async (): Promise<BubbleRB> => {
                try {
                    let url = `${this.portalURL}rooms/jids/${bubbleJid}?format=full&webinar=true&${nbUsersToKeep ? 'nbUsersToKeep=' + nbUsersToKeep : ''}`;
                    if (this.context === 'webinar') { url += '&context=webinar'; }
                    const headers = this.authService.getRequestHeader();
                    const response = await fetch(url, { method: 'GET', headers });
                    if (!response.ok) { throw (response); }
                    const roomData = (await response.json()).data;
                    await this.getMinimalBubbleUsers([roomData]);
                    this.logger.info(`[bubbleService] getServerBubbleByJid(${bubbleJid}) -- SUCCESS`);
                    delete this.getBubbleByJidPromises[bubbleJid];
                    const doNotSendPresence = sendPresence !== undefined && !sendPresence;
                    const bubble = this.createOrUpdateBubbleFromData(roomData, doNotSendPresence, true);
                    return bubble;
                }
                catch (error) {
                    const errorInfo = await this.errorHelperService.getErrorInfo(error, 'getServerBubbleByJid');
                    this.logger.error(`[bubbleService] ${errorInfo.message}`);
                    delete this.getBubbleByJidPromises[bubbleJid];
                    throw errorInfo.error;
                }
            })();
        }
        return this.getBubbleByJidPromises[bubbleJid];
    }

    public async getServerBubblesByIds(bubbleIds: string[], sendPresence?: boolean, webinars?: boolean): Promise<void> {
        try {
            if (bubbleIds.length === 0) return;
            let url = `${this.portalURL}rooms/ids?format=full&userId=${this.userContact.dbId}&needIsAlertNotificationEnabled=false&nbUsersToKeep=4`;
            if (webinars) url += '&webinar=true';
            const headers = this.authService.getPostHeader();
            const response = await fetch(url, { method: 'POST', headers, body: JSON.stringify({ roomIds: bubbleIds }) });
            if (!response.ok) { throw (response); }
            const bubblesData = (await response.json()).data;
            await this.getMinimalBubbleUsers(bubblesData);
            this.logger.info(`[bubbleService] getServerBubblesByIds -- SUCCESS`);
            const doNotSendPresence = sendPresence !== undefined && !sendPresence;
            bubblesData.forEach((bubbleData: any) => {
                try { this.createOrUpdateBubbleFromData(bubbleData, doNotSendPresence, true); }
                catch { this.logger.error(`[bubbleService] getServerBubblesByIds -- create bubble ${bubbleData.id} failure`); }
            });
        }
        catch (error) {
            const errorInfo = await this.errorHelperService.getErrorInfo(error, 'getServerBubblesByIds');
            this.logger.error(`[bubbleService] ${errorInfo.message}`);
            throw errorInfo.error;
        }
    }


