    /**
     * Create a new bubble.
     * This API also sends BubbleServiceEvents.ON_BUBBLE_CREATED event.
     * @param bubbleName - The name of the bubble
     * @param createBubbleData - Bubble properties that can be specified when it is created.
     */
    public async createBubble(bubbleName: string = "", createBubbleData: BubbleCreationData = {}): Promise<BubbleRB> {
        try {
            this.createBubbleInProgress = this.createBubbleInternal(bubbleName, createBubbleData);
            const bubble = await this.createBubbleInProgress;
            this.createBubbleInProgress = null;
            let hasError = false;
            let invalidUsersIds = [];
            if (createBubbleData.contacts?.length || createBubbleData.guestEmails?.length) {
                try {
                    invalidUsersIds = await this.addUsersToBubble(bubble, createBubbleData.contacts, createBubbleData.guestEmails, createBubbleData.role);
                    hasError = Boolean(invalidUsersIds?.length);
                }
                catch {
                    hasError = true;
                    this.logger.error(`[bubbleService] createBubble -- could not add users inside`);
                }
            }

            // Send event that bubble has been created (with some errors or not)
            this.sendEvent(BubbleServiceEvents.ON_BUBBLE_CREATED, { bubble, invitedUsersError: hasError, invalidUsersIds });
            return bubble;
        }
        catch (error) {
            this.createBubbleInProgress = null;
            throw error;
        }
    }

