    /**
    * Add user to the bubble; Can be used to directly add user without invitation or as a organizer
    * @param bubble - the bubble
    * @param user - the user to add
    * @param reason - [optional] the reason to add
    * @param role - the role to be set ('user' or 'organizer'), by default is 'user'
    * @param  withoutInvitation - if TRUE, the user will be added without invitation before
    */
    public async addUserToBubble(bubble: Bubble, user: User, reason: string = null, role: BubbleUserRole = null, withoutInvitation: boolean = false): Promise<Bubble> {
        try {
            if (!bubble) { throw new Error("[bubbleService] addUserToBubble -- bubble not found"); }
            const userContact = user as Contact;

            const isUserInvitedOrAccepted = (bubble as BubbleRB).users.some((bubbleUser) => {
                return ((bubbleUser.status === BubbleUserStatus.INVITED ||
                    bubbleUser.status === BubbleUserStatus.ACCEPTED) &&
                    bubbleUser.user.dbId === userContact.dbId);
            });

            if (isUserInvitedOrAccepted) {
                this.logger.debug(`[bubbleService] user: ${userContact.dbId} already invited or accepted, will not be added`);
                return bubble;
            }

            const bubbleUsersCurrentNb = (bubble as BubbleRB).users.filter((user) => { return user.status !== BubbleUserStatus.DELETED; }).length;

            // Reject not allowed operations
            if (bubbleUsersCurrentNb >= this.maxBubblesUsers) {
                const profileError: any = new Error("addRoomUser failure - Not Allowed : Participants max limit has been reached: " + this.maxBubblesUsers);
                profileError.status = profileError.errorDetailsCode = "403";
                profileError.errorDetailsLabel = `MaximumNumberRoomUsersReach`;
                profileError.errorDetailsCode = `403620`;
                this.logger.error("[bubbleService] " + profileError.message);
                throw profileError;
            }

            // Manage status invitation
            const userStatus = (withoutInvitation) ? BubbleUserStatus.ACCEPTED : BubbleUserStatus.INVITED;
            const userReason = reason ? reason : "JustForFun";
            const userRole = role ? role : BubbleUserRole.USER;

            const url = `${this.portalURL}rooms/${bubble.dbId}/users`;
            const headers = this.authService.getPostHeader();
            const body = JSON.stringify({ userId: userContact.dbId, privilege: userRole, reason: userReason, status: userStatus });
            const response: Response = await fetch(url, { method: 'POST', headers, body });
            if (!response.ok) throw (response);

            this.logger.info(`[bubbleService] addUserToBubble ${userContact.nameForLogs} to room ${bubble.dbId} (${bubble.getNameForLogs()}) success`);

            const userData = (await response.json()).data;
            const bubbleUser: BubbleUser = (bubble as BubbleRB).getUserByJid(userData.jid_im);
            if (bubbleUser) {
                bubbleUser.status = userData.status;
                bubbleUser.date = new Date();
                bubbleUser.role = userData.privilege;
            }
            else {
                (bubble as BubbleRB).users.push({ user, status: userStatus, date: new Date(), role: userRole } as BubbleUser);
            }

            this.refreshMemberAndOrganizerLists(bubble as BubbleRB);
            return bubble;
        }
        catch (error) {
            const errorInfo = await this.errorHelperService.getErrorInfo(error, 'addUserToBubble');
            this.logger.error(`[bubbleService] ${errorInfo.message}`);
            throw errorInfo.error;
        }
    }


