    /**
     * This API allows to search Rainbow bubbles that match a search criteria applied on some name properties such as the name of the bubble
     * or the names of bubble participants for example.
     * One or more name properties can be optionally specified to define the scope of the search.
     * If no scope is specified, the search is performed by default on the name of the bubble only.
     * It is also possible to optionally specify how the list of bubbles returned as results should be sorted.
     * By default, the bubbles list will be sorted by bubble name.
     * @param searchPattern - The search criteria
     * @param options - Options to specify the scope of the search and how the results are to be returned.
     */
    public async searchBubbles(searchPattern: string, options?: BubbleSearchOptions): Promise<BubbleSearchResult[]> {
        let searchByBubbleName: boolean = false;
        let searchByTagsName: boolean = false;
        let searchByParticipantsName: boolean = false;
        let foundBubbles: Bubble[] = [];
        let foundBubblesByName: Bubble[] = [];
        let foundBubblesByTag: Bubble[] = [];
        let foundBubblesByParticipantsName: Bubble[] = [];
        const bubbleSearchResults: BubbleSearchResult[] = [];

        // Check if some name" properties have been specified to restrict the search
        // If not, the search will be performed by default on the bubble name only
        if (options?.scope) {
            searchByBubbleName = options.scope.includes(BubbleSearchScope.SEARCH_BY_BUBBLE_NAME);
            searchByTagsName = options.scope.includes(BubbleSearchScope.SEARCH_BY_TAG_NAME);
            searchByParticipantsName = options.scope.includes(BubbleSearchScope.SEARCH_BY_PARTICIPANT_NAME);
            if (!searchByBubbleName && !searchByTagsName && !searchByParticipantsName) {
                searchByBubbleName = true;
                searchByParticipantsName = true;
            }
        } else {
            searchByBubbleName = true;
            searchByParticipantsName = true;
        }

        // If requested, performs a search on the name of bubbles
        // Optimization: If a search on the bubble name is specified but not on the participants' names,
        // then the search will be performed locally without requesting the server.
        // if ((searchByBubbleName) && (!searchByParticipantsName)) {
        if (searchByBubbleName) {
            foundBubblesByName = this.searchRooms(searchPattern);
        }

        // If requested, performs a search on the name of participants
        if (searchByParticipantsName) {
            foundBubblesByParticipantsName = await this.getServerBubblesByParticipantsName(searchPattern);
        }

        // If requested, performs a search on the name of tags
        if (searchByTagsName && this.bubbleTagService) foundBubblesByTag = await this.bubbleTagService.findBubblesByTag(searchPattern);

        // Filter duplicates (Code could be better to perform filters among the 3 arrays .. Please just suggest ! !)
        // 1. Remove from foundBubblesByTag bubbles already found by bubble name
        // 2. Remove from foundBubblesByTag bubbles already found by participants names
        // 3. Remove from foundBubblesByParticipantsName bubbles already found by bubble name

        let filteredBubblesByTag: Bubble[] = foundBubblesByTag.filter((taggedBubble: Bubble) => {
            return foundBubblesByName.find((bubble: Bubble) => { return bubble && bubble.dbId === taggedBubble.dbId; }) === undefined;
        });
        filteredBubblesByTag = filteredBubblesByTag.filter((taggedBubble: Bubble) => {
            return foundBubblesByParticipantsName.find((bubble: Bubble) => { return bubble && bubble.dbId === taggedBubble.dbId; }) === undefined;
        });
        const filteredBubblesByParticipantsName: Bubble[] = foundBubblesByParticipantsName.filter((participantsBubble: Bubble) => {
            return foundBubblesByName.find((bubble: Bubble) => { return bubble && bubble.dbId === participantsBubble.dbId; }) === undefined;
        });

        foundBubbles = foundBubblesByName.concat(filteredBubblesByParticipantsName).concat(filteredBubblesByTag);

        // Sort the found bubbles acording to specified option or by using the default one.
        // For ease of use, the sorting is done BEFORE setting the data indicating how the bubbles were found.
        if (options?.sortBy) {
            if (options.sortBy === BubbleSearchSortBy.SORT_BY_BUBBLE_NAME) {
                foundBubbles.sort((bubble1: Bubble, bubble2: Bubble) => { return bubble1.name.localeCompare(bubble2.name); });
            } else if (options.sortBy === BubbleSearchSortBy.SORT_BY_LAST_ACTIVITY) {
                foundBubbles.sort((bubble1: Bubble, bubble2: Bubble) => { return bubble2.lastActivityDate.getTime() - bubble1.lastActivityDate.getTime(); });
            }
        } else {
            // By default, the found Bubbles are sorted according to displayName
            foundBubbles.sort((bubble1: Bubble, bubble2: Bubble) => { return bubble1.name.localeCompare(bubble2.name); });
        }

        foundBubbles.forEach((foundBubble: Bubble) => {
            const bubbleSearchResult: BubbleSearchResult = { bubble: null, foundBy: [] };
            bubbleSearchResult.bubble = foundBubble;

            // this.logger.info(`[bubbleService] searchBubbles -- foundBubble: name = ${foundBubble.name} -- lastActivityDate = ${foundBubble.lastActivityDate}`);
            if (foundBubblesByName.find((bubble: Bubble) => { return bubble.dbId === foundBubble.dbId; })) {
                bubbleSearchResult.foundBy.push(BubbleSearchFoundBy.FOUND_BY_BUBBLE_NAME);
                // this.logger.info(`[bubbleService] searchBubbles -- foundBubble: name = ${foundBubble.name} -- FOUND_BY_BUBBLE_NAME`);
            }
            if (foundBubblesByTag.find((bubble: Bubble) => { return bubble.dbId === foundBubble.dbId; })) {
                bubbleSearchResult.foundBy.push(BubbleSearchFoundBy.FOUND_BY_TAG_NAME);
                // this.logger.info(`[bubbleService] searchBubbles -- foundBubble: name = ${foundBubble.name} -- FOUND_BY_TAG_NAME`);
            }
            if (foundBubblesByParticipantsName.find((bubble: Bubble) => { return bubble.dbId === foundBubble.dbId; })) {
                bubbleSearchResult.foundBy.push(BubbleSearchFoundBy.FOUND_BY_PARTICIPANT_NAME);
                // this.logger.info(`[bubbleService] searchBubbles -- foundBubble: name = ${foundBubble.name} -- FOUND_BY_PARTICIPANT_NAME`);
            }

            bubbleSearchResults.push(bubbleSearchResult);
        });

        return bubbleSearchResults;
    }

