    private async createBubbleInternal(bubbleName: string = "", createBubbleData: BubbleCreationData = {}) {
        // Add default name if there's none
        if (!bubbleName) {
            bubbleName = this.contactService.userContact.initials + " " + this.i18n.translate("new") + " " + this.i18n.translate("bubble") + " ";
        }
        const bubbleNameForLogs = bubbleName.charAt(0) + "***" + bubbleName.slice(-1);

        try {
            this.logger.info("[bubbleService] createRoom \"" + bubbleNameForLogs + "\"");

            let history: string = "all";
            if (createBubbleData.hasOwnProperty('history')) {
                history = createBubbleData.history ? "all" : "none";
            }
            const autoAccept = Boolean(createBubbleData.autoAcceptInvitation);
            const description = createBubbleData.description ? createBubbleData.description : "";
            let visibility: string = "private";
            if (createBubbleData.hasOwnProperty('visibility')) {
                visibility = createBubbleData.visibility === BubbleVisibility.PUBLIC ? "public" : "private";
            }

            const data = {
                name: bubbleName, topic: description, history, disableNotifications: true, createConversation: true,
                autoAcceptInvitation: autoAccept, muteUponEntry: Boolean(createBubbleData.muteUponEntry),
                playEntryTone: createBubbleData.playEntryTone, visibility
            };

            const url = `${this.portalURL}rooms/`;
            const headers = this.authService.getPostHeader();
            const body = JSON.stringify(data);

            const response: Response = await fetch(url, { method: 'POST', headers, body });
            if (!response.ok) throw (response);
            const bubbleData = (await response.json()).data;

            if (this.bubbles[bubbleData.id]) {
                this.logger.info("[bubbleService] createRoom -- room \"" + bubbleNameForLogs + "\" already exists");
                return this.bubbles[bubbleData.id];
            }

            const bubble = BubbleRB.create();
            bubble.update(bubbleData);
            bubble.owner = this.contactService.userContact;

            // Add bubble participants
            bubbleData.users.forEach((userData: any) => {
                const contact = this.contactService.getContactFromCacheById(userData.userId);
                if (contact) {
                    const newUserBubble: BubbleUser = { user: contact, status: userData.status, date: new Date(userData.additionDate), role: userData.privilege, invitingUserId: userData.invitingUserId };
                    bubble.users.push(newUserBubble);
                    // If The current bubble user is the connected user, mandatory to update bubbleConnectedUser !
                    if (this.contactService.isUserContact(contact)) {
                        bubble.bubbleConnectedUser = newUserBubble;
                    }
                }
            });
            this.refreshMemberAndOrganizerLists(bubble);
            bubble.usersReady.next(true);
            this.bubbles[bubble.dbId] = bubble;
            this.bubblesByJids[bubble.jid] = bubble;
            this.logger.info("[bubbleService] createRoom \"" + bubbleNameForLogs + "\" -- success");

            // Use try catch to avoid blocking avatar stuff
            try { await bubble.setCustomAvatar(createBubbleData.bubbleAvatar); }
            catch { this.logger.error("[bubbleService] createRoom: setBubbleAvatar ERROR"); }

            await this.sendInitialRoomPresenceSync(bubble);
            return this.bubbles[bubble.dbId];
        }
        catch (error) {
            const errorInfo = await this.errorHelperService.getErrorInfo(error, 'createRoom');
            this.logger.error(`[bubbleService] ${errorInfo.message}`);
            throw errorInfo.error;
        }
    }

    private async addUsersToBubble(bubble: BubbleRB, userList: User[] = [], emails: string[] = [], role?: BubbleUserRole) {
        try {
            if (!emails?.length && !userList?.length) return null;

            const users = userList.map((contact: Contact) => { return contact.dbId; });
            const bodyParams = { scenario: "chat", emails: emails, lang: this.getLanguageWithIsoCode(), users };

            if (role) { bodyParams["privilege"] = role; }

            this.logger.info("[bubbleService] addUsersToBubble");

            const url = `${this.portalURL}rooms/${bubble.dbId}/invitations`;
            const headers = this.authService.getPostHeader();
            const body = JSON.stringify(bodyParams);
            const response: Response = await fetch(url, { method: 'POST', headers, body });
            if (!response.ok) { throw (response); }

            const myBody = await response.json();
            const invalidUsers = [];

            //in case there's an error in the invitation of some users, remove them from the added users
            if (myBody.data?.failed?.invalidUsers.length) {
                if (users?.length) {
                    users.forEach((dbId, index) => {
                        if (myBody.data?.failed?.invalidUsers.some((invalidUser) => { return invalidUser?.id === dbId; })) {
                            users.splice(index, 1);
                        }
                    });
                }

                myBody.data?.failed?.invalidUsers.forEach((invalidUser) => {
                    const locError = this.errorHelperService.getLocalizedError(invalidUser.errorDetailsCode, null, null);
                    this.logger.warn(`[bubbleService] addUsersToBubble user not added ${invalidUser.id} -- ${locError})`);
                    invalidUsers.push(invalidUser.id);
                });
            }

            //add users to the bubble
            users?.forEach((dbId) => {
                this.logger.info(`[bubbleService] addUsersToBubble user added -- ${dbId}`);
            });

            this.refreshMemberAndOrganizerLists(bubble);
            bubble.updateAvatarInfo();
            return invalidUsers;
        }
        catch (error) {
            const errorInfo = await this.errorHelperService.getErrorInfo(error, 'addUsersToBubble');
            this.logger.error(`[bubbleService] ${errorInfo.message}`);

            if (errorInfo?.error?.errorDetailsCode === 403621) {
                const profileError: any = new Error("addUsersToBubble failure - Not Allowed : Participants max limit has been reached: " + this.maxBubblesUsers);
                profileError.status = profileError.errorDetailsCode = "403";
                profileError.errorDetailsLabel = `MaximumNumberRoomUsersReach`;
                profileError.errorDetailsCode = `403620`;
                this.logger.error("[bubbleService] " + profileError.message);
                throw profileError;
            }

            throw errorInfo.error;
        }
    }


