    private sendInitialRoomPresence(bubble: BubbleRB, attempt: number = 0) {
        const attemptInfo = attempt ? " -- attempt " + attempt : "";
        this.logger.info("[bubbleService] sendInitialRoomPresence " + attemptInfo + " -- " + bubble.getNameForLogs() + " -- " + bubble.dbId);
        const presenceIq = $pres({ to: bubble.jid + "/" + this.xmppService.fullJid });
        presenceIq.c("x", { "xmlns": "http://jabber.org/protocol/muc" }).c("history", { maxchars: "0" });
        this.xmppService.send(presenceIq);
    }

    public sendInitialBulkRoomPresence(): Promise<any> {
        this.logger.info('[bubbleService] sendInitialBulkRoomPresence');
        const presenceIq = $pres({ to: `muc.${this.authService.xmppDomain}/${this.xmppService.fullJid}`, from: `${this.xmppService.jid}`, xmlns: 'jabber:client' });
        const ext = presenceIq.c('x', { 'xmlns': 'http://jabber.org/protocol/muc' });
        ext.c('history', { maxchars: '0' }).up();
        ext.c('options', { acknowledge: 'false', subject: 'false', capability: 'false', webinar: 'true' });
        return this.xmppService.send(presenceIq);
    }

    public sendInitialRoomPresenceSync(bubble: BubbleRB, intervalDelay: number = 7500): Promise<any> {
        if (bubble.initPresPromise) { return bubble.initPresPromise; }
        if (bubble.ready) {
            this.logger.info(`[bubbleService] sendInitialRoomPresenceSync -- ${bubble.getNameForLogs()} -- ${bubble.dbId} -- bubble already activated`);
            if (this.roomPresenceWaitingList?.length) {
                this.roomPresenceWaitingList.forEach((waitingListRoom, index) => {
                    if (waitingListRoom.dbId === bubble.dbId) {
                        this.roomPresenceWaitingList.splice(index, 1);
                    }
                });
            }
            return Promise.resolve();
        }

        bubble.initPresPromise = new Promise((resolve, reject) => {
            bubble.initPresPromiseResolve = resolve;
            this.sendInitialRoomPresence(bubble, 0);

            // Retry mechanism
            const maxAttemptNumber = 3;
            let attemptNumber = 0;

            bubble.initPresInterval = interval(intervalDelay)
                .subscribe(() => {
                    if (attemptNumber < maxAttemptNumber) {
                        // up to <maxAttemptNumber> retries
                        attemptNumber += 1;
                        this.sendInitialRoomPresence(bubble, attemptNumber);
                    } else {
                        // if no response after <maxAttemptNumber> retries, we clean the presence promise in the bubble
                        // (to make it possible for further trials to re-establish presence state and chat history access)
                        this.logger.error("[bubbleService] sendInitialRoomPresenceSync : no response after " + attemptNumber + " retries => clean presence promise and interval for " + bubble.getNameForLogs() + " -- " + bubble.jid);
                        reject("[bubbleService] sendInitialRoomPresenceSync : no response");
                        bubble.initPresPromise = null;
                        if (bubble.initPresInterval) {
                            bubble.initPresInterval.unsubscribe();
                            bubble.initPresInterval = null;
                        }

                        //refresh the bubble from the local bubble cache
                        bubble = this.bubbles[bubble.dbId];
                        //should sent an update, so that the conversation is updated and we can sent chat messages inside
                        // this.eventService.publish(RoomServiceEvents.ROOM_UPDATE_EVENT, bubble);
                    }
                });
        });
        return bubble.initPresPromise;
    }

    private sendUnavailableRoomPresence(bubble: BubbleRB): void {
        const presenceIq = $pres({ to: bubble.jid + "/" + this.contactService.userContact.jid, type: "unavailable" });
        presenceIq.c("x", { "xmlns": "http://jabber.org/protocol/muc" });
        this.xmppService.send(presenceIq);
    }


