    private updateUserStatus(bubble: BubbleRB, bubbleUser: BubbleUser, status) {

        // We immediately determine the event associated with the user's status in the bubble.
        // This event will only be sent at the end of status processing, except in special cases.
        let actionEvent: BubbleServiceEvents = this.getEventFromBubbleStatus(status); ;

        if (this.contactService.isUserContactJid(bubbleUser.user.jid)) {
            // Handle presence from myself
            this.logger.info("[bubbleService] Connected User status " + status);

            switch (status) {
                case "deleted":
                    bubbleUser.status = BubbleUserStatus.DELETED;
                    delete this.bubblesByJids[bubble.jid];
                    delete this.bubbles[bubble.dbId];
                    this.logger.info("[bubbleService] updateUserStatus --deleteRoom successfully (" + bubble.dbId + ")");

                    //remove my presence from the room
                    this.sendUnavailableRoomPresence(bubble);
                    this.fileStorageService?.removeRoomFileViewer(bubble);

                    if (this.contactService.userContact.guestMode && !bubble.isWebinarBubble()) {
                        this.eventService.publish("ON_OPEN_POPUP", "concludeInvitation");
                    }
                    // Clear conference stuff
                    // @DNI: added for CRRAINB-35019 but not sure if that's a good idea to add an eventService publish ...
                    if (bubble.isBubbleConferenceStarted()) {
                        //we need to leave any active conference just in case
                        const activeConference = this.webConferenceService?.getWebConferenceSessionById(bubble.dbId);
                        if (activeConference?.haveJoined) {
                            this.webConferenceService?.leaveWebConference(activeConference);
                        }
                        this.webConferenceService?.sendWebConferenceEvent(BubbleConferenceServiceEvents.ON_CONFERENCE_ENDED, bubble);
                    }
                    break;

                case "unsubscribed":
                    this.logger.info("[bubbleService] unsubscribed successfully (" + bubble.dbId + ")");
                    this.sendUnavailableRoomPresence(bubble);
                    bubbleUser.status = BubbleUserStatus.UNSUBSCRIBED;
                    bubble.updateAvatarInfo();
                    bubble.ready = false;
                    break;

                case "accepted":
                    // User has accepted the invitation
                    bubbleUser.status = BubbleUserStatus.ACCEPTED;
                    this.updateMyUserToAcceptedStatus(bubble, true);
                    // Reset the event action to send: Event ON_USER_INVITATION_ACCEPTED has already be sent in 'updateMyUserToAcceptedStatus'
                    actionEvent = undefined;
                    break;

                case "rejected":
                    // User has rejected the invitation
                    delete this.bubblesByJids[bubble.jid];
                    delete this.bubbles[bubble.dbId];
                    bubbleUser.status = BubbleUserStatus.REJECTED;
                    break;

                default:
                    break;
            }
            if (actionEvent) {
                this.sendEvent(actionEvent, { bubble: bubble, bubbleUser: bubbleUser});
            }
        }

        // Handle presence for other participant
        else {
            this.logger.info(`[bubbleService] Update user ${bubbleUser.user.dbId} with status ${status}`);
            if (bubbleUser.status === BubbleUserStatus.DELETED && status === BubbleUserStatus.ACCEPTED) {
                bubbleUser.date = new Date();

                //remove user's organizer rights
                if (bubbleUser.role === BubbleUserRole.ORGANIZER) {
                    bubbleUser.role = BubbleUserRole.USER;
                }
            }
            bubbleUser.status = status;
            bubble.updateAvatarInfo();
            this.refreshMemberAndOrganizerLists(bubble);

            switch (status) {
                case "invited":
                    // User has received an invitation to join the bubble
                    bubble.nbParticipants += 1;
                    // Reset the event action to send: Event ON_USER_INVITATION_RECEIVED must not be sent
                    // if it does not concern the connected user (no current interest for components/services) .
                    actionEvent = undefined;
                    break;

                case "accepted":
                    // User has accepted the invitation
                    break;

                case "rejected":
                    // User has rejected the invitation
                    bubble.nbParticipants -= 1;
                    break;

                case "deleted":
                    // User has been removed from the bubble by the owner or one of the moderators
                    bubble.nbParticipants -= 1;
                    break;

                case "unsubscribed":
                    // User has left the bubble of his own
                    bubble.nbParticipants -= 1;
                    break;

                default:
                    break;
            }

            if (actionEvent) {
                // We have to send the same event to both the bubble instance and the service
                // because we don't know how the ‘subscriber client’ listens to these events.
                const bubbleActionEvent: BubbleEvents = this.convertToBubbleEvents(actionEvent);
                bubble.sendEvent(bubbleActionEvent, bubbleUser);
                this.sendEvent(actionEvent, { bubble: bubble, bubbleUser: bubbleUser });
            }
        }
    }

    private async updateMyUserToAcceptedStatus(bubble: BubbleRB, updateFromServer: boolean = false) {
        // User has accepted the invitation
        bubble.bubbleConnectedUser.status = BubbleUserStatus.ACCEPTED;
        if (this.fileStorageService) this.fileStorageService.retrieveReceivedFilesForNewRoom(bubble.dbId);
        this.sendInitialRoomPresenceSync(bubble);
        bubble.updateAvatarInfo();

        // refresh the room for any updates between the invite and the accept, if necessary
        if (updateFromServer) {
            try {
                await this.updateRoomFromServer(bubble);
            }
            catch {
                this.logger.warn("[bubbleService] getServerRoom " + bubble.dbId + " failed");
            }
        }

        this.sendEvent(BubbleServiceEvents.ON_USER_INVITATION_ACCEPTED, { bubble: bubble, bubbleUser: bubble.bubbleConnectedUser});

        if (bubble.isBubbleConferenceStarted()) {
            bubble.sendEvent(BubbleEvents.ON_CONFERENCE_START_EVENT);
            this.webConferenceService?.sendEvent(BubbleConferenceServiceEvents.ON_WEBCONFERENCE_STARTED_EVENT_IN_BUBBLE, { roomDbId: bubble.dbId });
            this.logger.info("[bubbleService] onBubbleEventMessage : conferenceAdd");
        }
    }


