    /**
     * Helper API that is used to get the participant object from the CALL (PSTN or WebRTC) that can be used to create Ad-hoc conference via startAdHocConference API
     * @param call - The active call to conference: this call must have a status ACTIVE (it could be a PSTN call or WebRTC call)
     * @returns  object with 2 properties, participant object that should be send to the startAdHocConference and blindTrasfer boolean if the call also needs to
     * be redirected to the bubble via Blind Transfer API
     */
    public getParticipantDataForAdhocFromCall(call: CallRB) {
        const result = {
            participant: null,
            blindTrasfer: false
        };

        //build participant list to send to the ADDHOC API in the room (via ad-hoc or MERGE calls)
        if (call.callType === CallType.PHONE) {
            let deskphoneCase = false;
            if (call.sipWiseEndPointDeviceList?.length &&
                call.id === call.sipWiseEndPointDeviceList[0].callId) {
                deskphoneCase = (call.sipWiseEndPointDeviceList[0].deviceType !== "webrtc"); //CRRAINB-36312 inverse logic
            } else {
                //CRRAINB-36312 when no info (sip generic case ) use blindTransfer as default
                // meaning deskphoneCase otherwise a deviceType = "webrtc" would have been received
                // that is conveniant because Adhoc conf only proposed with active call (so device is known)
                deskphoneCase = true;
            }

            //if contact is a PSTN number (temporary contact)
            if (call.contact.temp) {
                result.participant = { phoneNumber: call.contact.id, connected: true };
                result.blindTrasfer = true;
            }
            else if (call.sipWiseData?.called?.phoneNumber && call.sipWiseData.called.phoneNumber.indexOf("+") !== -1) {
                result.participant = { phoneNumber: call.sipWiseData.called.phoneNumber, connected: true };
                result.blindTrasfer = true;
            }
            else if (!call.sipWiseEndPointDeviceList?.length) {
                //list of endpoint device is empty
                result.participant = { phoneNumber: call.remoteParty?.phoneNumber, connected: true };
                result.blindTrasfer = true;
            }
            else {
                result.participant = { userId: call.contact.dbId, connected: true, deskphone: deskphoneCase };
                if (deskphoneCase) { result.blindTrasfer = true; }
            }
        } else {
            result.participant = { userId: call.contact.dbId, connected: true };
        }

        let typeInfo: string = "Undefined";
        switch (call.callType) {
            case CallType.WEBRTC:
                typeInfo = "Video";
                break;
            case CallType.PHONE:
                typeInfo = "Phone";
                break;
            default: break;
        }
        this.logger.info(`[bubbleService] getParticipantDataForAdhocFromCall for call ${call.id}: type ${typeInfo} -- ${JSON.stringify(result.participant)} -- blind transfer : ${result.blindTrasfer}`);

        return result;
    }

    private getLanguageWithIsoCode(): string {
        let result = "en";
        if (this.contactService.userContact.language) {
            const splitted = this.contactService.userContact.language.split("-");
            if (splitted.length > 1) {
                result = splitted[0] + "-" + splitted[1].toUpperCase();
            } else {
                result = splitted[0];
            }
        }
        return result;
    }

