    // Crer une methode private pour rendre event à envoyer en fonction de status
    private getEventFromBubbleStatus(status: string): BubbleServiceEvents|undefined {
        switch (status) {
            case "invited":
                // User has received an invitation to join the bubble
                return BubbleServiceEvents.ON_USER_INVITATION_RECEIVED;

            case "accepted":
                // User has accepted the invitation
                return BubbleServiceEvents.ON_USER_INVITATION_ACCEPTED;

            case "rejected":
                // User has rejected the invitation
                return BubbleServiceEvents.ON_USER_INVITATION_DECLINED;

            case "deleted":
                // User has been removed from the bubble by the owner or one of the moderators
                return BubbleServiceEvents.ON_USER_BUBBLE_REMOVED;

            case "unsubscribed":
                // User has left the bubble of his own
                return BubbleServiceEvents.ON_USER_BUBBLE_LEFT;

            default:
                this.logger.info(`[bubbleService] getEventFromBubbleStatus -- Unknown specified bubble user status ${status}`);
                return undefined;
        }
    }

    private convertToBubbleEvents(bubbleServiceEvents: BubbleServiceEvents): BubbleEvents|undefined {

        switch (bubbleServiceEvents) {
            case BubbleServiceEvents.ON_USER_INVITATION_ACCEPTED:
                return BubbleEvents.ON_USER_INVITATION_ACCEPTED;

            case BubbleServiceEvents.ON_USER_INVITATION_DECLINED:
                return BubbleEvents.ON_USER_INVITATION_DECLINED;

            case BubbleServiceEvents.ON_USER_BUBBLE_LEFT:
                return BubbleEvents.ON_USER_BUBBLE_LEFT;

            case BubbleServiceEvents.ON_USER_BUBBLE_REMOVED:
                return BubbleEvents.ON_USER_BUBBLE_REMOVED;

            default:
                this.logger.info(`[bubbleService] convertToBubbleEvents -- Unknown specified bubble service event ${bubbleServiceEvents}`);
                return undefined;
        }
    }
