export interface ClassType<T extends Service> {
    build(): T;
}

export abstract class Service {
    protected static create<T extends Service>(name: string, _class: ClassType<T>): T {
        if (!window.rainbow) { window.rainbow = { plugins: {}, rainbowSDK: undefined, services: {} }; }
        if (!window.rainbow.services) { window.rainbow.services = {}; }
        if (!window.rainbow.services[name]) {
            window.rainbow.services[name] = _class.build();
        }
        return window.rainbow.services[name];
    }

    public static build(): Service {
        throw new Error('Not implemented');
    }
}