    RAINBOW_FILESTORAGE_NEEDS_POPUP = 'RAINBOW_FILESTORAGE_NEED_POPUP',

    ON_FILE_REMOVED_FROM_STORE_EVENT = "ON_FILE_REMOVED_FROM_STORE_EVENT",
    ON_FILE_DESCRIPTOR_RECEIVED_EVENT = "ON_FILE_DESCRIPTOR_RECEIVED_EVENT",
