    /**
     * @public
     * @function subscribe
     * @instance
     * @description Subscribe to updates from the fileStorageService (all events are of RBEvent type {name: string, data:any});
     * @param {any} handler The call-back function that will be subscribed to the RxJS subject
     * @param {string[]} eventNames (optional) array of event to listen
     * @returns {Subscription} Returns RxJS Subscription
     */
    public subscribe(handler: any, eventNames?: string | string[]): Subscription {
        const observable = eventNames ? this.rxSubject.pipe(filter((event: RBEvent) => {
            if (eventNames instanceof Array) return eventNames.indexOf(event.name) !== -1;
            return event.name === eventNames;
        })) : this.rxSubject;

        return observable.subscribe((event: RBEvent) => {
            try { handler(event); }
            catch (error) { this.logger.error(`[FileStorageService] subscribe () -- error -- ${error.message}`); }
        });
    }

    public sendEvent(name: FileStorageServiceEvents, data?: any): void {
        this.rxSubject.next(RBEvent.create<FileStorageServiceEvents, any>(name, data));
    }

