    /**
     * Method requests server to create a file descriptor this will be saved to local file descriptor list (i.e. this.fileDescriptors)
     * @param {File} file [required] file for which file descriptor has to be created
     * @param {FileViewer[]} viewers [required] list of viewers having access to the file (a viewer could be either be a user or a room)
     * @returns {Promise<FileDescriptor>} file descriptor created by server or error
     * @memberof FileStorageService
     */
    public async createFileDescriptor(file: File, viewers: FileViewer[] = [], voiceMessageData = null, ccarelogs: boolean = false, ccareclientlogs: boolean = false): Promise<FileDescriptor> {
        try {
            return await this.createFileDescriptorInternal(file, viewers, voiceMessageData, ccarelogs, ccareclientlogs);
        }
        catch (error) {
            if (this.externalStorage && error?.errorDetailsCode === 401230) {
                this.logger.warn(`[FileStorageService] createFileDescriptor -- externalStorage -- ${error?.error?.errorDetails}`);
                await this.authenticateExternalStorage();
                return await this.createFileDescriptorInternal(file, viewers, voiceMessageData, ccarelogs, ccareclientlogs);
            }
            throw error;
        }
    }

    private async createFileDescriptorInternal(file: File, viewers: FileViewer[] = [], voiceMessageData = null, ccarelogs: boolean = false, ccareclientlogs: boolean = false): Promise<FileDescriptor> {
        const fileName = file.name;
        const extension = file.name.split(".").pop();
        const size = file.size;
        try {
            const data: any = { fileName, extension, size, viewers };

            if (voiceMessageData) {
                data.voicemessage = true;
                data.encoding = true;
                data.duration = voiceMessageData.duration;

                if (data.duration === 0) {
                    data.duration = 1;
                }
            }
            if (ccarelogs) {
                data.ccarelogs = true;
                data.ccareclientlogs = ccareclientlogs;
            }

            const url = this.portalURL;
            const headers = this.authService.getPostHeader();
            const body = JSON.stringify(data);
            const response: Response = await fetch(url, { method: 'POST', headers, body });
            if (!response.ok) { throw (response); }
            const fileDescriptorData = (await response.json()).data;
            const fileDescriptor = this.createFileDescriptorFromData(fileDescriptorData);
            if (fileDescriptor) {
                this.fileDescriptors.push(fileDescriptor);
                this.uploadingFileDescriptors.push(fileDescriptor);

                this.uploadingFileDescriptorsSubject.next({ size: this.getUploadingFilesSize() });
            }
            this.logger.info("[FileStorageService] createFileDescriptor -- " + fileDescriptor.id + " -- success");
            return fileDescriptor;
        }
        catch (error) {
            const errorInfo = await this.errorHelperService.getErrorInfo(error, 'createFileDescriptor');
            if (errorInfo.error.errorDetailsCode === 403153) {
                this.contactService.userContact.fileSharingEnabled = false;
            }
            this.logger.error(`[fileStorageService] ${errorInfo.message}`);
            throw errorInfo.error;
        }
    }

    private createFileDescriptorFromData(data: any): FileDescriptor {
        let viewers: FileViewer[] = [];
        if (data.viewers) { viewers = FileViewer.createFromData(data.viewers); }
        let url = data.url;
        if (!url) { url = config.restServerUrl + "/api/rainbow/fileserver/v1.0/files/" + data.id; }

        const state = data.isUploaded ? FileState.UPLOADED : FileState.NOT_UPLOADED;
        const voiceMessage = (data.tags && data.tags.purpose === "voicemail");
        const recordingFile = (data.tags && data.tags.purpose === "conference_record");
        const recordingConferenceId = recordingFile && data.tags && data.tags.conferenceRecording ? data.tags.conferenceRecording.filesConfRecordingId : null;

        let virusScanState = "unknown";
        if (data.isClean === null) { virusScanState = "notScanned"; }
        else if (data.isClean === true) { virusScanState = "isClean"; }
        else { virusScanState = "isInfected"; }

        const fd = FileDescriptor.create(data.id, url, data.ownerId, data.fileName, data.extension, data.typeMIME,
            data.size, data.registrationDate, data.uploadedDate, data.dateToSort, viewers, state, data.thumbnail, data.orientation, data.original_w, data.original_h, data.tags, virusScanState, voiceMessage, recordingFile, recordingConferenceId);
        fd.externalStorage = data.backendType !== undefined && data.backendType !== 'Swift';
        return fd;
    }

