    /**
     * Method retrieve full list of files belonging to user making the request
     * @returns {Promise<FileDescriptor[]>} return
     * @memberof FileStorageService
     */
    public async retrieveVoiceMessageFileDescriptorsListPerOwner(): Promise<FileDescriptor[]> {
        try {
            const url = `${this.portalURL}?format=full&path=/voice-messages`;
            const headers = this.authService.getRequestHeader();
            const response: Response = await fetch(url, { method: 'GET', headers });
            if (!response.ok) { throw (response); }
            const fileDescriptorsData = (await response.json()).data;
            if (!fileDescriptorsData) return [];

            // Create file descriptors
            this.voiceMessageFileDescriptors = fileDescriptorsData.reduce((fileDescriptors: FileDescriptor[], fileDescriptorData: any) => {
                const fileDescriptor = this.createFileDescriptorFromData(fileDescriptorData);
                if (fileDescriptor.state === FileState.NOT_UPLOADED) {
                    this.logger.info(`[FileStorageService] file ${fileDescriptor.fileName} not uploaded`);
                    if (fileDescriptor && fileDescriptor.ownerId === this.contactService.userContact.dbId) {
                        this.logger.info(`[FileStorageService] file ${fileDescriptor.fileName} is our property, we can delete it`);
                        this.deleteFileDescriptor(fileDescriptor.id);
                    }
                    else this.logger.info(`[FileStorageService] file ${fileDescriptor.fileName} is NOT our property, we CANNOT delete it`);
                }
                else fileDescriptors.push(fileDescriptor);
                return fileDescriptors;
            }, []);

            this.logger.info("[FileStorageService] retrieveVoiceMessageFileDescriptorsListPerOwner -- success");
            return this.voiceMessageFileDescriptors;
        }
        catch (error) {
            const errorInfo = await this.errorHelperService.getErrorInfo(error, 'retrieveVoiceMessageFileDescriptorsListPerOwner');
            this.logger.error(`[fileStorageService] ${errorInfo.message}`);
            throw errorInfo.error;
        }
    }

