    /**
     * Method adds a viewer to a given file on server if it is not already one
     * @param {string} fileId [required] Identifier of file
     * @param {string} viewerId [required] Identifier of viewer to be added
     * @param {string} type [required] type of viewer to be added (user or room)
     * @returns {Promise<FileDescriptor>} file descriptor with newly added viewer
     * @memberof FileStorageService
     */
    public async addFileViewer(fileId: string, viewerId: string, type: string): Promise<FileDescriptor> {
        let fileDescriptor = this.getFileDescriptorById(fileId);
        if (!fileDescriptor) {
            fileDescriptor = await this.retrieveOneFileDescriptor(fileId);
        }

        if (fileDescriptor) {
            if (fileDescriptor.isAlreadyFileViewer(viewerId)) { return fileDescriptor; }

            try {
                const url = `${this.portalURL}/${fileId}/viewers`;
                const headers = this.authService.getPostHeader();
                const body = JSON.stringify({ viewerId, type });
                const response: Response = await fetch(url, { method: 'POST', headers, body });
                if (!response.ok) { throw (response); }

                this.logger.info("[FileStorageService] addFileViewer success");
                const viewerAdded: FileViewer = FileViewer.createFromData([{ viewerId, type }])[0];
                fileDescriptor.viewers.push(viewerAdded);
                fileDescriptor.stateSubject.next(fileDescriptor.state);
                return fileDescriptor;
            }
            catch (error) {
                const errorInfo = await this.errorHelperService.getErrorInfo(error, 'addFileViewer');
                this.logger.error(`[fileStorageService] ${errorInfo.message}`);
                throw errorInfo.error;
            }
        }
        return null;
    }

