    public updateAFileDescriptorLocally(fileDesc: FileDescriptor): void {
        this.fileDescriptors = this.fileDescriptors.map((fd) => {
            if (fd.id === fileDesc.id) {
                return fileDesc;
            }
            return fd;
        });
        this.receivedFileDescriptors = this.receivedFileDescriptors.map((fd) => {
            if (fd.id === fileDesc.id) {
                return fileDesc;
            }
            return fd;
        });
    }


    public removeRecordFromRecordingFile(deletedFileId: string, recordingFileId: string) {
        this.logger.info("[FileStorageService] removeRecordFromRecordingFile " + deletedFileId + " belonging to " + recordingFileId);


        const matchingRecordingFile = this.conferenceRecordingFiles.find((recordingFile: ConferenceRecordingFile) => {
            return recordingFile.id === recordingFileId;
        });

        const indexTosuppr = matchingRecordingFile.records.findIndex((confRecord: ConferenceRecord) => {
            return confRecord.fileId === deletedFileId;
        });

        matchingRecordingFile.records.splice(indexTosuppr, 1);

        // If no records left, delete the file
        if (matchingRecordingFile.records.length === 0) {
            this.logger.info(`[FileStorageService] removeRecordFromRecordingFile - no associated record left, remove ${recordingFileId} from conferenceRecordingFiles`);
            const filteredConferenceRecordingFiles: ConferenceRecordingFile[] = this.conferenceRecordingFiles.filter((recordingFile: ConferenceRecordingFile) => {
                return recordingFile.id !== recordingFileId;
            });
            this.conferenceRecordingFiles = filteredConferenceRecordingFiles;
            this.conferenceRecordingFilesSubject.next(this.conferenceRecordingFiles);
        }

    }

