    public async authenticateExternalStorage(): Promise<any> {
        this.logger.info(`[FileServerService] authenticateExternalStorage`);
        try {
            // Fetch the externalStorage authentication URL
            const serverUrl: URL = new URL(`${config.restServerUrl}/api/rainbow/fileserver/v1.0/external-storage/oidc-client/login?callback=${window.location.origin}/externalStorage.html`);
            const headers = this.authService.getRequestHeader();
            const response: Response = await fetch(serverUrl.href, { method: 'GET', headers });
            if (!response.ok) { throw (response); }
            const url = (await response.json()).data.url;

            // Add localStorage change handler
            let externalStoragePromiseResolver: any;
            let authPopup: Window;
            const localStorageHandler = async (event: StorageEvent) => {
                if (event.key === 'externalStorage' && event.newValue) {
                    this.logger.info(`[FileServerService] externalStorage -- authentication done detected -- close popup`);
                    window.removeEventListener('storage', localStorageHandler);
                    localStorage.removeItem('externalStorage');
                    if (authPopup) { authPopup.close(); authPopup = null; }
                    externalStoragePromiseResolver();
                    this.externalStorage.authenticationNeeded = false;
                }
            };
            window.addEventListener('storage', localStorageHandler, false);

            // Open the popup
            authPopup = window.open(url, "popup", "scrollbars=1,resizable=1,height=560,width=770");
            if (!authPopup || authPopup.closed || typeof authPopup.closed === 'undefined') {
                this.sendEvent(FileStorageServiceEvents.RAINBOW_FILESTORAGE_NEEDS_POPUP);
            }
            else {
                // Wait close signal
                await new Promise<any>((resolve: any) => { externalStoragePromiseResolver = resolve; });
            }
        }
        catch (error) {
            const errorInfo = await this.errorHelperService.getErrorInfo(error, 'authenticateExternalStorage');
            this.logger.error(`[fileServerService] ${errorInfo.message}`);
            throw errorInfo.error;
        }
    }

