    /**
     * @function searchForFilesOnExternalStorage
     * @description Method used to search for files on the external storage server based on different criteria
     *              Note that this method only returns my own files
     * @param {string} path define the directory to search from
     * @returns {Promise<FileDescriptor>} Object containing the { fileDescriptors: FileDescriptor[], limit: number, offset: number }
     * @memberof FileStorageService
     */
    public async searchForFilesOnExternalStorage(path: string = '', sortedBy: string = 'name', sortDirection: string = 'bottom', filterBy: string = "all", filterValue: string = '', force: boolean = false): Promise<GetFilesResultInterface> {
        try {

            // Launch authentication flow if necessary
            if (this.externalStorage.authenticationNeeded) await this.authenticateExternalStorage();

            // Get folder data from server if necessary
            if (force || !this.externalStorageFileDescriptors || this.externalStoragePath !== path) {

                const serverUrl = `${config.restServerUrl}/api/rainbow/fileserver/v1.0/external-storage/files?path=${path}`;
                const headers = this.authService.getRequestHeader();
                const response: Response = await fetch(serverUrl, { method: 'GET', headers });
                if (!response.ok) { throw (response); }
                this.externalStoragePath = path;
                const fileDescriptorsData = (await response.json()).data.content;

                // Create fileDescriptors from receive data
                this.externalStorageFileDescriptors = fileDescriptorsData.map((fdData: any) => {
                    return FileDescriptor.createFromExternalStorageData(fdData);
                });
            }

            // Convert external storage data to genericFileDescriptor format
            const fileDescriptors = this.externalStorageFileDescriptors.reduce((acc: any, fileDesc: FileDescriptor) => {

                // Apply filtering criteria
                if (filterBy !== 'all' && (fileDesc.type === 'directory' || fileDesc?.thumbnailPlaceholder.type !== filterBy)) return acc;

                if (filterValue !== '' && !fileDesc.fileNameToFilter.includes(filterValue.toLowerCase().trim().normalize('NFD').replace(/[\u0300-\u036f]/g, ''))) return acc;

                // Store fileDescriptor in acc
                (fileDesc.type === 'directory' ? acc.folders : acc.files).push(fileDesc);

                return acc;
            }, { folders: [], files: [] });

            // Sort files
            const descd = sortDirection === 'bottom';
            switch (sortedBy) {
                case 'file':
                    fileDescriptors.folders.sort((itA: any, itB: any) => itA.name.localeCompare(itB.name));
                    fileDescriptors.files.sort((itA: any, itB: any) => descd ? itA.thumbnailPlaceholder.icon.localeCompare(itB.thumbnailPlaceholder.icon) : itB.thumbnailPlaceholder.icon.localeCompare(itA.thumbnailPlaceholder.icon));
                    break;
                case 'name':
                    fileDescriptors.folders.sort((itA: any, itB: any) => descd ? itA.fileNameToFilter.localeCompare(itB.fileNameToFilter) : itB.fileNameToFilter.localeCompare(itA.fileNameToFilter));
                    fileDescriptors.files.sort((itA: any, itB: any) => descd ? itA.fileNameToFilter.localeCompare(itB.fileNameToFilter) : itB.fileNameToFilter.localeCompare(itA.fileNameToFilter));
                    break;
                case 'date':
                    fileDescriptors.folders.sort((itA: any, itB: any) => descd ? itA.time - itB.time : itB.time - itA.time);
                    fileDescriptors.files.sort((itA: any, itB: any) => descd ? itA.time - itB.time : itB.time - itA.time);
                    break;
                case 'size':
                    fileDescriptors.folders.sort((itA: any, itB: any) => descd ? itA.size - itB.size : itB.size - itA.size);
                    fileDescriptors.files.sort((itA: any, itB: any) => descd ? itA.size - itB.size : itB.size - itA.size);
                    break;
                default: break;
            }
            return { allReceived: true, fileDescriptors: fileDescriptors.folders.concat(fileDescriptors.files) };
        }
        catch (error) {
            const errorInfo = await this.errorHelperService.getErrorInfo(error, 'searchForFilesOnExternalStorage');

            if (this.externalStorage && errorInfo?.error?.errorDetailsCode === 401230) {
                this.logger.warn(`[FileStorageService] searchForFilesOnExternalStorage -- ${error?.error?.errorDetails}`);
                await this.authenticateExternalStorage();
                return await this.searchForFilesOnExternalStorage(path, sortedBy, sortDirection, filterBy, filterValue, force);
            }
            this.logger.error(`[fileServerService] ${errorInfo.message}`);
            throw errorInfo.error;
        }
    }

    public async shareExternalStorageFiles(path: string, basename: string, fileId: string, viewerId: string, type: string): Promise<FileDescriptor> {
        try {
            // Fetch the externalStorage authentication URL
            const serverUrl: URL = new URL(`${config.restServerUrl}/api/rainbow/fileserver/v1.0/external-storage/files/share`);
            const headers = this.authService.getPostHeader();
            const body = JSON.stringify({ path, basename, fileId, viewerId, type });
            const response: Response = await fetch(serverUrl.href, { method: 'POST', headers, body });
            if (!response.ok) { throw (response); }
            const data = (await response.json()).data;

            // Create the file Descriptor
            const fd = this.createFileDescriptorFromData(data);

            const fds = fd.ownerId === this.contactService.userContact.dbId ? this.fileDescriptors : this.receivedFileDescriptors;
            if (fds.findIndex((fd2) => (fd2.id === fd.id)) === -1) fds.push(fd);
            this.logger.info(`[fileServerService] shareExternalStorageFile -- success`);
            return fd;
        }
        catch (error) {
            const errorInfo = await this.errorHelperService.getErrorInfo(error, 'shareExternalStorageFile');
            this.logger.error(`[fileServerService] ${errorInfo.message}`);
            throw errorInfo.error;
        }
    }

    public async createExternalStorageSharingSpace(bubble: BubbleRB): Promise<void> {
        try {
            // Fetch the externalStorage authentication URL
            const serverUrl: URL = new URL(`${config.restServerUrl}/api/rainbow/fileserver/v1.0/external-storage/rooms/${bubble.dbId}/synchronize`);
            const headers = this.authService.getPostHeader();
            const response: Response = await fetch(serverUrl.href, { method: 'PUT', headers });
            if (!response.ok) { throw (response); }
            const data = (await response.json());
            bubble.externalStorageAccessUrl = data.data.webUrl;
            this.logger.info(`[fileServerService] createExternalStorageSharingSpace (${bubble.dbId}) : ${data.status} -- ${bubble.externalStorageAccessUrl}`);
        }
        catch (error) {
            const errorInfo = await this.errorHelperService.getErrorInfo(error, 'createExternalStorageSharingSpace');
            this.logger.error(`[fileServerService] ${errorInfo.message}`);
            bubble.externalStorageAccessUrl = undefined;
            throw errorInfo.error;
        }
    }

