/**
 * Display format for users' full names (first and last names).
 * - "FL": "First name, last name",
 * - "LF": "Last name, first name",
 */
export type DisplayOrder = 'FL' | 'LF';

/**
 * User-specific custom data in the form of an Object with a free keys/values structure
 * Restrictions on a CustomData Object:
 * - max 20 keys,
 * - max key length: 64 cEharacters.
 * - max value length: 4096 characters.
 * It is up to the client to manage the user's customData (new customData provided overwrite the existing one).
 */
export type UserCustomData = Record<string, string>;

export interface UserAvatar { src: string }

export enum UserPresenceStatus {
    /**
     * User goes to online by leaving any manual state.
     * In case of a call in progress, the user will go to busy state;
     */
    ONLINE = 'online',

    /**
     * 'Do not disturb' manual state
     */
    DND = 'dnd',

    /**
     * 'Invisible' or 'Appear offline' manual state
     */
    XA = 'xa',

    /**
     * 'Away' manual state
     */
    AWAY = 'away'
}


/**
 * This interface represents a user's phone number with its properties, the type of number and data for managing it.
 */
export interface UserPhoneNumber {
    /**
     * The type of the phone number (business, personal, etc.)
     */
    type: PhoneNumberType;

    /**
     * Related phone number. It can be used to make a phone call to this user
     */
    number: string;

    /**
     * Indicates if the phone number is visible by other users.
     * This information is only available and managed for some phone numbers: the business mobile, the personal phone and the personal mobile numbers.
     * For other phone numbers, this information is not relevant and will be ignored, particularly during an update.
     * In the absence of this property, the phone number will be considered to be not in shared use.
     */
    shared?: boolean;

    /**
     * Indicates if the phone number can be updated or not.
     * In the absence of this property, the phone number is considered modifiable.
     */
    updateAllowed?: boolean;
}

export interface WebCallCapabilities {
    /**
     * Indicates if the audio media can be used at a given moment in a WebRTC Call with a defined remote party.
     */
    audio?: boolean;

    /**
     * Indicates if the video media can be used at a given moment in a WebRTC Call with a defined remote party.
     */
    video?: boolean;

    /**
     * Indicates if the sharing media can be used at a given moment in a WebRTC Call with a defined remote party.
     */
    sharing?: boolean;
}

