/**
 * @eventProperty
 * `User` specific events
 * Can listen to it via `user.subscribe()` API
 */
export enum UserEvents {

    /**
     * @eventProperty
     * This RBEvent is send when the user presence status is updated
     */
    ON_PRESENCE_CHANGE = 'ON_PRESENCE_CHANGE',

    /**
     * @eventProperty
     * This RBEvent is send when the user identity is updated (firstName, lastName, title, nickName or jobTitle)
     */
    ON_IDENTITY_CHANGE = 'ON_IDENTITY_CHANGE',

    /**
     * @eventProperty
     * This RBEvent is send when the user avatar is updated
     */
    ON_AVATAR_CHANGE = 'ON_AVATAR_CHANGE' //CHECK
}

export interface ConnectedUser extends User {

     /**
     * Specifies the type of administration for a logged-in user with an Administrator role.
     * @readonly
     */
    adminType: string;


    /**
    * Set the current user presence status (if allowed); The status list can be get at all time via computeStatusList
    * @param status - The presence status that the user wants to set to his user. The status list can be get via computeStatusList API
    */
    setPresenceStatus(status: UserPresenceStatus | string): void;

    /**
     * Return a list of status that the user can currently Set (via 'setPresenceStatus' API).
     * Possible Values are 'online', 'away', 'xa', 'dnd'.
     * + online: user goes to online (or can 'exit') any manual state; In case of a call in progress, the user will go to busy state;
     * + away: a manual Away state
     * + xa: 'invisble' or 'appear offline' manual state
     * + dnd:  Do not disturb manual state
     * @returns Returns an array of all available values to be used if the user wants to change his presence
    */
    getAvailablePresenceStatusList(): string[];

    /**
     * Set the user's password
     * @param oldPassword - the old password
     * @param newPassword - the new password
     * @param async - if TRUE, the resolve of this API will be done once the change is taken into account also on XMPP side; Default value is FALSE
     */
    setPassword(oldPassword: string, newPassword: string, async: boolean): Promise<User>;

    /**
     * Set the user's profile data (name, emails, numbers, etc)
     * @param userProfile - the conneted user'profile to update
     */
    setProfile(userProfile: ConnectedUserProfile): Promise<User>;

    /**
     * Set the display format for users' full names (first and last names)
     */
    setDisplayOrder(displayOrder: DisplayOrder): void;

    /**
     * Get display format for users' full names (first and last names)
     */
    getDisplayOrder(): DisplayOrder;


    /**
     * Delete current user Account.
     * This method deletes the connectedUser account and all its associated data.
     * Depending on the configuration of the company hosting the connectedUser, this method may not work.
     */
    deleteAccount(): Promise<void>;

    /**
     * Users have a default avatar generated from the initials of their first and/or last names.
     * Ex: User John Do, will have the default avatar : JD.
     * But this avatar can be overloaded by an image chosen by the user
     * @param base64AvatarImg - Base64 image to be uploaded
     */
    setCustomAvatar(base64AvatarImg: string): Promise<User>;

    /**
     * Users have a default avatar generated from the initials of their first and/or last names.
     * Ex: User John Do, will have the default avatar : JD.
     * But this avatar can be overloaded by an image chosen by the user
     * @param base64AvatarImg - Base64 image to be uploaded
     */

    // $$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$
    // PMA OPEN : A Revoir
    // setPhoneNumber(phoneNumber: UserPhoneNumber): Promise<User>;
    // setMail(mail: UserPhoneNumber): Promise<User>;
    // PMA OPEN : A Revoir
    // $$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$

    /**
     * Remove the current user custom avatar (reset to default avatar)
     */
    removeCustomAvatar(): Promise<User>;

    /**
     * Get the capabilities representing the medias that could be used for a WebRTC Call with the specified remote Rainbow user.
     * The returned capabilities are a SNAPSHOT taken at the time of this API call and are valid (so guaranteed) only for the time of this call.
     * @param remoteParty - The Rainbow user you want to make a WebRTC call to
     */
    getMakeWebCallCapabilities(remoteParty: User): WebCallCapabilities;

    /**
     * Monitor which medias can be used for a WebRTC call with the specified remote Rainbow user.
     * This monitoring is done through a subscription wihch allows to receive real-time updates on the capabilities representing these medias.
     * A callback is required to retrieve and managed the current values of these capabilities that will be returned "as parameter" of this callback.
     * An error callback can also be optionally specified to handle thrown errors.
     * It is important to note that, once this monitoring is no longer required, it must be stopped using the 'unsubscribe' method on this subscription.
     * @param remoteParty - The Rainbow user you want to make a WebRTC call to
     * @param callbackResult - Callback to manage capabilities sent in real time
     * @param callbackError - Callback to manage errors
     */
    monitorWebCallCapabilities(remoteParty: User, callbackResult: (arg0: WebCallCapabilities) => any, callbackError?: (error: any) => any): Subscription;
}

/**
 * This interface is used to represent a Rainbow user<br/>
 * A User is defined by a set of public information (name, firstname, avatar...) and a set of private information that are only shared with contacts that are in the user's network or in the same company (email, phone numbers...)
 */
export interface User {

    /**
     * Permits to emit UserEvents events
     * Can be listened via user.subscribe() API
     * @param name - the name of the event
     * @param data - the data to be send (an object
     */
    sendEvent(name: UserEvents, data?: any): void;

    /**
     * Subscribe to updates on the current contact (all events are of RBEvent type {name: string, data:any});
     * @param handler - The call-back function that will be subscribed to the RxJS subject
     * @param filterEvent - A list of event names that the user wants to receive when subscribing (used a filter)
     */
    subscribe(handler: (event: RBEvent<UserEvents>) => any, eventNames?: UserEvents[]): Subscription;

    /**
     * User unique identifier
     * @readonly
     * @internal
     */
    id: string;

    /**
     * User unique database identifier
     * @readonly
     * @internal
     */
    dbId: string;

    /**
     * User unique xmpp identifier
     * @readonly
     * @internal
     */
    jid: string;

    /**
     * User login (main email adress)
     * @readonly
     */
    login: string;

    /**
     * @readonly
     */
    loginEmail?: string;

    /**
     * The user displayName (depending of lastname/firstname order settings)
     * @readonly
     */
    displayName?: string;

    /**
     * The user firstname
     * @readonly
     */
    firstname?: string;

    /**
     * The user lastname
     * @readonly
     */
    lastname?: string;

    /**
     * The user nickname
     * @readonly
     */
    nickname?: string;

    /**
     * The user title
     * @readonly
     */
    title?: string;

    /**
     * The user job title
     * @readonly
     */
    jobTitle?: string;

    /**
     * The user company name
     * @readonly
     */
    company?: Company;

    /**
     * The user favorite language name
     * @readonly
     */
    language?: string;

    /**
     * The user favorite Country
     * @readonly
     */
    country?: string;

    /**
     * The user avatar object
     * @readonly
     */
    avatar?: UserAvatar;

    /**
     * The user avatar last modification date
     * @readonly
     */
    lastAvatarUpdateDate?: Date;

    /**
     * The user professional email
     * @readonly
     */
    emailPro?: string;

    /**
     * The user personal email
     * @readonly
     */
    emailPerso?: string;

    /**
     * The user presence status
     * @readonly
     */
    status: 'online' | 'away' | 'offline' | 'unknown' | string;

    /**
     * The user presence status message
     * @readonly
     */
    statusInfo?: string;

    // $$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$
    // PMA OPEN : A Revoir
    // PMA: TODO BIG SHIT
    // Phone numbers section
    phoneInternalNumber?: string;
    /**
     * Get all the phone numbers (personal and business) asssociated to the user
     */
    // getPhoneNumbers(): UserPhoneNumber[];
    // PMA OPEN : A Revoir
    // $$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$


    /**
     * Syntactic sugar to check if a user is the connectedUser
     * @readonly
     */
    isConnectedUser(): boolean;

    /**
     * The guest user's company name
     */
    companyNameOfGuest?: string;

    /**
     * Indicates whether the user is a guest
     * @readonly
     */
    guest: boolean;

    /**
     * Indicates whether the user is considered initialized, i.e. whether he has entered his first and last name
     * when logging in for the first time.
     */
    initialized: boolean;

    /**
     * Indicates whether the user has been deleted
     * @readonly
     */
    terminated: boolean;

    /**
     * Specifies the type of administration for a logged-in user with an Administrator role.
     * @readonly
     */
    // AdminType: string;

    isBot: boolean;
    isTv: boolean;

    toJSON(): any;
}

/**
 * @internal
 */
export class ConnectedUserRB extends Contact implements ConnectedUser {

    public setPresenceStatus(status: UserPresenceStatus | string): void { return this.contactService.setConnectedUserPresence(status); }
    public getAvailablePresenceStatusList(): string[] { return this.contactService.getConnectedUserAvailablePresenceStatusList(); }

    public async setPassword(oldPassword: string, newPassword: string, async: boolean): Promise<User> {
        return this.contactService.updateConnectedUserPassword(oldPassword, newPassword, async);
    }

    // public async initialize(userData: ConnectedUserProfile): Promise<User> { return this.contactService.updateConnectedUserProfile(userData); }
    public async setProfile(userData: ConnectedUserProfile): Promise<User> {
        return this.contactService.updateConnectedUserProfile(userData);
    }

    // public async setCustomData(customData: UserCustomData): Promise<User> { return this.contactService.updateConnectedUserCustomData(customData); }
    public async setCustomAvatar(base64AvatarImg: string): Promise<User> { return this.contactService.setAvatar(base64AvatarImg); }
    public async removeCustomAvatar(): Promise<User> { return this.contactService.removeAvatar(); }

    public setDisplayOrder(displayOrder: DisplayOrder): void {
        this.contactService.setUserSettings({ displayNameOrderFirstNameFirst: (displayOrder === 'FL') });
        this.contactService.setDisplayOrder(displayOrder);
    }

    public getDisplayOrder(): DisplayOrder {
        return this.contactService.getDisplayOrder();
    }

    public async deleteAccount(): Promise<void> { return this.contactService.deleteConnectedUserAccount(); }


    /**
     * Get the capabilities representing the medias that could be used for a WebRTC Call with the specified remote Rainbow user.
     * The returned capabilities are a SNAPSHOT taken at the time of this API call and are valid (so guaranteed) only for the time of this call.
     * @param remoteParty - The Rainbow user you want to make a WebRTC call to
     */
    public getMakeWebCallCapabilities(remoteParty: User): WebCallCapabilities { return this.contactService.getConnectedUserWebRTCCallCapabilities(remoteParty); }

    /**
     * Monitor which medias can be used for a WebRTC call with the specified remote Rainbow user.
     * This monitoring is done through a subscription wihch allows to receive real-time updates on the capabilities representing these medias.
     * A callback is required to retrieve and managed the current values of these capabilities that will be returned "as parameter" of this callback.
     * An error callback can also be optionally specified to handle thrown errors.
     * It is important to note that, once this monitoring is no longer required, it must be stopped using the 'unsubscribe' method on this subscription.
     * @param remoteParty - The Rainbow user you want to make a WebRTC call to
     * @param callbackResult - Callback to manage capabilities sent in real time
     * @param callbackError - Callback to manage errors
     */
    public monitorWebCallCapabilities(remoteParty: User, callbackResult: (arg0: WebCallCapabilities) => any, callbackError?: (error: any) => any): Subscription {
        // const webRTCCallCapabilitiesObservable: Observable<WebCallCapabilities> = this.contactService.userContact.monitorWebCallCapabilities(remoteParty);
        const webRTCCallCapabilitiesObservable: Observable<WebCallCapabilities> = this.contactService.createWebRTCCapabilitiesObservable(remoteParty);

        // Direct use of the observable: we subscribe to retrieve the current values of these capabilities.
        if (webRTCCallCapabilitiesObservable) {
            return webRTCCallCapabilitiesObservable.subscribe({
                next: callbackResult,
                error: callbackError
            });
        }
        return null;
    }

}
