import { FileDescriptor, FileState } from 'rainbow-sdk/models/common/fileDescriptor';
import { FileDescriptorEventHandlerService } from "rainbow-sdk/services/files/fileDescriptorEventHandler.service";
import { AuthService } from 'rainbow-sdk/services/core/auth.service';
import { XmppService } from 'rainbow-sdk/services/core/xmpp.service';
import { LoggerService } from 'rainbow-sdk/services/core/logger.service';
import { FileStorageCapabilities, FileStorageExternalStorage, FileStorageService } from 'rainbow-sdk/services/files/fileStorage.service';
import { ErrorHelperService } from 'rainbow-sdk/services/utilities/errorHelper.service';
