    /**
     * Method cancels the transfer for a given fileDescriptor
     * @param {string} fileDescriptorId ID of fileDescriptor transfer to cancel
     * @memberof FileServerService
     */
    public cancelCurrentFiletransfer(fileDescriptorId: string) {
        const fileDesc = this.fileStorageService.getFileDescriptorById(fileDescriptorId);
        if (fileDesc) {
            if (fileDesc.abortTransferController) fileDesc.abortTransferController.abort();
            if (fileDesc.abortXMLHttpRequestArray?.length) fileDesc.abortXMLHttpRequestArray.map((func) => { func(); });
            if (fileDesc.fileTransferSubscription) { fileDesc.fileTransferSubscription.unsubscribe(); }
            if (fileDesc.state === FileState.UPLOADING) fileDesc.state = FileState.NOT_UPLOADED;
            else if (fileDesc.state === FileState.DOWNLOADING) fileDesc.state = FileState.UPLOADED;
            fileDesc.progressSubject.next({});
        }
    }

    /**
     * This API advice client about file server constraints (maxChunkSize, maxFileSize). (API request to {@link https://api.openrainbow.org/filestorage/#api-files_server_capabilities Rainbow File Storage portal - files server capabilities - Capabilities})
     * @description
     *      Method retrieves user quota (capabilities) for user
     * @returns {Promise<FileServerCapabilities>} resolves with a {@link FileServerCapabilities} object
     * @memberof FileServerService
     */
    public async getServerCapabilities(): Promise<FileServerCapabilities> {
        try {
            await this.waitTillStarted();
            const serverUrl: URL = new URL(config.restServerUrl + "/api/rainbow/fileserver/v1.0/capabilities");
            const headers = this.authService.getRequestHeader();
            const response: Response = await fetch(serverUrl.href, { method: 'GET', headers });
            if (!response.ok) { throw (response); }
            this.capabilities = (await response.json()).data;
            if (this.capabilities.externalStorage) {
                this.fileStorageService.externalStorage = this.capabilities.externalStorage;
                this.logger.info(`[FileServerService] getServerCapabilities -- external storage server available ${this.capabilities.externalStorage.type}`);
            }
            this.logger.info(`[FileServerService] getServerCapabilities -- success`);
            return this.capabilities;
        } catch (error) {
            const errorInfo = await this.errorHelperService.getErrorInfo(error, 'getServerCapabilities');
            this.logger.error(`[fileServerService] ${errorInfo.message}`);
            throw errorInfo.error;
        }
    }

    public getFileDescriptorCapability(fileDescriptor: FileDescriptor, capability: FileStorageCapabilities): boolean {

        switch (capability) {
            case FileStorageCapabilities.THUMBNAILS:
                return fileDescriptor.isThumbnailPossible();
            case FileStorageCapabilities.SAVE:
                return !fileDescriptor.externalStorage;
            case FileStorageCapabilities.TRANSFERT:
                return !fileDescriptor.externalStorage;
            default: return false;
        }
    }
