// @ts-strict-ignore
import { XmppService } from 'rainbow-sdk/services/core/xmpp.service';
import { LoggerService } from 'rainbow-sdk/services/core/logger.service';
import { ContactService } from 'rainbow-sdk/services/core/contact.service';
import { EventService } from 'rainbow-sdk/services/core/event.service';
import { ProfileService } from 'rainbow-sdk/services/core/profile.service';
import { SettingsService } from 'rainbow-sdk/services/core/settings.service';
import { PromiseQueue } from 'rainbow-sdk/utils/promiseQueue';
import { CallDirection, CallRB, CallStatus, CallType } from 'rainbow-sdk/models/call.model';
import anonymizer from 'rainbow-sdk/utils/anonymizer';
import { Contact } from 'rainbow-sdk/models/contact.model';
import { MainService } from 'rainbow-sdk/services/core/main.service';
import { BubbleServiceRB } from '../bubbles/bubble.service';
import { MPCallState, WEBRTC_GATEWAY_SVC } from 'rainbow-sdk/services/webrtcGateway/webrtcGateway.service';
import { IOxeGroup, TelephonyService } from 'rainbow-sdk/services/telephony/telephony.service';
import { RBEvent } from 'rainbow-sdk/models/event.model';
