import { LoggerService } from 'rainbow-sdk/services/core/logger.service';
import { AuthService } from 'rainbow-sdk/services/core/auth.service';
import { Service } from 'rainbow-sdk/services/service';

export const URL_METADATA_SVC = 'UrlMetadataService';

export class UrlMetaData {

    public title: string;
    public url: string;
    public description: string;
    public image: string;

    public static create(data: any): UrlMetaData | null {
        if (!data.image || !data.image) return null;
        const metaData = new UrlMetaData();
        metaData.title = data.title;
        metaData.url = data.url;
        metaData.description = data.description;
        if (data.image.startsWith('/')) metaData.image = metaData.url + data.image;
        if (data.image.startsWith('./') || data.image.startsWith('../')) metaData.image = metaData.url + '/' + data.image;
        else metaData.image = data.image;
        return metaData;
    }

}

export interface IUrlMetadataService {
    getUrlFromString(text: string): string
    getUrlMetadata(url: string, timeout: number): Promise<UrlMetaData | null>
}

/**
 * @module
 * @name UrlMetadataService
 * @public
 * @description This service manages urlMetadata in Rainbow.
 */
export class UrlMetadataService extends Service implements IUrlMetadataService {

    private logger: LoggerService = LoggerService.getInstance();
    private authService: AuthService = AuthService.getInstance();
    private linkRegex = /(\b(https?|ftp|file):\/\/[-A-Z0-9+&@#\/%?=~_|!:,.;]*[-A-Z0-9+&@#\/%=~_|])/ig;
    private abortController: AbortController;

    /**
     * @function getInstance
     * @static
     * @private
     * @description return the urlMetaSErvice singleton
     * @returns {UrlMetadataService} the UrlMetadataService instance
     */
    public static getInstance() {
        return Service.create(URL_METADATA_SVC, UrlMetadataService);
    }

    public static build() {
        return new UrlMetadataService();
    }

    private constructor() { super(); }

    public getUrlFromString(text: string): string {
        const urls = text.match(this.linkRegex);
        return urls ? urls[0] : undefined;
    }

    public async getUrlMetadata(url: string, timeout: number = 60000): Promise<UrlMetaData | null> {
        try {
            if (this.abortController) this.abortController.abort();
            else this.abortController = new AbortController();
            setTimeout(() => { this.abortController.abort(); }, timeout);

            const serviceUrl = `${config.restServerUrl}/api/rainbow/urlmetadata/v1.0/url`;
            const headers = this.authService.getPostHeader();
            const response = await fetch(serviceUrl, {
                method: 'POST', headers,
                body: JSON.stringify({ url }),
                signal: this.abortController.signal
            });
            if (!response.ok) throw response;
            const data = (await response.json()).data;
            this.abortController = null;
            this.logger.info(`[urlMetadataService] getUrlMetadata -- success`);
            return UrlMetaData.create(data);
        }
        catch (error) {
            this.abortController = null;
            this.logger.info(`[urlMetadataService] getUrlMetadata -- failure`);
            return null;
        }
    }

    public abortUrlMetadataRequest(): void {
        this.logger.info(`[urlMetadataService] abortUrlMetadataRequest`);
        if (this.abortController) {
            this.abortController.abort();
            this.abortController = null;
        }
    }
}