const ITERATION_POLLING_SHORT = 2; //CRRAINB-24110
const TO_PILLAR_POLLING_SHORT = 15000;//CRRAINB-24110
const TO_PILLAR_POLLING_MIN = 300000;
const TO_PILLAR_POLLING_MAX = 900000;
const TO_PILLAR_POLLING_STEP = TO_PILLAR_POLLING_MAX / 500;

export const WEBRTC_GATEWAY_SVC = 'WebrtcGatewayService';

export enum MPCallState {
    Unknow = "Unknown",
    Free = "Free",
    WaitWebrtc = "WaitWebrtc",
    WaitTelephony = "WaitTelephony",
    CallOffer = "CallOffer",
    CallOnGoing = "CallOnGoing",
    CallActive = "CallActive",
    CallActiveNoWebMedia = "CallActiveNoWebMedia",
    TelCallReleasing = "TelCallReleasing",
    WebCallReleasing = "WebCallReleasing",
    RemoteControled = "RemoteControled",
    AnomalyCCS = "AnomalyCCS"
}

declare let config: any;
declare let $iq: any;

interface MediaPillarStates {
    mediaPillarConfigured: boolean;
    mediaPillarAlive: boolean;
}
// Media Pillar connection interface
interface MediaPillarConnection {
    keepAlive_TO: any; //Time Out for keepAlive
    mediaPillarJidArray: string[];
    rainbowPhoneNumber: string;
    remoteExtension: string;
    mediaPillarStatesPool: {};
}

// Media Pillar call context shell interface
interface MediaPillarCallContext {
    id: number;
    callState: MPCallState;
    callState_TO: any; //Time Out for callstate/transition
    waitTelephony_TO: any; //Time Out for waitTelephony transition,
    isOutgoingCall3PCC: boolean; //if outgoing call
    telephonyCallRefs: any[]; //tab of refs associated to telephonic calls
    webrtcCallRef: any; //pointer to associated webrtc call
    previousCallConnectionId: string; //the previously received call id in state machine
    previousCallStatus: string; //the previously received call status in state machine
    updateContactFlag: boolean; //CCRAINB-4634
    getMediaPillarJid: any;
    onGoingCallMediaPillarJid: string;//RQRAINB-6670
    callOwnerForOxoMultiClientFlag: boolean; //RQ6394
}

