    private listeners: any[] = [];
    private myContact = null;
    private mediaPillarContact = null; // 1PCC CPaaS
    private mediaPillarConfigured = false;
    private mediaPillarAlive = false;
    private evtQueue = [];
    private SEM = 0;
    private mediaPillarPollingSelected = false;

