    private TO_transition_long = 30000; //Time Out transition for long case //CRRAINB-3271
    private TO_NoWebMedia = 60000; //Time Out for webmedia lost 1mn //CRRAINB-3500
    private TO_NoWebMediaNotel = 5000; //Time Out for webmedia lost 5s //CRRAINB-6895
    private TO_PILLAR_POLLING = TO_PILLAR_POLLING_MIN; //Polling timer
    private TO_waitTelephony = 600; // short Time Out transition waiting telephony
    private mediaPillarKeepAliveSuspend = false; //Polling trigger CRRAINB-3757
    private keepAliveIterationCpt = 0; //CRRAINB-24110

    public mediaPillarConnection: MediaPillarConnection;

    // Media Pillar call context shell (only one shell used at once)
    public mediaPillarCallContext: MediaPillarCallContext;
    public mediaPillarCallContexts: MediaPillarCallContext[] = [];

    public mediaPillarCallContextId = 1;

    private isMixPstnWebRtcAllowed: boolean = false;

