    /**
     * Method mediaPillarMakeCall1PCC
     * @private
     * @param {number} phoneNumber [required] the number to join by mediaPillar
     * @param {contact} contact [optional]  the called contact if available
     * @returns {call} call : the 1PCC call object
     * @memberof WebrtcGatewayService
     * make a media pillar call 1PCC to the phoneNumber
     */
    public mediaPillarMakeCall1PCC(phoneNumber: any, contact: any): CallRB {
        this.logger.info("[WebrtcGatewayService] mediaPillarMakeCall1PCC");
        const mediaPillarJid = this.getDefaultMediaPillarJid();

        if (!this.mediaPillarConfigured || !this.mediaPillarAlive) {
            this.logger.info("[WebrtcGatewayService] mediaPillarMakeCall1PCC ANOMALY webrtcgateway not available");
            return null;
        }
        //we're making a webrtc call right now
        this.webrtcP2PService.makingCall = true;

        if (mediaPillarJid !== "") {
            const id = "web_" + crypto.randomUUID();

            if (!contact || contact === null) { //no contact provided then use predefined mediaPillarContact
                // 1PCC CPaaS ++
                //Create the call object
                const call = CallRB.create(CallStatus.DIALING, id, CallType.WEBRTC, this.mediaPillarContact);
                call.fullJid = mediaPillarJid;
                this.mediaPillarStartCall(call, phoneNumber, mediaPillarJid);
                return call;
                // 1PCC CPaaS --
            }

            //Create the call object
            const call = CallRB.create(CallStatus.DIALING, id, CallType.WEBRTC, contact);
            call.fullJid = mediaPillarJid;
            this.mediaPillarStartCall(call, phoneNumber, mediaPillarJid);
            return call;
        }
        this.logger.info("[WebrtcGatewayService] mediaPillarMakeCall ANOMALY no mediaPillarJid");
        return null;
    }
    //end mediaPillarMakeCall1PCC

    /**
     * Method mediaPillarReleaseCall1PCC
     * @private
     * @param {call} call [required] the 1PCC call to release
     * @memberof WebrtcGatewayService
     * release media pillar call 1PCC previously initiated
     */
    public mediaPillarReleaseCall1PCC(call) {
        this.logger.info("[WebrtcGatewayService] mediaPillarReleaseCall1PCC");
        if (!this.mediaPillarConfigured) {
            this.logger.info("[WebrtcGatewayService] mediaPillarReleaseCall1PCC ANOMALY webrtcgateway not available");
            return;
        }
        const foundCall = this.webrtcP2PService.calls[call.id];
        if (!foundCall || foundCall.callType !== CallType.WEBRTC) {
            this.logger.info("[WebrtcGatewayService] mediaPillarReleaseCall1PCC ANOMALY invalid call");
        } else {
            this.webrtcP2PService.terminateCall(foundCall);
        }
    }//end mediaPillarMakeCall1PCC

