    /**
     * Method isMediaPillarPoolConfigured
     * @private
     * @returns {boolean} true if at least one MP is configured (or the specified one when jid is given as parameter)
     * @memberof WebrtcGatewayService
     * @param MPJid when null check all MPs for at least one configured else check only the given MP jid
     */
    public isMediaPillarPoolConfigured(MPJid: string): boolean { //RQRAINB-6670
        let result = false;
        if (MPJid && this.mediaPillarConnection.mediaPillarStatesPool[MPJid]) {
            result = this.mediaPillarConnection.mediaPillarStatesPool[MPJid].mediaPillarConfigured;
        } else {
            const foundMPJid = this.mediaPillarConnection.mediaPillarJidArray.find((mediaPillarJid) => {
                return (this.mediaPillarConnection.mediaPillarStatesPool[mediaPillarJid] &&
                    this.mediaPillarConnection.mediaPillarStatesPool[mediaPillarJid].mediaPillarConfigured === true);
            });
            if (foundMPJid) { result = true; }
        }
        return result;
    }

    /**
     * Method isMediaPillarPoolAlive
     * @private
     * @returns {boolean} true if at least one MP is alive (or the specified one when jid is given as parameter)
     * @memberof WebrtcGatewayService
     * @param MPJid when null check all MPs for at least one alive else check only the given MP jid
     */
    public isMediaPillarPoolAlive(MPJid: string): boolean { //RQRAINB-6670
        let result = false;
        if (MPJid && this.mediaPillarConnection.mediaPillarStatesPool[MPJid]) {
            result = this.mediaPillarConnection.mediaPillarStatesPool[MPJid].mediaPillarAlive;
        } else {
            result = this.mediaPillarConnection.mediaPillarJidArray.some((mediaPillarJid) => {
                return (this.mediaPillarConnection.mediaPillarStatesPool[mediaPillarJid] &&
                    this.mediaPillarConnection.mediaPillarStatesPool[mediaPillarJid].mediaPillarAlive === true);
            });
        }
        return result;
    }

