    /**
     * Method mediaPillarReleaseWebrtcCall
     * @public
     * @memberof WebrtcGatewayService
     * release only webrtc call (not tel part)
     * @param mediaPillarCallContext
     */
    public mediaPillarReleaseWebrtcCall(mediaPillarCallContext: MediaPillarCallContext) {
        //Free web call //CRRAINB-3500
        if (mediaPillarCallContext.webrtcCallRef) {
            mediaPillarCallContext.webrtcCallRef.mediaPillarCall = null; //cut the link from call to mediapillar call context
            this.webrtcP2PService.releaseCall(mediaPillarCallContext.webrtcCallRef);
        }
    }

    /**
     * Method timeOutCallActiveNoWebMedia
     * @public
     * @memberof WebrtcGatewayService
     * @param mediaPillarCallContext
     */
    public timeOutCallActiveNoWebMedia(mediaPillarCallContext) {
        //CRRAINB-3500
        this.logger.info("[WebrtcGatewayService] timeOutCallActiveNoWebMedia");
        if (mediaPillarCallContext.callState === MPCallState.CallActiveNoWebMedia) {
            this.mediaPillarCallTerminator(mediaPillarCallContext);
            this.mediaPillarKeepAlive();
            this.logger.info("[WebrtcGatewayService] timeOutCallActiveNoWebMedia noWebMedia then release calls if existing & force keepalive");
        }
    }

    /**
     * Method mediaPillarCallTerminator
     * @public
     * @memberof WebrtcGatewayService
     * Deep release of media pillar context including release of associated calls
     * @param mediaPillarCallContext
     */
    public mediaPillarCallTerminator(mediaPillarCallContext: MediaPillarCallContext = null) {
        if (!mediaPillarCallContext) { mediaPillarCallContext = this.mediaPillarCallContext; }

        //Free the tel calls
        if (mediaPillarCallContext.telephonyCallRefs.length !== 0) {
            mediaPillarCallContext.telephonyCallRefs.forEach((callRef) => {
                if (callRef !== null && callRef.type.value === CallType.PHONE) {
                    callRef.mediaPillarCall = null; //cut the link from associated call to this mediapillar call context
                    this.telephonyService.releaseCall(callRef); //and release call
                    this.logger.info("[WebrtcGatewayService] mediaPillarCallTerminator | release call" + callRef);
                    if (this.telephonyService.isSipWise()) { //CRRAINB-37068
                        this.telephonyService.clearCall(callRef);
                    }
                }
            });
        }
        this.mediaPillarReleaseWebrtcCall(mediaPillarCallContext); //Free web call
        this.releaseMediaPillarCallContext(mediaPillarCallContext); //free mediapillar call context
        this.resetEvtAutomaton(); //reset eventing automaton
        this.TO_PILLAR_POLLING += TO_PILLAR_POLLING_MIN;
        this.mediaPillarKeepAlivePolling("START", this.TO_PILLAR_POLLING);
        this.logger.warn("[WebrtcGatewayService] mediaPillarCallTerminator | Full cleaning");
    }

