    /**
     * @param jid
     */
    private createMediaPillarContact(jid: string): any {
        this.logger.info("[webrtcGatewayService] createMediaPillarContact -- " + jid);
        const contact = this.contactService.createBasicContact(jid);
        contact.displayName = "mediaPillar";
        contact.avatar = new Image();

        if (config.sdk) {
            // unknownUser.jpeg is not available in SDK, create exception to avoid error
            contact.avatar.src = "";
        } else {
            contact.avatar.src = "/assets/skins/rainbow/images/conversations/unknownUser.jpeg";
        }

        //create also contact with bare jid for webrtc telephony (required in acceptProposition / incomingCall methods when answering mediapillar webrtc call)
        if (this.xmppService.getResourceFromJid(jid)) {
            this.contactService.createBasicContact(this.xmppService.getBareJidFromJid(jid));
        }
        return contact;
    }

