    /**
     * Retrieve and Process the telephony connections snapshot service (implemented by iq request for hybrid system)
     * @private
     * @param {boolean} secondary True for a secondary call
     * @async
     * @returns {Promise<void>} Status promise resolved when the handling is complete
     * @instance
     * @function
     */
    public async snapshotCalls(secondary: boolean): Promise<void> {

        //sipWise++
        if (this.isSipWise()) {
            this.logger.info("[telephonyService][TEL][API] snapshotCalls -- sipWise snapshot");
            try {
                await this.telephonyServiceSipWise.processSnapshot();
                return;
            } catch (error) {
                const errorMessage = "sipwise snapshotCalls -- " + error.message;
                this.logger.error("[telephonyService][TEL][API] " + errorMessage);
                throw error;
            }
        }//sipWise--

        // Create the iq request
        let iq: any;
        if (!secondary) {
            iq = $iq({ type: "get", to: this.userJidTel + "/phone" })
                .c("callservice", { xmlns: this.CALLSERVICE_NS })
                .c("connections");
        }
        else {
            iq = $iq({ type: "get", to: this.userJidTel + "/phone" })
                .c("callservice", { xmlns: this.CALLSERVICE_NS })
                .c("connections", { deviceType: "SECONDARY" });
        }

        try {
            // Send "get connections" iq
            const data = await this.xmppService.sendIQ(iq, 60000); // connections response may come after the standard 10 sec timeout : use 60 sec here

            // Handle eventual error message
            const errorMessage = this.getErrorMessage(data, "snapshotCalls");
            if (errorMessage) {
                this.logger.info("[telephonyService] snapshotCalls -- failure -- " + errorMessage);
                throw new Error(errorMessage);
            }

            let serverDeviceType: string;
            const connections = $(data).find("connections");
            if (connections.length) {
                serverDeviceType = $(connections).attr("deviceType");
            }
            serverDeviceType = serverDeviceType || "MAIN";

            // Handle existing calls on server
            const existingCalls = $(data).find("connection");

            this.logger.info("[telephonyService] [TEL][API] snapshotCalls (" + (secondary ? "SECONDARY" : "MAIN") + ") -- success -- " + existingCalls.length + " existing call(s) on server, type: " + serverDeviceType);

            if (existingCalls.length === 0) {
                // delete all client calls
                this.deleteCallsNotInList([]);
                return;
            }

            // Build existing calls
            const getCallPromises = [];
            existingCalls.each((__index: number, connection: Element) => {
                getCallPromises.push(this.createCallFromConnectionElem(connection, secondary, serverDeviceType === "SECONDARY"));
            });

            // Send all getContactPromise
            try {
                const discoveredCalls: CallRB[] = await Promise.all(getCallPromises);
                this.logger.info("[telephonyService] snapshotCalls (" + (secondary ? "SECONDARY" : "MAIN") + ") -- calls creation completed -- " + existingCalls.length + " calls created");

                // delete all client calls not present in discovered calls
                this.deleteCallsNotInList(discoveredCalls);
            }
            catch (error) {
                this.logger.error("[telephonyService] [TEL][API] snapshotCalls -- calls creation failure -- " + error.message);
                throw error;
            }

        } catch (error) {
            this.logger.error("[telephonyService] [TEL][API] snapshotCalls -- failure -- " + error.message);
            throw error;
        }
    }

    public deleteCallsNotInList(calls: CallRB[]): void {
        const callIds = (calls || []).map((call) => { return call ? call.id : ""; });
        Object.keys(this.calls || {}).forEach((key) => {
            const call = this.calls[key];

            if (call && !callIds.includes(call.id)) {
                // This current call in client does not exist on server : clear it
                this.logger.info("[telephonyService] [TEL] deleteCallsNotInList delete call " + call);

                if (call.callStatus !== CallStatus.ENDED) {
                    call.setStatus(CallStatus.ENDED);
                    call.sendEvent(CallEvents.ON_CALL_UPDATED_EVENT);
                    this.eventService.publish("ON_CALL_UPDATED_EVENT", call);
                }
                delete this.calls[call.id];
            }
        });
    }

    public async checkCallWithLostAudio(call: CallRB): Promise<void> {
        if (call.isSecondary && call.isMPAudioOwner) {
            const webrtcGatewayService = this.mainService.inject<WebrtcGatewayService>(WEBRTC_GATEWAY_SVC);
            const mpContext = webrtcGatewayService?.getMediaPillarCallContext(call);
            if (!mpContext?.webrtcCallRef) {
                // The call is secondary and had webrtc audio in our client before tel/xmpp disconnection,
                // but there is no webtrtc audio anymore after reconnection => release this "ghost" call with blank audio
                this.logger.info("[telephonyService] checkCallWithLostAudio -- release call in computer mode which has lost audio " + call);
                try {
                    await this.releaseCall(call);
                } catch (error) {
                    this.logger.error("[telephonyService] checkCallWithLostAudio -- release call error " + error);
                }
            }
        }
    }

    /**
     * Retrieve the telephony connections snapshot service, implemented by REST api request,
     * used by gatewayservice in case od parallel oxe hunting groups
     * @public
     * @param {boolean} secondary True for a secondary call
     * @async
     * @returns {Promise<any>} Promise resolved with the snaphot result data
     * @instance
     * @function
     */
    public async snapshotDevice(secondary: boolean): Promise<any> {
        //sipWise++
        if (this.isSipWise()) {
            return undefined;
        }//sipWise--

        let reqUrl = this.portalURL + "snapshotdevice";
        if (secondary) {
            reqUrl += "?deviceType=SECONDARY";
        }

        try {
            const url = reqUrl;
            const headers = this.authService.getRequestHeader();
            const response: Response = await fetch(url, { method: 'GET', headers });
            if (!response.ok) {
                throw (response);
            }
            const responseBody: any = await response.json();
            const data: any = responseBody.data;
            this.logger.info("[telephonyService] snapshotdevice success ");
            return data;
        }
        catch (error) {
            const errorInfo = await this.errorHelperService.getErrorInfo(error, 'snapshotdevice');
            this.logger.error(`[telephonyService] ${errorInfo.message}`);
            throw errorInfo.error;
        }
    }

