    /**
     * Send the answer Call service request to the server
     * Used by SDK (public)
     * Warning when modifying this method
     * @public
     * @param {Call} call The call to answer
     * @async
     * @returns {Promise<CallRB>} Promise resolved with the answered call
     * @instance
     * @function
     */
    public async answerCall(call: CallRB): Promise<CallRB> {
        this.logger.info("[telephonyService] [TEL][API] answerCall : " + call.id);

        //reject not allowed operations
        if (!this.isBasicCallAllowed) {
            const profileError: any = new Error("answerCall failure - Not Allowed");
            profileError.status = profileError.errorDetailsCode = "403";
            this.logger.error("[telephonyService] " + profileError.message);
            throw profileError;
        }

        // First hold the current active call
        const activeCall = this.getActiveCall();

        if (this.isMixPstnWebRtcAllowed && !call.webConferenceRoom) {
            //check if any active webrtc call and put it on hold before we make another call
            this.eventService.publish("PUT_ACTIVE_WEBRTC_CALL_OR_CONF_ON_HOLD", { call });
        }

        //sipWise++
        if (this.isSipWise()) { //sipWise case
            return this.telephonyServiceSipWise.answerCall(call);
        }//sipWise--

        if (call.callStatus === CallStatus.QUEUED_INCOMMING && activeCall && this.isOxe && !this.isCCDAgentEnabled()) {
            // On Oxe pbx only, in order to answer a queued call on a multiline device, we must first hold the active call before answering the queued call
            try {
                await this.holdCall(activeCall);
            }
            catch (error) {
                //we don't reject if this holdCall service has failed because it is normal on monoline devices
                //Quest: Is it possible to have a queued call on a monoline device ?
                this.logger.warn("[telephonyService] holdCall (before answerCall) failed on callId:" + activeCall.connectionId + " " + error);
            }
            try {
                // We do launch the answerCall request to the server
                return await this.doRequestAnswerCall(call);
            }
            catch (error) {
                const errorMessage = "answerCall failure : " + error.message;
                this.logger.error("[telephonyService] - callService -  " + errorMessage);
                throw new Error(errorMessage);
            }
        }
        else {
            return this.doRequestAnswerCall(call);
        }
    }

    /**
     * Send the answer Call service request to the server
     * @private
     * @param {Call} call The call to answer
     * @async
     * @returns {Promise<CallRB>} Promise resolved with the answered call
     * @instance
     * @function
     */
    private async doRequestAnswerCall(call: CallRB): Promise<CallRB> {
        try {
            const url = this.portalURL + "calls/" + encodeURIComponent(call.connectionId) + "/answer";
            const headers = this.authService.getPostHeader();
            const response: Response = await fetch(url, { method: 'PUT', headers });
            if (!response.ok) {
                throw (response);
            }
            const responseBody: any = await response.json();
            const data: any = responseBody.data;
            this.logger.info("[telephonyService] [TEL][API] answerCall - success : " + anonymizer(call.contact.displayName) + " Call (" + call + ")");
            if (this.isOxo) { //RQ6394++
                this.logger.info("[telephonyService] answerCall call id " + call.id + " -- OXO specific mng wait established");
                return call;
            }//RQ6394--
            if (call.callStatus === CallStatus.RINGING_INCOMMING || call.callStatus === CallStatus.QUEUED_INCOMMING) {
                // Update call status
                call.setConnectionId(data.callId);
                call.setStatus(CallStatus.ACTIVE);

                // Send call update event
                call.sendEvent(CallEvents.ON_CALL_UPDATED_EVENT);
                this.eventService.publish("ON_CALL_UPDATED_EVENT", call);
            } else {
                // don't modify call status if its status has changed (if it's no more a ringing incoming call)
                this.logger.info("[telephonyService] answerCall Call (" + call + ") not ringing anymore: don't modify it");
            }
            return call;
        }
        catch (error) {
            const errorInfo = await this.errorHelperService.getErrorInfo(error, 'answerCall');
            this.logger.error(`[telephonyService] [TEL][API] doRequestAnswerCall ${errorInfo.message}`);

            // UGLY ERROR MANAGMENT (NO ERROR CODE)
            if (errorInfo.error && errorInfo.error.errorDetails === "Device is not able to answer a call") {
                this.logger.info(`[telephonyService] [TEL][API] doRequestAnswerCall errorDetails ${errorInfo.error.errorDetails}`);
                this.mainService.showGlobalPopupMessage({
                    autoClose: false,
                    okLabel: "close",
                    popupTitle: "warning",
                    popupBody: "deviceDoesntAllowAnswer"
                });
            }

            // clean client call not existing on server
            this.deleteCallIfInvalid(errorInfo.error, call);

            throw errorInfo.error;
        }
    }


