    /**
     * Send the blind transfer Call service request (transfer 1 existing active call to a destination number)
     * SipWise only
     * Used by SDK (public)
     * Warning when modifying this method
     * @public
     * @param {Call} activeCall The active call to transfer: this call must have a status ACTIVE
     * @param {string} calleeNumber The destination number of the transfer
     * @param {any} [destionationObject] Destination object containing the properties "userId" and "resource",
     * which identify the destination user identifier and xmpp client resource
     * @param {Contact} [contact] destination contact (used for hybrid systems)
     * @async
     * @returns {Promise<void>} Status promise resolved when the active call is transferred
     * @instance
     * @function blindTransfertCall
     */
    public async blindTransfertCall(activeCall: CallRB, calleeNumber: string, destionationObject: any = undefined, contact: Contact = undefined): Promise<void> {
        if (!activeCall || (!calleeNumber && !destionationObject && !contact)) {
            throw new Error("[telephonyService] blindTransfertCall -- missing parameters");
        }

        if ((calleeNumber || contact) && !this.isTransferAllowed) {
            const profileError: any = new Error("[telephonyService] blind transfertCall failure - Transfer Not Allowed");
            profileError.status = profileError.errorDetailsCode = "403";
            this.logger.error("[telephonyService] " + profileError.message);
            throw profileError;
        }

        if (destionationObject && !this.isMixPstnWebRtcAllowed) {
            const profileError: any = new Error("[telephonyService] blind transfertCall failure - Mix WEBRTC_PSTN Not Allowed");
            profileError.status = profileError.errorDetailsCode = "403";
            this.logger.error("[telephonyService] " + profileError.message);
            throw profileError;
        }

        this.logger.info("[telephonyService] [TEL][API] blindTransferCall : activeCall : " + activeCall.id + " to destination: " + calleeNumber);

        if (this.isSipWise()) {
            return this.telephonyServiceSipWise.blindTransferCall(activeCall, calleeNumber, destionationObject);
        }

        // Hybrid system
        if (activeCall.callStatus !== CallStatus.ACTIVE) {
            const error: any = new Error("[telephonyService] [TEL][API] blind transfertCall failure - call not active");
            error.status = error.errorDetailsCode = "403";
            this.logger.error("[telephonyService] " + error.message);
            throw error;
        }

        let consultCall: CallRB;
        try {
            if (!contact) {
                contact = await this.contactService.getOrCreateContact(null, calleeNumber);
            }
            this.logger.debug("[telephonyService] blindTransferCall : make consultation call with activeCall : " + activeCall.id + " to destination: " + calleeNumber);
            const consultCallId: string = await this.makeConsultationCall(contact, calleeNumber, activeCall.id, undefined, undefined, true); //true to hide the consultation call
            consultCall = this.calls[consultCallId];

            this.logger.debug("[telephonyService] blindTransferCall : wait ringing state of consultation call : " + consultCallId);
            await this.waitCallState(consultCall, [CallStatus.RINGING_OUTGOING, CallStatus.QUEUED_OUTGOING, CallStatus.ACTIVE]);

            this.logger.debug("[telephonyService] blindTransferCall : transfer the calls " + activeCall.id + " and " + consultCallId);
            return await this.transfertCall(consultCall, activeCall);
        } catch (error) {
            this.logger.info("[telephonyService] [TEL][API] blindTransferCall : error" + error);
            if (consultCall) {
                this.logger.debug("[telephonyService] [TEL][API] blindTransferCall : error release consultation call " + consultCall.id);
                // if the transfer has failed, we release the possible consultation call created
                this.releaseCall(consultCall);
            }
            throw error;
        }
    }

