    /**
     * Configure forward to a device
     * @public
     * @param {string} phoneNumber phonenumber on which the call will be forwarded
     * @param {string} forwardType type of forward (immediate, busy, noreply)
     * @param {string} destId  the (optional) dest Id (a contact Id or HG id) in order to manage welcome forward
     * @param {Contact} [user] user (optional) for which the forward is modified (used by supervisors only). If not set, the user modified is the logged user
     * @async
     * @returns {Promise<void>} Status promise resolved when the process is complete
     * @instance
     * @function forwardToDevice
     */
    public async forwardToDevice(phoneNumber: string, forwardType: string, destId?: string, user?: Contact): Promise<void> {
        this.logger.info("[telephonyService] [TEL][API] forwardToDevice : " + phoneNumber + " forwardType :" + forwardType);

        //reject not allowed operations
        if (!this.isForwardEnabled) {
            const profileError: any = new Error("forwardToDevice failure - Not Allowed");
            profileError.status = profileError.errorDetailsCode = "403";
            this.logger.error("[telephonyService] " + profileError.message);
            throw profileError;
        }

        if (this.contactService.userContact.phonePro === phoneNumber || this.contactService.userContact.phoneProCan === phoneNumber || this.contactService.userContact.phonePbx === phoneNumber) {
            const errorMessage = "forwardToDevice failure: impossible to forward its own phone number";
            this.logger.error("[telephonyService] " + errorMessage);
            throw new Error(errorMessage);
        }

        //sipWise++
        if (this.isSipWise()) { //sipWise case
            try {
                let contact: Contact = this.contactService.getContactFromCacheContainsPhoneNumber(phoneNumber);
                if (!contact) {
                    contact = await this.contactService.getOrCreateContact(null, phoneNumber);
                }
                const phoneInfo = this.getPhoneInfo(contact, phoneNumber);
                let destType = "externalNumber";//as default
                forwardType = "immediate"; //as default
                let welcomeDestRef = null;
                if (destId) { //RQRAINB-9750 destId explicitely given
                    welcomeDestRef = destId;
                    destType = "internalNumber";
                    phoneNumber = phoneInfo.shortNumber;
                } else { //destId not provided only number
                    if (phoneInfo.longNumber !== "") {
                        destType = "externalNumber";
                        phoneNumber = phoneInfo.longNumber;
                    } else {
                        destType = "internalNumber";
                        phoneNumber = phoneInfo.shortNumber;
                        welcomeDestRef = contact.id; //RQRAINB-9750 the contactId (user or HG) to search the welcome service
                    }
                }
                await this.telephonyServiceSipWise.forwardToDeviceWithWelcome(welcomeDestRef, phoneNumber, destType, forwardType);//RQRAINB-9750
                return;
            }
            catch (error) {
                const errorInfo = await this.errorHelperService.getErrorInfo(error, 'forwardToDevice');
                this.logger.error(`[telephonyService] ${errorInfo.message}`);
                throw errorInfo.error;
            }
        }//sipWise--

        try {
            let contact: Contact = this.contactService.getContactFromCacheContainsPhoneNumber(phoneNumber);
            if (!contact) {
                contact = await this.contactService.getOrCreateContact(null, phoneNumber);
            }

            const phoneInfo = this.getPhoneInfo(contact, phoneNumber);
            forwardType = forwardType ? forwardType : "immediate"; //as default

            let url = "";
            if (forwardType !== "overflow_to_associated") { //standart case
                url = user ? (this.portalURL + "admin/forward/" + user.jidtel) : (this.portalURL + "forward");
            } else { //RQRAINB-8850 specific OXE immediate overflow when Rainbow client not reachable
                url = this.portalURL + "forwardOverflow";
            }
            const headers = this.authService.getPostHeader();
            const data = {
                calleeExtNumber: phoneInfo.longNumber,
                calleeIntNumber: phoneInfo.internalNumber,
                calleeShortNumber: phoneInfo.shortNumber,
                calleePbxId: phoneInfo.pbxId,
                calleeDisplayName: contact.displayName,
                forwardType: forwardType
            };
            const body = JSON.stringify(data);
            const response: Response = await fetch(url, { method: 'PUT', headers, body });
            if (!response.ok) throw response;
            this.logger.info("[telephonyService] [TEL][API] forwardToDevice - success");
        }
        catch (error) {
            const errorInfo = await this.errorHelperService.getErrorInfo(error, 'forwardToDevice');
            this.logger.error(`[telephonyService] [TEL][API] ${errorInfo.message}`);
            throw errorInfo.error;
        }
    }

    /**
     * Configure the forward to the Voicemail
     * @public
     * @param {string} [forwardType] Type of forward (immediate, busy, noreply)
     * @param {Contact} [user] user for which the forward is modified (used by supervisors only). If not set, the user modified is the logged user
     * @async
     * @returns {Promise<void>} Status promise resolved when the process is complete
     * @instance
     * @function forwardToVoicemail
     */
    public async forwardToVoicemail(forwardType?: string, user?: Contact): Promise<void> {

        this.logger.info("[telephonyService] [TEL][API] forwardToVoicemail forwardType :" + forwardType);

        if (!this.voiceMailFeatureEnabled || !this.isForwardEnabled) {
            const profileError: any = new Error("forwardToVoicemail failure - voicemail/forward feature not enabled");
            //profileError.status = profileError.errorDetailsCode = "404";
            this.logger.error("[telephonyService] " + profileError.message);
            throw profileError;
        }

        forwardType = forwardType ? forwardType : "immediate"; //as default
        //sipWise++
        if (this.isSipWise()) { //sipWise case
            const destType = "voicemail";
            try {
                await this.telephonyServiceSipWise.forwardToDeviceWithWelcome(null, this.voicemailNumber, destType, forwardType, user?.dbId);//RQRAINB-9750
                return;
            }
            catch (error) {
                const errorInfo = await this.errorHelperService.getErrorInfo(error, 'forwardToVoicemail');
                this.logger.error(`[telephonyService] ${errorInfo.message}`);
                throw errorInfo.error;
            }
        }//sipWise--

        try {
            const url = user ? (this.portalURL + "admin/forward/" + user.jidtel) : (this.portalURL + "forward");
            const headers = this.authService.getPostHeader();
            const data = {
                calleeExtNumber: "",
                calleeIntNumber: "VOICEMAILBOX",
                calleePbxId: this.pbxId,
                forwardType: forwardType
            };
            const body = JSON.stringify(data);
            const response: Response = await fetch(url, { method: 'PUT', headers, body });
            if (!response.ok) throw response;
            this.logger.info("[telephonyService] [TEL][API] forwardToVoicemail - success");
        }
        catch (error) {
            const errorInfo = await this.errorHelperService.getErrorInfo(error, 'forwardToVoicemail');
            this.logger.error(`[telephonyService] [TEL][API] ${errorInfo.message}`);
            throw errorInfo.error;
        }
    }

