    /**
     * Update the Nomadic Object with new data received
     * @public
     * @param {any} response new data received
     * @async
     * @returns {Promise<boolean>} return if the main device is nomadic configured
     * @instance
     * @function updateNomadicData
     */
    public async updateNomadicData(response: any): Promise<boolean> {
        const destination = response.destination ? anonymizer(response.destination) : "";

        this.logger.info("[telephonyService] [TEL][API] updateNomadicData destination: " + destination + " featureActivated: " + response.featureActivated +
            " makeCallInitiatorIsMain: " + response.makeCallInitiatorIsMain + " modeActivated: " + response.modeActivated + " monodevice: " +
            this.contactService.userContact.isVirtualTerm + " NomadicInitialized: " + response.nomadicModeInitialized + " otherPhoneModeDenied:" + response.otherPhoneModeDenied);

        const nomadicObjectOrg = JSON.parse(JSON.stringify(this.nomadicObject));

        this.nomadicObject.featureActivated = response.featureActivated === "true";
        this.nomadicObject.modeActivated = response.modeActivated === "true";
        this.nomadicObject.destination = response.destination;
        this.nomadicObject.makeCallInitiatorIsMain = response.makeCallInitiatorIsMain === "true";
        this.nomadicObject.otherPhoneModeDenied = response.otherPhoneModeDenied === "true";
        if (response.nomadicModeInitialized === undefined) {
            this.nomadicObject.nomadicModeInitialized = true;
        }
        else {
            this.nomadicObject.nomadicModeInitialized = response.nomadicModeInitialized === "true";
        }

        const makeCallInitiatorIsMainChanged = (nomadicObjectOrg.makeCallInitiatorIsMain !== this.nomadicObject.makeCallInitiatorIsMain);

        if (!this.nomadicAnswerNotTakedIntoAccount) {
            this.eventService.publish("ON_CALL_NOMADIC_EVENT", this.nomadicObject);
        }
        this.nomadicAnswerNotTakedIntoAccount = false;

        // By default if mobilepro or mobileperso exist, then add it on destination
        /*if (service.nomadicObject.featureActivated && (service.nomadicObject.destination === "" || service.nomadicObject.destination === undefined) && (this.contactService.userContact.mobileProCan || this.contactService.userContact.mobilePerso)) {
            var defaultNumber = this.contactService.userContact.mobileProCan ? this.contactService.userContact.mobileProCan : this.contactService.userContact.mobilePerso;
            service.nomadicLogin(defaultNumber)
                .then(() => {
                    service.nomadicLoginOnOfficePhone();
                });
        }*/

        //by default, in multidevices, if mediapillar exist, then add it on destination
        // else if by default, in multidevice, mobilepro or mobileperso exist, then add it on destination
        // by default, in monodevice, if mediapillar exist, then add it on destination
        // else if by default, in monodevice, mobilepro or mobileperso exist, then add it on destination
        if (this.nomadicObject.featureActivated && this.nomadicObject.nomadicModeInitialized && !this.nomadicObject.makeCallInitiatorIsMain && this.isMediaPillarConfigured() && this.contactService.userContact.useComputerMode && !this.contactService.userContact.useOtherPhoneMode) {
            const defaultNumber = await this.getMyMediaPillarRemoteExtensionRefreshed();
            if (this.nomadicObject.destination !== defaultNumber) {
                this.nomadicLogin(defaultNumber);
            }
        }
        else if (this.nomadicObject.featureActivated && !this.nomadicObject.nomadicModeInitialized && this.isMediaPillarConfigured() && this.contactService.userContact.useComputerMode) {
            const defaultNumber = await this.getMyMediaPillarRemoteExtensionRefreshed();
            this.nomadicLogin(defaultNumber);
        }
        else if (!this.contactService.userContact.isVirtualTerm && this.nomadicObject.featureActivated && !this.nomadicObject.nomadicModeInitialized &&
            (this.contactService.userContact.mobileProCan || this.contactService.userContact.mobilePerso) && this.contactService.userContact.useOtherPhoneMode) {
            //const defaultNumber = this.contactService.userContact.mobileProCan ? this.contactService.userContact.mobileProCan : this.contactService.userContact.mobilePerso;
            (async (): Promise<void> => {
                //await this.nomadicLogin(defaultNumber, false, true);
                //this.nomadicLoginOnOfficePhone();
                this.nomadicLogout();
            })();
        }
        else if (this.contactService.userContact.isVirtualTerm && this.nomadicObject.featureActivated && !this.nomadicObject.nomadicModeInitialized && (this.contactService.userContact.mobileProCan || this.contactService.userContact.mobilePerso) && this.contactService.userContact.useOtherPhoneMode) {
            const defaultNumber = this.contactService.userContact.mobileProCan ? this.contactService.userContact.mobileProCan : this.contactService.userContact.mobilePerso;
            this.nomadicLogin(defaultNumber);
        }
        else if (this.contactService.userContact.isVirtualTerm && this.nomadicObject.featureActivated && !this.nomadicObject.makeCallInitiatorIsMain && !this.nomadicObject.modeActivated && this.isMediaPillarConfigured() && this.contactService.userContact.useComputerMode) {
            const defaultNumber = await this.getMyMediaPillarRemoteExtensionRefreshed();
            this.nomadicLogin(defaultNumber);
        }
        return makeCallInitiatorIsMainChanged;
    }

