    /**
     * Send DTMF to a call
     * @public
     * @param {Call} call callto send a DTMF
     * @param {string} dtmf  dtmf to send
     * @async
     * @returns {Promise<any>} Promise return the dtmf status
     * @instance
     * @function sendDtmf
     */
    public async sendDtmf(call: CallRB, dtmf: string): Promise<any> {
        if (call && dtmf) {
            this.logger.info("[telephonyService] [TEL][API] sendDtmf for call " + call.id);
            //sipWise++
            if (this.isSipWise()) { //sipWise case
                await this.telephonyServiceSipWise.sendDtmf(call, dtmf);
                return undefined;
            }//sipWise--

            try {
                const url = this.portalURL + "calls/" + encodeURIComponent(call.connectionId) + "/dtmf";
                const data = { dtmf: dtmf };
                const body = JSON.stringify(data);
                const headers = this.authService.getPostHeader();
                const response: Response = await fetch(url, { method: 'PUT', headers, body });
                if (!response.ok) throw response;

                this.logger.info("[telephonyService] [TEL][API] sendDtmf - success");
                const responseData = (await response.json()).data;
                return responseData;
            }
            catch (error) {
                const errorInfo = await this.errorHelperService.getErrorInfo(error, 'sendDtmf');
                this.logger.error(`[telephonyService] [TEL][API] ${errorInfo.message}`);
                throw errorInfo.error;
            }
        }
        return undefined;
    }

    public clearCall(call: CallRB, nobroadcast: boolean = false): void {
        if (!call) {
            const errorMessage = "clearCall failure : call null";
            this.logger.error("[telephonyService]" + errorMessage);
            return;
        }
        this.logger.info("[telephonyService] clearCall for call id: " + call.id);
        call.setStatus(CallStatus.ENDED);
        if (!nobroadcast) {
            call.sendEvent(CallEvents.ON_CALL_UPDATED_EVENT);
            this.eventService.publish("ON_CALL_UPDATED_EVENT", call);
        }
        if (call.contact) { delete this.calls[call.contact.id]; }
    }

    public startAsPhoneNumber(phoneNumber: string): boolean {
        const cleanPhoneNumber = phoneNumber.trim().split(".").join("");
        if (cleanPhoneNumber.length < 1) { return false; }
        const pattern1 = /^(\+|\d|#|\*|\(|\)|\.|-|–|—|\s|\/)*$/;
        const match = cleanPhoneNumber.match(pattern1);
        if (!match) { return false; }
        return (match[0] === cleanPhoneNumber);
    }


