    /**
     * Retrieve the user's hunt groups
     * @public
     * @async
     * @returns {Promise<void>} Status promise resolved when the process is complete
     * @instance
     * @function getUserHuntGroupsConfig
     */
    public async getUserHuntGroupsConfig(): Promise<void> {

        if (this.starting || this.started) { //telephony starting or started means that the user is attached to a pbx device
            if (this.isSipWise()) {
                try {
                    this.getSipWiseUserGroups();
                    return;
                }
                catch (error) {
                    const errorInfo = await this.errorHelperService.getErrorInfo(error, 'getUserHuntGroupsConfig');
                    this.logger.error(`[telephonyService] ${errorInfo.message}`);
                    throw errorInfo.error;
                }
            } else if (!this.isOxe) { return; }

            this.logger.info("[telephonyService] [TEL][API] getUserHuntGroupsConfig for Oxe user");

            try {
                //retrieve the oxe group info
                const url: string = this.portalURL + "dynamicstate/huntinggroupinfo";
                const headers: any = this.authService.getRequestHeader();
                const response: Response = await fetch(url, { method: 'GET', headers });
                if (!response.ok) {
                    throw (response);
                }
                const responseBody: any = await response.json();
                const data: any = responseBody.data;

                if (data?.huntingGroupNumber) {
                    // user is member of a hunt group
                    if (data.huntingGroupNumber !== this.oxeUserGroupData?.huntingGroupNumber) {
                        // we don't already know the group number
                        this.oxeUserGroupData = { huntingGroupNumber: data.huntingGroupNumber, huntingGroupName: data.huntingGroupName, logged: undefined };
                    }
                    this.logger.info(`[telephonyService] getUserHuntGroupsConfig - success - huntingGroupNumber: ${data.huntingGroupNumber} huntingGroupName: ${data.huntingGroupName}`);
                } else {
                    this.oxeUserGroupData = undefined;
                    this.logger.info("[telephonyService] getUserHuntGroupsConfig - success - no hunt group associated to user");
                }
            }
            catch (error) {
                const errorInfo = await this.errorHelperService.getErrorInfo(error, 'getUserHuntGroupsConfig');
                if (errorInfo?.error?.status === 406) {
                    this.logger.info("[telephonyService] getUserHuntGroupsConfig - no hunt group associated to user");
                } else {
                    this.logger.error(`[telephonyService] ${errorInfo.message}`);
                }
                this.oxeUserGroupData = undefined;
            }

        } else {
            throw new Error("getUserHuntGroupsConfig failure - Telephony not started");
        }
    }


    /**
     * Retrieve the Dynamic State
     * @public
     * @async
     * @param {string} userJidTel Telephony jid identifier of the user for which we request the ringing state
     * (this param is optional : not used to get the logged user's ringing state; it is used
     * by an attendant to get the ringing state of a supervised user)
     * @returns {Promise<void>} Status promise resolved when the process is complete
     * @instance
     * @function getOxeDynamicState
     */
    public async getOxeDynamicState(userJidTel?: string): Promise<any> {
        this.logger.info("[telephonyService] [TEL][API] getOxeDynamicState");

        try {
            // retrieve the oxe dynamic state
            const url: URL = new URL(userJidTel ?
                (this.portalURL + "admin/dynamicstate/" + userJidTel) :
                (this.portalURL + "dynamicstate"));

            const headers: any = this.authService.getRequestHeader();
            const response: Response = await fetch(url, { method: 'GET', headers });
            if (!response.ok) {
                throw (response);
            }
            const responseBody: any = await response.json();
            const data: any = responseBody.data;

            if (!userJidTel) {
                // apply changes to our user data
                if (data.ringingActivated) {
                    this.setOxeDeskPhoneNonRinging(data.ringingActivated !== "true");
                    this.publish(RBEvent.create('onSilentRingingUpdatedEvent', this.getOxeDeskPhoneNonRinging()));
                }

                if (data.secretIdentity) { //RQRAINB-9582
                    this.setOxeSecretIdentity(data.secretIdentity === "true");
                    this.publish(RBEvent.create('onSecretIdentityUpdatedEvent', this.getOxeSecretIdentity()));
                }

                if (data.doNotDisturb) {
                    this.setOxeDoNotDisturb(data.doNotDisturb === "true");
                    this.publish(RBEvent.create('onDoNotDisturbUpdatedEvent', this.getOxeDoNotDisturb()));
                }
            }

            this.logger.info(`[telephonyService] getOxeDynamicState - success - doNotDisturb: ${data.doNotDisturb} inHuntingGroup: ${data.inHuntingGroup} lock: ${data.lock} ringingActivated: ${data.ringingActivated} secretCodeBlocked: ${data.secretCodeBlocked} secretIdentity: ${data.secretIdentity} waitingOnBusy: ${data.waitingOnBusy}`);
            return data;
        }
        catch (error) {
            const errorInfo = await this.errorHelperService.getErrorInfo(error, 'getOxeDynamicState');
            this.logger.error(`[telephonyService] ${errorInfo.message}`);
        }
        return undefined;
    }

