    /**
     * sipWiseManAssistActivat
     * @param {boolean} active true to activate the manager forward to assistant
     * @param {string} groupName Name of manager assistant group
     * @description Deprecated / former mng Assist way to activate manager forward
     * for new manager-Assistant as hunting group use instead
     */
    public sipWiseManAssistActivate(active: boolean, groupName: string = undefined): void {
        let groupNotFound = true;
        let groupId: string;
        this.logger.info("[telephonyService] [TEL][API] sipWiseManAssistActivate  Activ : " + active + " groupName : " + groupName);
        if (this.sipWiseUserGroupsData.managerAssistantNb === 0) {
            const errorMessage = "sipwise sipWiseManAssistActivate -- no Manager Assistant group available";
            this.logger.error("[telephonyService] " + errorMessage);
            return;
        }
        if (!groupName) { groupName = ""; }
        this.sipWiseUserGroupsData.sipWiseUserGroupsList.forEach((group) => {
            if (groupNotFound && group.type === "manager_assistant") {
                if (groupName === group.name || groupName === "") { //if empty groupName use the 1st found
                    groupId = group.id;
                    groupNotFound = false;
                }
            }
        });
        if (groupNotFound) {
            return;
        }
        const forwardData = { destinationType: "managersecretary", activate: active };
        this.setSipWiseUserGroupsForwards(groupId, "immediate", forwardData);
    }

    /************************* Manager-Assistant as Hunting Group STUFF *************************/
    /**
     * sipWiseManAssistAsHGJoinLeave
     * @param {string} action from {"join" or "leave"}
     * @param {string} groupId manager-assistant group id (optional)
     * @param {string} leaderId manager-assistant leader id from assistant point of view (optional)
     * @description
     */
    public async sipWiseManAssistAsHGJoinLeave(action: string = "", groupId: string = undefined, leaderId: string = undefined): Promise<any> {

        this.logger.info("[telephonyService] [TEL][API] sipWiseManAssistAsHGJoinLeave  Activ : " + action + " groupId: " + groupId + " leaderId: " + leaderId);
        //some controls
        if (!this.isSipWise()) {
            const errorMessage = "sipWiseManAssistAsHGJoinLeave -- not a sipWise situation";
            this.logger.error("[telephonyService] " + errorMessage);
            return;
        }

        if (!this.sipWiseUserGroupsData.isSomeMngAssistAsHG) {
            const errorMessage = "sipwise sipWiseManAssistAsHGJoinLeave -- no Manager Assistant group available";
            this.logger.error("[telephonyService] " + errorMessage);
            return;
        }
        if (action !== "join" && action !== "leave") {
            const errorMessage = "sipwise sipWiseManAssistAsHGJoinLeave -- invalid action";
            this.logger.error("[telephonyService] " + errorMessage);
            return;
        }
        if (groupId) {
            const found = this.sipWiseUserGroupsData.sipWiseUserGroupsList.find((group) =>
                (group.type === "hunting_group" && group.subType === "manager_assistant" && group.id === groupId)
            );
            if (!found) {
                const errorMessage = "sipwise sipWiseManAssistAsHGJoinLeave -- invalid groupId";
                this.logger.error("[telephonyService] " + errorMessage);
                return;
            }
        }
        if (leaderId) {
            const found = this.sipWiseUserGroupsData.sipWiseUserGroupsList.find((group) =>
            // eslint-disable-next-line @typescript-eslint/indent
                (group.type === "hunting_group" && group.subType === "manager_assistant" &&
                group.members[0].memberId === leaderId)
            );
            if (!found) {
                const errorMessage = "sipwise sipWiseManAssistAsHGJoinLeave -- invalid leaderId";
                this.logger.error("[telephonyService] " + errorMessage);
                return;
            }
        }
        // perform the action following situation
        if (groupId) {
            if (action === "join") {
                try {
                    await this.telephonyServiceSipWise.joinGroup(groupId, leaderId);
                    //this.eventService.publish("ON_TEL_USER_GROUPS_EVENT", this.sipWiseUserGroupsData);
                }
                catch (error) {
                    this.logger.info("[telephonyService] sipWiseManAssistAsHGJoinLeave CATCH");
                    const errorMessage = "sipwise joinGroup -- " + error.message;
                    this.logger.error("[telephonyService] " + errorMessage);
                    throw error;
                }
            } else {
                try {
                    await this.telephonyServiceSipWise.leaveGroup(groupId, leaderId);
                    //this.eventService.publish("ON_TEL_USER_GROUPS_EVENT", this.sipWiseUserGroupsData);
                }
                catch (error) {
                    this.logger.info("[telephonyService] sipWiseManAssistAsHGJoinLeave CATCH");
                    const errorMessage = "sipwise leaveGroup -- " + error.message;
                    this.logger.error("[telephonyService] " + errorMessage);
                    throw error;
                }
            }
        } else //else it is a global joinAllGroups or leaveAllgroups as manager-assistant group
            if (action === "join") {
                try {
                    await this.telephonyServiceSipWise.joinAllGroups("manager_assistant");
                    //this.eventService.publish("ON_TEL_USER_GROUPS_EVENT", this.sipWiseUserGroupsData);
                }
                catch (error) {
                    this.logger.info("[telephonyService] setSipWiseJoinAllGroups CATCH");
                    const errorMessage = "sipwise joinAllGroups -- " + error.message;
                    this.logger.error("[telephonyService] " + errorMessage);
                    throw error;
                }
            } else { //else it is a leave All group
                try {
                    await this.telephonyServiceSipWise.leaveAllGroups("manager_assistant");
                    //this.eventService.publish("ON_TEL_USER_GROUPS_EVENT", this.sipWiseUserGroupsData);
                }
                catch (error) {
                    this.logger.info("[telephonyService] setSipWiseLeaveAllGroups CATCH");
                    const errorMessage = "sipwise leaveAllGroups -- " + error.message;
                    this.logger.error("[telephonyService] " + errorMessage);
                    throw error;
                }
            }
    } //end sipWiseManAssistAsHGJoinLeave

