    public async resetAllSipWiseCall(): Promise<void> {
        /*WARNING:
            That is a servicing IQ for maintenance only,
            requesting PCG to force cleaning all ghost stucked user's calls
        */
        if (this.isSipWise()) {
            // Forge request iq
            const iq = $iq({ type: "set", to: this.userJidTel + "/pcg2" })
                .c("telephony", { xmlns: "urn:xmpp:pbxagent:telephony:1" })
                .c("service")
                .c("deleteCalls", { forced: "true" });

            try {
                // Send "get SnapshotCall" iq
                const data = await this.xmppService.sendIQ(iq, 60000);
                this.logger.error("[telephonyService] resetAllSipWiseCall : try to reset all ghost calls !" + data);
            }
            catch (error) {
                const errorMessage = "resetAllSipWiseCall failure : " + error.message;
                this.logger.error("[telephonyService]" + errorMessage);
            }
        }
    }//end resetAllSipWiseCall

