    public isRemoteControlledPhoneCallId(phoneCallId: string): boolean {
        if (!phoneCallId) return false;
        const remoteControlledCallIdsArray: string[] = Array.from(this.remoteControlledPhoneCallIds.values());
        return remoteControlledCallIdsArray.some((callId) => { return callId.includes(phoneCallId); });
    }

    public removeRemoteControlledPhoneCallId(phoneCallId: string): boolean {
        if (!phoneCallId) return false;
        const remoteControlledCallIdsArray: string[] = Array.from(this.remoteControlledPhoneCallIds.values());
        const foundCallId: string = remoteControlledCallIdsArray.find((callId) => { return callId.includes(phoneCallId); });
        if (foundCallId) {
            this.remoteControlledPhoneCallIds.delete(foundCallId);
        }
        return Boolean(foundCallId);
    }
