    public onChatMessageReceived(stanza: any): boolean {
        try {
            const stanzaElem = xmlParser(stanza);

            if (stanzaElem.find("event").length > 0 || stanzaElem.find("propose").length > 0 || stanzaElem.find("received").length > 0) {
                return true;
            }

            if (stanzaElem.find("recording").length > 0) { // intercept recording msg
                this.logger.info("[ConversationServiceEventHandler] onChatMessageReceived : recording msg case");
                this.onRecordingMessageReceived(stanza);
            }
            else if (stanzaElem.find("record").length > 0) { // intercept recording msg in conference
                //ignore this message as this is for conf V1
            }
            else {
                this.extractStanzaData(stanza)
                    .then((stanzaData: any) => {
                        if (stanzaData) {
                            if (stanzaData.body || stanzaData.additionalContent || stanzaData.oob || stanzaData.conference || stanzaData.replace || stanzaData.modified) {
                                this.logger.info("[ConversationServiceEventHandler] onChatMessageReceived");
                                this.handleChatMessage(stanzaData);
                            }
                            else if (!stanzaData.outgoingMessage && !this.contactService.isUserContact(stanzaData.participant) && stanzaData.status) {
                                this.handleStatusMessage(stanzaData.conversation, stanzaData.participant, stanza);
                            }
                            else if (stanzaData.pin) {
                                this.handlePinMessage(stanzaData);
                            }
                        }
                    });
            }
            return true;
        }
        catch (error) {
            this.logger.error("[ConversationServiceEventHandler] onChatMessageReceived ERROR " + error);
            return true;
        }
    }

    public async onErrorMessageReceived(stanza: any): Promise<void> {
        try {
            const stanzaData = await this.extractStanzaData(stanza);
            const message: Message = stanzaData.conversation.getMessageById(stanzaData.messageId);
            message.sendStatus = MessageStatus.ERROR;
            message.sendUpdateEvent();
            this.logger.info("[ConversationServiceEventHandler] onErrorMessageReceived");
        }
        catch (error) {
            this.logger.error("[ConversationServiceEventHandler] onErrorMessageReceived ERROR " + error);
        }
    }

    public onConferenceMessageReceived(stanza: any): boolean {
        this.logger.info("[ConversationServiceEventHandler] onConferenceMessageReceived");
        try {
            const stanzaElem = xmlParser(stanza);
            if (stanzaElem.find("event").length === 0) {
                this.logger.info("[ConversationServiceEventHandler] onConferenceMessageReceived ignore the message");
            }
            else {
                this.extractStanzaData(stanza).then((stanzaData: any) => {
                    if (stanzaData.conference) { this.handleChatMessage(stanzaData); }
                });
            }
            return true;
        }
        catch (error) {
            this.logger.error("[ConversationServiceEventHandler] onConferenceMessageReceived ERROR " + error);
            return true;
        }
    }

    public onRoomAdminMessageReceived(conversation: ConversationRB, contact: Contact, type: string, msgId: string, translatedMessage: any): void {

        if (type === 'StageUpdate') return;
        if (type === 'pollVote' || type === 'pollDelete') return;
        this.logger.info(`[ConversationServiceEventHandler] onRoomAdminMessageReceived of type: ${type}`);

        const message = this.conversationService.addAdminBubbleMessage(conversation, contact, new Date(), type, msgId, translatedMessage);
        this.conversationService.setStatusMessage(conversation, contact, ConversationStatus.ACTIVE);

        this.conversationService.sendAckReceivedMessage(conversation, message);

        conversation.setMissedCounter(conversation.missedCounter + 1);
        this.conversationService.sendInnerEvent(ConversationServiceInnerEvents.RAINBOW_CONVERSATION_AUTO_ACK_CHECK, { conversation, message });


        // Send conversations update event
        // this.eventService.publish("ON_CONVERSATION_MESSAGE_RECEIVED", message, conversation, false);
        // this.eventService.publish("ON_CONVERSATIONS_UPDATED_EVENT", conversation, Conversation.EventType.IM);
    }

    public onFileMessageReceived(stanza: any): boolean {
        this.logger.info("[ConversationServiceEventHandler] onFileMessageReceived");
        try {
            this.extractStanzaData(stanza)
                .then((stanzaData: any) => {
                    if (stanzaData.body) {
                        const conversation: ConversationRB = stanzaData.conversation;
                        this.conversationService.addFileMessage(conversation, stanzaData.participant, stanzaData.date, stanzaData.body, stanzaData.messageId, stanzaData.urgency);
                        this.conversationService.setStatusMessage(conversation, stanzaData.participant, ConversationStatus.ACTIVE);
                        // this.eventService.publish("ON_CONVERSATIONS_UPDATED_EVENT", conversation, Conversation.EventType.FILE);
                    }
                });
            return true;
        }
        catch (error) {
            this.logger.error("[ConversationServiceEventHandler] onFileMessageReceived ERROR " + error);
            return true;
        }
    }

    public onWebRTCMessageReceived(stanza: any): boolean {
        this.logger.info("[ConversationServiceEventHandler] onWebRTCMessageReceived");
        try {
            // Treat new call_log messages
            if (xmlParser(stanza).find("call_log").length > 0) {
                this.extractWebrtcStanzaData(stanza)
                    .then((stanzaData: any) => {
                        if (stanzaData?.body) {
                            const conversation: ConversationRB = stanzaData.conversation;
                            const message = this.conversationService.addWebRTCMessage(conversation, stanzaData.participant, stanzaData.date, stanzaData.body, stanzaData.messageId);
                            this.conversationService.setStatusMessage(conversation, stanzaData.participant, ConversationStatus.ACTIVE);
                            this.conversationService.sendAckReceivedMessage(conversation, message);

                            if (message.side === MessageSide.RIGHT || (stanzaData.state && stanzaData.state === "answered")) {
                                conversation.ackReadMessage(message);
                            }
                            else {
                                conversation.setMissedCounter(conversation.missedCounter + 1);
                                this.conversationService.sendInnerEvent(ConversationServiceInnerEvents.RAINBOW_CONVERSATION_AUTO_ACK_CHECK, { conversation, message });
                            }

                            // this.eventService.publish("ON_CONVERSATIONS_UPDATED_EVENT", conversation);
                        }
                    });
            }
            // Compatibility with old messages
            else {
                this.extractStanzaData(stanza)
                    .then((stanzaData: any) => {
                        if (stanzaData?.body) {
                            const conversation: ConversationRB = stanzaData.conversation;
                            this.conversationService.addWebRTCMessage(conversation, stanzaData.participant, stanzaData.date, stanzaData.body, stanzaData.messageId);
                            this.conversationService.setStatusMessage(conversation, stanzaData.participant, ConversationStatus.ACTIVE);
                            // this.eventService.publish("ON_CONVERSATIONS_UPDATED_EVENT", conversation);
                        }
                    });
            }
            return true;
        }
        catch (error) {
            this.logger.error("[ConversationServiceEventHandler] onWebRTCMessageReceived error " + error);
            return true;
        }
    }

