/**
 * @module RainbowSDK
 */

import { stringify } from 'flatted';

export class RBEvent<N = any, T = any> {
    public static create<N, T>(name: N, data: T = null): RBEvent<N, T> { return new RBEvent<N, T>(name, data); }

    public name: N | null = null;
    public data: T | null = null;

    /** @internal */
    constructor(name: N, data: T) {
        this.name = name;
        this.data = data;
    }

    /** @internal */
    public toString(): string {
        return `${this.name as string} ${stringify(this.data)}`;
    }
}
