import { LoggerService } from 'rainbow-sdk/services/core/logger.service';
import { DeviceManagementServiceRB } from '../deviceManagement/deviceManagement.service';
import { RBEvent, WebinarSessionParticipant } from 'rainbow-sdk/models';
import { WebinarConferenceService } from './webinarConference.service';
export class WebinarAudioMixer {

    private audioElements?: Map<WebinarSessionParticipant, HTMLAudioElement>;
    private sharingElements?: Map<WebinarSessionParticipant, HTMLAudioElement>;
    private logger: LoggerService = LoggerService.getInstance();
    private deviceManagement: DeviceManagementServiceRB = DeviceManagementServiceRB.getInstance();

    constructor(private webinarConferenceService: WebinarConferenceService) {}

    private async initialize(): Promise<void> {
        try {
            this.logger.info(`[WebinarServiceAudioMixer] initialize ()`);
            this.audioElements = new Map<WebinarSessionParticipant, HTMLAudioElement>();
            this.sharingElements = new Map<WebinarSessionParticipant, HTMLAudioElement>();
        }
        catch (error) {
            this.logger.error(`[WebinarServiceAudioMixer] initialize () - FAILURE - ${error}`);
        }
    }

    public destroy(): void {
        this.audioElements.forEach(audioElement => audioElement.pause());
        this.sharingElements.forEach(audioElement => audioElement.pause());
        this.audioElements.clear();
        this.sharingElements.clear();
        this.logger.info(`[WebinarServiceAudioMixer] destroy (audio: ${this.audioElements.size}, sharing: ${this.sharingElements.size})`);
    }

    public async addAudioStream(participant: WebinarSessionParticipant, type: 'audio'|'sharing', videoType: string = ''): Promise<void> {
        try {
            if (!this.audioElements) this.initialize();
            const stream = type === 'sharing' ? participant.sharingStream : participant.audioVideoStream;
            if (stream.getAudioTracks().length === 0) return;
            const audioOutputDevice = this.deviceManagement.getCurrentSpeaker();
            const audioElements = (type === 'audio' ? this.audioElements : this.sharingElements);
            let audioElement = audioElements.get(participant);
            if (!audioElement) {
                audioElement = new Audio();
                audioElements.set(participant, audioElement);
                this.logger.info(`[WebinarServiceAudioMixer] addAudioStream (type: ${type}${videoType}, part: ${participant.id}, audio: ${this.audioElements.size}, sharing: ${this.sharingElements.size}, stream: ${stream.id}, device: ${audioOutputDevice?.label})`);
            }
            else this.logger.info(`[WebinarServiceAudioMixer] updateAudioStream (type: ${type}${videoType}, part: ${participant.id}, audio: ${this.audioElements.size}, sharing: ${this.sharingElements.size}, stream: ${stream.id}, device: ${audioOutputDevice?.label})`);
            audioElement.srcObject = stream;
            await this.deviceManagement.setSpeakerForAudioElement(audioElement, audioOutputDevice);
            this.audioElemPlay(audioElement);
        }
        catch (error) {
            this.logger.error(`[WebinarServiceAudioMixer] addAudioStream (type: ${type}, part: ${participant.id}) - FAILURE - ${error}`);
        }
    }

    public async removeAudioStream(participant: WebinarSessionParticipant, type: 'audio'|'sharing'|'all'): Promise<void> {
        try {
            if (!this.audioElements) this.initialize();
            if (type === 'audio' || type === 'all') {
                const audioElem = this.audioElements.get(participant);
                if (audioElem) {
                    audioElem.pause();
                    this.audioElements.delete(participant);
                    this.logger.info(`[WebinarServiceAudioMixer] removeAudioStream (type: audio, part: ${participant.id}, audio: ${this.audioElements.size}, sharing: ${this.sharingElements.size})`);
                }
            }
            if (type === 'sharing' || type === 'all') {
                const sharingElement = this.sharingElements.get(participant);
                if (sharingElement) {
                    sharingElement.pause();
                    this.sharingElements.delete(participant);
                    this.logger.info(`[WebinarServiceAudioMixer] removeAudioStream (type: sharing, part: ${participant.id}, audio: ${this.audioElements.size}, sharing: ${this.sharingElements.size})`);
                }
            }
        }
        catch (error) {
            this.logger.error(`[WebinarServiceAudioMixer] removeAudioStream (type: ${type}, part: ${participant.id}) - FAILURE - ${error}`);
        }
    }

    public activateAudio(): void {
        if (!this.audioElements) this.initialize();
        this.logger.info(`[WebinarServiceAudioMixer] activateAudio ()`);
        this.audioElements?.forEach(audioElement => this.audioElemPlay(audioElement));
        this.sharingElements?.forEach(audioElement => this.audioElemPlay(audioElement));
    }

    public async updateAudioDevice(): Promise<void> {
        const audioOutputDevice = this.deviceManagement.getCurrentSpeaker();
        this.logger.info(`[WebinarServiceAudioMixer] updateAudioDevice (${audioOutputDevice?.label})`);
        if (!audioOutputDevice) return;

        this.audioElements.forEach(async (audioElement) => {
            await this.deviceManagement.setSpeakerForAudioElement(audioElement, audioOutputDevice);
            this.audioElemPlay(audioElement);
        });
        this.sharingElements.forEach(async (audioElement) => {
            await this.deviceManagement.setSpeakerForAudioElement(audioElement, audioOutputDevice);
            this.audioElemPlay(audioElement);
        });
    }

    private audioElemPlay(audioElement: HTMLAudioElement): void {
        audioElement?.play().catch(() => {
            if (!this.webinarConferenceService.isInteractEventSent) {
                this.webinarConferenceService.isInteractEventSent = true;
                this.webinarConferenceService.activeWebinarSubject.next(RBEvent.create('ON_ACTIVE_WEBINAR_NOSOUND', { webinar: this.webinarConferenceService.activeWebinar }));
            }
        });
    }
}
