
import { SettingsService } from 'rainbow-sdk/services/core/settings.service';
import { Service } from 'rainbow-sdk/services/service';

/**
 * @internal
 */
export const LOGGER_SVC = 'LoggerService';

interface ExternalLoggerInterface {
    error: (message: string, ...args: unknown[]) => void;
    warn: (message: string, ...args: unknown[]) => void;
    info: (message: string, ...args: unknown[]) => void;
    infoBlue: (message: string, ...args: unknown[]) => void;
    infoEvent: (message: string, ...args: unknown[]) => void;
    infoUser: (message: string, ...args: unknown[]) => void;
    infoOrange: (message: string, ...args: unknown[]) => void;
    log: (message: string, ...args: unknown[]) => void;
    debug: (message: string, ...args: unknown[]) => void;
    webrtc: (message: string, ...args: unknown[]) => void;
    sdk: (message: string, ...args: unknown[]) => void;
    sdkError: (message: string, ...args: unknown[]) => void;
}

enum LogLevelColor {
    trace = 'color:blue',
    debug = 'color:gray',
    info = 'color:teal',
    infoUser = 'color:darkslateblue',
    infoEvent = 'color:darkslategrey',
    infoBlue = 'color:white; background: blue',
    infoRed = 'color:white; background: red',
    infoOrange = 'color:black; background: orange',
    log = 'color:teal',
    warn = 'color:red',
    error = 'color:red',
    webrtc = 'color:green'
}

export enum LogLevelEnum {
    ERROR = 0,
    WARNING = 1,
    INFO = 2,
    DEBUG = 3
}

type LogLevel = keyof typeof LogLevelColor;

export class LoggerService extends Service implements ExternalLoggerInterface {
    /**
    * @internal
    */
    public enableConsoleLog: boolean = false;
    public logLevel: LogLevelEnum = LogLevelEnum.DEBUG;
    public logsBufferSize: number = 6000;
    private logsBuffer: string[] = [];

    private desktopMode: boolean = false;
    private externalLogger?: ExternalLoggerInterface;
    private settingsService: SettingsService = SettingsService.getInstance();

    /**
     * @internal
     */
    public static getInstance() {
        return Service.create(LOGGER_SVC, LoggerService);
    }

    /**
     * @internal
     */
    public static build() {
        return new LoggerService();
    }

    private constructor() {
        super();
        this.computeConsoleStatus();
        this.settingsService.subscribeUpdateEvent('SETTINGS_UPDATED', () => { this.computeConsoleStatus(); });
        const ua = navigator.userAgent.toLowerCase();
        this.desktopMode = ua.indexOf("qtwebengine") > -1 || ua.indexOf('electron/') > -1;
    }

    /**
     * @internal
     */
    public computeConsoleStatus(): void {
        if (this.settingsService.getSetting('fullDebugMode')) { this.logsBufferSize = 12000; }
        else { this.logsBufferSize = 6000; }

        //clear the buffer just in case
        while (this.logsBuffer.length >= this.logsBufferSize) { this.logsBuffer.shift(); }

        if (this.settingsService.getSetting('forceConsoleLog') === 'true' || localStorage.getItem('webinarOptionAutolog') === 'true') { this.enableConsoleLog = true; }
        else this.enableConsoleLog = ((window as any).config && (window as any).config.consoleLog) || false;
    }

    /**
     * @internal
     */
    public configure<T extends ExternalLoggerInterface>(externalLogger: T) { this.externalLogger = externalLogger; }

    public static makeObscure(str: string): string {
        if (str.length < 2) return str;
        return str[0] + "***" + str[str.length - 1];
    }

    public error(message: string, ...args: unknown[]): void {
        if (this.externalLogger) { this.externalLogger.error(message); }
        else { this.logger('error', message, ...args); }
    }

    public warn(message: string, ...args: unknown[]): void {
        if (this.externalLogger) { this.externalLogger.info(message); }
        else { this.logger('warn', message, ...args); }
    }

    public info(message: string, ...args: unknown[]): void {
        if (this.externalLogger) { this.externalLogger.info(message); }
        else { this.logger('info', message, ...args); }
    }

    public log(message: string, ...args: unknown[]): void {
        if (this.externalLogger) { this.externalLogger.debug(message, ...args); }
        else { this.logger('log', message, ...args); }
    }

    public debug(message: string, ...args: unknown[]): void {
        if (this.externalLogger) { this.externalLogger.debug(message, args); }
        else { this.logger('debug', message); }
    }

    /**
     * @internal
     */
    public infoEvent(message: string, ...args: unknown[]): void {
        if (this.externalLogger) { this.externalLogger.info(message, args); }
        else { this.logger('infoEvent', message, ...args); }
    }

    /**
     * @internal
     */
    public infoUser(message: string, ...args: unknown[]): void {
        if (this.externalLogger) { this.externalLogger.info(message, args); }
        else { this.logger('infoUser', message, ...args); }
    }

    /**
     * @internal
     */
    public infoBlue(message: string, ...args: unknown[]): void {
        if (this.externalLogger) { this.externalLogger.info(message, args); }
        else { this.logger('infoBlue', message, ...args); }
    }

    /**
     * @internal
     */
    public infoOrange(message: string, ...args: unknown[]): void {
        if (this.externalLogger) { this.externalLogger.info(message, args); }
        else { this.logger('infoOrange', message, ...args); }
    }

    /**
     * @internal
     */
    public infoRed(message: string, ...args: unknown[]): void {
        if (this.externalLogger) { this.externalLogger.info(message, ...args); }
        else { this.logger('infoRed', message, ...args); }
    }

    /**
     * @internal
     */
    public webrtc(message: string, ...args: unknown[]): void {
        if (this.externalLogger) { this.externalLogger.webrtc(message, args); }
        else { this.logger('info', message, ...args); }
    }

    /**
     * @internal
     */
    public sdk(message: string, ...args: unknown[]): void {
        if (this.externalLogger) { this.externalLogger.webrtc(message, ...args); }
        else { this.logger('info', `[SDK] ${message}`); }
    }

    /**
     * @internal
     */
    public sdkError(message: string, ...args: unknown[]): void {
        if (this.externalLogger) { this.externalLogger.webrtc(message, ...args); }
        else { this.logger('error', `[SDK] ${message}`, ...args); }
    }

    /**
     * @internal
     */
    public getLogs(): string[] { return this.logsBuffer; }

    /**
     * @internal
     */
    public logger(level: LogLevel, text: string, ...args: unknown[]) {

        // Compute real level
        const realLevel = this.getRealLevel(level);

        // Filter logs
        const logLevelEnum = this.getLogLevelEnum(realLevel);
        if (logLevelEnum > this.logLevel) return;

        const browserConsole: Console = console;
        if (this.desktopMode) { browserConsole[realLevel](`${realLevel.toUpperCase()} ${text}`); }
        else {
            const tzoffset = (new Date()).getTimezoneOffset() * 60000; //offset in milliseconds
            const localISOTime = (new Date(Date.now() - tzoffset)).toISOString().slice(0, -1);
            const message = `${localISOTime} ${realLevel.toUpperCase()} ${text}`;
            if (this.enableConsoleLog) {
                browserConsole[realLevel](`%c ${message}`, LogLevelColor[level], ...args);
            }
            if (this.logsBuffer.length === this.logsBufferSize) { this.logsBuffer.shift(); }
            this.logsBuffer.push(message + '\n');
        }
    }

    private getRealLevel(level: LogLevel): string {
        switch (level) {
            case 'infoRed': case 'infoOrange': case 'infoBlue': case 'infoEvent': case 'infoUser': return 'info';
            default: return level;
        }
    }

    private getLogLevelEnum(level: string): LogLevelEnum {
        switch (level) {
            case 'debug': case 'log': case 'trace': return LogLevelEnum.DEBUG;
            case 'info': return LogLevelEnum.INFO;
            case 'warning': return LogLevelEnum.WARNING;
            default: return LogLevelEnum.ERROR;
        }
    }
}
