    public async startConference(bubble: Bubble): Promise<BubbleConference> {
        try {
            if (!this.profileService.isFeatureEnabled(this.profileService.FeaturesEnum.WEBRTC_CONFERENCE_ALLOWED))
                throw Error("[WebConferenceService] createWebConference -- User does not have the profile feature WEBRTC_CONFERENCE_ALLOWED");

            const params: any = { lounge: true };
            if (this.profileService.isFeatureEnabled(this.profileService.FeaturesEnum.WEBRTC_GRID49) || this.settingsService.getBooleanSetting("grid49")) {
                this.logger.info("[WebConferenceService] createWebConference -- activate grid 49");
                params.services = ['video-compositor'];
            }
            const body = JSON.stringify(params);
            const url = `${config.restServerUrl}/api/rainbow/conference/v1.0/rooms/${bubble.dbId}/start`;
            const headers = this.authService.getPostHeader();
            const response = await fetch(url, { method: 'POST', headers, body });
            if (!response.ok) throw response;

            let webConferenceSession = this.webConferenceSessions[bubble.dbId];
            if (!webConferenceSession) {
                webConferenceSession = new WebConferenceSession(bubble.dbId, bubble as BubbleRB);
                this.webConferenceSessions[bubble.dbId] = webConferenceSession;
            }
            webConferenceSession.isMyConference = true;

            this.logger.info(`[WebConferenceService] createWebConference (id: ${webConferenceSession.id}) -- successfully`);

            return webConferenceSession;
        }
        catch (error) {
            const errorInfo = await this.errorHelperService.getErrorInfo(error, 'createWebConference');
            this.logger.error(`[WebConferenceService] -- ${errorInfo.message}`);
            delete this.webConferenceSessions[bubble.dbId];
            throw errorInfo.error;
        }
    }

    public getConference(bubble: Bubble): BubbleConference|undefined {
        let webConference = this.getWebConferenceSessionById(bubble.dbId);
        if (webConference) return webConference;
        else if (bubble.isBubbleConferenceStarted()) {
            webConference = new WebConferenceSession(bubble.dbId, bubble as BubbleRB);
            webConference.status = BubbleConferenceStatus.UNJOINED;
            if (bubble.getBubbleConferenceOwnerId() === this.contactService.userContact.dbId) webConference.isMyConference = true;
            this.webConferenceSessions[bubble.dbId] = webConference;
            return webConference;
        }
        return undefined;
    }

    /**
     * Start a web conference in the given bubble
     * @param bubble - The bubble where the user is going to start the conference
     * @returns Returns WebConference object that is related to the web conference session in that bubble
     */
    public async startWebConference(bubble: Bubble): Promise<BubbleConference> {

        if (!bubble) { throw Error("Wrong or missing parameters"); }

        if (!this.profileService.isFeatureEnabled(this.profileService.FeaturesEnum.WEBRTC_CONFERENCE_ALLOWED)) {
            throw Error("[WebConferenceService] startWebConference -- User does not have the profile feature WEBRTC_CONFERENCE_ALLOWED");
        }

        try {
            this.logger.debug("[WebConferenceService] startWebConference -- " + bubble.dbId);

            let webConferenceSession = this.webConferenceSessions[bubble.dbId];
            if (!webConferenceSession) {
                webConferenceSession = new WebConferenceSession(bubble.dbId, bubble as BubbleRB);
                this.webConferenceSessions[bubble.dbId] = webConferenceSession;
            }

            if (!webConferenceSession.localParticipant) {
                webConferenceSession.localParticipant = BubbleConferenceParticipant.create(this.contactService.userContact.dbId);
                webConferenceSession.localParticipant.contact = this.contactService.userContact;
            }

            webConferenceSession.isMyConference = true;
            webConferenceSession.haveJoined = true;
            if (webConferenceSession.status !== BubbleConferenceStatus.CONNECTING) {
                webConferenceSession.status = BubbleConferenceStatus.CONNECTING;
                this.sendEvent(BubbleConferenceServiceEvents.ON_CONFERENCE_STATUS_UPDATE, { bubbleConference: webConferenceSession, status: BubbleConferenceStatus.CONNECTING });
            }

            const params: any = {};
            if (this.profileService.isFeatureEnabled(this.profileService.FeaturesEnum.WEBRTC_GRID49) || this.settingsService.getBooleanSetting("grid49")) {
                this.logger.info("[WebConferenceService] startWebConference -- activate grid 49");
                params.services = ['video-compositor'];
            }
            const body = JSON.stringify(params);
            const url = `${config.restServerUrl}/api/rainbow/conference/v1.0/rooms/${bubble.dbId}/start`;
            const headers = this.authService.getPostHeader();
            const response = await fetch(url, { method: 'POST', headers, body });
            if (!response.ok) throw response;
            this.logger.info("[WebConferenceService] startWebConference -- successfully");
        }
        catch (error) {
            this.resetBusyStateIfNeeded();
            const errorInfo = await this.errorHelperService.getErrorInfo(error, 'startWebConference');
            this.logger.error(`[WebConferenceService] -- ${errorInfo.message}`);

            const data = {
                popupTitle: "unableToJoin",
                popupBody: "joinMeetingFailure",
                okLabel: "ok"
            };

            delete this.webConferenceSessions[bubble.dbId];

            this.mainService.showGlobalPopupMessage(data);
            throw errorInfo.error;
        }

        return this.joinWebConference(bubble);
    }

