    public sendWebConferenceEvent(name: BubbleConferenceServiceEvents, bubble: Bubble): void {
        let bubbleConference = this.getWebConferenceSessionById(bubble.dbId);
        if (name === BubbleConferenceServiceEvents.ON_CONFERENCE_ENDED) {
            if (!bubbleConference) bubbleConference = new WebConferenceSession(bubble.dbId, bubble as BubbleRB);
            bubbleConference.status = BubbleConferenceStatus.ENDED;
        }
        this.sendEvent(name, { bubbleConference: bubbleConference });
    }

