    /**
     * Add audio to an existing web conference session (ONLY IN CASE THE JOIN IS DONE VIA NOAUDIO OPTION)
     * @param webConferenceSession - the WebConferenceSession object where we want to add the media
     */
    public async addAudioToWebConferenceSession(webConferenceSession: WebConferenceSession) {
        if (webConferenceSession?.localParticipant && webConferenceSession.haveJoined && webConferenceSession.noAudio) {
            this.logger.info(`[WebConferenceService] addAudioToWebConferenceSession`);

            const mediaToGet = ["audio"];
            try {
                let stream = await this.webrtcConfigAndUtils.getBrowserMedia(mediaToGet);

                if (this.speechEnhancementService && (this.settingsService.getSetting('speechEnhancementType') !== "none" || this.settingsService.getSetting("enableSpeechEnhancement") === "true") && stream && stream.getAudioTracks().length) {
                    stream = await this.speechEnhancementService.startProcessStream(webConferenceSession.id, stream, "[WebConferenceService] addAudioToWebConferenceSession");
                }

                webConferenceSession.localStreams.push(stream);

                if (webConferenceSession.audioSession) {
                    webConferenceSession.audioSession.addStream(webConferenceSession.localStreams[0]);
                    webConferenceSession.audioSession.sendTransportReplace();

                    if (webConferenceSession.localParticipant.noMicrophone) {
                        webConferenceSession.noAudio = false;
                        this.updateParticipant(webConferenceSession, webConferenceSession.localParticipant.id, "plug");
                    }
                }
                else {
                    //user is in no audio case
                    await this.updateParticipant(webConferenceSession, webConferenceSession.localParticipant.id, "addAudio");
                    const callId = "web_" + crypto.randomUUID();
                    await this.initJingleCall(webConferenceSession.jingleJid, webConferenceSession.id, callId);
                    webConferenceSession.noAudio = false;
                }

                // try {
                //     //try to change the audio track "on the fly"
                //     await webConferenceSession.audioSession.replaceTransceiverTrack(stream.getAudioTracks()[0]);

                //     webConferenceSession.localStreams.push(stream);

                //     if (webConferenceSession.localParticipant.noMicrophone) {
                //         this.updateParticipant(webConferenceSession, webConferenceSession.localParticipant.id, "plug");
                //     }

                //     this.logger.info(`[WebConferenceService] addAudioToWebConferenceSession -- success 'on the fly'`);
                // }
                // catch {
                //     //change the audio track "on the fly" does not work, should renego the session
                //     webConferenceSession.localStreams = [];
                //     webConferenceSession.localStreams.push(stream);
                //     webConferenceSession.audioSession.addStream(webConferenceSession.localStreams[0]);
                //     webConferenceSession.audioSession.sendTransportReplace();

                //     if (webConferenceSession.localParticipant.noMicrophone) {
                //         this.updateParticipant(webConferenceSession, webConferenceSession.localParticipant.id, "plug");
                //     }

                //     this.logger.info(`[WebConferenceService] onAudioInputDeviceChange -- success 'via transport-replace'`);
                // }
            }
            catch {
                this.logger.info(`[WebConferenceService] onAudioInputDeviceChange -- audio device unplugged`);
                webConferenceSession.audioSession.removeStream();
                this.webrtcConfigAndUtils.disableAllStreamsForSession(webConferenceSession.audioSession);
                webConferenceSession.audioSession.sendTransportReplace();

                if (!webConferenceSession.localParticipant.noMicrophone) {
                    this.updateParticipant(webConferenceSession, webConferenceSession.localParticipant.id, "unplug");
                }
            }
        }
    }

    private async applyConstraintsToSharingStream(session) {
        try {
            let frameRate;
            const maxBitRate = 1500000;
            const scaleResolutionDownBy = 1;
            const stream = session.localStreams[0];
            const senderTranceiver = session.localTransceivers[0].sender;
            //check and apply contraints for sharing session
            if (stream.getAudioTracks().length) {
                frameRate = 24;
            }

            if (stream && senderTranceiver) {
                const track = stream.getVideoTracks()[0];
                // Apply scale factor and maxBitRate
                const params = senderTranceiver.getParameters();
                params.encodings[0].scaleResolutionDownBy = scaleResolutionDownBy;
                params.encodings[0].maxBitrate = maxBitRate;
                senderTranceiver.setParameters(params);

                // Apply frame rate constraints on src track
                const constraints = track.getConstraints();
                if (frameRate) constraints.frameRate = frameRate;
                await track.applyConstraints(constraints);

                this.logger.info(`[WebConferenceService] applyConstraintsToSharingStream(${scaleResolutionDownBy}, frameRate:${frameRate}fps, maxBitRate: ${maxBitRate})`);
            }
        }
        catch (error) { this.logger.error(`[WebConferenceService] applyConstraintsToSharingStream -- failure -- ${error.message}`); }
    }


