import { Plugin } from 'rainbow-sdk/plugins/plugin';
import { LoggerService } from 'rainbow-sdk/services/core/logger.service';
import { WebrtcGlobalEventHandlerService } from 'rainbow-sdk/services/webrtc/webrtcGlobalEventHandler.service';
import { WebrtcP2PService } from 'rainbow-sdk/services/webrtc/webrtcP2P.service';

export class WebRTCPlugin extends Plugin {
    public static initialize(): WebRTCPlugin {
        Plugin.initialize();

        if (!window.rainbow.plugins[WebRTCPlugin.name]) {
            const logger = LoggerService.getInstance();
            logger.info("[WebRTCPlugin] initialized");
            window.rainbow.plugins[WebRTCPlugin.name] = new WebRTCPlugin();
            WebrtcP2PService.getInstance();
            WebrtcGlobalEventHandlerService.getInstance();
        }

        return window.rainbow.plugins[WebRTCPlugin.name];
    }

    private constructor() {
        super();
    }
}
