/* eslint-disable no-case-declarations */

/**
 * @module Documents
 */

import { Service } from 'rainbow-sdk/services/service';
import { LoggerService } from '../core';
import { Bubble, Conversation, DocumentSearchOptions, RBEvent, User } from '../../models';
import { ConversationRB } from '../../models/conversation.model';
import { ConsumptionData, FileStorageService, FileStorageServiceEvents } from '../files/fileStorage.service';
import { FileDescriptor, RBError, RBErrorCode } from '../../models/common';
import { FileServerService } from '../files/fileServer.service';
import { Subject, Subscription, filter } from 'rxjs';
import { Document, DocumentEvents, DocumentRB, DocumentSearchSet, DocumentSearchSortBy, DocumentSearchSortDirection } from '../../models/document.model';
import { Contact } from '../../models/contact.model';

/**
 * @internal
 */
export const DOCUMENTS_SVC = 'DocumentsService';

/**
 * @eventProperty
 * Events fired by the DocumentsService
 */
export enum DocumentsServiceEvents {
    /**
     * @eventProperty
     * This event is fired when a document is added in the storage
     */
    ON_DOCUMENT_UPLOADED = "ON_DOCUMENT_UPLOADED",

     /**
     * @eventProperty
     * This event is fired when a document is updated (state change or viewer added/removed) in the storage
     */
    ON_DOCUMENT_UPDATED = "ON_DOCUMENT_UPDATED",

    /**
     * @eventProperty
     * This event is fired when a document is removed from the storage
     */
    ON_DOCUMENT_REMOVED = "ON_DOCUMENT_REMOVED",

    /**
     * @eventProperty
     * This event is fired when document storage consumption is updated
     */
    ON_CONSUMPTION_UPDATED = "ON_CONSUMPTION_UPDATED",

    /**
     * @eventProperty
     * This event is fired when document storage usage exceeds 90%.
     */
    ON_CONSUMPTION_WARNING = "ON_CONSUMPTION_WARNING",
}

export interface DocumentConsumptionData extends ConsumptionData {
    /** @internal */
    option?: any;
}
export interface DocumentsService {

    /**
     * This property contains the current usage status of your document storage.
     */
    consumption?: DocumentConsumptionData

    /**
     * Subscribe to updates from the service (all events are of RBEvent);
     * @param handler - The call-back function that will be subscribed to the RxJS subject
     * @param eventNames - array of event to listen
     */
    subscribe(handler: (event: RBEvent<DocumentsServiceEvents>) => any, eventNames?: DocumentsServiceEvents | DocumentsServiceEvents[]): Subscription;

    /**
     * This factory allows to create Document instance from a JavaScript File
     * @param file - the JavaScript file to manage
     * @throws an RBError (ex: RBErrorCode.STORAGE_NOT_ENOUGH_SPACE_AVAILABLE)
     */
    createDocument(file: File): Promise<Document>;

    /**
     * This method allows you to search for documents in your document storage.
     * The main search criterion is by name, but you can also leave this field empty
     * and use the criteria contained in search options
     * @param search - Used for name searches
     * @param options - Search options
     */
    searchDocuments(options?: DocumentSearchOptions): Promise<Document[]>;

    /**
     * This method retrieves the documents shared in a conversation.
     * For obvious performance reasons, it does not return the full list of documents, but a page of 1000 documents.
     * To retrieve the next page, simply call it up again.
     * @param conversation - the conversation
     */
    getConversationDocuments(conversation: Conversation): Promise<{documents: Document[], complete: boolean}>
}


/** @internal */
export class DocumentServiceRB extends Service implements DocumentsService {

    private logger: LoggerService = LoggerService.getInstance();
    private fileStorage: FileStorageService = FileStorageService.getInstance();
    private fileServer: FileServerService = FileServerService.getInstance();
    private eventSubject: Subject<RBEvent<DocumentsServiceEvents>> = new Subject<RBEvent<DocumentsServiceEvents>>();
    private subscriptions?: Subscription[];
    private documents: Record<string, Document> = {};

    public static getInstance() {
        return Service.create(DOCUMENTS_SVC, DocumentServiceRB);
    }

    public static build() {
        return new DocumentServiceRB();
    }

    private constructor() {
        super();
    }

    public async start(): Promise<void> {
        this.attachEventHandler();
    }

    public async reconnect(): Promise<void> {
        this.attachEventHandler();
    }

    public async stop(): Promise<void> {
        this.subscriptions?.forEach(subscription => { subscription.unsubscribe(); subscription = undefined; });
    }

    private attachEventHandler(): void {
        this.logger.info(`[DocumentsService] attachEventHandler()`);
        this.subscriptions?.forEach(subscription => { subscription.unsubscribe(); subscription = undefined; });
        this.subscriptions = [];
        this.subscriptions?.push(this.fileStorage.subscribe(async (event: RBEvent) => {
            switch (event.name) {
                case FileStorageServiceEvents.ON_FILE_DESCRIPTOR_RECEIVED_EVENT:
                    const document = this.documents[event.data.fileId];
                    if (document) this.sendEvent(DocumentsServiceEvents.ON_DOCUMENT_UPDATED, document);
                    else {
                        const addedDocument = await this.getDocumentById(event.data.fileId) as DocumentRB;
                        addedDocument.sendEvent(DocumentEvents.ON_UPLOADED);
                        this.sendEvent(DocumentsServiceEvents.ON_DOCUMENT_UPLOADED, addedDocument);
                    }
                    break;
                case FileStorageServiceEvents.ON_FILE_REMOVED_FROM_STORE_EVENT:
                    delete this.documents[event.data.fileId];
                    this.sendEvent(DocumentsServiceEvents.ON_DOCUMENT_REMOVED);
                    break;
                case FileStorageServiceEvents.ON_CONSUMPTION_DATA_UPDATED_EVENT:
                    this.sendEvent(DocumentsServiceEvents.ON_CONSUMPTION_UPDATED, event.data);
                    break;
                case FileStorageServiceEvents.ON_CONSUMPTION_DATA_WARNING_EVENT:
                    this.sendEvent(DocumentsServiceEvents.ON_CONSUMPTION_WARNING, event.data);
                    break;
                default: break;
            }
        }));
    }

    public subscribe(handler: (event: RBEvent<DocumentsServiceEvents>) => any, eventNames?: DocumentsServiceEvents | DocumentsServiceEvents[]): Subscription {
        const observable = eventNames ? this.eventSubject.pipe(filter((event: RBEvent<DocumentsServiceEvents>) => {
            if (eventNames instanceof Array) return eventNames.indexOf(event.name) !== -1;
            return event.name === eventNames;
        })) : this.eventSubject;

        return observable.subscribe((event: RBEvent<DocumentsServiceEvents>) => {
            try { handler(event); }
            catch (error) { this.logger.error(`[DocumentsService] subscribe () -- error -- ${error.message}`); }
        });
    }

    public sendEvent(name: DocumentsServiceEvents, data?:any): void {
        this.eventSubject.next(RBEvent.create(name, data));
    }

    public async createDocument(file: File): Promise<Document> {
        const fd = await this.fileStorage.createFileDescriptor(file);
        if (!this.fileStorage.isEnoughAvailableSpaceForFiles([fd.id])) {
            throw RBError.create("Not enough space available on storage", RBErrorCode.STORAGE_NOT_ENOUGH_SPACE_AVAILABLE);
        }
        fd.fileToSend = file;
        return this.createDocumentFromFileDescriptor(fd);
    }

    public hasEnoughSpace(document: Document): boolean {
        const documentRB = document as DocumentRB;
        this.logger.info(`[DocumentsService] hasEnoughSpace(document: ${document.id})`);
        return this.fileStorage.isEnoughAvailableSpaceForFiles([documentRB.fileDescriptor.id]);
    }

    public async uploadDocument(document: Document): Promise<Document> {
        try {
            const documentRB = document as DocumentRB;
            this.logger.info(`[DocumentsService] uploadDocument(document: ${document.id})`);
            const fileDescriptor: FileDescriptor = documentRB.fileDescriptor;
            documentRB.handleTransferProgress();
            await this.fileServer.uploadFile(fileDescriptor);
            return document;
        }
        catch (error) {
            this.logger.error(`[DocumentsService] uploadDocument(document: ${document.id}) -- failure -- ${error?.message}`);
            throw error;
        }
    }

    public async downloadDocument(document: Document): Promise<Blob> {
        try {
            const documentRB = document as DocumentRB;
            this.logger.info(`[DocumentsService] downloadDocument(document: ${document.id})`);
            documentRB.handleTransferProgress();
            return await this.fileServer.getBlobFromFileDescriptor(documentRB.fileDescriptor, true);
        }
        catch (error) {
            this.logger.error(`[DocumentsService] downloadDocument(document: ${document.id}) -- failure -- ${error?.message}`);
            throw error;
        }
    }

    public async abortDocumentTransfert(document: Document): Promise<Document> {
        const documentRB: DocumentRB = document as DocumentRB;
        this.logger.info(`[DocumentsService] abortDocumentTransfert(document: ${document.id})`);
        this.fileServer.cancelCurrentFiletransfer(documentRB.fileDescriptor.id);
        documentRB.transfertProgressSubscription?.unsubscribe();
        documentRB.transfertProgressSubscription = undefined;
        return document;
    }

    public async copyDocument(document: Document): Promise<Document> {
        try {
            const documentRB = document as DocumentRB;
            this.logger.info(`[DocumentsService] copyDocument(document: ${document.id})`);
            const copiedFileDescriptor = await this.fileStorage.copyFileToUserCloudStorage(documentRB.fileDescriptor.id);
            const copiedDocument = this.createDocumentFromFileDescriptor(copiedFileDescriptor);
            return copiedDocument;
        }
        catch (error) {
            this.logger.error(`[DocumentsService] copyDocument(document: ${document.id}) -- failure -- ${error?.message}`);
            throw error;
        }
    }

    public async deleteDocument(document: Document): Promise<void> {
        try {
            this.logger.info(`[DocumentsService] deleteDocument(document: ${document.id})`);
            const documentRB = document as DocumentRB;
            await this.fileStorage.deleteFileDescriptor(documentRB.fileDescriptor.id);
            return;
        }
        catch (error) {
            this.logger.error(`[DocumentsService] deleteDocument(document: ${document.id}) -- failure -- ${error?.message}`);
            throw error;
        }
    }

    public get consumption(): DocumentConsumptionData { return this.fileStorage.getConsumptionData(); }

    public async addDocumentViewer(document: Document, viewer: User|Bubble): Promise<void> {
        try {
            const documentRB = document as DocumentRB;
            const type = (viewer instanceof Contact) ? 'user' : 'room';
            this.logger.info(`[DocumentsService] addDocumentViewer(${viewer.dbId})`);
            const fd = await this.fileStorage.addFileViewer(documentRB.fileDescriptor.id, viewer.dbId, type);
            documentRB.fd = fd;
        }
        catch (error) {
            this.logger.error(`[DocumentsService] addDocumentViewer(${viewer.dbId}) -- failure -- ${error?.message}`);
            throw error;
        }
    }

    public async deleteDocumentViewer(document: Document, viewer: User|Bubble): Promise<void> {
        try {
            const documentRB = document as DocumentRB;
            this.logger.info(`[DocumentsService] deleteViewer(${viewer.dbId})`);
            const fd = await this.fileStorage.deleteFileViewer(viewer.dbId, documentRB.fileDescriptor.id);
            documentRB.fd = fd;
        }
        catch (error) {
            this.logger.error(`[DocumentsService] deleteViewer(${viewer.dbId}) -- failure -- ${error?.message}`);
            throw error;
        }
    }

    public async searchDocuments(searchOptions?: DocumentSearchOptions): Promise<Document[]> {
        try {
            this.logger.info(`[DocumentsService] searchDocuments()`);
            const nameFilter = searchOptions?.name ? searchOptions.name : '';
            const documentSet = searchOptions?.documentSet ? searchOptions.documentSet : DocumentSearchSet.ALL;
            const mime = searchOptions?.mime ? searchOptions.mime : '';
            const sortBy = searchOptions?.sortBy ? searchOptions.sortBy : DocumentSearchSortBy.UPLOADED_DATA;
            const sortDirection = searchOptions?.sortDirection ? searchOptions.sortDirection : DocumentSearchSortDirection.DOWN;
            const results = await this.fileStorage.searchForFilesOnServer(documentSet, nameFilter, mime, sortBy, sortDirection, 0, true, true);
            return results.fileDescriptors.map(fd => this.createDocumentFromFileDescriptor(fd));
        }
        catch (error) {
            this.logger.error(`[DocumentsService] searchDocuments() -- failure -- ${error?.message}`);
            throw error;
        }
    }

    public async getConversationDocuments(conversation: Conversation): Promise<{documents: Document[], complete: boolean}> {
        try {
            this.logger.info(`[DocumentsService] getConversationDocuments(conv: ${conversation.id})`);
            const results = await this.fileStorage.loadMoreDescriptorsForConversation(conversation as ConversationRB);
            const documents = results.fileDescriptors.map(fd => this.createDocumentFromFileDescriptor(fd));
            const complete = results.allReceived;
            return { documents, complete };
        }
        catch (error) {
            this.logger.error(`[DocumentsService] getConversationDocuments(conv: ${conversation.id}) -- failure -- ${error?.message}`);
            throw error;
        }
    }

    /* ***************************************************** */
    /* ** INTERNAL TOOLS                                  ** */
    /* ***************************************************** */

    public async getFileDescriptorUrl(fd: FileDescriptor): Promise<string> {
        return this.fileServer.getFileDescriptorUrl(fd, true, true);
    }

    public async getDocumentById(documentId: string): Promise<Document> {
        if (this.documents[documentId]) return this.documents[documentId];
        const fd = this.fileStorage.getFileDescriptorById(documentId);
        return this.createDocumentFromFileDescriptor(fd);
    }

    private createDocumentFromFileDescriptor(fd: FileDescriptor): DocumentRB {
        const document = new DocumentRB();
        document.fd = fd;
        document.handleThumbnail();
        this.documents[document.id] = document;
        return document;
    }
}

