    public onHistoryMessageReceived(stanza: any): boolean {
        try {
            this.logger.debug("[ConversationServiceHistoryHandler] onHistoryMessageReceived: " + stanza);
            let conversation = null;
            const stanzaElem = $(stanza);
            const queryId = stanzaElem.find("result").attr("queryid");
            if (queryId) {
                if (queryId.startsWith("cache_")) {
                    this.logger.info("[ConversationServiceHistoryHandler] onHistoryMessageReceived : Query Id for Cached Message");
                    let conversationId = queryId.substring(6);
                    conversationId = conversationId.substring(0, conversationId.length - 5);

                    conversation = this.conversationService.getConversationFromCache(conversationId);
                    if (conversation) {
                        this.logger.info("[ConversationServiceHistoryHandler] onHistoryMessageReceived : Conversation Found");

                        // Extract fromJid
                        let fromJid;
                        const brutJid = stanzaElem.find("forwarded message").attr("from");

                        if (brutJid && brutJid.indexOf("room_") === 0) {
                            fromJid = brutJid.split("/")[1];
                        } else {
                            fromJid = this.xmppService.getBareJidFromJid(stanzaElem.find("forwarded message").attr("from"));
                        }

                        if (!fromJid && stanzaElem.find("event").length) {
                            const roomEvent = stanzaElem.find("event").attr("name");
                            fromJid = stanzaElem.find("event").attr("jid");

                            if (roomEvent === "welcome" && conversation.bubble && conversation.bubble.owner) {
                                fromJid = conversation.bubble.owner.jid;
                            }
                        }

                        if (!fromJid) {
                            this.logger.warn("[ConversationServiceHistoryHandler] onHistoryMessageReceived - Receive message without valid fromJid information");
                            return true;
                        }

                        let from = this.contactService.getContactFromCacheByJid(fromJid);
                        const messageId = stanzaElem.find("forwarded message").attr("id");
                        const date = new Date(stanzaElem.find("forwarded delay").attr("stamp"));
                        const body = stanzaElem.find("forwarded message body").text();
                        const side = this.contactService.isUserContact(from) ? MessageSide.RIGHT : MessageSide.LEFT;

                        if (!from) {
                            this.logger.warn("[ConversationServiceHistoryHandler] onHistoryMessageReceived missing contact for jid : " + fromJid + ", ignore message");
                            from = this.contactService.createEmptyContact(fromJid);
                        }

                        const message = Message.create(messageId, date, from, side, body);
                        if (message) conversation.addMessageInCacheMessages(message);
                    }
                }
            }
            return true;
        }
        catch (error) {
            this.logger.error("[ConversationServiceHistoryHandler] onHistoryMessageReceived error -- " + error);
            return true;
        }

    }

