    public retrieveMsgByDate(conversation: ConversationRB, msgDate: any): Promise<void> {
        return new Promise((resolve, reject) => {
            // Do nothing for userContact
            if (this.contactService.isUserContact(conversation.contact)) reject();

            const queryId = `cache_${conversation.id}${this.utilitiesService.randomString(5)}`;
            this.getCommonHistoryPageAroundMsg(queryId, conversation, 1, msgDate, "after", () => {
                this.logger.info("[ConversationServiceHistoryHandler] retrieveMsgByDate finished");
                this.getCommonHistoryPageAroundMsg(queryId, conversation, 1, msgDate, "before", () => {
                    this.logger.info("[ConversationServiceHistoryHandler] retrieveMsgByDate finished");
                    resolve();
                });
            });
        });
    }

    private getCommonHistoryPageAroundMsg(queryId, conversation, size, centeredMsgDate, order, finishMethod) {
        this.logger.info("[ConversationServiceHistoryHandler] getCommonHistoryPageAroundMsg(" + queryId + ", " + size + ", " + conversation.historyIndex + ")");

        // Request for history messages for the room chat
        if (conversation.bubble) {
            const mamRequest = {
                "queryid": queryId,
                "with": this.contactService.userContact.jid,
                "max": size,
                onComplete: finishMethod
            };
            mamRequest[order] = centeredMsgDate;

            this.xmppService.connection.mam.querymuc(queryId, conversation.bubble.jid, mamRequest);
        } else {
            const mamRequest = {
                "queryid": queryId,
                "with": conversation.id,
                "max": size,
                onComplete: finishMethod
            };
            mamRequest[order] = centeredMsgDate;

            // Request for history messages for the conversation
            this.xmppService.connection.mam.query(queryId, mamRequest);
        }
    }
