import { LoggerService } from 'rainbow-sdk/services/core/logger.service';
import { AuthService } from 'rainbow-sdk/services/core/auth.service';
import { XmppService } from 'rainbow-sdk/services/core/xmpp.service';
import { MainService } from 'rainbow-sdk/services/core/main.service';
import { ErrorHelperService } from 'rainbow-sdk/services/utilities/errorHelper.service';
import { BehaviorSubject, Observable, Subscription } from 'rxjs';
import { RBEvent } from 'rainbow-sdk/models/event.model';
import { WEBINAR_SVC, WebinarService } from 'rainbow-sdk/services/webinars/webinars.service';
import { BubbleServiceEvents, BubbleServiceRB } from 'rainbow-sdk/services/bubbles/bubble.service';
import { Service } from 'rainbow-sdk/services/service';
