    /**
     * @function terminatePoll
     * @public
     * @description Terminate a Poll (changing its state to 'terminated', no one will be able to vote anymore)
     * @param poll the Poll to terminate
     * @returns the updated Poll
     */
    public async terminatePoll(poll: Poll): Promise<Poll> {
        try {
            let url = `${config.restServerUrl}/api/rainbow/enduser/v1.0/polls/${poll.id}/terminate`;
            if (this.bubbleService.context === 'webinar') url += '?context=webinar';
            const response = await fetch(url, { method: "PUT", headers: this.authService.getPostHeader(), body: poll.getVoteData() });
            if (!response.ok) throw response;
            this.logger.info(`[PollsService] terminatePoll request -- ${poll.id} -- success`);
            poll.state = 'terminated';
            poll._valueChanges.next(poll);
            return poll;
        }
        catch (error) {
            const errorInfo = await this.errorHelperService.getErrorInfo(error, "terminatePoll");
            this.logger.error(`[PollsService] ${errorInfo.message}`);
            throw errorInfo.error;
        }
    }

