    /**
     * Method deleteAllContacts
     * @description This API allows users to delete all the contacts present in its personal directory
     * @memberof PersonalDirectoryService
     * @public
     * @returns {Promise<void>} resolves when deletion is done
     * @fires PersonalDirectoryEvent#PERSONAL_DIRECTORY_DELETE_ALL
     */
    public async deleteAllPersonalContacts(): Promise<void> {
        try {
            const promiseArray: Promise<any>[] = [];

            // First, Check licence
            if (!this.personalDirectoryEnabled)
                throw Error("[PersonalDirectoryService] deleteAllPersonalContacts -- User does not have the profile feature PERSONAL_DIRECTORY");

            const getResults: any = await this.getPersonalContacts();

            this.deleteAllInProgress = true;
            getResults.contacts.forEach((persContact) => {
                promiseArray.push(this.deletePersonalContactById(persContact.id));
            });
            await Promise.all(promiseArray);
            this.deleteAllInProgress = false;

            this.logger.info(`[PersonalDirectoryService] Delete of all Personal Contacts success from server`);
            this.rxSubject.next(RBEvent.create(PersonalDirectoryEvent.PERSONAL_DIRECTORY_DELETE_ALL));
            this.eventService.publish(PersonalDirectoryEvent.PERSONAL_DIRECTORY_DELETE_ALL);

            return;

        } catch (error) {
            const errorInfo = await this.errorHelperService.getErrorInfo(error, 'deleteAllPersonalContacts');
            this.logger.error(`[PersonalDirectoryService] deleteAllPersonalContacts failure: ${errorInfo.message}`);
            throw errorInfo.error;
        }
    }

    /**
     * Method updatePersonalContactFromUserData
     * @description This API allows users to update a personal contact present in its personal directory
     * (API request to {@link https://api.openrainbow.org/directory/#api-directory-PutDirectory Rainbow Company Directory portal - directory - Update a directory entry})
     * @memberof PersonalDirectoryService
     * @public
     * @param {Contact} contact Contact instance associated to the personal directory contact to update
     * @returns {Promise<Contact>} The created personal directory contact as a Contact model
     * @fires PersonalDirectoryEvent#PERSONAL_DIRECTORY_UPDATE
     */
    public async updatePersonalContactFromUserData(contact: Contact): Promise<Contact | null> {
        try {
            const url: string = `${this.directoryPortalURL}/entries/${contact.id}`;
            const headers = this.authService.getPostHeader();

            // First, Check licence
            if (!this.personalDirectoryEnabled)
                throw Error("[PersonalDirectoryService] updatePersonalContactFromUserData -- User does not have the profile feature PERSONAL_DIRECTORY");

            // Convert the Contact into a personal directory contact as known from server
            const persDirectoryContact: any = this.createPersonalDirectoryDataFromContact(contact);

            const response: Response = await fetch(url, { method: 'PUT', headers, body: JSON.stringify(persDirectoryContact) });
            if (!response.ok) { throw (response); }
            const responseData: any = (await response.json());

            // OPEN Point: Once operation is done on server, is it mandatory to update once again the contact for security ?
            //             Indeed, the contact passed in parameter is supposed to already contain the last modifications
            // Convert the personal directory contact (server format) into a directory contact object
            const dirContact: DirectoryContact = DirectoryContact.createFromData(responseData.data);

            const contactUpdated = this.updateContactFromPersonalDirectoryData(dirContact);

            this.logger.info(`[PersonalDirectoryService] Update Personal Contact ${contactUpdated.id} success from server for user ${contactUpdated.userId}`);

            this.rxSubject.next(RBEvent.create(PersonalDirectoryEvent.PERSONAL_DIRECTORY_UPDATE, contactUpdated));
            this.eventService.publish(PersonalDirectoryEvent.PERSONAL_DIRECTORY_UPDATE, contactUpdated);

            // Useful to update the data (display name, avatar) in the favorite list
            this.favoritesService.searchAndUpdateFavoriteContact(contactUpdated);
            // Useful to eventually update the user infos on right panel
            contactUpdated.rxSubject.next({ name: 'update' });

            return contactUpdated;
        } catch (error) {
            const errorInfo = await this.errorHelperService.getErrorInfo(error, 'updatePersonalContactFromUserData');
            this.logger.error(`[PersonalDirectoryService] updatePersonalContactFromUserData failure: ${errorInfo.message}`);
            throw errorInfo.error;
        }
    }


