    /**
     * This API allows users to search personal directory contacts by specifying a pattern
     * (API request to {@link https://api.openrainbow.org/directory/#api-directory-GetDirectoryList Rainbow Company Directory portal - directory - Get a list of directory entries data})
     * @public
     * @description
     * Search contacts in the personal directory of the user by using a specified pattern to filter items.
     * This search is only available if the user has the feature PERSONAL_DIRECTORY in its profile.
     * Concerning 'extendedMode' in 'options' parameter:
     * If requested and the user has the feature SEARCH_BY_TAGS in its profile, a multi-criteria search will then be performed.
     * The multi-criteria search applies on fields firstName, lastName, jobTitle, companyName, department and tags.
     * If this option is not specified or the user does not have the feature SEARCH_BY_TAGS in his profile,
     * the search is based on names only (first name, last name and company name).
     * @param {string} searchPattern Pattern to search
     * @param {DirectorySearchOptions} [options] Search options {@link DirectorySearchOptions}
     * @returns {Promise<DirectoryInternalSearchResults[]>} Resolves with an array of {@link DirectoryInternalSearchResults} results and
     * the total number of directory items matching the criteria.
     * @memberof PersonalDirectoryService
     */
    public async searchPersonalContacts(searchPattern: string, options?: DirectorySearchOptions): Promise<DirectoryInternalSearchResults> {
        try {
            // First, Check user licence
            if (!this.personalDirectoryEnabled) {
                this.logger.debug(`[PersonalDirectoryService] searchPersonalContacts -- User does not have the profile feature PERSONAL_DIRECTORY`);
                return { contacts: [], total: 0 };
            }

            this.logger.info(`[PersonalDirectoryService] search personal contacts with pattern ${searchPattern}`);

            // Define useful search options
            const searchOptions: any = {};
            searchOptions.type = "all";
            searchOptions.view = "personal";
            searchOptions.format = "full";

            if (options?.limit) { searchOptions.limit = options.limit; }

            // Simple OR Multi criteria search ?
            const searchByTagAllowed: boolean = this.profileService.isFeatureEnabled(this.profileService.FeaturesEnum.SEARCH_BY_TAGS);
            let searchType: string = "";

            if (options?.extendedMode) {
                if (searchByTagAllowed) {
                    searchType = options.extendedMode ? "search" : "name";
                } else {
                    if (options.extendedMode) {
                        this.logger.warn(`[PersonalDirectoryService] searchPersonalContacts -- 'extendedMode' option not allowed and ignored `);
                    }
                    searchType = "name";
                }
            } else {
                searchType = "name";
            }
            if (searchType === "name") {
                searchOptions.name = searchPattern;
            } else {
                searchOptions.search = searchPattern;
            }

            // Build Request for Server
            const url: URL = new URL(`${this.directoryPortalURL}/entries`);
            const urlParams: string = new URLSearchParams(searchOptions).toString();
            const headers: any = this.authService.getRequestHeader();
            url.search = urlParams;
            const response: any = await fetch(url.toString(), { method: 'GET', headers: headers });

            if (!response.ok) { throw (response); }
            const responseData: any = (await response.json());
            const contacts: any = responseData.data;

            this.logger.info(`[PersonalDirectoryService] search success -- Found ${responseData.total} contact(s)`);

            const foundContacts: Contact[] = contacts.map((contactData) => {
                // Convert the personal directory contact (server format) into a directory contact object
                const persDirContact: DirectoryContact = DirectoryContact.createFromData(contactData);

                // Create a new Contact object or update the existing one with the retrieved personal contact
                return this.createOrUpdateContact(persDirContact);
            });
            this.logger.info(`[PersonalDirectoryService] searchPersonalContacts -- Return ${foundContacts.length} contact(s)`);

            return { contacts: foundContacts, total: responseData.total };
        } catch (error) {
            const errorInfo: ErrorHelperInfo = await this.errorHelperService.getErrorInfo(error, 'searchPersonalContacts');
            this.logger.error(`[PersonalDirectoryService] ${errorInfo.message}`);
            if (errorInfo.error.status === 403) {
                // Request rejected by server probably because of a user license problem
                // Return a "no results found" like reponse
                return { contacts: [], total: 0 };
            }
            throw errorInfo.error;
        }
    }

    /**
     * Method getPersonalDirectoryContactFromNumber
     * @memberof PersonalDirectoryService
     * @public
     * @param {string} phoneNumber The number
     * @returns {Contact} Found contact or null otherwise
     */
    public getPersonalDirectoryContactFromNumber(phoneNumber: string): Contact | null {
        // First, Check licence
        if (!this.personalDirectoryEnabled) {
            // this.logger.info(`[PersonalDirectoryService] getPersonalDirectoryContactFromNumber -- User does not have the profile feature PERSONAL_DIRECTORY`);
            return null;
        }

        const foundContactByNumber = this.contactService.getDirectoryContactByPhoneNumber(phoneNumber);
        if (foundContactByNumber) {
            // Checks if the contact is from the personal directory
            // If not the case, ignore the found contact
            if (!foundContactByNumber.personalDirectoryFlag)
                return null;

            // Check that the found contact can still be used
            // It may not be the case if the personal contact has been deleted recently, so the associated contact model set as obsolete
            if (foundContactByNumber.directoryObsolete)
                return null;

            return foundContactByNumber;
        }

        return null;
    }

