    /**
     * Method createContactFromPersonalDirectoryData
     * @description Create a new contact based on Contact model from a personal directory object (DirectoryContact)
     * @memberof PersonalDirectoryService
     * @private
     * @param {DirectoryContact} persDirContact The created personal directory contact
     * @returns {Contact} Created contact or null if creation failed
     */
    private createContactFromPersonalDirectoryData(persDirContact: DirectoryContact): Contact | null {
        const contact: Contact = this.contactService.createDirectoryContact(persDirContact.id, true);

        if (!contact) {
            this.logger.error(`[PersonalDirectoryService] createContactFromPersonalDirectoryData -- Contact creation failed for ${persDirContact.id}`);
            return null;
        }

        // Set specific data which does not come from the contact itself but useful to manage and identify
        // the personal contact in contact Model
        // These flags must be set BEFORE the update of the created contact names (via 'updateName') because some are deduced
        // from the firstname/lastname OR the company name and the contact type.
        contact.companyDirectoryFlag = false;
        contact.personalDirectoryFlag = true;
        contact.userId = persDirContact.userId;

        // Fields coming from the personal contact card
        contact.email = persDirContact.eMail;
        contact.jobTitle = persDirContact.jobTitle;
        contact.department = persDirContact.department;
        contact.companyName = persDirContact.companyName;

        contact.updateName(persDirContact.firstName, persDirContact.lastName);
        contact.setAvatarFromDefault();

        // Address
        contact.street = persDirContact.street;
        contact.city = persDirContact.city;
        contact.postalCode = persDirContact.postalCode;
        // contact.country = this.countryService.getCountryName(persDirContact.country);
        // contact.state = this.countryService.getStateName(persDirContact.country, persDirContact.state);
        contact.country = persDirContact.country;
        contact.state = persDirContact.state;

        // Phone numbers
        contact.businessPhones = persDirContact.workPhoneNumbers;
        contact.mobilePhones = persDirContact.mobilePhoneNumbers;
        contact.otherPhoneNumbers = persDirContact.otherPhoneNumbers;

        contact.note1 = persDirContact.custom1;
        contact.note2 = persDirContact.custom2;
        contact.tags = persDirContact.tags ? persDirContact.tags : [];

        return contact;
    }


    /**
     * Method updateContactFromPersonalDirectoryData
     * @description Update an existing contact with a personal directory object (DirectoryContact)
     * @memberof PersonalDirectoryService
     * @private
     * @param {DirectoryContact} persDirContact The updated personal directory object
     * @returns {Contact} Updated contact or null if update failed
     */
    private updateContactFromPersonalDirectoryData(persDirContact: DirectoryContact): Contact | null {
        const contact: Contact = this.contactService.getContactFromCacheByJid(persDirContact.id);

        if (!contact) {
            this.logger.error(`[PersonalDirectoryService] updateContactFromData -- Unable to find contact for ${persDirContact.id} for update`);
            return null;
        }

        // Set contact type (this data should not have been modified but for security only)
        contact.companyDirectoryFlag = false;
        contact.personalDirectoryFlag = true;
        // Allows an exiting personal contact to be valid again after a new complete retrieval of the contacts from the server
        contact.directoryObsolete = false;
        contact.userId = persDirContact.userId;

        // Fields coming from the personal contact card
        contact.email = persDirContact.eMail;
        contact.jobTitle = persDirContact.jobTitle;
        contact.department = persDirContact.department;
        contact.companyName = persDirContact.companyName;

        contact.updateName(persDirContact.firstName, persDirContact.lastName);
        contact.setAvatarFromDefault();

        // Address
        contact.street = persDirContact.street;
        contact.city = persDirContact.city;
        contact.postalCode = persDirContact.postalCode;
        // contact.country = this.countryService.getCountryName(persDirContact.country);
        // contact.state = this.countryService.getStateName(persDirContact.country, persDirContact.state);
        contact.country = persDirContact.country;
        contact.state = persDirContact.state;

        // Phone numbers
        contact.businessPhones = persDirContact.workPhoneNumbers;
        contact.mobilePhones = persDirContact.mobilePhoneNumbers;
        contact.otherPhoneNumbers = persDirContact.otherPhoneNumbers;

        contact.note1 = persDirContact.custom1;
        contact.note2 = persDirContact.custom2;
        contact.tags = persDirContact.tags ? persDirContact.tags : [];

        return contact;
    }

    /**
     * Method createOrUpdateContact
     * @description Create or update an existing contact with a personal directory object (DirectoryContact)
     * @memberof PersonalDirectoryService
     * @private
     * @param {DirectoryContact} persDirContact A personal directory object just retrieved from server
     * @returns {Contact} Created or Updated contact
     */
    private createOrUpdateContact(persDirContact: DirectoryContact): Contact | null {
        // Create  a new Contact object or update the existing one with the retrieved personal contact
        const existingContact: Contact = this.contactService.getContactFromCacheByJid(persDirContact.id);

        if (existingContact) {
            const updatedContact: Contact = this.updateContactFromPersonalDirectoryData(persDirContact);
            return updatedContact;
        }
        // Else Contact creation
        const createdContact: Contact = this.createContactFromPersonalDirectoryData(persDirContact);
        return createdContact;
    }


    /**
     * Method createPersonalDirectoryDataFromContact
     *
     * Create a personal directory object (DirectoryContact) from a contact based on Contact model
     * Useful to update on server side a personal directory contact from data stored in a contact
     * @memberof PersonalDirectoryService
     * @private
     * @param {Contact} contactData The contact associated to the given personal directory
     * @returns {DirectoryContact} Personal directory contact object used for update on server side
     */
    private createPersonalDirectoryDataFromContact(contactData: Contact): DirectoryContact {
        const persDirectoryContact = new DirectoryContact("personal");

        // Fields coming from the personal contact card
        persDirectoryContact.firstName = contactData.firstname;
        persDirectoryContact.lastName = contactData.lastname;
        persDirectoryContact.eMail = contactData.email;
        persDirectoryContact.jobTitle = contactData.jobTitle;
        persDirectoryContact.department = contactData.department;
        persDirectoryContact.companyName = contactData.companyName;

        // Address
        persDirectoryContact.street = contactData.street;
        persDirectoryContact.city = contactData.city;
        persDirectoryContact.postalCode = contactData.postalCode;

        // persDirectoryContact.country = this.countryService.getCountryCodeFromName(contactData.country);
        persDirectoryContact.country = contactData.country;
        persDirectoryContact.state = this.countryService.getStateCodeFromName(contactData.country, contactData.state);

        // Phone numbers
        persDirectoryContact.workPhoneNumbers = contactData.businessPhones;
        persDirectoryContact.mobilePhoneNumbers = contactData.mobilePhones;
        persDirectoryContact.otherPhoneNumbers = contactData.otherPhoneNumbers;

        persDirectoryContact.custom1 = contactData.note1;
        persDirectoryContact.custom2 = contactData.note2;
        persDirectoryContact.tags = contactData.tags;

        return persDirectoryContact;
    }

