    /********************************************************/
    /** EXPORT CSV FILE PERSONAL DIRECTORY                 **/
    /********************************************************/

    public async exportPersonalDirectory(): Promise<any> {
        this.logger.info(`[PersonalDirectoryService] >exportPersonalDirectory`);

        try {
            // Build Request for Server
            const url: URL = new URL(this.massProPortalURL + "directories/synchronize");
            const headers: any = this.authService.getRequestHeader();
            const response: any = await fetch(url.toString(), { method: 'GET', headers: headers});

            if (!response.ok) { throw (response); }

            const dataResult: any = await response.json();

            let csvContent = '';
            const keys = [];
            if (dataResult.data.length > 0) {
                let keyIndex = 0;
                dataResult.data.forEach((entry) => {
                    for (const [key, value] of Object.entries(entry)) {
                        if (keys.indexOf(key) === -1) {
                            keys.push(key);
                            if (keyIndex > 0) csvContent += ";";
                            csvContent += key;
                            keyIndex++;
                        }
                    }
                });

                dataResult.data.forEach((csvLine) => {
                    csvContent += "\n";
                    keys.forEach((key, index) => {
                        if (index > 0) csvContent += ";";
                        if (csvLine[key] !== undefined) csvContent += csvLine[key];
                    });
                });
            }
            const exportDataBlob = new Blob([csvContent], { type: 'text/csv;charset=utf-8,' });

            this.logger.info(`[PersonalDirectoryService] GET Personal Directory Success`);

            return exportDataBlob;

        } catch (error) {
            const errorInfo: ErrorHelperInfo = await this.errorHelperService.getErrorInfo(error, "exportPersonalDirectory");
            this.logger.error(`[PersonalDirectoryService] Export Personal Directory failure -- ${errorInfo.error.message}`);
            if (error.data && error.data.errorCode === 401) {
                this.rxSubject.next(RBEvent.create('ON_SESSION_EXPIRED_NOTIFICATION_EVENT'));
            }
            throw errorInfo.error;
        }
    }

