/* eslint-disable @typescript-eslint/no-unsafe-return */
/**
 * @module RainbowSDK
 */
import { Service } from "rainbow-sdk/services/service";
import {v4 as uuidv4 } from 'uuid';


/** @internal */
export const UTILITIES_SVC = 'UtilitiesService';

export class UtilitiesService extends Service {
    /**
     * @internal
     * */
    public static getInstance() {
        return Service.create(UTILITIES_SVC, UtilitiesService);
    }

    /**
     * @internal
     * */
    public static build() {
        return new UtilitiesService();
    }

    private rtlDirCheck: RegExp;
    private usableRandomChars: string;

    private constructor() {
        super();
        const rtlChars = '\u0591-\u07FF\u200F\u202B\u202E\uFB1D-\uFDFD\uFE70-\uFEFC';
        this.rtlDirCheck = new RegExp('^[^' + rtlChars + ']*?[' + rtlChars + ']');
        this.usableRandomChars = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz";
    }

    /**
     * @internal
     * */
    public async asyncForEach(array: any[], callback: any) {
        for (let i = 0; i < array.length; i++) {
            await callback(array[i], i, array);
        }
    }

    /**
     * @internal
     * */
    public isRTL(str: string): boolean {
        return this.rtlDirCheck.test(str.charAt(0));
    }

    /**
     * @internal
     * */
    public randomString(length: number = 10): string {
        let outString: string = "";
        let rnd: number;
        while (length > 0) {
            rnd = Math.floor(Math.random() * this.usableRandomChars.length);
            outString += this.usableRandomChars.charAt(rnd);
            length--;
        }
        return outString;
    }


    /**
     * @internal
     * */
    public getUUID(): string {
        return uuidv4();
    }

    /**
     * @internal
     * */
    public addUrlParameter(url: string, urlParameter) {
        if (!url.includes("?")) url += "?";
        else url += "&";
        url += urlParameter;

        return url;
    }

    /**
     * @internal
     * */
    public isNumeric(str: any): boolean {
        if (typeof str !== "string") return false;

        return !isNaN(parseFloat(str));
    }

    /**
     * @internal
     * */
    public asyncTimeout(ms: number) {
        return new Promise(resolve => setTimeout(resolve, ms));
    }

    /**
     * @internal
     * */
    public selectRandomly(possibilities: any[]) {
        const random = Math.floor(Math.random() * possibilities.length);
        return possibilities[random];
    }

    /**
     * @internal
     * */
    public arrayMove(arr: any[], oldIndex: number, newIndex: number) {
        while (oldIndex < 0) {
            oldIndex += arr.length;
        }
        while (newIndex < 0) {
            newIndex += arr.length;
        }
        if (newIndex >= arr.length) {
            let k = newIndex - arr.length + 1;
            while (k--) {
                arr.push(undefined);
            }
        }
        arr.splice(newIndex, 0, arr.splice(oldIndex, 1)[0]);
    }

    /**
     * @internal
     * */
    public removeSpecialChars(initialStr: string): string {
        return initialStr.replace(/[^a-zA-Z0-9 ]/g, '');
    }

    public async getBase64Image(url: string): Promise<string> {
        return new Promise((resolve) => {
            const image = new Image();
            image.crossOrigin = 'anonymous';
            const canvas = document.createElement('canvas');
            image.onload = () => {
                canvas.width = image.width;
                canvas.height = image.height;
                const ctx = canvas.getContext('2d');
                ctx?.drawImage(image, 0, 0);
                resolve(canvas.toDataURL("image/png"));
            };
            image.src = url;
        });
    }
}

export const asyncForEach = async (array: any[], callback: any) => {
    for (let i = 0; i < array.length; i++) {
        await callback(array[i], i, array);
    }
};
