    public get phoneNumbers(): UserPhoneNumber[] {
    // public phoneNumbers(): any[] {
        //shit got real :)
        const phoneNumbers: UserPhoneNumber[] = [];

        // BUSINESS phone number
        if (this.phonePbx && !this.phonePro) {
            phoneNumbers.push({type: PhoneNumberType.BUSINESS, number: this.phonePbx });
        }
        if (this.phonePro && this.phoneProCan) {
            phoneNumbers.push({type: PhoneNumberType.BUSINESS, number: this.phoneProCan });
        }
        if (this.businessPhones?.length) {
            this.businessPhones.forEach((businessPhone) => {
                if (businessPhone?.length > 0) { phoneNumbers.push({type: PhoneNumberType.BUSINESS, number: businessPhone }); }
            });
        }

        // BUSINESS MOBILE phone number
        if (this.mobilePro && this.mobileProCan) {
            phoneNumbers.push({type: PhoneNumberType.BUSINESS_MOBILE, number: this.mobileProCan, shared: this.isMobileProShared });
        }
        if (this.mobilePhones?.length) {
            this.mobilePhones.forEach((mobilePhone) => {
                if (mobilePhone?.length > 0) { phoneNumbers.push({type: PhoneNumberType.BUSINESS_MOBILE, number: mobilePhone }); }
            });
        }

        // BUSINESS INTERNAL phone number
        if (this.phoneInternalNumber) {
            phoneNumbers.push({type: PhoneNumberType.BUSINESS_INTERNAL, number: this.phoneInternalNumber});
        }

        //  PERSONAL phone number
        if (this.phonePerso && this.phonePersoCan) {
            phoneNumbers.push({type: PhoneNumberType.PERSONAL, number: this.phonePersoCan, shared: this.isPhonePersoShared });
        }

        //  PERSONAL MOBILE phone number
        if (this.mobilePerso && this.mobilePersoCan) {
            phoneNumbers.push({type: PhoneNumberType.PERSONAL_MOBILE, number: this.mobilePersoCan, shared: this.isMobilePersoShared });
        }

        // OTHER numbers (Business Directory contact)
        if (this.otherPhoneNumbers?.length && this.otherPhoneNumbers?.forEach) {
            this.otherPhoneNumbers.forEach((otherPhone) => {
                if (otherPhone?.length > 0) { phoneNumbers.push({type: PhoneNumberType.OTHER, number: otherPhone }); }
            });
        }

        return phoneNumbers;
    }

