    // -- AVATAR STUFF
    // --------------------------------
    public getAvatarInBase64() {
        return new Promise(resolve => {
            try {
                if (!this.avatar?.src) {
                    resolve(undefined);
                }
                if (this.avatar.src && !this.avatar.src.startsWith("data:image/png")) {
                    const img = new Image();
                    const canvas = document.createElement("canvas");
                    canvas.width = 120;
                    canvas.height = 120;
                    const ctx = canvas.getContext("2d");
                    ctx.rect(0, 0, 120, 120);
                    ctx.fillStyle = this.color;
                    ctx.fill();
                    img.onload = () => {
                        ctx.drawImage(img, 0, 0, 120, 120);
                        resolve(canvas.toDataURL("image/png"));
                    };
                    img.src = this.avatar.src;
                } else {
                    resolve(this.avatar.src);
                }
            } catch (error) {
                resolve(undefined);
            }
        });
    }

    public dateEncode(date: string): string {
        return Array.from(date).reduce((buf: string, char: string) => { buf += char.charCodeAt(0).toString(16); return buf; }, '');
    }

    public createAvatar(size: number = 256, forced: boolean = false) {
        const isDirectoryContact: boolean = (this.o365Flag || this.companyDirectoryFlag || this.outlookFlag || this.personalDirectoryFlag);

        // Directory contacts have no avatar managed by the below API
        // Check has been therefore added to avoid breaking the default avatar based on the contact's initials.
        if (this.dbId && this.lastAvatarUpdateDate && !isDirectoryContact) {
            this.avatarSrc = `${this.avatarServerURL}/api/avatar/${this.dbId}?size=${size}&update=${this.dateEncode(this.lastAvatarUpdateDate)}`;
            if (this.avatar) this.avatar = { src: this.avatarSrc };
        }

        this.createTextAvatarImage();

        // If this is a Rainbow TV, get the avatar from local sources
        if (this.isTv) {
            this.defaultAvatar = { src: "/assets/skins/rainbow/images/misc/androidtv.svg" };
        }

        // If the displayname refers to a phone number (unknown external number or number without name resolution),
        // we will not use the default avatar built from this number (so containing for example '+' or a digit)
        // but we override it with the 'unknownUser' avatar.
        let isDisplayNamePhoneNumber: boolean = false;
        isDisplayNamePhoneNumber = this.startAsPhoneNumber(this.displayName);
        if (isDisplayNamePhoneNumber || this.displayName === "Anonymous") {
            this.defaultAvatar = { src: "/assets/skins/rainbow/images/conversations/unknownUser.jpeg" };
        }

        if (forced || !this.lastAvatarUpdateDate) {
            this.avatar = null;
        }
    }

    public createTextAvatarImage() {
        const image = new Image();
        const canvas = document.createElement("canvas");
        canvas.width = image.width = 225;
        canvas.height = image.height = 225;

        const ctx = canvas.getContext("2d");
        ctx.rect(0, 0, 225, 225);
        ctx.fillStyle = this.color;
        ctx.fill();
        ctx.font = "bold 100px Helvetica";
        ctx.textAlign = "center";
        ctx.fillStyle = "white";
        ctx.fillText(this.initials, 110, 150);
        image.src = canvas.toDataURL("image/png");
        this.defaultAvatar = image;
    }

    /**
     * @function setAvatarFromDefault
     * @description Set the 'avatar' with the current value of the default avatar
     * This is mainly useful for personal and business contacts for which no avatar can be defined at the moment.
     * Only the default avatar is available for them, based on the initials of lastname/firstname or company name
     * To take into account that the default avatar data can be changed later by the phone in a call situation,
     * (following an update of the display name), the default avatar also becomes the real avatar (until we can specify one)
     * @public
     */
    public setAvatarFromDefault() {
        this.avatar = this.defaultAvatar;
        this.lastAvatarUpdateDate = new Date();
    }

    //  NAME STUFF
    // --------------------------------
    public updateName(firstName: string, lastName: string): void {
        this.firstname = firstName;
        this.lastname = lastName;
        this.computeDisplayName();
        this.createAvatar();
    }

    public computeDisplayName() {
        const firstName = this.firstname ? this.firstname.charAt(0).toUpperCase() + this.firstname.slice(1) : null;
        const lastName = this.lastname ? this.lastname.charAt(0).toUpperCase() + this.lastname.slice(1) : null;
        const nickName = this.nickname ? this.nickname.charAt(0).toUpperCase() + this.nickname.slice(1) : null;

        if (this.isTv) {
            this.displayName = lastName;
            this.initials = this.displayName.charAt(0);
        } else if (!lastName && !firstName && (this.personalDirectoryFlag || this.companyDirectoryFlag)) {
            // Personal/Company directory contact defined with no firstname/lastname but only a company name (contact of type 'company')
            // The display name is deducded from the company name
            this.displayName = this.companyName;
            this.initials = this.displayName.charAt(0);
        } else if (lastName && firstName) {
            if (this.displayOrder === "FL") {
                this.displayName = firstName + " " + lastName;
                this.displayShortName = firstName + " " + lastName.charAt(0);
                this.initials = firstName.charAt(0) + lastName.charAt(0);
            } else {
                this.displayName = lastName + " " + firstName;
                this.displayShortName = lastName + " " + firstName.charAt(0);
                this.initials = lastName.charAt(0) + firstName.charAt(0);
            }
        } else if (lastName && !firstName) {
            this.displayName = this.displayShortName = lastName;
            this.initials = lastName.charAt(0);
        } else if (nickName) {
            this.displayName = nickName;
            this.displayShortName = nickName;
            this.initials = nickName.charAt(0);
        } else if (this.loginEmail) {
            this.displayName = this.loginEmail;
            this.displayShortName = this.loginEmail;
            this.initials = this.loginEmail.substring(0, 2).toUpperCase();
        } else if (firstName) {
            this.displayName = firstName;
            this.initials = firstName.charAt(0);
        } else {
            this.displayName = "Anonymous";
            this.displayShortName = "Anonymous";
            this.initials = "A";
        }

        // Compute contact color
        const upperCaseDisplayName = this.displayName.toUpperCase();
        let sum = 0;
        for (let i = 0; i < upperCaseDisplayName.length; i++) {
            sum += upperCaseDisplayName.charCodeAt(i);
        }
        this.colorIndex = sum % 12;
        this.color = Contact.textAvatarColor[this.colorIndex];
        this.colorName = Contact.textAvatarName[this.colorIndex];
    }


