    public getSupervisionDevices() {
        return this._supervisionDevices ? Object.keys(this._supervisionDevices) : [];
    }

    public setSupervisionDeviceState(device: string, state: string) {
        if (!this._supervisionDevices) { this._supervisionDevices = {}; }
        if (state !== "free") {
            this._supervisionDevices[device] = state;
        } else {
            delete this._supervisionDevices[device];
        }

        // compute  user's supervision state from devices supervision states
        const existWaitingDevice = Object.keys(this._supervisionDevices).some((deviceNumber: string) => {
            const deviceState = this._supervisionDevices[deviceNumber];
            return deviceState === "waiting";
        });
        if (existWaitingDevice) {
            this.supervisionState = "waiting";
            return;
        }

        const existRingingInDevice = Object.keys(this._supervisionDevices).some((deviceNumber: string) => {
            const deviceState = this._supervisionDevices[deviceNumber];
            return deviceState === "ringingIn";
        });
        if (existRingingInDevice) {
            this.supervisionState = "ringingIn";
            return;
        }

        const existEngagedOutDevice = Object.keys(this._supervisionDevices).some((deviceNumber: string) => {
            const deviceState = this._supervisionDevices[deviceNumber];
            return deviceState === "engagedOut";
        });
        if (existEngagedOutDevice) {
            this.supervisionState = "engagedOut";
            return;
        }

        const existBusyDevice = Object.keys(this._supervisionDevices).some((deviceNumber: string) => {
            const deviceState = this._supervisionDevices[deviceNumber];
            return deviceState === "busy";
        });
        if (existBusyDevice) {
            this.supervisionState = "busy";
            return;
        }

        this.supervisionState = "free";
    }

    public set supervisionState(supervisionState: any) {
        const previousState = this._supervisionState;
        this._supervisionState = supervisionState;
        if (previousState !== supervisionState) {
            this.rxSubject.next({ name: "supervisionState" });
        }
    }

    public get supervisionState() {
        return this._supervisionState;
    }

    public get supervisionCallInfos(): any[] {
        return this._supervisionCallInfos;
    }

    public set supervisionCallInfos(supervisionCallInfos: any[]) {
        const prevCallInfos = this._supervisionCallInfos;
        this._supervisionCallInfos = supervisionCallInfos;

        // retrieve call notification info from previous callInfos for each call in new callInfos
        (this._supervisionCallInfos || []).forEach(newCallInfo => {
            const prevCallInfoFound = (prevCallInfos || []).find(prevCallInfo => prevCallInfo.callId === newCallInfo.callId);
            if (prevCallInfoFound) {
                newCallInfo.notified = prevCallInfoFound.notified;
            }
        });
        this.rxSubject.next({ name: "supervisionCallInfos" });
    }

    public updateSupervisionCallInfo(supervisionCallInfo: any): void {
        const callInfoToUpdateIndex: number = this._supervisionCallInfos.findIndex(callInfo => callInfo.callId === supervisionCallInfo.callId);
        if (callInfoToUpdateIndex !== -1) {
            //replace old callinfo by new one
            this._supervisionCallInfos.splice(callInfoToUpdateIndex, 1, supervisionCallInfo);
            this.rxSubject.next({ name: "supervisionCallInfos" });
        }
    }


