    public containsEmail(email: string): boolean {
        const lowerCaseEmail = email.toLowerCase();
        if (this.loginEmail && this.loginEmail.toLowerCase() === lowerCaseEmail) {
            return true;
        }
        if (this.emailPro && this.emailPro.toLowerCase() === lowerCaseEmail) {
            return true;
        }
        if (this.emailPerso && this.emailPerso.toLowerCase() === lowerCaseEmail) {
            return true;
        }
        return false;
    }

    public containsPhoneNumber(phoneNumber: string) {
        if (!phoneNumber) {
            return false;
        }
        return [
            this.phonePbx,
            this.phoneInternalNumber,
            this.phonePro,
            this.phoneProCan,
            this.mobilePro,
            this.mobileProCan,
            this.phonePerso,
            this.phonePersoCan,
            this.mobilePerso,
            this.mobilePersoCan
        ].includes(phoneNumber);
    }

    public containsDirectoryPhoneNumber(phoneNumber: string) {
        if (!phoneNumber) {
            return false;
        }

        const mobilePhones: string[] = this.mobilePhones || [];
        const businessPhones: string[] = this.businessPhones || [];
        const otherPhoneNumbers: string[] = this.otherPhoneNumbers || [];

        if (mobilePhones.includes(phoneNumber))
            return true;

        if (businessPhones.includes(phoneNumber))
            return true;

        if (otherPhoneNumbers.includes(phoneNumber))
            return true;

        return false;
    }

    /**
     * @function startAsPhoneNumber
     * @description Check if the given string corresponds to a phone number (canonical format or not)
     * @memberof Contact
     * @public
     * @param {string} phoneNumber The string to check
     * @returns {boolean} Return true if the string match a phone number
     */
    public startAsPhoneNumber(phoneNumber: string): boolean {
        const cleanPhoneNumber = phoneNumber.trim().split(".").join("");
        if (cleanPhoneNumber.length < 1) { return false; }
        const pattern1 = /^(\+|\d|#|\*|\(|\)|\.|-|–|—|\s|\/)*$/;
        const match = cleanPhoneNumber.match(pattern1);
        if (!match) { return false; }
        return (match[0] === cleanPhoneNumber);
    }


