    // CONTACT INSTANCE DEBUG (MAY BE USED BY SDKv2)
    // ----------------------------------------------------

    public toJSON(): any {
        const json: any = {};
        json.id = this.dbId;
        json.jid = this.jid;
        json.presenceStatus = this.status + this.statusInfo ? this.statusInfo : '';
        if (this.displayName) json.displayName = this.displayName;
        if (this.lastname) json.last = this.lastname;
        if (this.firstname) json.firstname = this.firstname;
        if (this.nickname) json.nickname = this.nickname;
        if (this.title) json.title = this.title;
        if (this.lastAvatarUpdateDate) json.lastAvatarUpdateDate = this.lastAvatarUpdateDate;
        // Users + Company Business contacts: display Company info if available
        if (this.company) {
            if (this.company.id) json.companyId = this.company.id;
        }
        else if (this.companyDirectoryFlag) {
            if (this.businessCompanyId) json.businessCompanyId = this.businessCompanyId;
        }
        return json;
    }

