/**
 * @module Favorites
 */

import { Subject } from "rxjs";
import { Contact } from "rainbow-sdk/models/contact.model";
import { Bubble } from 'rainbow-sdk/models/bubble.model';
import { User } from 'rainbow-sdk/models/user.model';
import { Conversation } from "rainbow-sdk/models/conversation.model";


export enum FavoriteType {
    /**
     * Rainbow user
     */
    USER = "user",

    /**
     * Rainbow bubble
     */
    ROOM = "room",

    /**
     * Directory contact, from Personal Contacts or Business Contacts directory.
     */
    DIRECTORY = "directory",

    /**
     * Microsoft Azure AD users/Microsoft O365 contacts
     */
    OFFICE365 = "office365",

    /**
     * Rainbow bot
     */
    BOT = "bot"
}

export interface Favorite {
    /**
     * The identifier of the favorite.
     * @readonly
     */
    id: string;

    /**
     * Type of the favorite, one of the following values defined in *FavoriteType* enum.
     * @readonly
     */
    type: FavoriteType;

    /**
     * Peer object related to the favorite.
     * The object is an instance of Bubble if the associated *type* property is set to **room**.
     * The object is an instance of User in all other cases.
     */
    peer: Bubble | User | undefined;
}

/**
 * @ignore
 */
export class FavoriteRB implements Favorite {

    /**
     * The identifier of the favorite.
     * @readonly
     */
    public id: string;


    /**
     * Id of the peer linked to the favorite.
     * @readonly
     */
    public peerId: string;


    /**
     * Type of the favorite, one of the following values defined in FavoriteType enum.
     * @readonly
     */
    public type: FavoriteType;

    /**
     * Peer object related to the favorite.
     * The object is an instance of Bubble if the associated 'type' property is set to 'room'.
     * The object is an instance of User in all other cases.
     */
    public peer: Bubble | User | undefined;

    /**
     * Conversation object related to the favorite
     * A conversation can only be present for 'user', 'bot', and 'room' favorite types.
     * But not for directory favorite (from personal/business/office365 directory as they are only contact cards.
     */
    public conv: Conversation | undefined;


    // Observables for inner events sent by a favorite (an instance, not the service !)
    public innerRxSubject: Subject<any> = new Subject<any>();

    constructor(id: string, peerId: string, type: FavoriteType) {
        this.id = id;
        this.peerId = peerId;
        this.type = type;
    }

    // ----------------------------------------------------
    // UCaaS Only: UI management
    // ----------------------------------------------------

    /**
     * Update the contact information of a favorite
     * This is useful if one of the names (lastname, firstname) or the avatar of the contact has been changed.
     * Updating the contact property(s) allows to refresh the display of the favorites list.
     * @param contact - The new contact that will be associated to the favorite
     */
    public updateContact(contact: Contact): void {
        this.peer = contact;
        this.innerRxSubject.next({ name: "updateFavoriteContactData", data: contact });
    }

}
