    private constructor() {
        super();
        const storedVersion = localStorage.getItem('version');
        const storedMajorVersion = this.getMajorVersion(storedVersion);
        const currentMajorVersion = this.getMajorVersion(this.win.version);
        if (!config.appModuleKey) { config.appModuleKey = this.win.moduleIds ? this.win.moduleIds.join('') : 'default'; }
        if (storedMajorVersion !== currentMajorVersion) { this.firstUseNewVersion = true; }
        localStorage.setItem('version', this.win.version);
        this.getServerApiUrls();

        if (localStorage?.webinarOptionAllowMultitab === 'true' || config.webinarOptionAllowMultitab === true) {
            this.logger.info(`[AuthService] webinar debug option : ignore token storage update`);
        }
        else {
            window.addEventListener('storage', (event: StorageEvent) => {
                if (event.key === 'token' && event.newValue) {
                    this.logger.info('[AuthService] Detect token change, restart token survey mechanism');
                    this.token = event.newValue;
                    this.startTokenSurvey();
                }
            }, false);
        }
    }

    public subscribe(handler: any): Subscription { return this.rxSubject.subscribe(handler); }
