    public async logon(login: string, password: string, rememberMe: boolean = true, authSettings?: AuthSettings): Promise<{ mfaPolicy: MultiFactorAuthPolicy; authType: AUTH_TYPE.TOTP; token: string } | null> {
        try {
            // Check login email syntax
            if (login.indexOf("@") === -1) { throw this.createError(`Wrong login format '${login}'`, 'errorUnauthorized', 401500, undefined, true); }

            // Rainbow login url was given by the server (otherwise use the default url)
            let url = `${config.restServerUrl}/api/rainbow/authentication/v1.0/login`;
            if (authSettings?.type === AUTH_TYPE.RAINBOW) { url = authSettings.loginUrl; }
            else if (authSettings?.safetyUrl) { url = authSettings.safetyUrl; this.authType = authSettings.type; }

            // Compute authentication request headers
            const headers: any = {};
            headers.Authorization = `Basic ${window.btoa(unescape(encodeURIComponent(login + ":" + password)))}`;
            headers.Accept = 'application/json';
            this.setInformationHeaders(headers);

            // Set id associated to the application which realizes the login operation
            // This id will be checked to the ones stored in datababase in case of multifactor authentication is activated for the user and configured to be run only for only unstrusted application
            const trustedAppId = localStorage.getItem("x-rainbow-trusted-appid");
            if (trustedAppId) { headers["x-rainbow-trusted-appid"] = trustedAppId; }

            if (config.rainbowApiClientKey) {
                const clientKey = config.rainbowApiClientKey + ":" + SHA256(config.appModuleKey + password);
                headers["x-rainbow-app-auth"] = "Basic " + window.btoa(unescape(encodeURIComponent(clientKey)));
            }

            // Call authentication REST api
            const response: Response = await fetch(url, { method: 'GET', headers, credentials: 'include' });
            if (!response.ok) { throw response; }
            const responseData: any = await response.json();

            // Extract authToken from response
            this.token = responseData.token;

            // Handle mfa login
            if (responseData.mfaRequired) {
                this.logger.info(`[AuthService] mfaRequired set to true, use token authentication`);
                return { mfaPolicy: responseData.mfaPolicy, authType: AUTH_TYPE.TOTP, token: this.token };
            }
            this.logger.info(`[AuthService] no mfaRequired use basic authentication`);

            this.extractUserInfo(responseData.loggedInUser);

            // Update credentials local storage storing policy
            if (rememberMe) {
                this.logger.info("[AuthService] Store authentication info in local storage");
                localStorage.setItem('login', this.login);
                localStorage.setItem('id', this.userId);
                localStorage.setItem('token', this.token);
                localStorage.setItem('authType', this.authType);
            }
            else { this.removeCredentials(); }

            localStorage.setItem('firstUse', 'false');
            const loginForLogs = login.charAt(0) + login.replace(/[^\s](?=.{1,}$)/g, "*").substr(1);
            this.logger.info(`[AuthService] logon () with ${loginForLogs} -- SUCCESS`);
            this.startTokenSurvey();
            return null;
        }
        catch (error) {
            const loginForLogs = login.charAt(0) + login.replace(/[^\s](?=.{1,}$)/g, "*").substr(1);
            let errorMessage: string = `logon () with ${loginForLogs} -- FAILURE -- `;
            if (error.localError) {
                this.logger.error(`[AuthService] ${errorMessage} ${error}`);
                throw error;
            }
            let errorStatus: string = 'errorUltimateUnknownError';
            let errorCode = null;
            let errorData = null;

            if (error.status === 0 || error.status === -1) {
                errorMessage += "No server response";
                errorStatus = "errorNoServerResponse";
            }
            else if (error.json) {
                const responseData: any = await error.json();
                if (error.status === 401) {
                    this.removeCredentials();
                    errorMessage += responseData.errorDetails;
                    errorCode = responseData.errorDetailsCode;

                    switch (errorCode) {
                        case 401500: errorStatus = 'errorUnauthorized'; break;
                        case 401700: errorStatus = 'errorWrongApplicationId'; break;
                        case 401522: errorStatus = "errorUnauthorized"; break;
                        case 401223: errorStatus = "errorLogNotAuthorized"; break;
                        case 401501:
                            errorStatus = "errorAccountLocked";
                            if (responseData.errorDetailsData) { errorData = { delay: responseData.errorDetailsData.forbiddenDelay }; }
                            break;
                        default: break;
                    }
                }
                else if (error.status === 500) {
                    errorMessage += responseData.errorDetails;
                    errorStatus = "errorInternalServerError";
                }
            }

            this.logger.error(`[AuthService] ${errorMessage}`);
            throw this.createError(errorMessage, errorStatus, errorCode, errorData);
        }
    }

