    public async autoAuth(noAutoLoginPatterns?: string[], commandLineInfo?: any): Promise<AutoAuthResult> {
        // Extract location search parameters
        const searchParams: any = this.getLocationSearchParameters();

        // Handle noAutoAuth parameter
        if (searchParams.hasOwnProperty('noAutoLogin')) {
            this.logger.info(`[AuthService] autoAuth -- IGNORED -- noAuthoLogin parameters`);
            return { type: AUTO_AUTH_TYPES.NoAuth };
        }

        // Handle noAutoAuth patterns
        if (noAutoLoginPatterns?.find((pattern: string) => {
            const patternMatch = window.location.hash.startsWith(`#/${pattern}`);
            if (patternMatch) this.logger.info(`[AuthService] autoAuth -- IGNORED -- pattern ${pattern} detected`);
            return patternMatch;
        })) { return { type: AUTO_AUTH_TYPES.NoAuth }; }

        // Handle Desktop keyChain auth information
        const keyChainAuthInfo = await this.getKeyChainDesktopAuthInfo();
        if (keyChainAuthInfo && keyChainAuthInfo.login && keyChainAuthInfo.passwd) {
            try {
                await this.logon(keyChainAuthInfo.login, keyChainAuthInfo.passwd, true);
                this.logger.info(`[AuthService] autoAuth -- authentication by keyChain ${keyChainAuthInfo.login} -- SUCCESS`);
                return { type: AUTO_AUTH_TYPES.KeyChain, status: AUTH_STATUS.Success };
            }
            catch (error) {
                this.logger.error(`[AuthService] autoAuth -- authentication by keyChain -- FAILURE -- ${error.message} `);
                return { type: AUTO_AUTH_TYPES.KeyChain, status: AUTH_STATUS.Failure, error, authInfo: keyChainAuthInfo };
            }
        }

        // Handle Login/Password commandLine authentication (rainbow:// or https://)
        if (!commandLineInfo) {
            this.logger.info(`[AuthService] autoAuth -- get commandLine`);
            const commandLine = await this.getCommandLine();
            commandLineInfo = this.handleAuthCommandLine(commandLine);
        }
        if (commandLineInfo) {
            try {
                // Handle domain change
                let currentDomain = config.xmpp.currentServer;
                if (currentDomain.startsWith('web-') || currentDomain.startsWith('web.')) {
                    this.logger.error(`[AuthService] autoAuth -- current domain ${currentDomain} is prefixed, remove prefix`);
                    currentDomain = currentDomain.slice(4);
                    this.logger.error(`[AuthService] autoAuth -- current domain is now ${currentDomain}`);
                }
                /* MCO : COMMENT FOR SSO TEAMS */
                if (currentDomain !== commandLineInfo.domain && !commandLineInfo.domain.includes('localhost')) {
                    this.logger.error(`[AuthService] autoAuth -- authentication by command line -- FAILURE -- Wrong domain detected (expected: ${commandLineInfo.domain}, current: ${currentDomain})`);
                    commandLineInfo.error = 'WrongDomain';
                    return { type: AUTO_AUTH_TYPES.CommandLine, status: AUTH_STATUS.Failure, authInfo: commandLineInfo };
                }
                // Handle temporary Microsoft token
                if (commandLineInfo.token) {
                    const token = await this.getRainbowTokenFromTemporaryToken(commandLineInfo.token);
                    await this.logonWithToken(token);
                    this.logger.info(`[AuthService] autoAuth -- authentication by token from commandLine -- SUCCESS`);
                    return { type: AUTO_AUTH_TYPES.AuthToken, status: AUTH_STATUS.Success };
                }
                else if (!commandLineInfo.passwd) return { type: AUTO_AUTH_TYPES.CommandLine, status: AUTH_STATUS.Failure, authInfo: commandLineInfo };
                await this.logon(commandLineInfo.login, commandLineInfo.passwd, true);

                this.logger.info(`[AuthService] autoAuth -- authentication by command line -- SUCCESS`);
                return { type: AUTO_AUTH_TYPES.CommandLine, status: AUTH_STATUS.Success };
            }
            catch (error) {
                this.logger.error(`[AuthService] autoAuth -- authentication by command line -- FAILURE -- ${error.message} `);
                return { type: AUTO_AUTH_TYPES.CommandLine, status: AUTH_STATUS.Failure, error, authInfo: commandLineInfo };
            }
        }

        // Get SSO token authentication (provided in the url by an Identity Provider)
        const authToken = searchParams.tkn;
        if (authToken) this.logger.info("[AuthService] autoAuth -- found SSO token");

        // No SSO token but SSO error found
        const errorCode = searchParams.errcode;
        if (errorCode) {
            const errType = searchParams.errtype;
            const errmsg = searchParams.errmsg;
            this.logger.error(`[AuthService] autoAuth -- SSO error -- ${errorCode} -- ${errType} -- ${errmsg}`);
            return { type: AUTO_AUTH_TYPES.AuthToken, status: AUTH_STATUS.Failure, errorCode, authInfo: keyChainAuthInfo };
        }

        // Handle authentication with authToken provided by SSO or use localStorage authToken
        const errorLabelType = authToken ? 'SSO' : 'Legacy';
        try {
            await this.logonWithToken(authToken);
            this.logger.info(`[AuthService] autoAuth -- authentication by token (${errorLabelType}) -- SUCCESS`);
            return { type: AUTO_AUTH_TYPES.AuthToken, status: AUTH_STATUS.Success };
        }
        catch (error) {
            // Handle specific SSO error
            if (error instanceof InvalidTokenError) {
                this.logger.error(`[AuthService] autoAuth -- authentication by token (${errorLabelType}) -- FAILURE`);
                return { type: AUTO_AUTH_TYPES.AuthToken, status: AUTH_STATUS.Failure, errorCode: 'errorInvalidToken' };
            }
            return { type: AUTO_AUTH_TYPES.AuthToken, status: AUTH_STATUS.Failure, authInfo: keyChainAuthInfo };
        }
    }

