    public async getCommandLine(): Promise<string | null> {
        try {
            // Desktop application case
            const parameters = await this.getMainProcessArguments();
            if (parameters && parameters.length > 1) {
                const rainbowParameters = parameters[parameters.length - 1];
                if (rainbowParameters.startsWith('rainbow:')) {
                    let commandLine = rainbowParameters.substring("rainbow://".length);
                    commandLine = commandLine !== '/' ? commandLine : null;
                    if (localStorage.showCommandLine) this.logger.info(`[AuthService] getCommandLine -- found 'rainbow://' command line : ${commandLine}`);
                    else this.logger.info(`[AuthService] getCommandLine -- found 'rainbow://' command line`);
                    return commandLine;
                }
            }

            // Desktop and Web application case
            const commandLine = window.location.href ? window.location.href.slice(window.location.protocol === 'http:' ? 7 : 8) : '';
            if (commandLine.length) {
                this.logger.info(`[AuthService] getCommandLine -- found 'https://' command line`);
                return commandLine;
            }
        }
        catch (error) {
            this.logger.error(`[AuthService] getCommandLine -- failure-- ${error.message} `);
        }
        return null;
    }

    public handleAuthCommandLine(commandLine: string): any {
        if (!commandLine) return undefined;

        const loginIndex = commandLine.indexOf('?login=');
        if (loginIndex === -1) return undefined;
        const params = commandLine.slice(loginIndex + 7).split('&');

        // Handle login
        let login = params[0] ? params[0] : null;
        if (login && login.length > 1) {
            login = decodeURIComponent(login);
            if (login.indexOf('@') === -1) login = atob(login);
        }

        // Handle password
        let passwd = params[1]?.includes('pwd=') ? params[1].slice("pwd=".length) : undefined;
        if (passwd) passwd = decodeURIComponent(passwd);

        // Handle token
        const token = params[1]?.includes('tkn=') ? params[1].slice('tkn='.length) : undefined;

        // Handle domain
        const charBeforeQuestionMark = commandLine.charAt(loginIndex - 1);
        const domainIndex = charBeforeQuestionMark === '/' ? loginIndex - 1 : loginIndex;
        const domain = commandLine.slice(0, domainIndex);

        const protocol = domain.includes('localhost') ? 'http://' : 'https://'; // Debug stuff
        const server = domain.includes('localhost') ? 'demo.openrainbow.org' : domain; // Debug stuff
        this.logger.info(`[AuthService] handleAuthCommandLine -- domain: ${domain}, login: ${login}, protocol: ${protocol}, server: ${server}`);
        if (token) this.logger.info(`[AuthService] handleAuthCommandLine -- token: ${token}`);
        return { domain, login, passwd, token, protocol, server };
    }

