    /**
     * @public
     * @async
     * @function loginCheck
     * @description
     *    This API allows Rainbow users to login during a short duration for executing some specific operation concerning a feature given in body content
            If login is successful, the API returns a JSON Web Token (<abbr title="JSON Web Token">JWT) which has to be provided by clients for all Rainbow APIs requiring this user authentication with short duration:
            The JWT is valid only for a given time period.
            The JWT cannot be renewed.
            Once the JWT expired, user must login again using this API. using {@link https://api.openrainbow.org/authentication/#api-Authentication-GetLimitedLogin Rainbow Authentication portal - Authentication - Login user with a short duration})
     * @param {string} login loginEmail of user trying to authenticate
     * @param {string} password password of user trying to authenticate
     * @param {string} feature feature for which the login is for. Default: 'mfa'
     * @param {number} duration duration in seconds of the limited login. Default: 600 seconds
     * @returns {Promise<void>} Returns if success
     * @memberof AuthService
     */
    public async loginCheck(login: string, password: string, feature: string = 'mfa', duration: number = 600): Promise<MultiFactorAuthFeatureInfo> {
        try {
            const url = `${config.restServerUrl}/api/rainbow/authentication/v1.0/limitedlogin?duration=${duration}`;

            // Compute authentication request headers
            const headers: any = {};
            headers.Authorization = `Basic ${window.btoa(unescape(encodeURIComponent(login + ":" + password)))}`;
            headers.Accept = 'application/json';
            this.setInformationHeaders(headers);
            headers['Content-Type'] = "application/json";

            if (config.rainbowApiClientKey) {
                const clientKey = config.rainbowApiClientKey + ":" + SHA256(config.appModuleKey + password);
                headers["x-rainbow-app-auth"] = "Basic " + window.btoa(unescape(encodeURIComponent(clientKey)));
            }

            const response = await fetch(url, { method: 'POST', headers, credentials: 'include', body: JSON.stringify({ feature: feature }) });
            if (!response.ok) { throw response; }

            const responseData = await response.json();
            if (responseData) {
                return new MultiFactorAuthFeatureInfo(responseData.feature, responseData.token, responseData.mfa);
            }

            throw new Error("[AuthService] loginCheck - Error in data returned");
        }
        catch (error) {
            const errorInfo = await this.errorHelperService.getErrorInfo(error, 'loginCheck');
            this.logger.error(`${errorInfo?.message}`);
            throw (errorInfo.error);
        }
    }

