    /**
     * @public
     * @async
     * @function getRainbowTokenFromTemporaryToken
     * @description Get a "standard" Rainbow JWT from a temporary microsoft token.
     * This API can only be used by the "Rainbow official Desktop application".
     * @param {string} temporaryToken a temporary microsoft token
     * @returns {Promise<string>} Returns  a "standard" Rainbow JWT if success
     * @memberof AuthService
     */
    public async getRainbowTokenFromTemporaryToken(temporaryToken: string): Promise<string> {
        try {
            const challenge = randomString(20);
            const url = `${config.restServerUrl}/api/rainbow/authentication/v1.0/microsoft/sso/jwt?challenge=${challenge}`;

            this.logger.info(`[AuthService] getRainbowTokenFromTemporaryToken()`);
            // Compute authentication request headers
            const headers: any = {};
            const clientKey = config.rainbowApiClientKey + ":" + SHA256(config.appModuleKey + challenge);

            headers["x-rainbow-app-auth"] = "Basic " + window.btoa(unescape(encodeURIComponent(clientKey)));
            headers['Authorization'] = `Bearer ${temporaryToken}`;
            headers.Accept = 'application/json';
            this.setInformationHeaders(headers);
            const response = await fetch(url, { method: 'GET', headers });
            if (!response.ok) { throw response; }
            const jsonResponse = await response.json();
            return jsonResponse.token;
        }
        catch (error) {
            const errorInfo = await this.errorHelperService.getErrorInfo(error, 'getRainbowTokenFromTemporaryToken');
            this.logger.error(`${errorInfo?.message}`);
            throw (errorInfo.error);
        }
    }

