    /**
     * @public
     * @async
     * @function loginUsingPasswordlessLogin
     * @description
     * This API allows Rainbow users to login without password, but with a verification code sent by mail or sms
     * @param {string} uid User identifier (loginEmail or loginPhone)
     * @param {string} code OTP code
     * @param {string} challenge for autorized application identification
     * @param {boolean} rememberMe Indicates wether the browser must memorize the token and do auto token renewals
     * @returns {Promise<void>}
     * @memberof AuthService
     */
    public async loginUsingPasswordlessLogin(uid: string, code: string, challenge: string, rememberMe: boolean): Promise<void> {
        try {
            const url = new URL(`${config.restServerUrl}/api/rainbow/authentication/v1.0/passwordless/login`);
            url.searchParams.set("challenge", challenge);

            const headers: any = {};
            headers['Content-Type'] = "application/json";
            headers.Accept = 'application/json';
            headers["x-rainbow-app-auth"] = "Basic " + this.getRainbowAppAuth(config.rainbowApiClientKey, config.appModuleKey, challenge);
            const jsonBody = {
                uid,
                code
            };
            const response = await fetch(url.toString(), { method: 'POST', headers, body: JSON.stringify(jsonBody) });
            if (!response.ok) { throw response; }

            const jsonResponse: any = await response.json();
            const responseData: any = jsonResponse;

            // Extract authToken from response
            this.token = responseData.token;
            this.extractUserInfo(responseData.loggedInUser);

            // Update credentials local storage storing policy
            if (rememberMe) {
                this.logger.info("[AuthService] Store authentication info in local storage");
                localStorage.setItem('login', this.login);
                localStorage.setItem('id', this.userId);
                localStorage.setItem('token', this.token);
                localStorage.setItem('authType', this.authType);
            }
            else { this.removeCredentials(); }

            localStorage.setItem('firstUse', 'false');
            this.startTokenSurvey();
        }
        catch (error) {
            const errorInfo = await this.errorHelperService.getErrorInfo(error, 'sendPasswordlessCodeToUser');
            this.logger.error(`${errorInfo?.message}`);
            throw (errorInfo.error);
        }
    }

    // Backchannel authentication for Sso Azure Cond access
    public async retrieveBackChannelUserToken(authSettings: AuthSettings, rememberMe: boolean, renewSession?: boolean): Promise<string> {
        this.authSettings = authSettings;
        this.rememberMe = rememberMe;
        this.backChannelRenewSession = renewSession;

        return new Promise((resolve, reject) => {
            // listen events for token retrieval operation: success, failure or intermediate redirect
            const backChannelSubscription: Subscription = this.subscribe((event: RBEvent) => {
                if (event.name === AuthServiceEvents.RAINBOW_ON_AUTH_BACKCHANNEL_SUCCESS) {
                    this.logger.info(`[authService] backchannel event received ${event.name}`);
                    resolve(this.token);
                    backChannelSubscription.unsubscribe();
                }
                if (event.name === AuthServiceEvents.RAINBOW_ON_AUTH_BACKCHANNEL_FAILURE) {
                    this.logger.info(`[authService] backchannel event received ${event.name}`);
                    reject();
                    backChannelSubscription.unsubscribe();
                }
                if (event.name === AuthServiceEvents.RAINBOW_ON_AUTH_BACKCHANNEL_REDIRECT_COMMAND) {
                    this.logger.info(`[authService] backchannel event received ${event.name}`);
                    // We have received the redirect command sent by the default browser:
                    // this means that the token is available in backend
                    // Let's do a last polling to retrieve the token and the logged in user data.
                    // This will also end the polling session in backend
                    if (this.backChannelPollingTimeout) {
                        clearTimeout(this.backChannelPollingTimeout);
                    }
                    this.startSsoCondAccessPoll();
                }
            });
            // start token polling
            this.startSsoCondAccessTokenPolling();
        });
    }

    private startSsoCondAccessTokenPolling(): void {
        this.backChannelPollingTimeout = setTimeout(this.startSsoCondAccessPoll.bind(this), 1000);
    }

    public stopPollingBackChannelUserToken() {
        if (this.backChannelPollingTimeout) {
            clearTimeout(this.backChannelPollingTimeout);
            this.backChannelRenewSession = undefined;
        }
    }

    private async startSsoCondAccessPoll(): Promise<void> {
        // retrieve backchannel jwt token, and retry while operation fails
        try {
            await this.pollingBackChannelUserToken(this.authSettings.backChannelSession.id, this.authSettings.backChannelSession.token);
            this.logger.info(`[authService] startSsoCondAccessPoll success`);

            this.backChannelPollingTimeout = null;
            this.sendEvent(AuthServiceEvents.RAINBOW_ON_AUTH_BACKCHANNEL_SUCCESS);
        } catch (error) {
            if (error.errorDetailsCode === 401208) {
                // Sso Azure Cond Access not yet completed : start again polling
                this.logger.info(`[authService] startSsoCondAccessPoll error ${error.message} : not yet completed => start again polling`);
                this.startSsoCondAccessTokenPolling();
                return;
            }
            this.logger.info(`[authService] startSsoCondAccessPoll unexpected error ${error.message} => stop polling url for token`);
            this.sendEvent(AuthServiceEvents.RAINBOW_ON_AUTH_BACKCHANNEL_FAILURE);
        }
    }

    /**
     * @public
     * @async
     * @function pollingBackChannelUserToken
     * @description
     * This API allows Rainbow users to login without password, but with a verification code sent by mail or sms
     * @param {string} uid User identifier (loginEmail or loginPhone)
     * @param {string} code OTP code
     * @param {string} challenge for autorized application identification
     * @param {boolean} rememberMe Indicates wether the browser must memorize the token and do auto token renewals
     * @returns {Promise<void>}
     * @memberof AuthService
     */
    private async pollingBackChannelUserToken(backChannelSessionId: string, pollingToken: string): Promise<void> {
        try {
            const url = new URL(`${config.restServerUrl}/api/rainbow/authentication/v1.0/backchannel/${backChannelSessionId}/jwt`);

            const headers: any = {};
            headers.Authorization = `Bearer ${pollingToken}`;
            headers.Accept = 'application/json';

            const response = await fetch(url.toString(), { method: 'GET', headers });
            if (!response.ok) { throw response; }

            const jsonResponse: any = await response.json();
            const responseData: any = jsonResponse;

            // Extract authToken from response
            this.token = responseData.token;

            if (this.backChannelRenewSession) {
                localStorage.setItem('token', this.token);
                this.sessionShouldBeUpdated = false;
                this.sendEvent(AuthServiceEvents.RAINBOW_ON_AUTH_SESSION_SHOULD_RENEW, false);
                this.backChannelRenewSession = false;
            } else {
                this.extractUserInfo(responseData.loggedInUser);

                // Update credentials local storage storing policy
                if (this.rememberMe) {
                    this.logger.info("[AuthService] Store authentication info in local storage");
                    localStorage.setItem('login', this.login);
                    localStorage.setItem('id', this.userId);
                    localStorage.setItem('token', this.token);
                    localStorage.setItem('authType', this.authType);
                }
                else { this.removeCredentials(); }

                localStorage.setItem('firstUse', 'false');
                this.startTokenSurvey();
            }
        }
        catch (error) {
            const errorInfo = await this.errorHelperService.getErrorInfo(error, 'pollingBackChannelUserToken');
            this.logger.error(`${errorInfo?.message}`);
            throw (errorInfo.error);
        }
    }
