export const VIRTUAL_BACKGROUND_TYPE = { IMAGE: 'image', BLUR: 'blur', BLUR_PLUS: 'blur-plus', NONE: 'none', VIDEO: 'video' };

export interface Dimensions {
    height: number;
    width: number;
}

export interface Options {
    backgroundType: string;
    imgBg?: string;
    stream?: MediaStream;
    segmentationDimensions?: Dimensions;
}

export interface IVideoPipeline {
    init(): void;
    render(): void;
    cleanUp(): void;
    updatePostProcessingConfig(): void;
}

/**
 * @eventProperty
 */
export enum VirtualBackgroundServiceEvents {
    /**
     * @eventProperty
     * This `RBEvent` is sent when the virtuallBackgroundService stream is updated
     */
    UPDATE_STREAM = 'UPDATE_STREAM',

    /**
    * @eventProperty
    * This `RBEvent` is sent when the virtuallBackgroundService mirror style is updated
    */
    UPDATE_STREAM_MIRROR = 'UPDATE_STREAM_MIRROR'
}

export interface VirtualBackgroundService {

    /**
     * Subscribe to updates from the service (all events are of RBEvent type
     * @param handler - The call-back function that will be subscribed to the RxJS subject
     * @param eventNames - Array of event to listen
     */
    start(): Promise<void>;
    stop(): Promise<void>;
    reconnect(): Promise<void>;
    subscribe(handler: (event: RBEvent<VirtualBackgroundServiceEvents>) => any, eventNames?: VirtualBackgroundServiceEvents | VirtualBackgroundServiceEvents[]): Subscription;
    startProcessStream(stream: MediaStream, serviceName?: string): Promise<MediaStream>;
    stopProcessStream(): Promise<void>;
    setBackgroundMode(mode: string, url: string): Promise<void>;
    getBackgroundMode(): any;
    setMirror(mirror: boolean): void;
    getMirror(): boolean;
    setFramerate(framerate: number): void;

    putAdminBackgroundImage(backgroundCompany: any): Promise<void>;
    deleteAdminBackgroundImage(backgroundIdAdmin: string): Promise<void>;

    putPersonnalBackgroundImage(backgroundUser: any, loadBgUrl: string): Promise<void>;
    deletePersonnalBackgroundImage(backgroundIdUser: string): Promise<void>;

    backgroundImages: BehaviorSubject<any>;
    loadBg: BehaviorSubject<any>;
}

