    private constructor() {
        super();

        // Check if WASM is available
        if (!this.wasmAvailable()) {
            this.settingsService.setSetting('virtualBackgroundFlag', 'false');
            this.logger.warn('[VirtualBackgroundService] NOT AVAILABLE -- REASON : ENHANCED BROWSER SECUITY ACTIVATED FOR THIS SITE');
            return;
        }
        this.settingsService.setSetting('virtualBackgroundFlag', 'true');

        // Check if mathematic co-processor is available
        this.simdSupported = this.simdAvailable();

        this.videoElement = document.createElement('video') as HTMLVideoElement;
        this.webglAvailable();

        // Get virtualBackground data
        this.isStreamMirrored = localStorage.getItem('virtualBackgroundMirror') === 'true';
        this.backgroundImages = new BehaviorSubject<any>({ companyBackgrounds: [], userBackgrounds: [] });
        this.loadBg = new BehaviorSubject<any>({ loadPersonalBg: [] });

    }

    public subscribe(handler: (event: RBEvent<VirtualBackgroundServiceEvents>) => any, eventNames?: VirtualBackgroundServiceEvents | VirtualBackgroundServiceEvents[]): Subscription {
        const observable = eventNames ? this.rxSubject.pipe(filter((event: RBEvent<VirtualBackgroundServiceEvents>) => {
            if (eventNames instanceof Array) return eventNames.indexOf(event.name) !== -1;
            return event.name === eventNames;
        })) : this.rxSubject;

        return observable.subscribe((event: RBEvent<VirtualBackgroundServiceEvents>) => {
            try { handler(event); }
            catch (error) { this.logger.error(`[VirtualBackgroundService] subscribe () -- error -- ${error.message}`); }
        }); 
    }

    /****************************************************************************/
    /** SERVICE LIFECYCLE                                                      */
    /****************************************************************************/

    /**
     * This async method has to be call to start the virtual Background Service
     */
    public async start(): Promise<void> {
        this.logger.info(`[VirtualBackgroundService] === Start === ${this.webglAllowed ? 'webgl' : 'canvas2d'} pipeline == simd ${this.simdSupported ? 'supported' : 'not supported'}`);
        this.backgroundImages.next(await this.getBackgrounds());
        this.backgroundImages.value.companyBackgrounds.reverse();
        this.backgroundImages.value.userBackgrounds.reverse();
        this.loadBg.next({ loadPersonalBg: [] });
        this.xmppSubscription = this.xmppService.addHandler((stanza: any) => { this.onXmppEvent(stanza); return true; }, 'jabber:iq:configuration', 'message', 'management');
    }

    /**
     * This async method has to be call to stop the virtual Background Service
     */
    public async stop(): Promise<void> {
        this.logger.info('[VirtualBackgroundService] === Stop ===');
        this.backgroundImages.next({ companyBackgrounds: [], userBackgrounds: [] });
        this.loadBg.next({ loadPersonalBg: [] });
        this.cleanUp();
        if (this.xmppSubscription) { this.xmppService.deleteHandler(this.xmppSubscription); this.xmppSubscription = null; }
        if (this.webglSubscription) { this.webglSubscription.unsubscribe(); }
    }

    /**
     * This async method has to be call to reconnect the virtual Background Service
     */
    public async reconnect(): Promise<void> {
        this.logger.info('[VirtualBackgroundService] === Reconnect ===');
        this.cleanUp();
        this.backgroundImages.next(await this.getBackgrounds());
        this.loadBg.next({ loadPersonalBg: [] });
        if (this.xmppSubscription) { this.xmppService.deleteHandler(this.xmppSubscription); this.xmppSubscription = null; }
        this.xmppSubscription = this.xmppService.addHandler((stanza: any) => { this.onXmppEvent(stanza); return true; }, 'jabber:iq:configuration', 'message', 'management');
    }

    /**
     * XMPP room event handler
     * @param stanza - the xmpp stanza event handler
     */
    private onXmppEvent(stanza: any): boolean {
        try {
            const stanzaElem = $(stanza);
            const backgroundElem = stanzaElem.find('background');
            const backgroundId = backgroundElem.attr('backgroundId');
            const action = backgroundElem.attr('action');
            const type = backgroundElem.attr('type');

            switch (action) {
                case 'create':
                    this.logger.info(`[virtualBackgroundService] onXmppEvent -- ${action} `);
                    setTimeout(() => {
                        if (type === 'userBackgrounds') { this.loadBg.next({ loadPersonalBg: [] }); }
                        this.backgroundImages.value[type].unshift({ id: backgroundId });
                        this.backgroundImages.next(this.backgroundImages.value);
                    }, 1);
                    break;

                case 'delete':
                    this.logger.info(`[virtualBackgroundService] onXmppEvent -- ${action} `);
                    this.backgroundImages.value[type].splice(this.backgroundImages.value[type].map(el => el.id).indexOf(backgroundId), 1);
                    this.backgroundImages.next(this.backgroundImages.value);
                    break;

                default:
                    break;
            }
        }
        catch (error) {
            this.logger.error("[VirtualBackgroundService] onXmppEvent -- failure -- " + error.message);
        }
        return true;
    }


