    /**
     * Start the process stream
     * @param stream - The MediaStream  that we will process
     * @param serviceName - The name of service that calls the method (optional, for debug purpose)
     */
    public async startProcessStream(stream: MediaStream, serviceName?: string): Promise<MediaStream> {
        this.logger.info(`[VirtualBackgroundService] startProcessStream from service ${serviceName ? serviceName : 'Unknown'}`);
        return this.setInputStream(stream);
    }

    /**
     * Stop the effect of virtual Background
     */
    public async stopProcessStream(): Promise<void> {
        this.logger.info(`[VirtualBackgroundService] stopProcessStream `);
        this.stream?.getTracks().forEach((track: MediaStreamTrack) => { track.enabled = false; track.stop(); track = null; });
        this.stream = undefined;
        this.modifiedStream?.getTracks().forEach((track: MediaStreamTrack) => { track.enabled = false; track.stop(); track = null; });
        this.modifiedStream = undefined;
        await this.stopEffect();
    }

    /**
     * Set the type and url of the virtual background
     * @param type - The type of virtual Background ('none", 'image', 'blur', 'blur-plus', 'video')
     * @param url -The url of virtual Background
     */
    public async setBackgroundMode(type: string, url: string = ''): Promise<void> {
        const currentBackgroundType = this.settingsService.getSetting('virtualBackgroundType');
        const currentBackgroundImageUrl = this.settingsService.getSetting('imgVirtualBackground');
        if (type !== currentBackgroundType || ((type === VIRTUAL_BACKGROUND_TYPE.IMAGE || type === VIRTUAL_BACKGROUND_TYPE.VIDEO) && currentBackgroundImageUrl !== url)) {
            this.logger.info(`[VirtualBackgroundService] setBackgroundMode "${type}" ${url ? '"' + url + '"' : ''} `);
            this.settingsService.setSetting('virtualBackgroundType', type);
            this.settingsService.setSetting('imgVirtualBackground', url);
            const modifiedStream = await this.setInputStream(this.stream);
            this.maskFrameTimerWorker.postMessage({ id: SET_TIMEOUT, timeMs: 1000 / 30 });
            if (currentBackgroundType === VIRTUAL_BACKGROUND_TYPE.NONE || type === VIRTUAL_BACKGROUND_TYPE.NONE) {
                this.rxSubject.next(RBEvent.create(VirtualBackgroundServiceEvents.UPDATE_STREAM, { stream: modifiedStream, type }));
            }
        }
    }

    /**
     * Get the type and url od the virtual background
     */
    public getBackgroundMode(): any {
        const type = this.settingsService.getSetting('virtualBackgroundType');
        const url = this.settingsService.getSetting('imgVirtualBackground');
        return { type, url };
    }

