import { LoggerService, RBEvent, Service } from "rainbow-sdk";
import { Subject, Subscription, filter } from "rxjs";

/** @internal */
export const USER_SVC = 'UserService';

/**
 * Users service events
 * Can listen to it via `UserService.subscribe()` API.
 * @eventProperty
 */
export enum UserServiceEvents {
    /**
    * @eventProperty
    */
    ON_USER_CHANGED = "ON_USER_CHANGED",
}

/**
 * User Service interface
 */
export interface UserService {
    /**
     * Subscribe to updates from the user service, all events are of RBEvent<UserServiceEvents>
     * @param callback - The callback function that will be called when events are received
     * @param eventNames - Array of event to listen
     * @returns Returns RxJS Subscription
     */
    subscribe(callback: (event: RBEvent<UserServiceEvents>) => any, eventNames?: UserServiceEvents | UserServiceEvents[]): Subscription;
}

/**
 * User Service implementation
 * @internal
 */
export class UserServiceRB extends Service implements UserService {

    private rxSubject: Subject<RBEvent<UserServiceEvents>> = new Subject<RBEvent<UserServiceEvents>>();
    private logger: LoggerService = LoggerService.getInstance();

    /**
      * Returns the Favorite service singleton
      */
    public static getInstance(): UserServiceRB {
        return Service.create(USER_SVC, UserServiceRB);
    }

    public static build(): UserServiceRB {
        return new UserServiceRB();
    }

    private constructor() { super(); }

    public subscribe(handler: (event: RBEvent<UserServiceEvents>) => any, eventNames?: UserServiceEvents | UserServiceEvents[]): Subscription {
        const observable = eventNames ? this.rxSubject.pipe(filter((event: RBEvent<UserServiceEvents>) => {
            if (eventNames instanceof Array) return eventNames.indexOf(event.name) !== -1;
            return event.name === eventNames;
        })) : this.rxSubject;

        return observable.subscribe((event: RBEvent<UserServiceEvents>) => {
            try { handler(event); }
            catch (error) { this.logger.error(`[UserService] subscribe () -- error -- ${error.message}`); }
        });
    }

    /**
     * User service events send method
     * Can listen to it via UserService.subscribe() API
     * @param name - the name of the event
     * @param data - the data to be send (an object)
     */
    public sendEvent(name: UserServiceEvents, data: any = null) {
        this.rxSubject.next(RBEvent.create<UserServiceEvents, any>(name, data));
    }

}
