/**
 * @module Documents
 */

import { LoggerService, MainService } from '../services/core';
import { FileDescriptor, FileViewer } from './common';
import { Subject, Subscription, filter } from 'rxjs';
import { Bubble, RBEvent, User } from '.';
import { ContactService } from '../services/core/contact.service';
import { DOCUMENTS_SVC, DocumentsService } from '../services/documents/documents.service';

export enum DocumentState {
    DELETED = "deleted",
    UPLOADING = "uploading",
    UPLOADED = "uploaded",
    NOT_UPLOADED = "not_uploaded",
    DOWNLOADING = "downloading",
    UPLOADERROR = "uploadError",
    UNKNOWN = "unknown"
}

export enum DocumentSearchMime {
    IMAGE = 'image',
    AUDIO_VIDEO = 'audio-video',
    PDF = 'pdf',
    PRESENTATION = 'presentation',
    DOCUMENT = 'document',
    SPREADSHEET = 'spreadsheet'
}

export enum DocumentSearchSet {
    ALL = "all",
    MINE = "mine",
    RECEIVED = "received"
}

export enum DocumentSearchSortBy {
    FILENAME = "fileName",
    UPLOADED_DATA = "uploadedDate",
    SIZE = "size"
}

export enum DocumentSearchSortDirection {
    TOP = 1,
    DOWN = -1
}

export interface DocumentThumbnail {
    /**
     *
     */
    possible: boolean;
    /**
     *
     */
    available: boolean;
    /**
     *
     */
    url(): Promise<string>
}

export interface DocumentSearchOptions {

    /**
     * Only searches for files whose name contains this string
     */
    name?: string;

    /**
     * DocumentSet, define in which collection set the search should be executed ALL, MINE or RECEIVED
     * Default is ALL
     */
    documentSet?: DocumentSearchSet;

    /**
     * The document media type (also known as a Multipurpose Internet Mail Extensions or MIME type) indicates the nature and format
     * of a document. MIME types are defined and standardized in IETF's RFC 6838
     * Default is ''
     */
    mime?: DocumentSearchMime;

    /**
     * The search result will be sorted following the sortBy info
     * Default is UPLOADED_DATA
     */
    sortBy?: DocumentSearchSortBy;

    /**
     * The sort direction
     * Default is DOWN
     */
    sortDirection?: DocumentSearchSortDirection;
}

/**
 * @eventProperty
 */
export enum DocumentEvents {
    /**
     * @eventProperty
     * When a document is uploaded, the backend will automatically generate a thumbnail whenever possible
     * (this function is in place for images, video files and pdf files).
     * This event is fired once when the thumbnail generation is complete and the document is available for download.
     */
    ON_THUMBNAIL_AVAILABLE = 'ON_THUMBNAIL_AVAILABLE',

    /**
     * @eventProperty
     * This event is fired once when the upload is complete and the document is available for download.
     */
    ON_UPLOADED = 'ON_UPLOADED',

    /**
    * @eventProperty
    * When a large document is uploaded, it will be sent to the backend in chunks, making it possible to monitor its progress.
    * This event is fired when the transfer progress (in %) changes.
    */
    ON_TRANSFERT_IN_PROGRESS = 'ON_TRANSFERT_IN_PROGRESS',
}

export class DocumentViewer {
    public id: string;
    public type?: string;

    static createFormFileViewer(fileViewer: FileViewer): DocumentViewer {
        const documentViewer = new DocumentViewer();
        documentViewer.id = fileViewer.viewerId;
        documentViewer.type = fileViewer.type === "user" ? 'user' : 'bubble';
        return documentViewer;
    }
}

export interface Document {

    /**
     * The document identifier
     */
    id: string;

    /**
     * The document name
     */
    name: string

    /**
     * The document size (in bytes)
     */
    size: number

    /**
     * The document date
     */
    date: Date

    /**
     * The document media type (also known as a Multipurpose Internet Mail Extensions or MIME type) indicates the nature and format
     * of a document. MIME types are defined and standardized in IETF's RFC 6838
     */
    mime: string;

    /**
     * The document current state
     */
    state: DocumentState;

    /**
     * To ensure the security of your data, every document uploaded to Rainbow will be scanned for viruses.
     * This field reflects the security status of the document.
     */
    securityStatus: string;

    /**
     * Document thumbnail information (possible, available, url)
     */
    thumbnail: DocumentThumbnail;

    /**
     * When a large document is uploaded, it is sent to the backend in chunks, so its progress can be tracked.
     * This progress index (in %) is updated when a document is transferred between the client and the backend
     * (see event "ON_TRANSFERT_PROGRESS_UPDATED").
     */
    transfertProgress: number;

    /**
     * This method makes it possible to subscribe to the document events (all events are of RBEvent);
     * @param handler - The call-back function that will be subscribed to the RxJS subject
     * @param eventNames - array of event to listen
     */
    subscribe(handler: (event: RBEvent<DocumentEvents>) => any, eventNames?: DocumentEvents | DocumentEvents[]): Subscription;

    /**
     * Get this document owner user
     */
    getOwner(): Promise<User>;

    /**
     * Uploads a document to the file server.
     * It is possible to interrupt the upload of a document using the `abortDocumentTransfer` method.
     */
    upload(): Promise<Document>;

    /**
     * Download a document
     * This method returns a blob that you can process as you see fit.
     * It is possible to interrupt the download of a document using the `abortDocumentTransfer` method.
     */
    download(): Promise<Blob>;

    /**
     * This method allows you to copy a document shared by another user into your own storage space.
     */
    copy(): Promise<Document>;

    /**
     * Abort a document transfert
     * This method allows you to interrupt a transfer operation (upload or download).
     */
    abortTransfert(): Promise<Document>;

    /**
     * Delete a document
     */
    delete(): Promise<void>;

    /**
     * Add a viewer to share the this document.
     * @param viewer - The viewer to be added, which can be either a `User` or a `Bubble` instance.
     */
    addViewer(viewer: User|Bubble): Promise<void>;

    /**
     * Remove a viewer
     * @param viewer - The viewer to be removed, which can be either a `User` or a `Bubble` instance.
     */
    removeViewer(viewer: User|Bubble): Promise<void>;

    //getUrl(): Promise<string>;

    /**
     * Utility method for generating a human readable JSON representation of this object (debug purpose only)
     */
    toJSON(): any;
}


/** @internal */
export class DocumentRB implements Document {

    private documentService: any = MainService.getInstance().inject<DocumentsService>(DOCUMENTS_SVC);
    private contactService: ContactService = ContactService.getInstance();
    private logger: LoggerService = LoggerService.getInstance();

    public fd: FileDescriptor;
    private eventSubject: Subject<RBEvent<DocumentEvents>> = new Subject<RBEvent<DocumentEvents>>();
    private thumbnailSubscription?: Subscription;
    public transfertProgressSubscription?: Subscription;
    private transfertProgressValue: number = -1;

    public get id(): string { return this.fd.id; }
    public get name(): string { return this.fd.fileName; }
    public get date(): Date { return this.fd.getDate(); }
    public get size(): number { return this.fd.size; }
    public get mime(): string { return this.fd.typeMIME; }
    public get state(): DocumentState { return this.fd.state as unknown as DocumentState; }
    public get securityStatus(): string { return this.fd.virusScanState; };
    public get fileDescriptor(): FileDescriptor { return this.fd; };
    public get transfertProgress(): number { return this.fd.chunkPerformedPercent; }
    public get viewers(): DocumentViewer[] { return this.fd.viewers.map(viewer => DocumentViewer.createFormFileViewer(viewer)); }

    public thumbnail: DocumentThumbnail;

    public subscribe(handler: (event: RBEvent<DocumentEvents>) => any, eventNames?: DocumentEvents | DocumentEvents[]): Subscription {
        const observable = eventNames ? this.eventSubject.pipe(filter((event: RBEvent<DocumentEvents>) => {
            if (eventNames instanceof Array) return eventNames.indexOf(event.name) !== -1;
            return event.name === eventNames;
        })) : this.eventSubject;

        return observable.subscribe((event: RBEvent<DocumentEvents>) => {
            try { handler(event); }
            catch (error) { this.logger.error(`[DocumentsService] subscribe () -- error -- ${error.message}`); }
        });
    }

    public sendEvent(name: DocumentEvents, data: any = null) {
        this.eventSubject.next(RBEvent.create<DocumentEvents, any>(name, data));
    }

    public async getOwner(): Promise<User> {
        return this.contactService.getContactByDBId(this.fd.ownerId);
    }

    public async upload(): Promise<Document> {
        return await this.documentService?.uploadDocument(this);
    }

    public async download(): Promise<Blob> {
        return await this.documentService?.downloadDocument(this);
    }

    public async copy(): Promise<Document> {
        return await this.documentService?.copyDocument(this);
    }

    public async abortTransfert(): Promise<Document> {
        return await this.documentService?.abortDocumentTransfert(this);
    }

    public async delete(): Promise<void> {
        return await this.documentService?.deleteDocument(this);
    }

    public hasEnoughSpace(): boolean {
        return this.documentService?.hasEnoughSpace(this);
    }

    public async addViewer(viewer: User|Bubble): Promise<void> {
        return await this.documentService?.addDocumentViewer(this, viewer);
    }

    public async removeViewer(viewer: User|Bubble): Promise<void> {
        return await this.documentService?.deleteDocumentViewer(this, viewer);
    }

    public toJSON(): any {
        const json: any = {
            id: this.id,
            name: this.name,
            date: this.date,
            size: this.size,
            mime: this.mime,
            state: this.state,
            owner: this.fd.ownerId,
            securityStatus: this.securityStatus,
            thumbnail: this.thumbnail,
        };
        if (this.viewers.length) json.viewers = this.viewers;
        return json;
    }

    public handleThumbnail(): void {
        // Handle thumbnail info
        this.thumbnail = {
            possible: this.fd.isThumbnailPossible(),
            available: this.fd.thumbnail.availableThumbnail,
            url: () => this.documentService?.getFileDescriptorUrl(this.fd, true, true)
        };

        // Listen once on availability
        if (this.thumbnail.possible && !this.thumbnail.available) {
            this.thumbnailSubscription = this.fd.previewBlobSubject.subscribe(() => {
                this.thumbnail.available = this.fd.previewBlobSubject.value !== undefined;
                this.sendEvent(DocumentEvents.ON_THUMBNAIL_AVAILABLE);
                this.thumbnailSubscription?.unsubscribe();
            });
        }
    }

    public handleTransferProgress(): void {
        this.transfertProgressValue = -1;
        this.transfertProgressSubscription = this.fd.progressSubject.subscribe(() => {

            // Handle only new transfert progress values
            if (this.fd.chunkPerformedPercent > this.transfertProgressValue) {

                // Send Progress event
                this.sendEvent(DocumentEvents.ON_TRANSFERT_IN_PROGRESS, this.fd.chunkPerformedPercent);
                this.transfertProgressValue = this.fd.chunkPerformedPercent;

                // Remove subscription when transfert is finnished
                if (this.fd.chunkPerformedPercent >= 100) {
                    this.transfertProgressSubscription.unsubscribe();
                    this.transfertProgressSubscription = undefined;
                }
            }
        });
    }


}
