    public letItSnowAvailable = false;

    private updateSubject = new Subject<any>();

    public static getInstance() {
        return Service.create(SETTINGS_SVC, SettingsService);
    }

    public static build() {
        return new SettingsService();
    }

    private constructor() {
        super();

        // Handle letItSnow date
        this.letItSnowAvailable = (new Date()).getMonth() === 11;
        setInterval(() => { this.letItSnowAvailable = (new Date()).getMonth() === 11; }, 3600000);
    }

    public letItSnowActivated(): boolean {
        if (this.letItSnowAvailable) return this.getBooleanSetting('letItSnow');
        return false;
    }

    public configure(): void {

        //this.redirectVoIP = localStorage.getItem("redirectVoIP") === 'true';
        this.languageCodes = this.languages.map((language: any) => { return language.settingCode; });
        const browserLanguage = navigator.languages ? navigator.languages[0] : (navigator.language || (navigator as any).userLanguage);

        // Config data detected in browser localStorage
        const localSettings = this.getLocalStorageSettings();
        if (localSettings.init) {
            Object.keys(localSettings).forEach((key: string) => { if (localSettings[key] !== null) { this.settings[key] = localSettings[key]; } });
            // If no language defined in settings yet, set it by default to the browser language
            // Localstorage must NOT be updated with this value, this will be done afterwards after user has logged in
            // by using the display language selected by the user.
            if (!this.settings.lang) {
                this.settings.lang = this.getMappedLanguage(browserLanguage);
            }
        }

        // No config found in browser localStorage
        else {
            // No default language for the moment, take the browser language
            // In Desktop client case, this browser language can be defined by the installer command line
            // It allows to specify the first login language (Rainbow_Instaler_name.exe /FirstStartLanguage=ar)
            Object.keys(this.settings).forEach((key: string) => { localStorage.setItem(key, this.settings[key]); });

            // Update of language in settings must be done AFTER the global init of localStorage with default
            // values present in 'this.settings'.
            // Localstorage must NOT be updated with this value, this will be done afterwards after user has logged in
            // by using the display language selected by the user.
            this.settings.lang = this.getMappedLanguage(browserLanguage);
        }

        if (localStorage.useOldFilePicker) config.useOldFilePicker = localStorage.useOldFilePicker === 'true';

        // Force speechEnhancementType to none
        this.setSetting('speechEnhancementType', 'none');

        this.sendUpdateEvent(RBEvent.create('LANGUAGE_UPDATED', this.settings.lang));
        this.sendUpdateEvent(RBEvent.create('SETTINGS_UPDATED'));
    }

    public setSetting(key: string, value: string): void {
        this.settings[key] = value;
        localStorage.setItem(key, value);
    }

    public getSetting<V extends string>(key: string): V | undefined { return this.settings[key]; }
    public getBooleanSetting(key: string): boolean { return this.settings[key] === 'true'; }
    public setSettingTemporarly(key: string, value: string, time: number = 300000): void {
        const previousValue = this.settings[key];
        this.settings[key] = value;
        this.timers.push(setTimeout(() => {
            this.settings[key] = previousValue;
        }, time));
    }

    public sendUpdateEvent(event: RBEvent): void { this.updateSubject.next(event); }
    public subscribeUpdateEvent(eventName: string, handler: any): Subscription {
        return this.updateSubject.subscribe((event: RBEvent) => { if (event.name === eventName) { handler(event.data); } });
    }


    private getLocalStorageSettings(): any {
        const settings: any = {};
        Object.keys(this.settings).forEach((key: string) => { settings[key] = localStorage.getItem(key); });

        if (!settings.nbMaxConversations) { settings.nbMaxConversations = this.settings.nbMaxConversations; }
        else {
            // In case the value is less than 50, reset it to 50
            if (parseInt(settings.nbMaxConversations, 10) < 50) { this.setSetting('nbMaxConversations', '50'); }
        }

        if (settings.headsetMicrophone === "default") { settings.headsetMicrophone = null; }
        if (settings.headsetSpeaker === "default") { settings.headsetSpeaker = null; }
        if (settings.speakerphoneMicrophone === "default") { settings.speakerphoneMicrophone = null; }
        if (settings.speakerphoneSpeaker === "default") { settings.speakerphoneSpeaker = null; }
        if (settings.customMicrophone === "default") { settings.customMicrophone = null; }
        if (settings.customSpeaker === "default") { settings.customSpeaker = null; }

        //workaround to activate conf V2 on AiO
        if (settings.webConfServiceV2 === "true") { config.confV2Model = true; }
        return settings;
    }

