    public getAvailableLanguages(): LanguageData[] { return this.languages; }

    public getAppliLanguage(): LanguageData {
        const language = this.languages.find((lang) => { return lang.settingCode === this.settings.lang; });
        return language ? language : this.defaultLanguage;
    }

    public getAppliLanguageCodeForServer(): string {
        const langArray = this.settings.lang.split("-");
        return langArray.length === 1 ? this.settings.lang : langArray[0] + "-" + langArray[1].toUpperCase();
    }

    public setAppliLangageCodeFromServer(serverCode: string) {
        const langArray = serverCode.split("-");
        let clientCode = langArray[0];
        if (clientCode) { clientCode = clientCode.toLowerCase(); }
        if (langArray.length === 2) { clientCode += ("-" + langArray[1].toLowerCase()); }
        clientCode = this.getMappedLanguage(clientCode);
        clientCode = (this.languageCodes.indexOf(clientCode) >= 0) ? clientCode : "en";
        this.setAppliLanguageCode(clientCode);
    }

    public setAppliLanguageCode(lang: string): void {
        this.setSetting("lang", lang);
        this.sendUpdateEvent(RBEvent.create('LANGUAGE_UPDATED', lang));
    }

    public getBestLanguageForIsoCode(isoCode: string) {
        const language = this.getLanguageByIsoCode(isoCode);
        if (language) return language;

        // Exact language not found: try to find language without country variant (if any)
        if (isoCode.indexOf("-") !== -1) {
            const isoLanguageWithoutCountry = isoCode.split("-")[0]; // Remove country variant
            return this.getLanguageByIsoCode(isoLanguageWithoutCountry);
        }

        // Really not found return default language
        return this.getLanguageByIsoCode("en");
    }

    public getSimpleLanguageCode(isoCode: string) {
        if (!isoCode) return 'en';
        const isoCodeLower = isoCode.toLowerCase();

        // Exact language not found: try to find language without country variant (if any)
        if (isoCodeLower.indexOf("-") !== -1) {
            const isoLanguageWithoutCountry = isoCodeLower.split("-")[0]; // Remove country variant
            return isoLanguageWithoutCountry;
        }
        return isoCodeLower;
    }

    public getLanguageByIsoCode(isoCode: string) {
        return this.languages.find((lang: any) => { return lang.isoCode === isoCode; });
    }

    // Translate the language return by the browser to a language supported by the application
    private getMappedLanguage(codedLanguage: string) {
        if (!codedLanguage) return 'en';
        const codedLang = codedLanguage.toLowerCase();
        switch (codedLang.split("-")[0]) {
            case "ar": return "ar";
            case "ca": return "ca";
            case "cs": return "cs";
            case "de": return "de";
            case "en": return "en";
            case "es": return "es-es";
            case "fi": return "fi";
            case "fr": return "fr";
            case "he": return "he";
            case "it": return "it";
            case "ja": return "ja";
            case "ko": return "ko";
            case "nl": return "nl";
            case "no": return "no";
            case "pt": return codedLang === "pt-br" ? "pt-br" : "pt-pt";
            case "pl": return "pl";
            case "ru": return "ru";
            case "sv": return "sv-se";
            case "tr": return "tr";
            case "zh": return (["zh-cn", "zh-tw"].indexOf(codedLang) >= 0) ? codedLang : "zh-cn";
            default: return "en";
        }
    }

