import { Subscription } from "rxjs";
import xmlParser from 'rainbow-sdk/utils/xmlParser';

import { RBEvent } from 'rainbow-sdk/models/event.model';

import { Service } from 'rainbow-sdk/services/service';
import { MainService } from 'rainbow-sdk/services/core/main.service';
import { ContactService } from 'rainbow-sdk/services/core/contact.service';
import { XmppService } from 'rainbow-sdk/services/core/xmpp.service';
import { LoggerService } from 'rainbow-sdk/services/core/logger.service';
import { BUBBLE_CONFERENCE_SVC, WebConferenceServiceRB } from 'rainbow-sdk/services/conference/webConference.service';
import { BUBBLE_SVC, BubbleServiceRB } from 'rainbow-sdk/services/bubbles/bubble.service';
import type { WebrtcP2PService } from "rainbow-sdk/services/webrtc/webrtcP2P.service";
import { TELEPHONY_SVC, TelephonyService } from '../telephony/telephony.service';
import { WEBRTC_P2P_SVC } from "rainbow-sdk/services/webrtc/webrtcP2P.service";
import { ConversationServiceInnerEvents, ConversationServiceRB } from '../conversation/conversation.service';
import { CONVERSATION_SVC } from '../conversation/conversation.service';
import { CallStatus } from "rainbow-sdk/models/call.model";
import { BubbleEvents } from "../../models/bubble.model";

export const WEBRTC_GLOBAL_EVENT_HANDLER_SVC = 'WebrtcGlobalEventHandlerService';

export class WebrtcGlobalEventHandlerService extends Service {

    public static getInstance() {
        return Service.create(WEBRTC_GLOBAL_EVENT_HANDLER_SVC, WebrtcGlobalEventHandlerService);
    }

    public static build() {
        return new WebrtcGlobalEventHandlerService();
    }

    private constructor() { super(); }

    private mainService: MainService = MainService.getInstance();
    private xmppService: XmppService = XmppService.getInstance();
    private logger: LoggerService = LoggerService.getInstance();
    private contactService: ContactService = ContactService.getInstance();

    private webrtcP2PService?: WebrtcP2PService;
    private webConferenceService: WebConferenceServiceRB = null;
    private telephonyService: TelephonyService = null;
    private bubbleService: BubbleServiceRB;

    private nameSpaceRbVoice = "urn:xmpp:jingle:apps:rtp:info:1";
    private messageHandlerRbVoiceRef = null;

    private xmppServiceSubscription: Subscription = null;
    private xmppConnectionSubscription: Subscription = null;
    private conversationService: ConversationServiceRB;

    public started: boolean = false;

    public start() {
        this.webrtcP2PService = this.mainService.inject<WebrtcP2PService>(WEBRTC_P2P_SVC);
        this.webConferenceService = this.mainService.inject(BUBBLE_CONFERENCE_SVC);
        this.telephonyService = this.mainService.inject(TELEPHONY_SVC);
        this.bubbleService = this.mainService.inject(BUBBLE_SVC);
        this.conversationService = this.mainService.inject(CONVERSATION_SVC);

        this.started = true;
        this.xmppConnectionSubscription = this.xmppService.subscribeToConnectionEvents((event: RBEvent) => { this.onConnectionStateChangeEvent(event); });
        if (this.xmppService.started) {
            if (this.xmppServiceSubscription) { this.xmppServiceSubscription.unsubscribe(); this.xmppServiceSubscription = null; }
            this.xmppServiceSubscription = this.xmppService.connection.jingle.rxSubject.subscribe((evt: RBEvent) => { this.onJingleMessage(evt); });
        }
        this.attachHandlers();
    }

    public stop() {
        this.started = false;
        this.removeHandlers();
        if (this.xmppServiceSubscription) this.xmppServiceSubscription.unsubscribe();
        if (this.xmppConnectionSubscription) { this.xmppConnectionSubscription.unsubscribe(); }
    }

    private attachHandlers() {
        this.removeHandlers();

        this.logger.info("[WebrtcGlobalEventHandlerService] attachHandlers");

        // Attach messages handler
        if (!this.messageHandlerRbVoiceRef) {
            this.messageHandlerRbVoiceRef = this.xmppService.addHandler((stanza) => {
                try {
                    this.onMessageReceived(stanza); return true;
                } catch (err) {
                    this.logger.error("[WebrtcGlobalEventHandlerService] caught error HandlerRef 2 : " + err);
                    return true;
                }
            }, this.nameSpaceRbVoice, "message");
        }
    }

    private onConnectionStateChangeEvent(event: RBEvent) {
        if (event.name === 'ON_XMPP_CONNECTED') {
            this.logger.log('[WebrtcGlobalEventHandlerService] onConnectionStateChangeEvent : connected');
            if (this.xmppServiceSubscription) { this.xmppServiceSubscription.unsubscribe(); this.xmppServiceSubscription = null; }
            this.xmppServiceSubscription = this.xmppService.connection.jingle.rxSubject.subscribe((evt: RBEvent) => { this.onJingleMessage(evt); });
            this.attachHandlers();
        }
    }

    private removeHandlers() {
        this.logger.info("[WebrtcGlobalEventHandlerService] removeHandlers");

        if (this.messageHandlerRbVoiceRef) {
            this.xmppService.deleteHandler(this.messageHandlerRbVoiceRef);
            this.messageHandlerRbVoiceRef = null;
        }
    }

    private onJingleMessage(event: RBEvent): void {
        try {
            switch (event.name) {
                case 'jingleP2PUpdateStream': this.jingleP2PUpdateStream(event.data.sid); break;
                case 'remotestreamremoved.jingle': this.jingleP2PUpdateStream(event.data.sid); break;
                case 'setLocalDescription.jingle': this.jingleP2POnSetLocalDescription(event.data.sid); break;
                case 'jingleSessionInfoRefer': this.onJingleSessionRefer(event.data.sid, event.data.status, event.data.confEndpointId, event.data.referTo, event.data.method, event.data.otherSid); break;
                default:
                    break;
            }
        }
        catch (error) {
            this.logger.info(`[WebrtcGlobalEventHandlerService] onJingleMessage -- failure -- ${event.name}`);
        }
    }

    //REFER should be managed in the web conference file, and not here
    private async onMessageReceived(stanza) {

        this.logger.info("[WebrtcGlobalEventHandlerService]   | onMessageReceived");
        const stanzaElem = xmlParser(stanza);
        const isRefer = stanzaElem.find("refer");
        const isError = stanzaElem.find("error");

        if (isError?.length) {
            this.logger.info("[WebrtcGlobalEventHandlerService]   | onMessageReceived -- error stanza received, do nothing");
            return;
        }
        //check if error response to IQ :

        // handle internally message refer without IQ
        if (isRefer) {
            const referElem = stanzaElem.find("refer");
            const confEndpointId = referElem.attr("confEndpointId");
            const referTo = referElem.attr("referTo");
            const status = referElem.attr("status");
            const from = stanzaElem.attr("from");//the originator jid
            const telCallId = referElem.attr("telCallId") ? referElem.attr("telCallId") : null;
            let myTelCall = null;
            let possibleCall = null;
            const shouldMute = false;
            const mediaPillarCalls = this.webrtcP2PService.getMediaPillarAudioCalls();

            if (telCallId) {
                if (!this.telephonyService) {
                    this.logger.info("[WebrtcGlobalEventHandlerService] | missing telephony service !!!");
                    return;
                }

                if (this.telephonyService.isOfficeMode()) {
                    //user is using office phone, manage the call by his id
                    myTelCall = this.telephonyService.calls[telCallId];
                }
                else {
                    possibleCall = this.telephonyService.calls[telCallId];
                    if (mediaPillarCalls?.length && possibleCall) {
                        myTelCall = this.telephonyService.calls[telCallId];
                    } else {
                        this.logger.info("[WebrtcGlobalEventHandlerService] | onMessageReceived : Not my callId then Ignore");
                        return;
                    }
                }

            } else { //if no call Id provided then infers from available info
                //check if we've a current MP call with the same contact from who we receive the refer message;
                possibleCall = (mediaPillarCalls?.length) ? mediaPillarCalls[0] : undefined;
                if (possibleCall?.contact && possibleCall.contact.jid === this.xmppService.getBareJidFromJid(from)) {
                    if (!this.telephonyService) {
                        this.logger.info("[WebrtcGlobalEventHandlerService] | missing telephony service !!!");
                        return;
                    }
                    myTelCall = this.telephonyService.getActiveCall();
                } else {
                    this.logger.info("[WebrtcGlobalEventHandlerService] | onMessageReceived : Not my call then Ignore");
                    return;
                }
            }

            if (confEndpointId && referTo && status !== 'complete') { //receiving a refer to join SFU
                // TO BE ACTIVATED ONCE WE're IN CONF V2 model only !
                if (this.bubbleService) {
                    let bubble = this.bubbleService.getBubbleFromCache(confEndpointId);
                    //wait for the room to be created, but it's better to use the event from the conversationService and use the DB ID
                    if (!bubble) {
                        try { bubble = await this.bubbleService.getServerBubble(confEndpointId); }
                        catch { this.logger.warn("[WebrtcGlobalEventHandlerService] | adhoc conference v1 type"); }
                    }

                    if (bubble?.isBubbleConferenceStarted()) {
                        bubble.sendEvent(BubbleEvents.ON_CONFERENCE_START_EVENT);
                        await this.webConferenceService.transferP2pCallToConference(null, referTo, bubble, false, shouldMute);
                        const nameSpaceRefer = 'urn:xmpp:jingle:apps:rtp:info:1';//new nameSpace
                        const id = "web_" + crypto.randomUUID();
                        this.xmppService.send($msg({ from: this.contactService.userContact.fullJid, to: from, id })
                            .c('refer', {
                                xmlns: nameSpaceRefer,
                                status: 'complete',
                                telCallId: telCallId
                            }));
                        this.conversationService?.sendInnerEvent(ConversationServiceInnerEvents.RAINBOW_ON_WEBCONF_ADD_HOC_COMPLETED, bubble);
                        return;
                    }
                }

            } else if (status === 'complete') { //receive refer complete
                this.logger.info("[WebrtcGlobalEventHandlerService]   | onMessageReceived : refer complete received");
                if (myTelCall && (myTelCall.callStatus === CallStatus.ACTIVE || myTelCall.callStatus === CallStatus.HOLD)) { //former tel call to release
                    this.logger.info("[WebrtcGlobalEventHandlerService]   | onMessageReceived : callId to release : " + telCallId);
                    this.telephonyService.releaseCall(myTelCall);
                }
            }
        }
    }

    private async onJingleSessionRefer(sid: string, status: string, confEndpointId: string, referTo: string, method: string, otherSid: string) {
        this.logger.info("[WebrtcGlobalEventHandlerService]  | refer: " + sid + " - status: " + status + " - confEndpointId: " + confEndpointId + " - referTo: " + referTo + " - method: " + method);
        const session = this.xmppService.connection.jingle.sessions[sid];

        if (status === "complete") {
            const call = this.webrtcP2PService?.calls[sid];
            this.webrtcP2PService.onCallTransferred(call);
        }
        else if (session) {
            const call = this.webrtcP2PService?.calls[sid];
            if (confEndpointId) {
                const shouldMute = (call?.isMuted);

                if (this.bubbleService) {
                    let bubble = this.bubbleService.getBubbleFromCache(confEndpointId);
                    //wait for the room to be created, but it's better to use the event from the conversationService and use the DB ID
                    if (!bubble?.isBubbleConferenceStarted()) {
                        try {
                            bubble = await this.bubbleService.getServerBubble(confEndpointId);
                        }
                        catch {
                            this.logger.warn("[WebrtcGlobalEventHandlerService] | adhoc conference v1 type");
                        }
                    }

                    if (bubble?.isBubbleConferenceStarted()) {
                        bubble.sendEvent(BubbleEvents.ON_CONFERENCE_START_EVENT);
                        await this.webConferenceService.transferP2pCallToConference(session, referTo, bubble, false, shouldMute);
                        this.conversationService?.sendInnerEvent(ConversationServiceInnerEvents.RAINBOW_ON_WEBCONF_ADD_HOC_COMPLETED, bubble);
                        this.webrtcP2PService.sendReferStatus(sid, "complete");
                        return;
                    }
                }
            }
            else if (referTo && otherSid) {
                this.logger.debug(`[WebrtcGlobalEventHandlerService]  | jingleSessionInfoRefer -- transfer call is requested for session ${sid} to contact ${referTo}`);
                //we need to make initial call to that user and send him the otherSid parameter
                await this.webrtcP2PService.webrtcP2PEventHandler.onTrasferCallEvent(referTo, otherSid);
                this.webrtcP2PService.onCallTransferred(call);
                this.webrtcP2PService.sendReferStatus(sid, "complete");
            } else if (method && referTo) { //RQRAINB-5819
                //this.webrtcP2PService.onCallBlindTransfer(call, {"method":method, "referTo":referTo});
                this.onCallBlindTransfer(call, { "method": method, "referTo": referTo });
            } else {
                this.logger.error("[WebrtcGlobalEventHandlerService]  | jingleSessionInfoRefer -- wrong parameters ");
            }
        }
        else {
            this.logger.error("[WebrtcGlobalEventHandlerService]  | jingleSessionInfoRefer -- no session ");
        }
    }

    private onCallBlindTransfer(call, transferData) { //RQRAINB-5819
        // const session = this.xmppService.connection.jingle.sessions[call.id];
        if (!transferData) {
            this.logger.info("[WebrtcGlobalEventHandlerService] | onCallBlindTransfer ERROR");
            this.logger.error("no transfer Data");
        } else {
            this.webrtcP2PService.releaseCall(call);//1st release former call
            if (transferData.method === "webrtc") {
                this.logger.info("[WebrtcGlobalEventHandlerService] | onCallBlindTransfer webrtc");
                const contact = this.contactService.getContactFromCacheByJid(transferData.referTo);
                if (contact) {
                    this.webrtcP2PService.makeCall(contact, "audio");
                } else {
                    this.logger.info("[WebrtcGlobalEventHandlerService] | onCallBlindTransfer ERROR");
                    this.logger.error("unknow contact");
                }
            } else if (transferData.method === "pbx") {
                this.logger.info("[WebrtcGlobalEventHandlerService] | onCallBlindTransfer sip");
                if (!this.telephonyService) {
                    this.logger.error("[WebrtcGlobalEventHandlerService] -- missing telephony service !");
                    return;
                }
                this.telephonyService.makeCallByPhoneNumber(transferData.referTo);
            } else {
                this.logger.info("[WebrtcGlobalEventHandlerService] | onCallBlindTransfer ERROR");
                this.logger.error("wrong transfer Data");
            }
        }
    }

    private jingleP2POnSetLocalDescription(sid: string) {
        const sess = this.xmppService.connection.jingle.sessions[sid];
        if (sess?.enableDSCP) {
            //we need to check if we need to update the session DSCP
            this.logger.info("[WebrtcGlobalEventHandlerService] | jingleP2POnSetLocalDescription for session " + sid);
            sess.setDSCPValues();
        }
    }

    private jingleP2PUpdateStream(sid: string) {
        const call = this.webrtcP2PService?.calls[sid];
        const sess = this.xmppService.connection.jingle.sessions[sid];
        if (call && sess && !this.webConferenceService?.hasActiveWebConferenceSession()) {
            this.logger.info("[WebrtcGlobalEventHandlerService] | jingleP2PUpdateStream for session " + sid);
            this.webrtcP2PService.attachDistantMediaStreams(true, call);
        }
    }
}
