    // Call capabilities
    public get capabilities(): CallCapabilities {
        return this._capabilities;
    }

    /**
     * Update globally the capabilities of the call.
     * Tests are performed to check whether capabilities have been modified and whether the data needs to be updated.
     * This avoids sending an 'ON_CALL_CAPABILITIES_UPDATED' event if no changement has been detected.
     * @param capabilities - The new values of the capabilities
     */
    public set capabilities(capabilities: CallCapabilities) {
        //compare both capabilities ...
        let update = false;
        Object.keys(this._capabilities).forEach((key) => {
            switch (key) {
                case 'transferCallDestinations': {
                    let dataUpdated = (this._capabilities['transferCallDestinations'].length !== capabilities['transferCallDestinations'].length);
                    if (!dataUpdated && this._capabilities['transferCallDestinations'].length) {
                        //compare array items
                        dataUpdated = !this._capabilities['transferCallDestinations'].every((call: CallRB) => {
                            return capabilities['transferCallDestinations'].find((call2) => ((call2 as CallRB).id) === call.id);
                        });
                    }
                    update = update || dataUpdated;
                    break;
                }

                case 'deflectPhoneNumberDestinations': {
                    // deflectPhoneNumberDestinations: [{ id: string; number: string }?];
                    let dataUpdated = (this._capabilities['deflectPhoneNumberDestinations'].length !== capabilities['deflectPhoneNumberDestinations'].length);
                    if (!dataUpdated) {
                        //compare array items
                        dataUpdated = !this._capabilities['deflectPhoneNumberDestinations'].every((elem1) =>
                            capabilities['deflectPhoneNumberDestinations'].some(
                                (elem2) => elem1.id === elem2.id && elem1.number === elem2.number
                            )
                        );
                    }
                    update = update || dataUpdated;
                    break;
                }

                default:
                    if (this._capabilities[key] !== capabilities[key]) {
                        update = true;
                    }
                    break;
            }
        });
        if (update) {
            this._capabilities = capabilities;
            this.sendEvent(CallEvents.ON_CALL_CAPABILITIES_UPDATED);
        }
    }


