    public isInConversationWithMobile() {
        if (!this.fullJid) {
            return false;
        }
        return this.fullJid.indexOf("mobile_android") !== -1 || this.fullJid.indexOf("mobile_ios") !== -1;
    }

    public isInConversationWithDesktopApp() {
        if (!this.fullJid) {
            return false;
        }
        return this.fullJid.indexOf("desk_") !== -1;
    }

    public toString() {
        let typeInfo: string = "Undefined";

        switch (this.callType) {
            case CallType.WEBRTC:
                typeInfo = "Video";
                break;

            case CallType.PHONE:
                typeInfo = "Phone";
                break;
            default: break;
        }

        let myString = `(type: ${typeInfo}, id: ${this.id}, status: ${this.callStatus}`;
        if (this.isConference) { myString += " conference"; }
        myString += ")";
        return myString;
    }

    public toJSON(): any {

        let typeInfo: string = "Undefined";

        switch (this.callType) {
            case CallType.WEBRTC:
                typeInfo = "Video";
                break;

            case CallType.PHONE:
                typeInfo = "Phone";
                break;
            default: break;
        }

        const json: any = {
            id: this.id,
            type: typeInfo,
            status: this.callStatus
        };

        if (this.contact) {
            json.contact = {
                id: this.contact.dbId,
            };
            if (this.contact?.name) {
                json.contact.name = this.contact.name;
            }
        }

        this.toString();

        return json;
    }

    // ----------------------------------------------------
    //  DURATION MANAGEMENT
    // ----------------------------------------------------

    private manageDurationTimer() {
        if (this.callStatus === CallStatus.ACTIVE) {
            //in case of ACTIVE call, start the TIMER
            this.startDuration();
        }
        else if (this.callStatus === CallStatus.ENDED) {
            //in case of UNKNOWN state, or in case of transfer
            this.stopDuration();
        }
    }

    private manageIncomingPopupData() {
        if (this.callStatus === CallStatus.ENDED) {
            //in case of UNKNOWN state, clear noIncomingPopup property
            this.noIncomingPopup = false;
        }
    }

    public startDuration() {
        if (this.durationTimer) return;
        this.durationTimer = interval(1000).subscribe(() => {
            this.duration++;
        });
    }

    public stopDuration() {
        if (this.durationTimer) {
            this.durationTimer.unsubscribe();
            this.durationTimer = null;
            this.duration = 0;
        }
    }


