    public isWebRtcMediaPillar() {
        return (this.fullJid && this.fullJid.indexOf("mp_") === 0);
    }

    /**
     * Check if the call is linked to a media pillar context
     * Note: if it is a new call not already managed through webrtcGatewayService then not conclusive
     * (because could be linked after)
     */
    public isMediaPillarCall() {
        return this.mediaPillarCall !== null || this.isWebRtcMediaPillar();
    }

    public isInCallWithMediaPillar() {
        return this.fullJid && this.fullJid.indexOf("mp_") !== -1;
    }

    public getMediaPillarCall() {
        return this.mediaPillarCall;
    }

    public setMediaPillarCall(mediaPillarCallContext: any) {
        this.mediaPillarCall = mediaPillarCallContext ? mediaPillarCallContext : null;
    }

