    public createdOffer(offer: any, actionName?: string, application?: any) {
        const self = this;
        try {
            // Fix offer
            offer = this.hackOfferSDP(offer);
            offer = this.hackMsLabelSDP(offer);

            // Create localSDP
            this.localSDP = new SDP(offer.sdp);

            const action = actionName ? actionName : 'session-initiate';
            this.logger.log(`[Strophe.jingle] createdOffer(spd: ${offer.sdp}, action: ${action}`);

            let init = $iq({
                to: this.peerjid,
                type: 'set'
            })
                .c('jingle', {
                    xmlns: 'urn:xmpp:jingle:1',
                    action: action,
                    initiator: this.initiator,
                    sid: this.sid,
                    localType: this.localType
                });

            if (application) {
                init = init.c("x-rainbow-app", { xmlns: 'urn:xmpp:jingle:rainbow:media:desc' })
                    .c('content', { id: application.id, name: application.name, description: application.description, affiliation: application.affiliation });
                init.up();
                init.up();
            }

            if (this.calledNumber && this.calledNumber !== "") { //callednumber for webrtcGateway-mediaPillar
                init = init.c('mediapillar', { xmlns: 'urn:xmpp:janus:1' })
                    .c('callednumber')
                    .t(this.calledNumber);
                init.up();
                init.up();
            }

            if (this.isEchoTest) {
                init = init.c('echotest', {
                    xmlns: 'urn:xmpp:janus:1'
                });
                init.up();
            }

            if (this.replaceSid && this.callShift) {
                init = init.c('replaces', {
                    sid: this.replaceSid,
                    callShift: true
                });
                init.up();
            }
            else if (this.replaceSid) {
                init = init.c('replaces', {
                    sid: this.replaceSid
                });
                init.up();
            }

            this.localSDP.toJingle(init, this.initiator === this.me ? 'initiator' : 'responder', this.conference_id, this.bandwidthLimitSettings);
            // this.addConferenceInfo(init);
            this.connection.sendIQ(init,
                function() {
                    const ack: any = {};
                    ack.source = 'offer';
                    //$(document).trigger('ack.jingle', [self.sid, ack]);
                    self.connection.jingle.rxSubject.next({ name: 'ack.jingle', data: { sid: self.sid, ack: ack } });
                },
                function(stanza) {
                    self.state = 'error';
                    if (self.peerconnection && self.peerconnection.signalingState !== "closed") {
                        self.logger.log('[Strophe.jingle] Clear peerconnection');
                        self.peerconnection.close();
                        self.peerconnection = null;
                    }
                    const error: any = ($(stanza).find('error').length) ? {
                        code: $(stanza).find('error').attr('code'),
                        reason: $(stanza).find('error :first')[0].tagName,
                    } : {};
                    error.source = 'offer';
                    //$(document).trigger('jingleError', { sid: self.sid, error: error });
                    self.connection.jingle.rxSubject.next({ name: 'jingleError', data: { sid: self.sid, error: error } });
                },
                this.jingleIqTimeout);

            offer.sdp = this.localSDP.raw;
            this.peerconnection.setLocalDescription(offer,
                function() {
                    //$(document).trigger('setLocalDescription.jingle', [self.sid]);
                    self.connection.jingle.rxSubject.next({ name: 'setLocalDescription.jingle', data: { sid: self.sid } });
                    self.logger.log('[Strophe.jingle] setLocalDescription success');
                },
                function(e) {
                    const msg = (e && e.toString) ? e.toString() : e;
                    self.logger.error('[Strophe.jingle] createdOffer -- setLocalDescription failed -- ' + msg);
                    self.logger.log('[Strophe.jingle] setLocalDescription failed ' + e);
                }
            );
        } catch (error) {
            self.logger.log('[Strophe.jingle] JingleSession.prototype.createdOffer failed: ' + error);
        }
    }

