    public async contentModify(mediaStreamType: string, options?: any): Promise<void> {
        try {
            this.logger.log(`[Strophe.jingle] contentModify(mediaStreamType: ${mediaStreamType}`);
            let readdStreamFlag = false;

            if (!options) {
                options = {};
                if (this.reconnectionOptions) options.offerToReceiveAudio = this.reconnectionOptions.offerToReceiveAudio;
            }

            // In case of MP call with RB Hub, the media modified message can be related to the "put on hold" / "unhold" events
            // We should store the current incoming SDP settings, so that we can generate correct SDP in case of transport-replace
            // So if we receive sendonly SDP for the m=audio media, then we should not resend audio in case of reconnection
            if (this.peerjid.indexOf("mp_rvcp") !== -1) {
                if (this.ice_config.sdpSemantics === "plan-b") {
                    const disableLocalAudio = this.checkIfRemoteSdpHasSendonlyAudioMedia(this.remoteSDP.raw);
                    if (disableLocalAudio) {
                        // Remove all streams from the peer connection, and add them after that
                        this.removeStream();
                        readdStreamFlag = true;
                    }
                }
                else if (this.localTransceivers[0].currentDirection === "recvonly")
                    this.localTransceivers[0].direction = "recvonly";
            }

            const sdp = await this.peerconnection.createOffer(options);
            this.contentUpdateOffer(sdp, mediaStreamType, "modify");
            if (readdStreamFlag) this.peerconnection.addStream(this.localStreams[0]);
        }
        catch (error) {
            this.logger.log('[Strophe.jingle] contentModify failed ' + error);
            this.logger.log(error);
        }
    }

