    private setCodecPreferencesForSession() {
        if (this.localTransceivers[0] && this.ice_config.forceRedCodec) {
            this.setCodecPreference("audio", "red", this.localTransceivers[0]);
        }
        if (this.localTransceivers[1] && (this.company_config?.videoExt?.preferredCodec === "h264" || navigator.platform.toUpperCase().indexOf("MAC") >= 0)) {
            this.setCodecPreference("video", "h264", this.localTransceivers[1]);
        }
        if (this.localTransceivers[2] && (this.company_config?.sharingExt?.preferredCodec === "h264" || navigator.platform.toUpperCase().indexOf("MAC") >= 0)) {
            this.setCodecPreference("video", "h264", this.localTransceivers[2]);
        }
    }

    private sortByMimeTypes(codecs: RTCRtpCodecCapability[], preferredOrder): RTCRtpCodecCapability[] {
        return codecs.sort((a, b) => {
            const indexA = preferredOrder.indexOf(a.mimeType);
            const indexB = preferredOrder.indexOf(b.mimeType);
            const orderA = indexA >= 0 ? indexA : Number.MAX_VALUE;
            const orderB = indexB >= 0 ? indexB : Number.MAX_VALUE;
            return orderA - orderB;
        });
    }

    //supported codecs are
    private setCodecPreference(media: string, preferredCodec: string, transceiver: RTCRtpTransceiver) {
        if (!RTCRtpReceiver?.getCapabilities || !transceiver.setCodecPreferences) {
            this.logger.log(`[Strophe.jingle] setCodecPreference ${this.sid} not supported`);
            return;
        }

        try {
            this.logger.log(`[Strophe.jingle] set codec preference for ${media} ${this.sid} to ${preferredCodec}`);
            const supportedCodecs = RTCRtpReceiver.getCapabilities(media).codecs;
            let preferredCodecs;
            if (preferredCodec === 'h264') { preferredCodecs = ["video/H264", "video/VP8", "video/VP9"]; }
            else if (preferredCodec === 'red') { preferredCodecs = ["audio/red", "audio/opus"]; }
            const sortedCodecs = this.sortByMimeTypes(supportedCodecs, preferredCodecs);
            transceiver.setCodecPreferences(sortedCodecs);
        }
        catch (error) {
            this.logger.log(`[Strophe.jingle] set codec preference for ${media} ${this.sid} to ${preferredCodec} error -- ${error}`);
        }
    }

    public async setRemoteDescription(elem, desctype) {
        const self = this;
        self.logger.log('[Strophe.jingle] setRemoteDescription ' + desctype);
        this.remoteSDP = new SDP('');
        this.remoteSDP.fromJingle(elem, this);

        if (this.isInitiator) {
            this.remoteSDP.raw = this.remoteSDP.raw.replace(/a=setup:passive/g, "a=setup:active");
        } else {
            this.remoteSDP.raw = this.remoteSDP.raw.replace(/a=setup:active/g, "a=setup:passive");
        }

        //activate Discontinuous Transmission (DTX)
        if (this.DTX) {
            self.logger.log('[Strophe.jingle] activate Discontinuous Transmission (DTX)');
            this.remoteSDP.raw = this.remoteSDP.raw.replace("useinbandfec=1", "useinbandfec=1;usedtx=1");
        }

        self.logger.log('[Strophe.jingle] setRemoteDescription after parsing for session ' + this.sid + " : " + this.remoteSDP.raw);
        const remotedesc = new window.RTCSessionDescription({ type: desctype, sdp: this.remoteSDP.raw });
        try {
            await this.peerconnection.setRemoteDescription(remotedesc);
            self.logger.log('[Strophe.jingle] setRemoteDescription success');
            self.localTransceivers = self.peerconnection.getTransceivers();

            //remove the wrong receivers for horizon
            if (this.ice_config.horizon) {
                self.localTransceivers.forEach((transceiver, index) => {
                    if (!transceiver["id"] && !transceiver.mid) {
                        self.localTransceivers.splice(index, 1);
                    }
                });

                //also order
                self.localTransceivers = self.localTransceivers.sort((a, b) => {
                    return (parseInt(a.mid, 10) < parseInt(b.mid, 10)) ? -1 : 1;
                });
            }

            //set codec preferences
            if ((!self.conference_id || self.conference_id === -1)) {
                //set codec preferences based on the configuration
                //only for direct P2P calls and no conferences
                this.setCodecPreferencesForSession();
            }
        }
        catch (e) {
            const msg = (e && e.toString) ? e.toString() : e;
            self.logger.error('[Strophe.jingle] setRemoteDescription -- setRemoteDescription failed -- ' + msg);
            self.logger.error(e);
        }
    }

    public addIceCandidate(elem) {
        // self.logger.log('add ice candidate ' + JSON.stringify(event.candidate, null, ' '));
        const self = this;
        self.logger.log('[Strophe.jingle] addIceCandidate');

        // operate on each content element
        elem.each(function() {

            ////// to modify
            let idx = -1;
            let i;
            for (i = 0; i < self.remoteSDP.media.length; i++) {
                if (SDPUtil.find_line(self.remoteSDP.media[i], 'a=mid:' + $(this).attr('name')) ||
                    self.remoteSDP.media[i].indexOf('m=' + $(this).attr('name')) === 0) {
                    idx = i;
                    break;
                }
            }
            if (idx == -1) { // fall back to localdescription
                for (i = 0; i < self.localSDP.media.length; i++) {
                    if (SDPUtil.find_line(self.localSDP.media[i], 'a=mid:' + $(this).attr('name')) ||
                        self.localSDP.media[i].indexOf('m=' + $(this).attr('name')) === 0) {
                        idx = i;
                        break;
                    }
                }
            }

            ////// to modify end
            const name = $(this).attr('name');
            // TODO: check ice-pwd and ice-ufrag?
            // if ($(this).attr('ufrag') && $(this).attr('pwd')) {
            //    self.logger.log($(this).attr('ufrag'));
            //    self.logger.log($(this).attr('pwd'));
            // }

            let ufrag;
            let pwd;

            const network = "";
            const id = "";
            // network = $(this).attr('network');
            // id = $(this).attr('id');

            $(this).find('content>transport').each(function() {
                ufrag = this.getAttribute("ufrag");
                pwd = this.getAttribute("pwd");
            });

            $(this).find('transport>candidate').each(function() {
                let line; let candidate;
                line = SDPUtil.candidateFromJingle(this, ufrag, pwd);
                candidate = new window.RTCIceCandidate({
                    sdpMLineIndex: idx,
                    sdpMid: name,
                    candidate: line
                });
                try {
                    if (candidate && self.iceFilterList && self.iceFilterList.length) {
                        if (self.iceFilterList.indexOf(candidate.type) !== -1) {
                            self.logger.log('[Strophe.jingle] Received ICE candidate ' + candidate.type + ' is filtered');
                            return;
                        }
                    }
                    self.peerconnection.addIceCandidate(candidate);
                } catch (e) {
                    self.logger.error('[Strophe.jingle] addIceCandidate failed ' + e.toString());
                }
            });
        });
    }

