    public addSource(elem) {
        const self = this;
        self.logger.log('[Strophe.jingle] addssrc', new Date().getTime());
        self.logger.log('[Strophe.jingle] ice', this.peerconnection.iceConnectionState);
        const sdp = new SDP(this.peerconnection.remoteDescription.sdp);


        $(elem).each(function(idx, content) {
            const name = $(content).attr('name');
            let lines = '';
            const tmp = $(content).find('>source[xmlns="urn:xmpp:jingle:apps:rtp:ssma:0"]');
            tmp.each(function() {
                const ssrc = $(this).attr('ssrc');
                $(this).find('>parameter').each(function() {
                    lines += 'a=ssrc:' + ssrc + ' ' + $(this).attr('name');
                    if ($(this).attr('value') && $(this).attr('value').length)
                        lines += ':' + $(this).attr('value');
                    lines += '\r\n';
                });
            });
            sdp.media.forEach(function(media, idx) {
                if (!SDPUtil.find_line(media, 'a=mid:' + name))
                    return;
                sdp.media[idx] += lines;
                if (!self.addssrc[idx]) self.addssrc[idx] = '';
                self.addssrc[idx] += lines;
            });
            sdp.raw = sdp.session + sdp.media.join('');
        });
        this.modifySources();
    }

