    public modifySources() {
        const self = this;
        if (!this.peerconnection || this.peerconnection.signalingState == 'closed') return;
        if (!(this.addssrc.length || this.removessrc.length || this.pendingop !== null)) return;
        if (!this.wait && !(this.peerconnection.signalingState == 'stable' && (this.peerconnection.iceConnectionState == 'connected' || this.peerconnection.iceConnectionState == 'completed'))) {
            self.logger.warn('[Strophe.jingle] modifySources not yet ' + this.peerconnection.signalingState + ' ' + this.peerconnection.iceConnectionState);
            this.wait = true;
            window.setTimeout(function() { self.modifySources(); }, 1500);
            return;
        }
        if (this.wait) {
            window.setTimeout(function() { self.modifySources(); }, 2500);
            this.wait = false;
            return;
        }

        const sdp = new SDP(this.peerconnection.remoteDescription.sdp);

        // add sources
        this.addssrc.forEach(function(lines, idx) {
            sdp.media[idx] += lines;
        });
        this.addssrc = [];

        // remove sources
        this.removessrc.forEach(function(lines, idx) {
            lines = lines.split('\r\n');
            lines.pop(); // remove empty last element;
            lines.forEach(function(line) {
                sdp.media[idx] = sdp.media[idx].replace(line + '\r\n', '');
            });
        });
        this.removessrc = [];

        sdp.raw = sdp.session + sdp.media.join('');
        this.peerconnection.setRemoteDescription(new window.RTCSessionDescription({ type: 'offer', sdp: sdp.raw }),
            function() {
                this.peerconnection.createAnswer()
                    .then((modifiedAnswer) => {
                        // change video direction, see https://github.com/jitsi/jitmeet/issues/41
                        if (self.pendingop !== null) {
                            const sdp = new SDP(modifiedAnswer.sdp);
                            if (sdp.media.length > 1) {
                                switch (self.pendingop) {
                                    case 'mute':
                                        sdp.media[1] = sdp.media[1].replace('a=sendrecv', 'a=recvonly');
                                        break;
                                    case 'unmute':
                                        sdp.media[1] = sdp.media[1].replace('a=recvonly', 'a=sendrecv');
                                        break;
                                }
                                sdp.raw = sdp.session + sdp.media.join('');
                                modifiedAnswer.sdp = sdp.raw;
                            }
                            self.pendingop = null;
                        }

                        self.peerconnection.setLocalDescription(modifiedAnswer,
                            function() {
                                //self.logger.log('modified setLocalDescription ok');
                                // $(document).trigger('setLocalDescription.jingle', [self.sid]);
                                self.connection.jingle.rxSubject.next({ name: 'setLocalDescription.jingle', data: { sid: self.sid } });
                            },
                            function(error) {
                                self.logger.log('[Strophe.jingle] modified setLocalDescription failed');
                            }
                        );
                    })
                    .catch((error) => {
                        self.logger.log('[Strophe.jingle] modified answer failed');
                        self.logger.log(error);
                    });
            },
            function(error) {
                self.logger.log('[Strophe.jingle] modify failed');
            }
        );
    }

