    public sendHold(hold: boolean): Promise<void> {
        return new Promise((resolve, reject) => {
            if (this.onHold === hold) resolve();
            else {
                // Create the info stanza
                const sessionInfo = $iq({ to: this.peerjid, type: 'set' })
                    .c('jingle', {
                        xmlns: 'urn:xmpp:jingle:1',
                        action: 'session-info',
                        initiator: this.initiator,
                        sid: this.sid
                    })
                    .c(hold ? 'hold' : 'unhold', { xmlns: 'urn:xmpp:jingle:apps:rtp:info:1' });

                this.connection.sendIQ(
                    sessionInfo,
                    () => { this.onHold = hold; resolve(); },
                    (error: any) => {
                        this.logger.error('[Strophe.jingle] JingleSession.prototype.sendHold failed: ' + error?.message);
                        reject(error);
                    }
                );
            }
        });
    }

