import { Plugin } from './plugin';
import { LoggerService } from 'rainbow-sdk/services/core/logger.service';
import { DocumentServiceRB } from 'rainbow-sdk/services/documents/documents.service';
import { FileStorageService } from '../services/files/fileStorage.service';
import { FileServerService } from '../services/files/fileServer.service';

export class DocumentsPlugin extends Plugin {
    public static initialize(): void {
        Plugin.initialize();

        if (!window.rainbow.plugins[DocumentsPlugin.name]) {
            const logger = LoggerService.getInstance();
            logger.info("[DocumentsPlugin] initialized");
            window.rainbow.plugins[DocumentsPlugin.name] = new DocumentsPlugin();
            FileStorageService.getInstance();
            FileServerService.getInstance();
            DocumentServiceRB.getInstance();
        }
    }

    private constructor() {
        super();
    }
}
