/**
 * Bubble user role
 * Each role gives access to different functionalities in Bubbles.
 */
export enum BubbleUserRole {
    /**
     * Users are basic members who have accepted an invitation to join a Bubble.
     * They can then send messages in the bubble, join a Web Conference and leave the Bubble.
     * Users have no right to manage the bubble and the members in this one.
     */
    USER = "user",

    /**
     * Organizers are bubble members who have been promoted to manage the bubble and the members in this one.
     * Organizers can be promoted by the owner or by another organizer.
     * They can also subsequently be demoted to basic member by another owner or organizer.
     * Organizers have the ability to invite or remove members/guests in the bubble, to share the bubble through a public direct link.
     * They can send messages in the bubble, start/join a Web Conference and leave the Bubble.
     */
    // !! IMPORTANT WARNING !! Don't change string value "moderator" for this enum
    ORGANIZER = "moderator",

    /**
     * @internal
     */
    GUEST = "guest"
}

/**
 * Status of a user in the bubble
 */
export enum BubbleUserStatus {
    /**
     * The user has been invited to join the bubble.
     */
    INVITED = 'invited',

    /**
     * The user has accepted the invitation to join the bubble and is an active member.
     */
    ACCEPTED = 'accepted',

    /**
     * The user has declined the invitation to join the bubble.
     */
    REJECTED = 'rejected',

    /**
     * This status applies to 3 situations:
     * - The user has been removed from the bubble by the owner or one of the organizers.
     * - The user left the bubble on his own and has not requested the creation of an archive for this bubble.
     * - The user has deleted the archive of a bubble he previously left
     */
    DELETED = 'deleted',

    /**
     * The user left the bubble of his own.
     * During this operation, the user has requested the creation of an archive for this bubble.
     */
    UNSUBSCRIBED = 'unsubscribed',
}

/**
 * Type of message history to be returned to a new bubble user.
 */
export enum BubbleHistoryType {
    /**
     * All the previous messages history are provided to a new bubble user
     */
    ALL = "all",

    /**
     * No message history is provided to a new bubble user
     */
    NONE = "none"
}


/**
 * Visibility of the bubble
 */
export enum BubbleVisibility {
    /**
     * A private bubble can be joined only by invitation or via a public link if the bubble has been shared (bubble configuration parameter).
     */
    PRIVATE = 0,

    /**
     * A public bubble can be found via a search operation (using 'searchBubbles()' method) or get by its identifier
     * even if a user is not a member of this bubble. Information on such bubbles are provided for guidance only.
     */
    PUBLIC = 1
}


/**
 * @eventProperty
 * `Bubble` specific events
 * Can listen to it via `bubble.subscribe()` API
 */
export enum BubbleEvents {

    /**
     * @eventProperty
     * This `RBEvent` is sent when a user has accepted the invitation in the bubble
     * **Event Data**
     * - **bubbleUser**: The bubble user who has accepted the invitation
    */
    ON_USER_INVITATION_ACCEPTED = 'ON_USER_INVITATION_ACCEPTED',

    /**
     * @eventProperty
     * This `RBEvent` is sent when a user has declined the invitation to join the bubble
     * **Event Data**
     * - **bubbleUser**: The bubble user who has declined the invitation
     */
    ON_USER_INVITATION_DECLINED = 'ON_USER_INVITATION_DECLINED',

    /**
     * @eventProperty
     * This `RBEvent` is sent when a user has left the bubble of his own
     * **Event Data**
     * - **bubbleUser**: The bubble user who has left the bubble
     */
    ON_USER_BUBBLE_LEFT = 'ON_USER_BUBBLE_LEFT',

    /**
     * @eventProperty
     * This `RBEvent` is sent when a user has been removed from the bubble by the owner or one of the organizers
     * **Event Data**
     * - **bubbleUser**: The bubble user who has been removed from the bubble
     */
    ON_USER_BUBBLE_REMOVED = 'ON_USER_BUBBLE_REMOVED',

    /**
     * @eventProperty
     * This RBEvent is sent when the bubble avatar is updated
     */
    ON_AVATAR_UPDATE = 'ON_AVATAR_UPDATE',

    /**
     * @eventProperty
     * This RBEvent is sent when the dialInCode is updated
     */
    ON_DIAL_IN_CODE_UPDATE = 'ON_DIAL_IN_CODE_UPDATE',

    /**
     * @eventProperty
     * This RBEvent is sent when the includeAllPhoneNumber is updated
     */
    ON_INCLUDE_ALL_PHONENUMBER_UPDATE = 'ON_INCLUDE_ALL_PHONENUMBER_UPDATE',

    /**
     * @eventProperty
     * This RBEvent is sent when the dialInPhoneNumber is updated
     */
    ON_DIAL_IN_PHONENUMBER_UPDATE = 'ON_DIAL_IN_PHONENUMBER_UPDATE',

    /**
     * @eventProperty
     * This RB event is sent when the user's role is updated
     */
    ON_USER_ROLE_UPDATE = 'ON_USER_ROLE_UPDATE',

    /**
     * @internal
     * @eventProperty
     * @param lobbyUsers - the updated list of lobby users
     * This RB event is send when the list of users in the waiting lobby is updated
     */
    ON_USERS_IN_LOBBY_UPDATE = 'ON_USERS_IN_LOBBY_UPDATE',

    /**
     * @internal
     * @eventProperty
     * @param status - The current status of the request of type AccessRequestStatus
     * This RB event is send when the connected user's request to join bubble is updated (or created)
     */
    ON_MY_USER_IN_LOBBY_UPDATE = 'ON_MY_USER_IN_LOBBY_UPDATE',

    /**
     * @eventProperty
     * This RB event is send when the conference attached to this bubble is started
     */
    ON_CONFERENCE_START_EVENT = 'ON_CONFERENCE_START_EVENT',

    /**
     * @eventProperty
     * This RB event is sent when the conference attached to this bubble is Stopped
     */
    ON_CONFERENCE_STOP_EVENT = 'ON_CONFERENCE_STOP_EVENT',

    /**
     * @eventProperty
     * This RB event is sent when the conference attached to this bubble is Stopped
     */
    ON_TAGS_UPDATED = 'ON_TAGS_UPDATED',

    /**
     * @eventProperty
     * This RB WTF event is sent when something happen !!!
     * Temporary event, please don't use this stuff
     */
    ON_DATA_UPDATED = 'ON_DATA_UPDATED'
}

/**
 * Bubble data that can be cleaned
 */
export enum BubbleCleanupData {
    /**
     * All rooms IM will be removed for all room members, all pins will also be removed
     */
    IM = "im",

    /**
     * All pools associated to that room will be removed
     */
    POLL = "poll",

    /**
     * That rooms won't be viewer of any document (Document's list will appear empty)
     */
    DOCUMENT = "document",

    /**
     *  All members of this room that is not an organizer will be removed
     */
    MEMBER = "member",

    /**
     * All recordings will be removed
     */
    RECORD = "record"
}
/**
 * This interface defines the settings that can be sent to the setSettings bubble API
 */
export interface BubbleSettings {
    /**
     * The bubble name
     */
    name?: string;

    /**
     * The bubble description
     */
    description?: string;

    /**
     * A user can create a bubble and not have to register users. He can share instead a public link also called 'public URL'(users public link).
     * Depending on the autoRegister value, if another person uses the link to join the bubble :
     * autoRegister = 'unlock':
     * If this user is not yet registered inside this bubble, he is automatically included with the status 'accepted' and join the bubble.
     * autoRegister = 'lock':
     * If this user is not yet registered inside this bubble, he can't access to the bubble. So that he can't join the bubble.
     * autoRegister = 'unlock_ack' (value not authorized yet):
     * If this user is not yet registered inside this bubble, he can't access to the bubble waiting for the bubble's owner acknowledgment.
     */
    autoRegister?: string;

    /**
     * Invited users will be auto-added in the bubble
     */
    autoAcceptInvitation?: boolean;

    /**
     * In case of conference in this bubble, all participants will be muted upon join
     */
    muteUponEntry?: boolean;

    /**
     * In the event of a conference in this bubble, specify whether a local tone should be played each time a participant joins the conference.
     */
    playEntryTone?: boolean;

    /**
     * Indicates if user chooses to include all Dial In phone numbers
     */
    includeAllPhoneNumbers?: boolean;

    /**
     * Content to clear automatically at conference end (only room creator can modify it)
     */
    contentToAutoClear?: {
        im: boolean,
        poll: boolean,
        document: boolean,
        member: boolean
    }
}

