export interface Bubble {
    conference: any;

    // ----------------------------------------------------
    // INTERFACE DATA
    // ----------------------------------------------------

    /**
     * The bubble database Identifier
     * @readonly
     */
    dbId: string;

    /**
     * The jid associated to this bubble
     * @readonly
     */
    jid: string;

    /**
     * The name of the bubble
     * @readonly
     */
    name: string;

    /**
     * A description of the purpose of the bubble
     * @readonly
     */
    description: string;

    /**
     * The bubble avatar
     * @readonly
     */
    avatar: string;

    /**
     * The visibility of the bubble
     * A public bubble can be found via a search operation (using 'searchBubbles()' method) or get by its identifier
     * even if the connectedUser is not a member of this bubble.
     * A private bubble can be joined only by invitation or via a public link if the bubble has been shared for this purpose.
     * @readonly
     */
    visibility: BubbleVisibility;

    /**
     * Allow newcomers to access or not messages history. If the value is "all", a newcomer can retrieve the full bubble messages history
     * @readonly
     */
    history: BubbleHistoryType;

    /**
     * When set to true, allows to automatically add participants in the bubble (default behavior is that participants need to accept the bubble invitation first before being a member of this bubble)
     * @readonly
     */
    autoAcceptInvitation: boolean;

    /**
     * A user can create a bubble and not have to register users. He can share instead a public link also called 'public URL'(users public link).
     * Depending on the autoRegister value, if another person uses the link to join the bubble :
     * autoRegister = 'unlock':
     * If this user is not yet registered inside this bubble, he is automatically included with the status 'accepted' and join the bubble.
     * autoRegister = 'lock':
     * If this user is not yet registered inside this bubble, he can't access to the bubble. So that he can't join the bubble.
     * autoRegister = 'unlock_ack' (value not authorized yet):
     * If this user is not yet registered inside this bubble, he can't access to the bubble waiting for the bubble's owner acknowledgment.
     * @readonly
     */
    autoRegister: string;

    /**
     * If the bubble has alert notification feature enabled
     * The notification feature must be enabled
     * @readonly
     */
    isAlertNotificationEnabled: boolean;

    /**
     * The owner of the bubble
     * @readonly
     */
    owner: User;

    /**
     * Information on the connected user in this bubble.
     * @readonly
     */
    bubbleConnectedUser: BubbleUser;

    /**
     * Custom data associated to the bubble
     * @readonly
     */
    customData: any;

    /**
     * The number of users of the bubble with the status 'accepted' (he joined the bubble) or 'invited'.
     * They are considered to be the actual participants in the bubble.
     * @readonly
     */
    nbParticipants: number;

    /**
     * The creation date of the bubble
     * @readonly
     */
    creationDate?: Date;

    /**
     * last activity date of bubble
     * @readonly
     */
    lastActivityDate?: Date;

    /**
     * Indicates whether the bubble is ready for chatting.
     * @readonly
     */
    ready: boolean;

    /**
     * Rainbow HUB specificity for Hunting Group .
     * Specifies whether the bubble is created as managed bubble.
     * In this case, there is no owner of the bubble; each member acts as organizer.
     * In addition, a group member cannot leave the bubble and cannot be removed from the bubble.
     * @readonly
     */
    isHuntingGroup: boolean;

    /**
     * The bubble is managed by a Rainbow user acting as the bubble administrator.
     * This user is not a member of the bubble (It is not known to other members) and does not, by default, have the role of owner.
     * But it can manage the list (settings, members), as if it were the owner. In fact, it can give itself this role.
     * @readonly
     */
    isOwnedByBubbleAdmin: boolean;

    /**
     * Bubble associated tags
     * @readonly
     */
    tags: BubbleTag[];

    /**
     * The bubble is managed by a Rainbow user acting as the bubble administrator.
     * This user is not a member of the bubble (It is not known to other members) and does not, by default, have the role of owner.
     * But it can manage the list (settings, members), as if it were the owner. In fact, it can give itself this role.
     */
    contentToClear: {im: boolean; document: boolean; poll: boolean; member: boolean; record: boolean}

    // ----------------------------------------------------
    // INTERFACE API
    // ----------------------------------------------------
    /**
     * Permits to emit BubbleEvents events
     * Can be listened via bubble.subscribe() API
     * @param name - the name of the event
     * @param data - the data to be send (an object
     */
    sendEvent(name: BubbleEvents, data?: any):void ;

    /**
     * Subscribe to updates on this bubble (all events are of `RBEvent` type)
     * @param handler - The call-back function that will be subscribed to the RxJS subject
     */
    subscribe(handler: (event: RBEvent<BubbleEvents>) => any, eventNames?: BubbleEvents | BubbleEvents[]): Subscription;

    /**
     * Bubbles have a default avatar made up of the avatars of the first 4 participants in the bubble.
     * But this avatar can be overloaded by an image chosen by the user
     * @param base64AvatarImg - The image to be set
     * @param width - The width of the image to be set
     * @param height - The height of the image to be set
     */
    setCustomAvatar(base64AvatarImg: string, width?: number, height?: number): Promise<Bubble>;

    /**
     * Remove this bubble custom avatar (reset to default avatar)
     */
    removeCustomAvatar(): Promise<Bubble>;

    /**
     * Update the bubble settings
     * @param bubbleSettings - The settings to be updated in the bubble
     */
    setSettings(bubbleSettings: BubbleSettings): Promise<Bubble>;

    /**
     * Update the bubble custom data
     * @param customData - the custom data to be set to the bubble
     */
    setCustomData(customData: any): Promise<Bubble>;

    /**
     * Update user's role in the Bubble.
     * This operation is only authorised for the organizers and the owner of the bubble.
     * The user can be updated to ORGANIZER or USER.
     * @param user - The user that should be updated
     * @param role - New user role: ORGANIZER or USER
     */
    setUserRole(user: User, role: BubbleUserRole): Promise<Bubble>;

    /**
     * Change the owner of the bubble
     * @param bubble - The bubble
     * @param newOwner - The user that should be the new owner
     */
    changeOwner(newOwner: User): Promise<Bubble>;

    /**
     * Add user to the bubble; Can be used to directly add user without invitation or as a organizer
     * @param user - The user to add in the bubble
     * @param role - The user role in this bubble ('user', 'organizer' or 'guest'), by default is 'user'
     * @param reason - Text that will be join in the invitation
     * @param withoutInvitation - When set to true no invitation is sent
     */
    addUser(user: User, role?: BubbleUserRole, reason?: string, withoutInvitation?: boolean): Promise<Bubble>;

    /**
     * Get all bubble users
     *
     * The 'role' parameter allows to get filtered user arrays (only users or only organizers)
     *
     * **Please note:** this method is asynchronous, as user loading is performed lazily to avoid weighing down the application.
     * @param role - users role (defaut value is 'ALL')
     */
    getUsers(role?: 'ALL'|'USER'|'ORGANIZER'): Promise<BubbleUser[]>;

    /**
     * Remove a user from the Bubble.
     * API only available for organizers / owner of the bubble
     * The user will no longer have access to this bubble nor the history
     * @param user - the contact that should be removed
     */
    removeUser(user: User): Promise<Bubble>;

    /**
     * Mass provisionning API, allow to invite users and guests to the bubble;
     * The guests will receive an email to join the bubble.
     * @param users - The users to add bubble
     * @param emails - List of emails to invite to the bubble
     * @param role - role to be applied to all invited users (organizer for instance)
     */
    inviteUsers(users: User[], emails?: string[], role?: BubbleUserRole): Promise<Bubble>;

    /**
     * Promote all users (basic member) of a bubble to organizer role.
     * This operation is only authorised for the owner of the bubble.
     */
    promoteAllUsers(): Promise<Bubble>;

    /**
     * Demote all organizers of a bubble, except the owner, to user (basic member) role.
     * This operation is only authorised for the owner of the bubble.
     */
    demoteAllUsers(): Promise<Bubble>;

    /**
     * User leaves the bubble.
     * If createArchive is TRUE, the bubble will be archived, i.e. the user can only read the
     * content that's already in the bubble, but no further action can be done inside the bubble
     * The participant will go to UNSUBSCRIBED state (read-only)
     * @param createArchive - If TRUE, the bubble will be archived for my user
     */
    leave(createArchive?: boolean): Promise<Bubble | undefined>;

    /**
     * Delete own bubble.
     * If createArchive is TRUE, the bubble will be archived, i.e. all users can only read the
     * content that's already in the bubble, but no further action can be done inside the bubble
     * All participants in the bubble will go to UNSUBSCRIBED state (read-only)
     * @param createArchive - If TRUE, the bubble will be archived for all users (i.e. read only mode for all users still inside);
     */
    delete(createArchive?: boolean): Promise<Bubble | undefined>;

    /**
     * Check if the given user is the owner of the bubble
     * @param user - The user to check
     */
    isUserOwner(user: User): boolean;

    /**
     * Check if the connected user is the owner of the bubble
     */
    isConnecteUserOwner(): boolean;

    /**
     * Check if the given user is an organizer of the bubble
     * @param user - The user to check
     */
    isUserOrganizer(user: User): boolean;

    /**
     * Check if the connected user is an organizer of the bubble
     */
    isConnecteUserOrganizer(): boolean;

    /**
     * Check if the connected user is a member of the bubble
     */
    isConnectedUserMember(): Promise<boolean>;

    /**
     * Indicates whether a conference has already been started in the bubble
     */
    isBubbleConferenceStarted(): boolean;

    /**
    * Method helper to know if bubble is a webinar bubble
    */
    isWebinarBubble(): boolean;

    /**
     * In case of active bubble conference, we might know the owner of the conference inside; This API will return the ID of the owner
     */
    getBubbleConferenceOwnerId(): string;

    /**
     * Method helper retrieve the name of the bubble as displayed in the logs
     */
    getNameForLogs(): string;

    /**
     * Get the bubble settings
     */
    getSettings(): BubbleSettings;

    /**
     * Method to retrieve all users of the bubble that have accepted
     */
    getAllAcceptedUsers(): BubbleUser[];

    /**
     * Method to retrieve conference.dialInCode code
     */
    getDialInCode(): string;

    /**
     * Method to retrieve conference.phoneNumbers array status
     */
    getPhoneNumbers(): DialInPhoneNumber[];

    /**
     * Method to create bubble "guest" access code
     */
    createBubbleLink(): Promise<string>;

    /**
     * Method to delete bubble "guest" access code
     */
    deleteBubbleLink(): Promise<void>;

    /**
     * Method to reset bubble "guest" access code
     */
    resetBubbleLink(): Promise<string>;

    /**
     * Method to get bubble "guest" access code
     */
    getBubbleLink(): Promise<string>;

    /**
     * Method to add already existing tags to bubble
     * @param tagNames - array of tag names to add
     */
    addTags(tagNames: string[]): Promise<void>;

    /**
     * Method to remove tags from bubble
     * @param tagNames - array of tag names to remove
     */
    removeTags(tagNames: string[]): Promise<void>;

    /**
     * Method to clear specified data from bubble
     * @param clearData - array of data to clear. Possibile values are: im, poll, document, pin
     */
    clearBubbleData(clearData: BubbleCleanupData[]): Promise<void>;

    /**
     * Method to return a simplified JSON representation of the Bubble object
     */
    toJSON(): any;
}

