    public sendEvent(name: BubbleEvents, data?: any): void {
        this.rxSubject.next(RBEvent.create<BubbleEvents, any>(name, data));
    }

    public subscribe(handler: (event: RBEvent<BubbleEvents>) => any, eventNames?: BubbleEvents | BubbleEvents[]): Subscription {
        const observable = eventNames ? this.rxSubject.pipe(filter((event: RBEvent<BubbleEvents>) => {
            if (eventNames instanceof Array) return eventNames.indexOf(event.name) !== -1;
            return event.name === eventNames;
        })) : this.rxSubject;
        return observable.subscribe((event: RBEvent<BubbleEvents>) => { try { handler(event); } catch {} });
    }

