    public update(bubbleData: any): this {
        this.dbId = bubbleData.id;
        this.jid = bubbleData.jid;
        this.name = bubbleData.name;
        this.description = bubbleData.topic; // Warning: topic = field name provided by Server
        if (bubbleData.creationDate) this.creationDate = new Date(bubbleData.creationDate);
        if (bubbleData.lastActivityDate) this.lastActivityDate = new Date(bubbleData.lastActivityDate);
        this.history = bubbleData.history;
        this.customData = bubbleData.customData ? bubbleData.customData : this.customData;
        this.conference = bubbleData.conference;
        if (!bubbleData.lastAvatarUpdateDate) this.avatar = null;
        this.isActive = bubbleData.isActive;
        this.autoRegister = bubbleData.autoRegister;
        this.autoAcceptInvitation = bubbleData.autoAcceptInvitation;
        this.visibility = bubbleData.visibility === 'public' ? BubbleVisibility.PUBLIC : BubbleVisibility.PRIVATE;

        this.containerId = bubbleData.containerId ? bubbleData.containerId : '';
        this.containerName = bubbleData.containerName ? bubbleData.containerName : '';
        this.isHuntingGroup = bubbleData.isOwnedByGroup;
        this.isOwnedByBubbleAdmin = bubbleData.isOwnedByRoomAdmin;
        this.isAlertNotificationEnabled = bubbleData.isAlertNotificationEnabled ? bubbleData.isAlertNotificationEnabled : false;
        this.nbParticipants = bubbleData.activeUsersCounter ? bubbleData.activeUsersCounter : 1;
        this.contentToClear = bubbleData.contentToClear ? bubbleData.contentToClear : { im: false, document: false, poll: false, member: false, record: false};

        // Handle bubble tags
        if (bubbleData.tags) {
            this.tags = bubbleData.tags.map((tagData:any) => { return { name: tagData.tag, color: tagData.color }; });
        }

        // Usefull only for guests
        this.endOfConferenceBehavior = bubbleData.endOfConferenceBehavior;

        this.hasLobby = Boolean(bubbleData.hasLobby);

        return this;
    }

    public updateAvatarInfo(): void {
        if (this.avatar) return;

        const avatarContacts = [];
        const orderedUsers: BubbleUser[] = this.users.slice();
        orderedUsers.sort((aa, bb) => {
            if (new Date(aa.date) > new Date(bb.date)) return 1;
            if (new Date(aa.date) < new Date(bb.date)) return -1;
            return 0;
        });

        for (let index = 0; index < orderedUsers.length; index++) {
            const contact = orderedUsers[index].user as Contact;
            const status = orderedUsers[index].status;
            if ((!this.owner || (contact.dbId !== this.owner.dbId)) &&
                !contact.isAnonymousGuest() &&
                !contact.isBadGuest() &&
                !contact.isTerminated) {
                if ((this.isConnecteUserOwner() || this.isConnecteUserOrganizer()) && (status === BubbleUserStatus.ACCEPTED || status === BubbleUserStatus.INVITED)) { avatarContacts.push(contact); }
                else if (status === BubbleUserStatus.ACCEPTED) { avatarContacts.push(contact); }
                if (avatarContacts.length === 5) { break; }
            }
        }

        let shouldUpdate = false;
        //compare the current avatar contacts and the new contacts
        if (this.avatarContacts.length !== avatarContacts.length) {
            shouldUpdate = true;
        } else {
            this.avatarContacts.forEach((contact, index) => {
                if (avatarContacts[index]?.id !== contact.id) {
                    shouldUpdate = true;
                }
            });
        }

        this.avatarContacts = avatarContacts;

        if (this.rxSubject && shouldUpdate) { this.rxSubject.next(RBEvent.create(BubbleEvents.ON_AVATAR_UPDATE, this.avatarContacts)); }
    }

