    public toString(): string {
        return "Bubble " + this.dbId + " " + this.name + " " + this.jid;
    }

    public toJSON(): any {
        // Special JSON output with only useful information for an invitation as defined in BubbleInvitation interface.
        if (this.bubbleConnectedUser && this.bubbleConnectedUser.status === BubbleUserStatus.INVITED) {
            const jsonInvitation: any = {
                id: this.dbId,
                name: this.name,
                status: this.bubbleConnectedUser.status,
                role: this.bubbleConnectedUser.role,
                invitationDate: this.bubbleConnectedUser.date,
                invitingUserId: this.bubbleConnectedUser.invitingUserId,
            };
            if (this.avatar) { jsonInvitation.avatar = this.avatar; }
            if (this.description) { jsonInvitation.description = this.description; }

            return jsonInvitation;
        }

        // JSON output for bubble information
        const json: any = {
            id: this.dbId,
            history: this.history,
            autoRegister: this.autoRegister,
            ownerId: this.owner.dbId,
            name: this.name,
            nbParticipants: this.nbParticipants,
            usersReady: this.usersReady.value,
            tags: this.tags
        };

        if (this.avatar) { json.avatar = this.avatar; }
        if (this.description) { json.description = this.description; }

        if (this.bubbleConnectedUser) {
            json.connectedUser = {
                status: this.bubbleConnectedUser.status,
                role: this.bubbleConnectedUser.role,
                invitationDate: this.bubbleConnectedUser.date,
                invitingUserId: this.bubbleConnectedUser.invitingUserId,
            };
        }
        else json.connectedUser = 'UNDEFINED';

        if (this.members?.length) {
            json.members = this.members.map((member: BubbleUser) => {
                const userJson: any = {
                    contact: member.user.dbId,
                    displayName: member.user.displayName,
                    status: member.status,
                    role: member.role,
                    date: member.date,
                    invitingUserId: member.invitingUserId
                };
                if (member.user.nickname) userJson.nickName = member.user.nickname;
                return userJson;
            });
        }

        if (this.organizers?.length) {
            json.organizers = this.organizers.map((organizer: BubbleUser) => {
                const userJson: any = {
                    contact: organizer.user.dbId,
                    displayName: organizer.user.displayName,
                    status: organizer.status,
                    role: organizer.role,
                    date: organizer.date,
                    invitingUserId: organizer.invitingUserId
                };
                return userJson;
            });
        }

        return json;
    }
