    /**
     * Asynchronous method to update waiting room video media for an existing webinar on server
     * @param webinarData - webinar instance which contains only "id and "waitingRoomMultimediaURL" fields
     */
    public async updateWebinarWaitingRoomMedias(webinarData: Webinar): Promise<Webinar> {
        try {
            const url = `${config.restServerUrl}/api/rainbow/webinar/v1.0/webinars/${webinarData.id}`;
            const headers = this.authService.getPostHeader();
            const body = JSON.stringify({ id: webinarData.id, waitingRoomMultimediaURL: webinarData.waitingRoomMultimediaURLs });
            const response = await fetch(url, { method: "PUT", headers, body });
            if (!response.ok) throw response;
            const data = (await response.json()).data;

            // Update webinar in cache (not the input webinar which can be partial data copy)
            const webinar = this.webinarsMap[webinarData.id];
            webinar.updateFromData(data);
            if (webinar.published) { this.submitEvent(WebinarServiceEvents.WEBINARS_UPDATE); }
            this.logger.info(`[WebinarService] updateWebinarWaitingRoomMedias -- ${webinar.id} -- success`);
            return webinar;
        }
        catch (error) {
            const errorInfo = await this.errorHelperService.getErrorInfo(error, "updateWebinarWaitingRoomMedias");
            this.logger.error(`[WebinarService] ${errorInfo.message}`);
            throw errorInfo.error;
        }
    }

    /**
     * Synchronous method to get and order webinars (no server request)
     * @param order - sort order (available values : "name", "date")
     */
    public getWebinars(order?: string): Webinar[] {
        if (order) {
            switch (order) {
                case "name":
                    this.webinars.sort((webinarA: Webinar, webinarB: Webinar) => { return webinarA.name.localeCompare(webinarB.name); });
                    break;
                default:
                    this.webinars.sort((webinarA: Webinar, webinarB: Webinar) => {
                        const dateA = moment(webinarA.webinarStartDate);
                        const dateB = moment(webinarB.webinarStartDate);
                        if (dateA.isSame(dateB)) return 0;
                        if (dateA.isBefore(dateB)) return -1;
                        return 1;
                    });
                    break;
            }
        }
        return this.webinars.filter((webinar: Webinar) => {
            return webinar.isAttendee || webinar.isTerminated() || webinar.room.bubbleConnectedUser.status === BubbleUserStatus.ACCEPTED;
        });
    }

    /**
     * Asynchronous method to retreive all webinars from server
     */
    private async getServerWebinars(): Promise<Webinar[]> {
        try {
            this.logger.info(`[WebinarService] getServerWebinars ()`);
            const url = `${config.restServerUrl}/api/rainbow/webinar/v1.0/webinars?limit=100&offset=0`;
            const headers = this.authService.getRequestHeader();
            const response = await fetch(url, { method: "GET", headers });
            if (!response.ok) throw response;
            const data = (await response.json()).data;

            // Get active and futur webinar rooms
            await this.getActiveAndFutureWebinarsRooms(data);

            this.webinars = data.reduce((webinars: Webinar[], webinarData: any) => {

                if (!webinarData.moderatorsSelectedAnNotified) {
                    this.deleteWebinar(webinarData.id);
                    this.logger.error(`[WebinarService] getServerWebinars () -- remove non finalized webinar -- ${webinarData.id}`);
                    return webinars;
                }

                let webinar = this.webinarsMap[webinarData.id];
                if (webinar) webinar.updateFromData(webinarData);
                else webinar = WebinarRB.createFromData(webinarData);

                this.updateRoles(webinar);

                if (!webinar.isTerminated()) {
                    webinar.room = this.bubbleService.getBubbleFromCache(webinar.roomId);
                    webinar.practiceRoom = this.bubbleService.getBubbleFromCache(webinar.roomModeratorsChatId);

                    if (webinar.room) { this.createWebinarSession(webinar, 'getServerWebinars'); }
                    if (!webinar.isAttendee && !webinar.room) {
                        if (webinar.isCreator) {
                            //this.deleteWebinar(webinarData.id);
                            this.logger.error(`[WebinarService] getServerWebinars () -- no room found for webinar ${webinarData.id} roomId ${webinar.roomId} -- remove corrupted webinar`);
                        }
                        else this.logger.warn(`[WebinarService] getServerWebinars () -- no room found for webinar ${webinarData.id} roomId ${webinar.roomId})`);
                        return webinars;
                    }
                }
                // Ignore non published webinar for attendee
                if (webinar.isAttendee && !webinar.published) return webinars;

                // Store in cache only non terminated webinars
                if (!this.webinarsMap[webinar.id]) {
                    this.webinarsMap[webinar.id] = webinar;
                    webinars.push(webinar);
                    this.logger.debug(`[WebinarServiceDebug] getServerWebinars () push webinar ${webinar.id} in cache`);
                }

                return webinars;
            }, []);
            this.logger.info(`[WebinarService] getServerWebinars () -- ${this.webinars.length} webinar(s) found -- success`);
            return this.webinars;
        }
        catch (error) {
            const errorInfo = await this.errorHelperService.getErrorInfo(error, "getServerWebinars");
            this.logger.error(`[WebinarService] ${errorInfo.message}`);
            return [];
        }
    }

    /**
     * Asynchronous method to retreive webinar room from server
     * @param webinarsData - data
     */
    public async getActiveAndFutureWebinarsRooms(webinarsData: any): Promise<void> {

        const roomsIdentifiers = webinarsData.reduce((roomsIds: string[], webinarData: any) => {
            if (webinarData.state !== 'terminated') {
                roomsIds.push(webinarData.roomId);
                roomsIds.push(webinarData.roomModeratorsChatId);
                this.logger.info(`[WebinarService] getActiveAndFutureWebinarsRooms (web: ${webinarData.id}, roomId: ${webinarData.roomId}, practId: ${webinarData.roomModeratorsChatId})`);
            }
            return roomsIds;
        }, []);


        try { await this.bubbleService.getServerBubblesByIds(roomsIdentifiers, false, true); } catch {
            this.logger.error(`[WebinarService] getActiveAndFutureWebinarsRooms -- failed -- getServerRooms`);
        }
    }


    /**
     * Asynchronous method to retreive webinar from server (reentrant ready method)
     * @param webinarId - the identifiant of webinar to get
     */
    public getWebinar(webinarId: string): Promise<Webinar> {

        if (this.webinarsMap[webinarId]) {
            this.logger.info(`[WebinarService] getWebinar (from cache) -- ${webinarId} -- success`);
            return Promise.resolve(this.webinarsMap[webinarId]);
        }

        if (!this.getWebinarPromise[webinarId]) {
            this.getWebinarPromise[webinarId] = new Promise<Webinar>((resolve: any, reject: any) => {

                const webinar = WebinarRB.create();
                webinar.id = webinarId;
                this.updateWebinarFromServer(webinar)
                    .then(() => {
                        this.addWebinarToCache(webinar);

                        this.logger.info(`[WebinarService] getWebinar (from server) -- ${webinarId} -- success`);
                        delete this.getWebinarPromise[webinarId];
                        this.updateRoles(webinar);

                        // Handle existing janus sessions (only one)
                        this.createWebinarSession(webinar, 'getWebinar');

                        resolve(webinar);
                    })
                    .catch((error) => {
                        this.logger.error(`[WebinarService] ${error.message}`);
                        delete this.getWebinarPromise[webinarId];
                        reject(error);
                    });

            });
        }
        return this.getWebinarPromise[webinarId];
    }

