    /**
     * Method to retreive webinar from cache
     * @param sessionId - session identifier
     * @param confId - the conference identifier (optional)
     */
    public getWebinarBySessionId(sessionId: string, confId?: string): Webinar | undefined {
        let conferenceId = confId;
        if (!conferenceId) {
            const session = this.xmppService.connection.jingle.sessions[sessionId];
            if (!session) return undefined;
            conferenceId = session.conference_id;
        }
        return this.webinars.find((webinar: Webinar) => { return webinar.roomId === conferenceId; });
    }

