    /**
     * Asynchronous method to retreive public webinar informations (this method can be call without authentication)
     * @param openInviteId - the webinar openInviteId
     * @param joinUuid - the webinar joinUuid
     * @param registrationCall - the registrationClickCount for statisitics (optional)
     */
    public async getPublicWebinarInfo(openInviteId: string, joinUuid: string, registrationCall?: boolean): Promise<any> {
        try {
            let url = `${config.restServerUrl}/api/rainbow/webinar/v1.0/webinars/public`;
            if (registrationCall) url += '?registrationClickCount=true';
            const headers = { 'Accept': 'application/json', 'Content-Type': 'application/json' };
            const bodyContent: any = {};
            if (!joinUuid) { bodyContent.registrationId = openInviteId; }
            if (joinUuid) {
                bodyContent.openInviteId = openInviteId;
                bodyContent.joinUuid = joinUuid;
            }
            const body = JSON.stringify(bodyContent);
            const response = await fetch(url, { method: 'POST', headers, body });
            if (!response.ok) throw response;
            const webinarInfo = (await response.json()).data;
            webinarInfo.errorDetailsCode = null;
            webinarInfo.publicWebinarId = openInviteId;
            webinarInfo.joinUuid = joinUuid;
            this.logger.info(`[WebinarService] -- getPublicWebinarInfo -- success`);
            return webinarInfo;
        }
        catch (error) {
            const errorInfo = await this.errorHelperService.getErrorInfo(error, 'getWebinar');
            this.logger.error(`[WebinarService] -- getPublicWebinarInfo -- failure -- ${errorInfo.message}`);
            if (errorInfo.error.errorDetailsCode === 403621) {
                const webinarInfo = errorInfo.error.errorDetailsData;
                webinarInfo.errorDetailsCode = 403621;
                return webinarInfo;
            }
            return { errorStatus: errorInfo.error.status, errorDetailsCode: errorInfo.error.errorDetailsCode, errorMessage: errorInfo.error.message, linkType: '' };
        }
    }

    /**
     * Asynchronous method to update the webinar already in cache with server data
     * @param webinar - the webinar openInviteId
     */
    public async updateWebinarFromServer(webinar: Webinar): Promise<Webinar> {
        try {
            const url = `${config.restServerUrl}/api/rainbow/webinar/v1.0/webinars/${webinar.id}`;
            const headers = this.authService.getRequestHeader();
            const response = await fetch(url, { method: "GET", headers });
            if (!response.ok) throw response;
            const data = (await response.json()).data;

            webinar.updateFromData(data);
            this.updateRoles(webinar);

            if (!webinar.isTerminated()) {
                if (!webinar.room) { try { webinar.room = await this.bubbleService.getBubble(webinar.roomId) as BubbleRB; } catch (error) { /**/ } }

                // Only try to get practice room if the user is accepted cause user is not added on practice room until he is accepted in main room
                if (!webinar.practiceRoom && (webinar.isOrganizer || webinar.isSpeaker) && webinar.room && webinar.room.bubbleConnectedUser.status === BubbleUserStatus.ACCEPTED) {
                    if (!webinar.practiceRoom) { try { webinar.practiceRoom = await this.bubbleService.getBubble(webinar.roomModeratorsChatId) as BubbleRB; } catch (error) { /**/ } }
                }

                if (!webinar.session) this.createWebinarSession(webinar, 'updateWebinarFromServer');
            }

            this.submitEvent(WebinarServiceEvents.WEBINARS_UPDATE);
            return webinar;
        }
        catch (error) {
            const errorInfo = await this.errorHelperService.getErrorInfo(error, "updateWebinarFromServer");
            this.logger.error(`[WebinarService] ${errorInfo.message}`);
            throw errorInfo.error;
        }
    }

