    /**
     * Asynchronous method to get available licence between a starting and ending dates
     * @param webinarStartDate - the start date
     * @param webinarEndDate - the end datae
     * @param excludeWebinarId - the webinarId to exclude frow search (optional)
     */
    public async getAvailableLicences(webinarStartDate: string, webinarEndDate: string, excludeWebinarId?: string): Promise<any> {
        try {
            let url = `${config.restServerUrl}/api/rainbow/webinar/v1.0/licenses?webinarStartDate=${webinarStartDate}&webinarEndDate=${webinarEndDate}`;
            if (excludeWebinarId) { url += `&excludeWebinarId=${excludeWebinarId}`; }
            const headers = this.authService.getPostHeader();
            const response = await fetch(url, { method: "GET", headers });
            if (!response.ok) throw response;
            const unorderedLicences = (await response.json()).data;
            const orderedLicences = unorderedLicences.sort((lic1: any, lic2: any) => {
                if (lic1.maxParticipants > lic2.maxParticipants) return 1;
                if (lic1.maxParticipants < lic2.maxParticipants) return -1;
                return 0;
            });
            return orderedLicences;
        }
        catch (error) {
            const errorInfo = await this.errorHelperService.getErrorInfo(error, "getAvailableLicences");
            this.logger.error(`[WebinarService] ${errorInfo.message}`);
            throw errorInfo.error;
        }
    }

