    /**
     * Method to check if connected user has active or futur webinars
     */
    public hasActiveOrFutureWebinar(): boolean {
        return this.webinars.some((webinar: Webinar) => { return webinar.isOrganizer || webinar.status !== WebinarStatus.TERMINATED; });
    }

    public hasWebinar(): boolean {
        return this.webinars.length > 0;
    }

    /**
     * Internal method to remove a webinar from the cache
     * @param webinar - the webinar to remove from cache
     */
    public removeWebinar(webinar: Webinar): void {
        const index = this.webinars.findIndex((web: Webinar) => { return web.id === webinar.id; });
        if (index !== -1) { this.webinars.splice(index, 1); delete this.webinarsMap[webinar.id]; }
        this.conference.removeActiveWebinar(webinar);
        webinar.session = null;
        webinar.status = WebinarStatus.TERMINATED;
        webinar.rxSubject.next(null);
        this.submitEvent(WebinarServiceEvents.WEBINARS_UPDATE);
    }


