    /**
     * add a webinar to service cache
     * @param webinar - the webinar
     */
    public addWebinarToCache(webinar: Webinar): void {
        if (this.webinarsMap[webinar.id]) {
            this.logger.warn(`[webinarService] addWebinarToCache (web: ${webinar.id}) -- already in cache -- ignore`);
            return;
        }
        this.webinars.push(webinar);
        this.webinarsMap[webinar.id] = webinar;
    }

    /**
     * Create webinar session from bubble information
     * @param webinar - the webinar
     * @param from - the origin of the request
     */
    public createWebinarSession(webinar: Webinar, from: string): void {
        const bubble = webinar.room as BubbleRB;
        if (bubble?.conference?.sessions.length) {
            const message: string = `[webinarService] createWebinarSession (web: ${webinar.id}, type: ${bubble.conference.sessions[0].type}, from: ${from})`;
            switch (bubble.conference.sessions[0].type) {
                case 'practiceWaitingRoom': webinar.session = WebinarSession.create(); this.logger.info(message); break;
                case 'practiceRoom': if (!webinar.isAttendee) { webinar.session = WebinarSession.create(); this.logger.info(message); } break;
                case 'waitingRoom': if (webinar.isAttendee) { webinar.session = WebinarSession.create(); this.logger.info(message); } break;
                case 'webinar': webinar.session = WebinarSession.create(); this.logger.info(message); break;
                default: break;
            }
        }
        else this.logger.info(`[webinarService] createWebinarSession (web: ${webinar.id}, from: ${from}) -- no room conference session`);
    }

