    /**
     * Compute busy slot
     */
    public async computeBusySlots(date: string): Promise<void> {
        const slots = Array.from({ length: 24 }, (v, i) => ({ begin: (i < 10 ? '0' : '') + i + ":00", end: "", duration: 0, height: null, top: null, state: "notBusy", webinarsIn: [] }));
        const busySlots = Array.from({ length: 24 }, (v, i) => ({ height: null, top: null, state: "notBusy" }));

        const allLicences = await this.getAllLicences();
        const numberLicences = allLicences.reduce((nbLicences: number, licence: any) => { nbLicences += licence.totalLicenses; return nbLicences; }, 0);

        this.webinars.forEach((webinar: Webinar) => {
            const startDate = format(new Date(webinar.webinarStartDate), 'yyyy-MM-dd');
            const endDate = format(new Date(webinar.webinarEndDate), 'yyyy-MM-dd');
            let end = this.getHours(webinar.webinarEndDate);
            const endString = format(new Date(webinar.webinarEndDate), 'HH:mm');
            const beginString = format(new Date(webinar.webinarStartDate), 'HH:mm');
            const beginMinutes = this.getMinutes(webinar.webinarStartDate);
            if (startDate !== date && (endDate !== date || (endDate === date && end === 0)))
                return;
            if (startDate === date && endDate !== date)
                webinar.webinarEndDate = new Date(startDate + " 23:59").toISOString();
            if (startDate !== date && endDate === date)
                webinar.webinarStartDate = new Date(endDate + " 00:00").toISOString();

            const begin = this.getHours(webinar.webinarStartDate);
            end = this.getHours(webinar.webinarEndDate);
            const endMinutes = this.getMinutes(webinar.webinarEndDate);
            if (end === 0)
                end = 24;
            let idx = 0;
            for (idx = begin; idx <= end; idx++) {
                let durationSlot = differenceInMinutes(new Date(webinar.webinarEndDate), new Date(webinar.webinarStartDate));
                let height = (durationSlot * 60) / 60;
                let top = (beginMinutes * 60) / 60;
                if (idx === end && endMinutes === 0)
                    continue;
                if (slots[idx].webinarsIn.length < numberLicences)
                    slots[idx].webinarsIn.push({ begin: beginString, end: endString, name: webinar.name, id: webinar.id });
                const intersection = this.findIntersection(slots[idx].webinarsIn);
                if (slots[idx].webinarsIn.length >= numberLicences && intersection !== null) {

                    durationSlot = this.deltaInMinutes(intersection.begin, intersection.end);
                    let busyHeight = (durationSlot * 60) / 60;
                    const index = this.myParseInt(intersection.begin);

                    let busyTop = (parseInt(intersection.begin.substring(3, 5), 10) * 60) / 60;
                    if (busySlots[index].top === null) busySlots[index].top = busyTop;
                    if (busySlots[index].height === null) busySlots[index].height = busyHeight;

                    let difference;
                    if (busySlots[index].top < busyTop) {
                        difference = busyTop - busySlots[index].top;
                        busyTop = busySlots[index].top;
                    }
                    else difference = busySlots[index].top - busyTop;

                    busyHeight = (busyHeight + difference > busySlots[index].height ? busyHeight + difference : busySlots[index].height);
                    busySlots[index].height = busyHeight;
                    busySlots[index].top = busyTop;
                    busySlots[index].state = "busy";
                }

                if (slots[begin].top === null) slots[begin].top = top;
                if (slots[begin].height === null) slots[begin].height = height;
                if (slots[begin].top < top) {
                    const difference = top - slots[begin].top;
                    height = (height + difference > slots[begin].height ? height + difference : slots[begin].height);
                    top = slots[begin].top;
                }
                else {
                    const difference = slots[begin].top - top;
                    height = (slots[begin].height + difference > height ? slots[begin].height + difference : height);
                }
                slots[begin] = { begin: slots[begin].begin, end: endString, duration: durationSlot, height: height, top: top, state: "partiallyBusy", webinarsIn: slots[begin].webinarsIn };
            }
        });
    }

    private getHours(date: string): number {
        return (new Date(date).getHours());
    }

    private getMinutes(date: string): number {
        return (new Date(date).getMinutes());
    }

    private findIntersection(timeRanges: { begin: string; end: string }[]): any {
        // Sort the array by start time in ascending order
        timeRanges.sort((a, b) => this.compareHour(a.begin, b.begin));

        // Initialize variables for the intersection
        let intersectionStart = timeRanges[0].begin;
        let intersectionEnd = timeRanges[0].end;

        // Traverse the time ranges to find the intersection
        for (let i = 1; i < timeRanges.length; i++) {
            const currentRange = timeRanges[i];
            // If the current range starts after the intersection end, there is no intersection
            if (currentRange.begin > intersectionEnd) return null;

            // Update the intersection start time if the current range has a later start time
            if (currentRange.begin > intersectionStart) intersectionStart = currentRange.begin;

            // Update the intersection end time if the current range has an earlier end time
            if (currentRange.end < intersectionEnd) intersectionEnd = currentRange.end;
        }

        // Final check for intersection
        if (intersectionStart < intersectionEnd) return { begin: intersectionStart, end: intersectionEnd };
        return null;
    }

    private compareHour(hour1: string, hour2: string): number {
        if (hour1 < hour2) return -1;
        else if (hour2 > hour1) return 1;
        return 0;
    }

    private deltaInMinutes(heure1, heure2): number {
        const date1 = parse(heure1, 'HH:mm', new Date());
        const date2 = parse(heure2, 'HH:mm', new Date());
        const difference = differenceInMinutes(date2, date1);
        return difference;
    }

    public myParseInt(hour: string): number {
        return parseInt(hour.substring(0, 3), 10);
    }

