    public async getConversation(convRef: string | User | Bubble | undefined, type?: 'contact' | 'room'): Promise<Conversation | undefined> {
        let conversation: ConversationRB | undefined;
        try {
            let id: string;
            let convType: string;
            if (!convRef) return undefined;
            if (convRef instanceof Contact) { id = (convRef as Contact).id; convType = 'contact'; }
            else if (convRef instanceof BubbleRB) { id = (convRef as BubbleRB).dbId; convType = 'room'; }
            else { id = (convRef as string); convType = type; }
            conversation = this.getConversationFromCache(id);
            if (!conversation) conversation = await this.getOrCreateConversation(id, convType);
        }
        catch (error) {
            this.logger.error(`[conversationService] getConversation -- FAILURE -- ${error.message}`);
        }
        return conversation;
    }

    public getConversations(): Conversation[] {
        return Object.keys(this.conversations).map((key: string) => { return this.conversations[key]; });
    }

    public getCallConversations(): Conversation[] {
        return this.getConversations().filter((conv) => { return conv.call; });
    }

    public getConversationFromCache(id: string): ConversationRB | undefined {
        if (!this.conversations || !id) { return null; }

        // Get conversation by conversation id
        let conversation = this.conversations[id];

        // Get conversation by dbId
        if (!conversation) {
            const convKey = Object.keys(this.conversations).find((key: string) => { return this.conversations[key] && this.conversations[key].dbId === id; });
            conversation = convKey ? this.conversations[convKey] : null;
        }

        // Get conversation by room dbId
        if (!conversation) {
            const convKey = Object.keys(this.conversations).find((key: string) => { return this.conversations[key]?.room && this.conversations[key].room.dbId === id; });
            conversation = convKey ? this.conversations[convKey] : null;
        }
        return conversation;
    }

    public updateMissedCounters() {
        let missedIMCounter = 0;
        const missedIMDetails = [];

        Object.keys(this.conversations).forEach((key: string) => {
            const conversation = this.conversations[key];

            // Only add in global missed IM counter the active webinar missedIM
            if (conversation.bubble?.isWebinarBubble() && this.webinarService) {
                const conversationWebinarId = conversation.bubble?.conference?.webinar?.id;
                const activeWebinarId = this.webinarService?.conference?.activeWebinar?.id;
                if (conversationWebinarId === activeWebinarId && conversation.missedCounter !== 0) {
                    missedIMCounter += conversation.missedCounter;
                    missedIMDetails.push(conversation);
                }
            }
            else if (conversation.missedCounter !== 0) {
                missedIMCounter += conversation.missedCounter;
                missedIMDetails.push(conversation);
            }
        });

        if (missedIMCounter === this.missedInfoCounters.value.missedIMCounter) return;

        //if the user is not allowed to do IM, reset all missed im to 0
        if (this.contactService.userContact && !this.contactService.userContact.instantMessagesEnabled) {
            missedIMCounter = 0;
        }
        this.missedInfoCounters.value.missedIMCounter = missedIMCounter;
        this.missedInfoCounters.value.missedIMDetails = missedIMDetails;
        this.missedInfoCounters.next(this.missedInfoCounters.value);
    }

