    /**
     * @param id - Id of the company
     * @param name - Name of the company
     * @returns the created company
     */
    public static create(id: string, name: string): Company {
        return new Company({ id: id, name: name });
    }

    /**
     * @param data - The object containing the attributes of the company
     * @returns the created company
     */
    public static createFromData(data: any): Company {
        const company = new Company(data);

        // Handle fields for themes management
        if (!company.selectedThemeCustomers) company.selectedThemeCustomers = {};
        if (!company.selectedTheme) company.selectedTheme = {};

        return company;
    }

    /**
     * Returns a copy of the company's data but expurgated by the unwanted and undefined optional properties.
     *
     * @param data - The object containing the attributes of the company
     * @param userContact - The logged user
     * @returns the updated company
     */
    public static prune(data: any, userContact: any): Company {
        const dataCopy = Object.assign({}, data);

        // Remove readonly fields
        delete dataCopy.dataLocation;
        delete dataCopy.businessSpecific;

        // Remove readonly fields for themes management
        if (dataCopy.selectedTheme && Object.prototype.hasOwnProperty.call(dataCopy.selectedTheme, "isFromBp")) {
            // Serveur doesn't accept this parameter in update so remove it!
            delete dataCopy.selectedTheme.isFromBp;
        }
        if (dataCopy.selectedThemeCustomers && Object.prototype.hasOwnProperty.call(dataCopy.selectedThemeCustomers, "isFromBp")) {
            // Serveur doesn't accept this parameter in update so remove it!
            delete dataCopy.selectedThemeCustomers.isFromBp;
        }

        // Remove deprecated fields
        delete dataCopy.giphyEnabled; // 'useGifCustomisation' is used instead

        // Remove unnecessary fields or inconsistent with other fields
        // Note: if the property bpId is null, we send it (used when bpType changes from IR to DR or VAD)
        if (dataCopy.isBP) {
            if (dataCopy.bpType !== "VAD" && dataCopy.bpType !== "DR") {
                delete dataCopy.bpBusinessType; // cannot be set when not a VAD or DR
            }
        } else {
            // these fields are only applicable if isBP is true.
            delete dataCopy.bpType;
            delete dataCopy.bpBusinessModel;
            delete dataCopy.bpApplicantNumber;
            delete dataCopy.bpCRDid;
            delete dataCopy.bpHasRightToSell;
            delete dataCopy.bpHasRightToConnect;
            delete dataCopy.bpIsContractAccepted;
        }
        if (dataCopy.economicActivityClassification === "") {
            delete dataCopy.economicActivityClassification;
        }

        // Remove fields for which the authorization level is not reached
        if (!dataCopy.allowDeviceFirmwareSelection) {
            delete dataCopy.selectedDeviceFirmware;
        }

        if (!userContact || (!userContact.isSuperadmin() && !userContact.isBPAdminFinance())) {
            // these fields can't be set if the user is not a "superadmin" or a "bp_finance".
            delete dataCopy.bpType;
            delete dataCopy.adminHasRightToUpdateSubscriptions;
            delete dataCopy.adminAllowedUpdateSubscriptionsOps;
            delete dataCopy.sendPrepaidSubscriptionsNotification;
        }
        if (!userContact?.isSuperadmin()) {
            // these fields can't be set if the user is not a "superadmin"
            delete dataCopy.superadminComment;
            delete dataCopy.allowDeviceFirmwareSelection;
        }
        if (!userContact || (!userContact.isSuperadmin() && (dataCopy.supportEmail === null || dataCopy.supportEmail === ""))) {
            delete dataCopy.supportEmail;
        }

        return dataCopy;
    }

