    /**
     * Indicates whether the CallLog Service has been initialized or not.
     * If this is not the case, no call log has yet been retrieved.
     * @returns True if the CallLog Service has been initialized; False otherwise.
     */
    public isInitialized(): boolean {
        return this.initialized;
    }


    // ---------------------------
    // METHODS TO FETCH CALL LOGS
    // ---------------------------

    /**
     * @function getCalllogs
     * @description Return an array of available call logs, each item representing one call log.
     * By available, we means first the call logs already recovered after the first initialization following a request to the server
     * to get the N most recent one. And then the call logs that have been added following new notification(s) from server.
     * Also some call logs may have been deleted following a user action.
     * Note that if it has not yet been done, the initialization phase will be automatically performed by retrieving
     * a certain number of logs from server (Fetch options defined by default by CallLogService are used)
     * @memberof CallLogServiceRB
     * @private
     * @async
     * @returns {Promise<CallLog[]>} Promise that resolves with an array of available call logs.
     */
    public async getCalllogs(): Promise<CallLog[]> {
        this.logger.info(`[CallLogService] getCalllogs -- init status = ${this.initialized}`);
        await this.initialize();
        return this.callLogs;
    }

    /**
     * @function getAggregatedCalllogs
     * @description Return an array of aggregated call logs, each item representing one more call logs grouped by contact.
     * The aggregated call logs are deduced from the available call logs (obtained with the 'getCalllogs' method) but the items
     * are grouped by contact according to different information such as status ("missed" or not), direction ("incoming", "outgoing")
     * Note that if it has not yet been done, the initialization phase will be automatically performed by retrieving
     * a certain number of logs from server (Fetch options defined by default by CallLogService are used)
     * @memberof CallLogServiceRB
     * @public
     * @async
     * @returns {Promise<CallLog[]>} Promise that resolves with an array of available aggregated call logs.
     */
    public async getAggregatedCalllogs(): Promise<CallLogRB[]> {
        this.logger.info(`[CallLogService] getAggregatedCalllogs -- init status = ${this.initialized}`);
        await this.initialize();
        return this.aggregatedCallLogs;
    }

    /**
     * @function fetchNextPage
     * @description Request to retrieve new call logs from the server.
     * The number of new call logs to retrieve can be specified.
     * This API returns the whole call logs, those already retrieved by previous requests and the new one.
     * Each call log will contain some selected and simplified information .
     * Note that the initialization phase must have been done previously. If this is not the case, an error is returned
     * @memberof CallLogServiceRB
     * @private
     * @async
     * @param {number} numberOfElts Number of new call logs to fetch
     * @returns {Promise<CallLog[]>} Promise that resolves with an array of available call logs with selected and simplified information
     */
    public async fetchNextPage(numberOfElts: number = CallLogServiceRB.NB_DEF_UCAAS_CALL_LOG): Promise<CallLog[]> {
        this.logger.info(`[CallLogService] fetchNextPage -- init status = ${this.initialized}, number requested = ${numberOfElts}`);

        const fetchOptions: IFetchOptions = {};

        // A request for the following call logs is now denied if the service has not been initialized through one of the following APIs:
        //  - getCalllogs
        //  - getAggregatedCalllogs
        if (!this.initialized) {
            const error = new Error("[CallLogService] Fetch next page error - The service is not initialized through one of the APIs authorized to do so");
            this.logger.error(error.message);
            return Promise.reject(error);
        }

        // Check is user has already requested next call logs from server. If the case, the new request is ignored
        if (this.fetchingCallLogs) {
            // Another fetch of the Call logs is in progress ... the current request will be rejected
            // Is the prmoise rejection  the good reaction ?
            const error = new Error("[CallLogService] Fetch next page error - A fetch of call logs is already is currently in progress. This request is ignored.");
            this.logger.error(error.message);
            return Promise.reject(error);
        }

        this.fetchingCallLogs = true;

        // Security Check (Should not happen !)
        // The number of call logs to retrieve from the server is limited to NB_MAX_NEXT_CALL_LOGS (250)
        if (numberOfElts > CallLogServiceRB.NB_MAX_NEXT_CALL_LOGS) {
            numberOfElts = CallLogServiceRB.NB_MAX_NEXT_CALL_LOGS;
        }
        fetchOptions.numberOfElementsToGet = numberOfElts;

        // To get the newest/latest call logs first, we need to use 'before'.
        // First request should contain empty <before> tag to get the latest messages
        // All the following requests should include <first> data in <before> tag.
        // firstTimeStamp is filled by onHistoryCallLogMessageReceived()
        if (this.firstTimeStamp) { fetchOptions.useBefore = this.firstTimeStamp; }

        await this.fetchCallLogsFromServer(fetchOptions);
        this.fetchingCallLogs = false;
        return await this.orderCallLogsHistory();
    }

    /**
     * @function orderCallLogsHistory
     * @description Return an customized array of call logs with selected and simplified item information.
     * The customized call logs are deduced from the available call logs
     * @memberof CallLogServiceRB
     * @private
     * @async
     * @returns {Promise<any[]>} Promise
     */
    private async orderCallLogsHistory(): Promise<CallLogRB[]> {
        this.logger.debug(`[CallLogService] orderCallLogsHistory`);

        await Promise.all(this.callLogPromises).catch(() => { });
        this.callLogPromises = [];

        // make sure that call logs are sorted by date. getTime is used to avoid type errors (TS)
        this.callLogs = this.callLogs.sort((a, b) => b.date.getTime() - a.date.getTime());

        return this.callLogs;
    }


