    /**
     * Returns the number total of missed calls.
     * Missed call is a call with the following properties: state is 'missed', direction is 'incoming' and read flag is 'false'.
     * This API can be called before the first call logs are retrieved, i.e. before the initialization step.
     */
    public getMissedCallsCounter(): number {
        this.logger.debug(`[CallLogService] getMissedCallsCounter -- Number returned = ${this.numberMissedCallLogs}`);
        return this.numberMissedCallLogs;
    }

    /**
     * Return the number total of call logs available for the connected user
     */
    public getCallLogsCounter(): number {
        this.logger.debug(`[CallLogService] getCallLogsCounter -- Number returned = ${this.numberTotalCallLogs}`);
        return this.numberTotalCallLogs;
    }

    /**
     * @function getMissedCallLogsInCacheCounter
     * @description Get the number of missed calls (state === "missed" && direction === CallDirection.INCOMING) for call logs
     * present in the internal cache ONLY.
     * This counter may be different to the counter known by the server which covers all call logs available on its side
     * @memberof CallLogServiceRB
     * @private
     * @returns {number} Number of missed calls
     */
    private getMissedCallLogsInCacheCounter(): number {
        let num = 0;
        this.callLogs.forEach((callLog) => {
            if (!callLog.read && callLog.state === "missed" && callLog.direction === CallDirection.INCOMING) {
                num++;
            }
        });

        this.logger.debug(`[CallLogService] getMissedCallLogsInCacheCounter -- Number returned = ${num}`);

        return num;
    }


