    /**
     * Mark a call log item specified by its object instance as read
     * @param calllog - The call log instance to mark as read
     */
    public markCallLogAsRead(callLog: CallLog): void {
        try {
            if (!callLog?.id) {
                throw Error("Unable to mark call log as read -- Missing call log id value");
            }
            this.logger.info(`[CallLogService] markCallLogAsRead -- id = ${callLog.id}`);

            const message = $msg({ from: this.xmppService.jid, to: this.xmppService.jid, id: "web_" + crypto.randomUUID() });
            // disable camel_case rule for this line as it's Strophe related (for 'call_id')

            message.c("read", { xmlns: CallLogServiceRB.CALL_LOG_ACK_NAMESPACE, call_id: callLog.id });
            this.xmppService.send(message);
        } catch (error) {
            this.logger.error(`[CallLogService] markCallLogAsRead -- failure: ${error.message}`);
            throw error;
        }
    }

    /**
     * Mark all call logs already known by the Call Log service as read
     * This concerns the call logs fetched from server during the initialization step and through additional fetch requests.
     */
    public markAllCallsLogsAsRead(): void {
        this.logger.info(`[CallLogService] markAllCallsLogsAsRead`);

        this.callLogs.forEach((callLog: CallLog) => {
            if (!callLog.read) {
                const message = $msg({ from: this.xmppService.jid, to: this.xmppService.jid, id: "web_" + crypto.randomUUID() });
                // disable camel_case rule for this line as it's Strophe related (for 'call_id')

                message.c("read", { xmlns: CallLogServiceRB.CALL_LOG_ACK_NAMESPACE, call_id: callLog.id });
                this.xmppService.send(message);
            }
        });
    }

