    /**
     * @function ackAllCallLogsInDB
     * @description
     * @memberof CallLogServiceRB
     * @private
     * @async
     * @returns {Promise<any>} Promise that resolves when ...
     */
    private async ackAllCallLogsInDB(): Promise<any> {
        try {
            if (this.ackAllCallLogsInDBDone) {
                this.logger.info(`ackAllCallLogsInDB --- aready done -- ignore`);
                return;
            }

            this.ackAllCallLogsInDBDone = true;
            this.logger.warn(`ackAllCallLogsInDB --- used for ${this.numberMissedCallLogs} call-logs`);
            const message = $iq({ from: this.xmppService.jid, type: 'set' });
            message.c('markallread', { xmlns: CallLogServiceRB.CALL_LOG_NAMESPACE });
            const stanza = await this.xmppService.sendIQ(message);
            const stanzaElem: XMLElement = xmlParser(stanza);

            if (stanzaElem.find("error").length > 0) {
                this.logger.warn(`ackAllCallLogsInDB --- error ...`);
                return;
            }
            await this.getMissedCallsCounterFromServer();
        }
        catch {
            this.logger.warn(`ackAllCallLogsInDB --- error ...`);
            return;
        }
    }

