    /**
     * Process the deletion of all call logs associated with a directory contact.
     * The contactId (i.E. the userId) is not managed by the xmpp server in "delete" IQ.
     * It will be necessary to carry out a deletion via the phone numbers used by the directory contact.
     * @param contact - The directory contact instance to delete
     */
    private deleteCallLogsForDirectoryContact(contact: Contact): void {
        if (!contact) {
            return;
        }

        this.logger.debug(`[CallLogService] deleteCallLogsForDirectoryContact -- directory contact id = ${contact.id}`);

        // New array containing only the entries linked to the directory contact for which it has asked to delete the call logs.
        const directoryContactCallLogs: CallLog[] = [...this.callLogs.filter(callLog => callLog.identityContactId === contact.id)];

        // Set containing telephone numbers defined in the directory contact and for which a call has been recorded.
        // A request will be made to the server to delete the call logs associated with these telephone numbers.
        const directoryContactPhoneNumbers = new Set<string>();

        directoryContactCallLogs.forEach((callLog: CallLogRB) => {
            this.logger.debug(`[CallLogService] deleteCallLogsForDirectoryContact -- call log tmp id = ${callLog.userOriginBackup.id}`);
            // Add in the set the phone number originally used to reach the contact.
            // Information provided by the server (xmpp message CALL_LOG_NOTIF_NAMESPACE) and stored in the 'backup' temp contact
            // to keep the main original information.
            directoryContactPhoneNumbers.add(callLog.userOriginBackup.id);
        });

        // The phone numbers found will be used as a key to delete the call logs
        directoryContactPhoneNumbers.forEach(async phoneNumber => {
            const message = $iq({ from: this.xmppService.jid, to: this.xmppService.jid, type: "set" });
            message.c("delete", { xmlns: CallLogServiceRB.CALL_LOG_NAMESPACE, peer: phoneNumber });
            await this.xmppService.sendIQ(message);
        });
    }

    /**
     * Delete all call logs associated to a user
     * A ON_CALLLOG_UPDATED event is sent afterwards at the completion of the operation to notify about the call logs history update.
     */
    public async deleteCallLogsForUser(user: User): Promise<any> {
        const userId = user.jid ? user.jid : user.id;

        this.logger.info(`[CallLogService] deleteCallLogsForUser -- user id used = ${userId}`);

        // Check if the request concerns the deletion of all call logs associated with a directory contact.
        // If this is the case, the deletion process required a special process.
        if (this.isDirectoryContact(user as Contact)) {
            this.deleteCallLogsForDirectoryContact(user as Contact);
        } else {
            const message = $iq({ from: this.xmppService.jid, to: this.xmppService.jid, type: "set" });
            message.c("delete", { xmlns: CallLogServiceRB.CALL_LOG_NAMESPACE, peer: userId });
            this.xmppService.sendIQ(message);
        }
    }

