import { Plugin } from 'rainbow-sdk/plugins/plugin';
import { BotService } from 'rainbow-sdk/services/bot/bot.service';
import { ConversationServiceRB } from 'rainbow-sdk/services/conversation/conversation.service';
import { LoggerService } from 'rainbow-sdk/services/core/logger.service';
import { BubbleServiceRB } from 'rainbow-sdk/services/bubbles/bubble.service';

export class BubblesPlugin extends Plugin {
    public static initialize(): BubblesPlugin {
        Plugin.initialize();

        if (!window.rainbow.plugins[BubblesPlugin.name]) {
            const logger = LoggerService.getInstance();
            logger.info("[BubblesPlugin] initialized");
            window.rainbow.plugins[BubblesPlugin.name] = new BubblesPlugin();
            BotService.getInstance();
            ConversationServiceRB.getInstance();
            BubbleServiceRB.getInstance();
        }

        return window.rainbow.plugins[BubblesPlugin.name];
    }

    private constructor() {
        super();
    }
}
