import { Plugin } from 'rainbow-sdk/plugins/plugin';
import { WebConferenceServiceRB } from 'rainbow-sdk/services/conference/webConference.service';
import { LoggerService } from 'rainbow-sdk/services/core/logger.service';

export class BubbleConferencePlugin extends Plugin {
    public static initialize(): BubbleConferencePlugin {
        Plugin.initialize();

        if (!window.rainbow.plugins[BubbleConferencePlugin.name]) {
            const logger = LoggerService.getInstance();
            logger.info("[BubbleConferencePlugin] initialized");
            window.rainbow.plugins[BubbleConferencePlugin.name] = new BubbleConferencePlugin();
            WebConferenceServiceRB.getInstance();
        }
        return window.rainbow.plugins[BubbleConferencePlugin.name];
    }

    private constructor() {
        super();
    }
}
