/* eslint-disable no-shadow */
import { BehaviorSubject, Subject } from "rxjs";
import { Contact } from "./contact.model";

export class PollAnswer {

    public text: string;
    public votes: any[] = [];
    public voters: number = 0;
    public nbVotes: number = 0;
    public voted: boolean = false;

    public _selected: boolean = false;
    public _details: boolean = false;
    public _votes: number[] = [];

    public static create(text: string): PollAnswer {
        const answer = new PollAnswer();
        answer.text = text;
        return answer;
    }

    public static createFromData(poll: Poll, data: any): PollAnswer {
        const answer = new PollAnswer();
        answer.text = data.text;
        answer.voters = data.votes ? data.votes.length : data.nbVotes;
        if (Array.isArray(data.votes)) {
            answer._votes = data.votes;
            answer.votes = data.votes.map((vote: number) => { return poll.voters[vote]; });
        }
        return answer;
    }

    public getData(): any {
        return { text: this.text };
    }

    public reset(): void {
        this.votes = [];
        this.voters = 0;
    }
}

export class PollQuestion {

    public text: string = null;
    public multipleChoice: boolean = false;
    public answers: PollAnswer[] = [];
    public voters: number = 0;
    public valueChanges?: Subject<PollQuestion> = new Subject<PollQuestion>();

    public _edit: boolean = false;

    public static create(text: string, answers: PollAnswer[], multipleChoice: boolean = false): PollQuestion {
        const question = new PollQuestion();
        question.text = text;
        question.answers = answers;
        question.multipleChoice = multipleChoice;
        return question;
    }

    public static createEmpty(): PollQuestion {
        const question = new PollQuestion();
        question.text = '';
        question.answers = [PollAnswer.create(''), PollAnswer.create('')];
        question.multipleChoice = false;
        question._edit = true;
        return question;
    }

    public static createFromData(poll: Poll, data: any): PollQuestion {
        const question = new PollQuestion();
        question.text = data.text;
        question.multipleChoice = data.multipleChoice;
        question.voters = data.voters !== undefined ? data.voters : poll.voters.length;
        question.answers = data.answers.map((answerData: any) => { return PollAnswer.createFromData(poll, answerData); });
        return question;
    }

    public update(text: string, answers: PollAnswer[], multipleChoice: boolean) {
        this.text = text;
        this.answers = answers;
        this.multipleChoice = multipleChoice;
        this.valueChanges.next(this);
    }

    public getPercent(answer: PollAnswer): number {
        return Math.floor(answer.voters * 100 / this.voters);
    }

    public getData(): any {
        const data: any = { text: this.text, multipleChoice: this.multipleChoice };
        data.answers = this.answers.map((answer: PollAnswer) => { return answer.getData(); });
        return data;
    }

    public reset(): void {
        this.voters = 0;
        this.answers.forEach((answer: PollAnswer) => { answer.reset(); });
    }
}

export class Poll {

    public id: string = null;
    public title: string = null;
    public state: string = 'unpublished';
    public roomId: string = null;
    public creator: Contact = null;
    public creatorId: string = null;
    public anonymous: boolean = false;
    public modifyVote: boolean = false;
    public questions: PollQuestion[] = [];
    public duration: number = 0;
    public voted: boolean = false;
    public created: boolean = false;
    public creationDate: Date | null = null;
    public publicationDate: Date | null = null;
    public voters: any[] = null;

    public _valueChanges: BehaviorSubject<Poll> | undefined;
    public _durationTimeout: any = null;

    public static create(roomId: string, questions: PollQuestion[]): Poll {
        const poll = new Poll();
        poll.roomId = roomId;
        poll.questions = questions;
        poll._valueChanges = new BehaviorSubject<Poll>(poll);
        return poll;
    }

    public static createFromData(data: any): Poll {
        const poll = new Poll();
        poll.id = data.id;
        poll.roomId = data.roomId;
        poll.creatorId = data.creatorId;
        poll.title = data.title;
        poll.state = data.state;
        poll.anonymous = data.anonymous;
        poll.modifyVote = data.modifyVote;
        poll.duration = data.duration;
        if (data.voters) poll.voters = data.voters;
        poll.questions = data.questions.map((dataQuestion: any) => { return PollQuestion.createFromData(poll, dataQuestion); });
        poll.voted = data.voted;
        poll.creationDate = new Date(data.creationDate);
        if (data.publishDate) poll.publicationDate = new Date(data.publishDate);
        poll._valueChanges = new BehaviorSubject<Poll>(poll);
        return poll;
    }

    public updateFromData(data: any): void {
        if (data.title) this.title = data.title;
        if (data.state) this.state = data.state;
        if (data.anonymous) this.anonymous = data.anonymous;
        if (data.modifyVote) this.modifyVote = data.modifyVote;
        if (data.duration) this.duration = data.duration;
        if (data.voters) this.voters = data.voters;
        if (data.questions) this.questions = data.questions.map((dataQuestion: any) => { return PollQuestion.createFromData(this, dataQuestion); });
        if (data.voted) this.voted = data.voted;
        if (data.creationDate) this.creationDate = new Date(data.creationDate);
        if (data.publishDate) this.publicationDate = new Date(data.publishDate);
        this._valueChanges.next(this);
    }

    public getVoteData(): string {
        const data = { votes: [] };
        this.questions.forEach((question: PollQuestion, questionIndex: number) => {
            const vote = { question: questionIndex, answers: [] };
            question.answers.forEach((answer: PollAnswer, answerIndex: number) => {
                if (answer._selected) vote.answers.push(answerIndex);
            });
            data.votes.push(vote);
        });
        return JSON.stringify(data);
    }

    public getData(): string {
        const data: any = { title: this.title, roomId: this.roomId, anonymous: this.anonymous, duration: this.duration, modifyVote: this.modifyVote };
        data.questions = this.questions.map((question: PollQuestion) => { return question.getData(); });
        return JSON.stringify(data);
    }

    public reset(): void {
        this.state = 'unpublished';
        this.voted = false;
        this.questions.forEach((question: PollQuestion) => { question.reset(); });
    }
}


