    public async setCliOption(cliOption: CliOption) {

        if (!cliOption || !cliOption.policy) {
            const error = "wrong parameters";
            const errorInfo = await this.errorHelperService.getErrorInfo(error, 'setCliOption');
            this.logger.error(`[TelephonyServiceSipWise] ${errorInfo.message}`);
            throw errorInfo.error;
        }
        try {
            const headers = this.authService.getPostHeader();
            const reqMethod = "PUT";
            const reqUrl = this.portalURL + "cli-options";
            this.logger.info("[TelephonyServiceSipWise] Set cli-options " + reqMethod + " " + reqUrl);

            const body = JSON.stringify(cliOption);
            const response: Response = await fetch(reqUrl, { method: reqMethod, headers, body });
            if (!response.ok) { throw response; }
            const newCliOption = (await response.json()).data;
            this.logger.debug(`[TelephonyServiceSipWise] Set cli-options -- SUCCESS -- `);
            return newCliOption;
        }
        catch (error) {
            const errorInfo = await this.errorHelperService.getErrorInfo(error, 'cli-options');
            this.logger.error(`[TelephonyServiceSipWise] ${errorInfo.message}`);
            throw errorInfo.error;
        }
    }

