    /**
     * getUserGroupForwards
     * Retrieve the forwards for one given group of the logged user
     * @param {string} groupId group identifier
     */
    public async getUserGroupForwards(groupId: string): Promise<void> {
        try {
            this.logger.info("[TelephonyServiceSipWise] getUserGroupForwards for groupId : " + groupId);
            let wrongParaMsg = "";
            if (groupId) {
                if (this.telephonyService.sipWiseUserGroupsData.sipWiseUserGroupsList.length === 0) {
                    wrongParaMsg = "invalid groupId";
                }
            } else {
                wrongParaMsg = "missing groupId";
            }
            //para checking to be completed
            if (wrongParaMsg !== "") { //reject if wrong parameters
                const error = new Error("get group forward failure - " + wrongParaMsg);
                this.logger.error("[TelephonyServiceSipWise] get group forward anomaly:" + wrongParaMsg);
                throw error;
            }

            const url = new URL(this.portalURL + "groups/" + encodeURIComponent(groupId) + "/forwards");
            const headers = this.authService.getRequestHeader();
            this.logger.info("[TelephonyServiceSipWise] getUserGroupForwards GET " + url);

            const response: Response = await fetch(url.toString(), { method: 'GET', headers });
            if (!response.ok) {
                throw (response);
            }

            const responseBody: any = await response.json();
            const respData: any = responseBody.data;

            const group = this.telephonyService.sipWiseUserGroupsData.sipWiseUserGroupsList.find(elt => elt.id === groupId);
            if (group.name !== respData.name) {
                this.logger.info("[TelephonyServiceSipWise] getUserGroupForwards Anomaly group name : " + group.name + " VS " + respData.name);

                const errorInfo = await this.errorHelperService.getErrorInfo(response, 'getUserGroupForwards');
                this.logger.error(`[TelephonyServiceSipWise] ${errorInfo.message}`);
                throw errorInfo.error;
            }

            group.forwardData = respData;//data for complex n:m situation
            //only for simple 1:1 manager/assistant management++
            if (groupId === this.telephonyService.sipWiseUserGroupsData.managerAssistGrId) { //unique handled manager_assistant group
                if (this.telephonyService.sipWiseUserGroupsData.managerAssistantNb > 1) {
                    this.logger.info("[TelephonyServiceSipWise] getUserGroupForwards : Anomaly not a 1:1 mng/ass situation");
                } else {
                    let fwdActivate = "unknown";
                    const mng = respData.members.find(elt => elt.memberId === this.telephonyService.sipWiseUserGroupsData.managerId);
                    if (mng && mng.displayName === this.telephonyService.sipWiseUserGroupsData.managerName) {
                        const fwd = mng.forwards.find(elt => elt.type === "immediate");
                        if (fwd && fwd.activate && fwd.destinationType === "managersecretary") {
                            fwdActivate = "activated";
                        } else {
                            fwdActivate = "unactivated";
                        }
                    } else {
                        this.logger.info("[TelephonyServiceSipWise] getUserGroupForwards : Anomaly manager forward status");
                    }
                    this.telephonyService.sipWiseUserGroupsData.managerForward = fwdActivate;
                }
            }//only for simple 1:1 manager/assistant management--

            this.logger.info("[TelephonyServiceSipWise] getUserGroupForwards success / status : " + response.statusText);
            return group;
        }
        catch (error) {
            const errorInfo = await this.errorHelperService.getErrorInfo(error, 'getUserGroupForwards');
            this.logger.error(`[TelephonyServiceSipWise] ${errorInfo.message}`);
            throw errorInfo.error;
        }
    }

