    /**
     * processSnapshot
     */
    public async processSnapshot(): Promise<void> {
        try {
            this.logger.info("[TelephonyServiceSipWise] processSnapshot");
            const MAXSNAPCALLS = 10;
            const MAXSNAPRINGINGIN = 10;
            let nbRingingIn = 0;
            //getSnapshot : no filtering param
            const respData = await this.getSnapshot();

            if (!respData || !respData.devices) {
                this.logger.error("[TelephonyServiceSipWise] processSnapshot / anomaly no device ");
            } else { //update devices state
                respData.devices.forEach((snapDevice) => {
                    const state = (snapDevice.type !== "webrtc") ? snapDevice.state : "inService"; //use the given snapshot state except for webrtc device which is always inService
                    this.routingData.devicesList.find(device => device.deviceId === snapDevice.deviceId).state = snapDevice.state;
                    this.logger.info("[TelephonyServiceSipWise] processSnapshot / devicesId=" + snapDevice.deviceId + "; state=" + state);
                });
                this.routingData.devicesList[0].state = "inService";//whatever snapshot content force webrtc device state inService
                this.telephonyService.rxSubject.next({ name: "ON_CURRENT_DEVICE_STATE", data: this.getCurrentDevice().state }); //fix pb of device.state update in GUI when current is Sip
            }
            const createCallPromises = [];
            if (!respData || !respData.calls) {
                this.logger.info("[TelephonyServiceSipWise] processSnapshot / no call elt");
                // delete all client calls
                this.telephonyService.deleteCallsNotInList([]);
                return;
            }
            if (respData.calls.length > MAXSNAPCALLS) { //defense against call number anomaly
                this.logger.error("[TelephonyServiceSipWise] processSnapshot / anomaly to much calls : " + respData.calls.length);
                return;
            }
            respData.calls.forEach((snapCall) => {
                if (snapCall.legs[0].state === "ringingIn") { //defense against number of incoming ringing call anomaly
                    nbRingingIn++;
                    if (nbRingingIn >= MAXSNAPRINGINGIN) {
                        this.logger.info("[TelephonyServiceSipWise] processSnapshot / anomaly to much ringingIn calls : " + nbRingingIn);
                    }
                }
                if (nbRingingIn < MAXSNAPRINGINGIN) {
                    createCallPromises.push(this.createCallFromSnapShotCallsElt(snapCall));
                }
            });
            if (createCallPromises.length === 0) {
                this.logger.info("[TelephonyServiceSipWise] processSnapshot / anomaly no call created");
                return;
            }
            try {
                const discoveredCalls: CallRB[] = await Promise.all(createCallPromises);
                this.logger.info("[TelephonyServiceSipWise] processSnapshot -- calls creation completed -- " + createCallPromises.length + " calls created");

                // delete all client calls not present in discovered calls
                this.telephonyService.deleteCallsNotInList(discoveredCalls);
            }
            catch (error) {
                this.logger.error("[TelephonyServiceSipWise] processSnapshot -- calls creation failure -- " + error.message);
                throw error;
            }
        }
        catch (error) {
            const errorInfo = await this.errorHelperService.getErrorInfo(error, 'processSnapshot');
            this.logger.error(`[TelephonyServiceSipWise] ${errorInfo.message}`);
            throw errorInfo.error;
        }
    }

    /**
     * createCallFromSnapShotCallsElt
     * @param {any} snapShotCallsElt Call element of snapshot response
     */
    private async createCallFromSnapShotCallsElt(snapShotCallsElt: any): Promise<CallRB> {
        try {
            //TBC++
            // Create the call object
            let call: CallRB;
            this.logger.info("[TelephonyServiceSipWise] createCallFromSnapShotCallsElt - callId = " + snapShotCallsElt.callId);
            //TBC :   provisory only endpoints[0] managed !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
            //note : in same call : multi legs => multi device // multi endpoints => conf "à n""
            let leg = null;
            let legId = null;
            let deviceId = null;
            let state = null;
            let endPoint = null;
            let phoneNumber = null;
            let jid = null;
            let displayName = null;

            if (snapShotCallsElt.legs) {
                const myMainDevice = this.getCurrentDevice();
                if (myMainDevice === null) {
                    const errorMessage = "createCallFromSnapShotCallsElt -- Anomaly no current device";
                    this.logger.error("[TelephonyServiceSipWise] " + errorMessage);
                    leg = snapShotCallsElt.legs[0]; //use leg[0] as default
                } else {
                    leg = snapShotCallsElt.legs.find((elt: any) => elt.deviceId === myMainDevice.id);
                    if (!leg) {
                        leg = snapShotCallsElt.legs[0]; //use leg[0] as default
                    }
                }
                legId = leg.legId ? leg.legId : null;
                deviceId = leg.deviceId ? leg.deviceId : null;
                state = (this.telephonyService.telephonyEventHandler as TelephonySipWiseEventHandler).convLegStateToCallStatus(leg.state);
                this.logger.info("[TelephonyServiceSipWise] createCallFromSnapShotCallsElt - legId = " + legId + " deviceId = " + deviceId + " leg_state = " + leg.state);
            } else {
                const errorMessage = "createCallFromSnapShotCallsElt -- Anomaly no leg";
                this.logger.error("[TelephonyServiceSipWise] " + errorMessage);
                return undefined;
            }
            if (snapShotCallsElt.endpoints) {
                endPoint = snapShotCallsElt.endpoints[0];
                phoneNumber = endPoint.phoneNumber;
                jid = endPoint.jid;
                displayName = endPoint.displayName;
            } else {
                this.logger.info("[TelephonyServiceSipWise] createCallFromSnapShotCallsElt -- No endPoint provided !");
                return undefined;
            }

            if (jid || phoneNumber) {
                const contact = await this.contactService.getOrCreateContact(jid, phoneNumber);
                if (!jid && !contact.displayName) { //only phone number and no contact.displayName then use this displayName ?? TO BE CHECKED
                    contact.displayName = displayName;
                    contact.initials = displayName.charAt(0);
                    contact.createAvatar();
                }
                call = this.telephonyService.getOrCreateCallSipWise(state, snapShotCallsElt.callId, legId, deviceId, contact);
                call.relevantEquipmentId = deviceId;// = CallRB.getDeviceIdFromConnectionId(call.connectionId); ??? TBC
                call.isSecondary = this.getCurrentDevice() && this.getCurrentDevice().type === "webrtc";
                this.eventService.publish("ON_CALL_UPDATED_EVENT", call);

                this.telephonyService.checkCallWithLostAudio(call);
                return call;
            }
            const errorMessage = "createCallFromSnapShotCallsElt -- Anomaly no jid no phoneNumber";
            this.logger.error("[TelephonyServiceSipWise] " + errorMessage);
            return undefined;//nothing to do or create an anonymous or reject ?
            //TBC--
        }
        catch (error) {
            const errorInfo = await this.errorHelperService.getErrorInfo(error, 'createCallFromSnapShotCallsElt');
            this.logger.error(`[TelephonyServiceSipWise] ${errorInfo.message}`);
            throw errorInfo.error;
        }
    }

