    /**
     * 	 GET FORWARD STATUS sipWise
     */
    public async getForwardStatus(): Promise<void> {
        try {
            this.logger.info("[TelephonyServiceSipWise] getForwardStatus");

            const url = new URL(this.portalURL + "forwards");

            const headers = this.authService.getRequestHeader();
            this.logger.info("[TelephonyServiceSipWise] forwards GET " + url.toString());

            const response: Response = await fetch(url.toString(), { method: 'GET', headers });
            if (!response.ok) {
                throw (response);
            }

            const responseBody: any = await response.json();
            const respData: any = responseBody.data;

            if (respData) {
                this.logger.info("[TelephonyServiceSipWise] getForwardStatus success");
                const forwardObjectAdapter = this.convForwardObject(respData);//former field adapter + new conditional Fwd
                this.logger.info("[TelephonyServiceSipWise] [TEL][API] getForwardStatus immediat fwdtype = " + forwardObjectAdapter.immediate.forwardType +
                    " immediat forwardTo = " + forwardObjectAdapter.immediate.forwardTo);
                if (forwardObjectAdapter.busy) {
                    this.logger.info("[TelephonyServiceSipWise] [TEL][API] getForwardStatus busy activate = " + forwardObjectAdapter.busy.activate);
                }
                if (forwardObjectAdapter.noreply) {
                    this.logger.info("[TelephonyServiceSipWise] [TEL][API] getForwardStatus noreply activate = " + forwardObjectAdapter.noreply.activate);
                }
                //update Fwd object
                this.telephonyService.forwardObject.forwardType = forwardObjectAdapter.immediate.forwardType;
                this.telephonyService.forwardObject.forwardTo = forwardObjectAdapter.immediate.forwardTo;
                this.telephonyService.forwardObject.pbxForwardType = "immediate";
                this.telephonyService.forwardObject.welcomeData = forwardObjectAdapter.immediate.welcomeData;//RQRAINB-9750
                this.telephonyService.forwardObject.destination = forwardObjectAdapter.immediate.destination;
                this.telephonyService.forwardObject.name = forwardObjectAdapter.immediate.name;

                //temporary until xmpp evt ++
                this.eventService.publish("ON_CALL_FORWARDED_EVENT", {
                    "forwardType": forwardObjectAdapter.immediate.forwardType,
                    "forwardTo": forwardObjectAdapter.immediate.forwardTo,
                    "pbxForwardType": "immediate",
                    "welcomeData": forwardObjectAdapter.immediate.welcomeData,
                    "destination": forwardObjectAdapter.immediate.destination,
                    "name": forwardObjectAdapter.immediate.name
                });

                if (forwardObjectAdapter.busy || forwardObjectAdapter.noreply) {
                    this.eventService.publish("ON_CALL_FORWARDED_CONDI_EVENT", {
                        "busy": forwardObjectAdapter.busy,
                        "noreply": forwardObjectAdapter.noreply
                    });
                    //update FWd object with new busy/noreply fields
                    this.telephonyService.forwardObject.busy = forwardObjectAdapter.busy;
                    this.telephonyService.forwardObject.noreply = forwardObjectAdapter.noreply;
                }
                //temporary until xmpp evt --
                return;
            }
            const error = new Error("getForwardStatus failure - invalide response");
            this.logger.error("[TelephonyServiceSipWise] getForwardStatus anomaly: invalide response");
            throw error;

        }
        catch (error) {
            const errorInfo = await this.errorHelperService.getErrorInfo(error, 'getForwardStatus');
            this.logger.error(`[TelephonyServiceSipWise] ${errorInfo.message}`);
            throw errorInfo.error;
        }
    }

    /**
     * FORWARD helper method
     * forwardObject converter (from new forward API to former forwardObject structure)
     * @param {any} sipWiseForwardData Server Forward data
     * @returns {any} client forward object
     */
    public convForwardObject(sipWiseForwardData: any): any {
        const forwardAdapter = { //default
            immediate: { forwardType: "Deactivation", forwardTo: "", welcomeData: null, destination: "", name: "" },
            busy: { forwardType: "Deactivation", forwardTo: "", welcomeData: null },
            noreply: { forwardType: "Deactivation", forwardTo: "", welcomeData: null },
            manAssist: {}
        };
        sipWiseForwardData.forEach((forward) => {

            //immediate case
            if (forward.type === "immediate") {
                if (forward.activate) {
                    //RQRAINB-9750++
                    switch (forward.destinationType) {
                        case "voicemail":
                            forwardAdapter.immediate.forwardType = "Activation";
                            forwardAdapter.immediate.forwardTo = "VOICEMAILBOX";
                            break;
                        case "welcomeservice":
                            forwardAdapter.immediate.forwardType = "Activation";
                            forwardAdapter.immediate.forwardTo = forward.name;
                            forwardAdapter.immediate.welcomeData = { destinationId: forward.destinationId, name: forward.name };
                            break;
                        default:
                            if (forward.number !== "") {
                                forwardAdapter.immediate.forwardType = "Activation";
                                forwardAdapter.immediate.forwardTo = forward.number;
                                forwardAdapter.immediate.destination = forward.destination;
                                forwardAdapter.immediate.name = forward.name;
                            }
                            break;
                    }//RQRAINB-9750--
                }
                if (forward.destinationType === "managersecretary") {
                    forwardAdapter.immediate.forwardType = forward.activate;
                    forwardAdapter.immediate.forwardTo = "MANAGERASSISTANT";
                    forwardAdapter.manAssist = forward;
                }
            } else if (forward.type === "busy") { //busy case
                forwardAdapter.busy = forward;
                if (forward.destinationType === "welcomeservice") { //RQRAINB-9750
                    forwardAdapter.busy.welcomeData = { destinationId: forward.destinationId, name: forward.name };
                }
            } else if (forward.type === "noreply") { //noreply case
                forwardAdapter.noreply = forward;
                if (forward.destinationType === "welcomeservice") { //RQRAINB-9750
                    forwardAdapter.noreply.welcomeData = { destinationId: forward.destinationId, name: forward.name };
                }
            }
        });
        return forwardAdapter;
    }


