    public async makeSimpleCall(contact: Contact, phoneNumber: string, calledNumber?: string): Promise<string> {
        try {
            this.logger.info("[TelephonyServiceSipWise] [TEL] makeSimpleCall to " + (contact ? contact.nameForLogs : anonymizer(phoneNumber)));

            //reject not allowed operations
            if (!this.telephonyService.isBasicCallAllowed) {
                const profileError: any = new Error("makeSimpleCallSipWise failure - Not Allowed");
                profileError.status = profileError.errorDetailsCode = "403";
                this.logger.error("[TelephonyServiceSipWise] [TEL][API] makeSimpleCall " + profileError.message);

                // Release makingCall flag
                this.telephonyService.makingCall = false;
                throw profileError;
            }

            const phoneInfo = this.telephonyService.getPhoneInfo(contact, phoneNumber);
            //select current main device as default outgoing device
            const currentDevice = this.getCurrentDevice();
            const deviceId = currentDevice ? currentDevice.deviceId : "";

            //RQRAINB-3835++  manage barring for emergencyCall when webrtc
            if ((this.emergencyCallData.WGEmergencyCallForbidden && currentDevice && (currentDevice.type === "webrtc")) ||
                (this.telephonyService.sipWiseMode() === "testemergency") //for test only with 3669
            ) {
                if (this.checkEmergencyNumber(phoneNumber)) {
                    this.logger.info("[TelephonyServiceSipWise] [TEL][API] makeVOIPSipemergencyCall - Not Allowed for num : " + phoneNumber);
                    this.telephonyService.rxSubject.next({ name: "ON_EMERGENCYCALL_VOIPSIP_NOTALLOWED_EVENT", data: phoneNumber });//subscribed at least in launcherService cf Mathieu
                    this.telephonyService.makingCall = false;
                    throw new Error();
                }
            }//RQRAINB-3835--

            const url = this.portalURL + "calls";
            const headers = this.authService.getPostHeader();
            const reqData: any = {
                deviceId: deviceId,
                calleeExtNumber: phoneInfo.longNumber,
                //calleeIntNumber: phoneInfo.internalNumber, no IntNumber in API
                calleeShortNumber: phoneInfo.shortNumber,
                calleePbxId: phoneInfo.pbxId,
                callerAutoAnswer: true
            };
            if (calledNumber) { reqData.calledNumber = calledNumber; }
            const body = JSON.stringify(reqData);

            this.logger.info("[TelephonyServiceSipWise] makeSimpleCall POST " + url);
            this.logger.info("[TelephonyServiceSipWise] makeSimpleCall data: " + body);

            const response: Response = await fetch(url, { method: 'POST', headers, body });
            if (!response.ok) {
                throw (response);
            }
            const responseBody: any = await response.json();
            const responseData: any = responseBody.data;

            const respCallId = responseData.callId;
            this.logger.info("[TelephonyServiceSipWise] [TEL][API] makeSimpleCall - success : callee " + anonymizer(phoneNumber) + " / callId = " + respCallId);

            if (!respCallId || respCallId === "") { //success but missing callId ???
                const call = CallRB.create(CallStatus.ERROR, null, CallType.PHONE, contact);
                call.errorMessage = "unexpectedError";
                this.telephonyService.calls[call.contact.id] = call;
                call.autoClear = setTimeout(() => { this.telephonyService.clearCall(call); }, 5000);
                // Release makinCall flag
                this.telephonyService.makingCall = false;
                // Send call update event
                this.eventService.publish("ON_CALL_UPDATED_EVENT", call);

                const errorInfo = await this.errorHelperService.getErrorInfo(response, 'makeCall');
                this.logger.error(`[TelephonyServiceSipWise] ${errorInfo.message}`);
                throw errorInfo.error;
            }
            // Otherwise Create the call object
            //At this stage legId & deviceId are unknown then set to null : if it is an issue use server obj link to read obj
            const call = this.telephonyService.getOrCreateCallSipWise(CallStatus.DIALING, respCallId, null, null, contact);
            call.setRelevantEquipmentId(call.getDeviceIdSipWise());//PROVISOIRE_SIPWISE
            call.isOwner = true; // The web client is the owner of this call

            this.logger.info("[TelephonyServiceSipWise] makeSimpleCall Call created (" + call + ")");

            // Indicate whether it is a call to own voicemail
            call.setIsVm(phoneNumber === this.telephonyService.voicemailNumber || phoneNumber === "voicebox");

            // keepAlive defence : Arm keep alive TO in case of NGCP dead case for this call
            call.autoClear = setTimeout(() => { this.logger.info("[TelephonyServiceSipWise] keepAlive CallReset (" + call + ")"); this.telephonyService.clearCall(call); }, 10000);

            // Send call update event
            this.eventService.publish("ON_CALL_UPDATED_EVENT", call);
            return call.id;
        }
        catch (error) {
            const errorInfo = await this.errorHelperService.getErrorInfo(error, 'makeCall');
            this.logger.error(`[TelephonyServiceSipWise] [TEL][API] ${errorInfo.message}`);

            const call = CallRB.create(CallStatus.ERROR, null, CallType.PHONE, contact);
            call.errorMessage = errorInfo.error.errorDetailsCode === "403" ? "notAllowed" : "invalidPhoneNumber";

            call.isSecondary = this.getCurrentDevice() && this.getCurrentDevice().type === "webrtc";//CRRAINB-40662
            call.isOwner = true; //CRRAINB-40662 The web client is the owner of this call

            this.telephonyService.calls[call.contact.id] = call;

            call.autoClear = setTimeout(() => { this.telephonyService.clearCall(call); }, 5000);

            // Send call update event
            call.sendEvent(CallEvents.ON_CALL_UPDATED_EVENT);
            this.eventService.publish("ON_CALL_UPDATED_EVENT", call);

            throw errorInfo.error;
        }
        finally {
            // Release makingCall flag
            this.telephonyService.makingCall = false;
        }
    }

