    /**
     * RELEASE SIPWISE CALL
     * @param {Call} call call to release
     */
    public async releaseCall(call: CallRB): Promise<CallRB> {
        try {
            this.logger.info("[TelephonyServiceSipWise] [TEL][API] releaseCall " + call.id);

            const url = this.portalURL + "calls/" + encodeURIComponent(call.id);
            const headers = this.authService.getPostHeader();
            const reqData = { //with sipWise legId = connectionId
                legId: (call.connectionId ? call.connectionId : "")
            };
            const body = JSON.stringify(reqData);
            this.logger.info("[TelephonyServiceSipWise] releaseCall DELETE " + url);
            this.logger.info("[TelephonyServiceSipWise] releaseCall data: " + body);

            const response: Response = await fetch(url, { method: 'DELETE', headers, body });
            if (!response.ok) {
                // don't read getErrorInfo here: it would generate error "body stream already read":
                // it can only be called once on the response data(it is already called in the catch block above)
                throw (response);
            }

            // Update call status
            call.setStatus(CallStatus.ENDED);
            call.startDate = null;
            call.setIsVm(false);
            this.logger.info("[TelephonyServiceSipWise] [TEL][API] releaseCall " + call.id + " - success");

            // Send call update event
            this.eventService.publish("ON_CALL_UPDATED_EVENT", call);

            // Remove the call from calls map
            delete this.telephonyService.calls[call.id];

            return call;
        }
        catch (error) {
            const errorInfo = await this.errorHelperService.getErrorInfo(error, 'releaseCall');
            this.logger.error(`[TelephonyServiceSipWise] [TEL][API] ${errorInfo.message}`);

            //clean client call not existing on server
            this.deleteCallIfInvalid(errorInfo.error, call);
            throw errorInfo.error;
        }
    }

    /**
     * deleteCallIfInvalid
     * delete call if not existing on server
     * @param {any} error error
     * @param {Call} call call to remove in client if it does not exist on server
     */
    private deleteCallIfInvalid(error: any, call: CallRB) {
        if (error && error.portal === "voice" && error.errorDetailsCode === 404201 && error.errorDetails === "Specified leg not found" && call) { // Invalid connection identifier
            this.logger.warn("[TelephonyServiceSipWise] deleteCallIfInvalid: delete client call non existing on server: " + call.id);

            call.setStatus(CallStatus.ENDED);
            // Send call update event
            this.eventService.publish("ON_CALL_UPDATED_EVENT", call);
            // Clean the call array
            if (this.telephonyService.calls[call.id]) {
                delete this.telephonyService.calls[call.id];
            }
        }
    }

