    /**
     * DEFLECT CALL sipWise
     * @param {Call} call the call to deflect
     * @param {string} destination the destination number to which the call must be deflected
     */
    public async deflectCall(call: CallRB, destination: string): Promise<void> {
        try {
            this.logger.info("[TelephonyServiceSipWise] deflectCall : " + call.id + " to destination : " + destination);
            //reject if missing destination
            if (!destination) {
                const error = new Error("deflect failure - no destination");
                this.logger.error("[TelephonyServiceSipWise] deflect anomaly: no destination");
                throw error;
            }

            const url = new URL(this.portalURL + "calls/" + encodeURIComponent(call.id) + "/deflect");
            const headers = this.authService.getPostHeader();
            const reqData = {
                destination: destination
            };
            const body = JSON.stringify(reqData);
            this.logger.info("[TelephonyServiceSipWise] deflectCall POST " + url);
            this.logger.info("[TelephonyServiceSipWise] deflectCall data: " + body);

            const response: Response = await fetch(url.toString(), { method: 'POST', headers, body });
            if (!response.ok) {
                throw (response);
            }

            this.logger.info("[TelephonyServiceSipWise] deflectCall success : " + " Call (" + call + ")");
        }
        catch (error) {
            const errorInfo = await this.errorHelperService.getErrorInfo(error, 'deflectCall');
            this.logger.error(`[TelephonyServiceSipWise] ${errorInfo.message}`);
            throw errorInfo.error;
        }
    }

