            const url = new URL(this.portalURL + "calls/" + encodeURIComponent(activeCall.id) + "/transfer");
            const headers = this.authService.getPostHeader();
            const reqData = {
                heldCallId: heldCall.id
            };
            const body = JSON.stringify(reqData);
            this.logger.info("[TelephonyServiceSipWise] transferCall POST " + url);
            this.logger.info("[TelephonyServiceSipWise] transferCall data: " + body);

            const response: Response = await fetch(url.toString(), { method: 'POST', headers, body });
            if (!response.ok) {
                throw (response);
            }
            this.logger.info("[TelephonyServiceSipWise] transferCall success : " + activeCall.id + "->" + heldCall.id);
