    /*************************************************************/
    /*                BLIND TRANSFERT CALL STUFF                 */
    /*************************************************************/
    /**
     * BLIND TRANSFERT CALL sipWise
     * @param {CallRB} activeCall the active call to transfer
     * @param {string} calleeNumber the phone number of the callee
     * @param {string} destination the destination object (used in mix webrtc/pstn transfers)
     */
    public async blindTransferCall(activeCall: CallRB, calleeNumber: string, destination: any): Promise<void> {
        try {
            this.logger.info("[TelephonyServiceSipWise] blindTransferCall : activeCall : " + activeCall.id);
            //reject if missing destination
            if (!activeCall || (!calleeNumber && !destination)) {
                const error = new Error("blind transfer failure - missing activeCall or callee number");
                this.logger.error("[TelephonyServiceSipWise] blind transfer anomaly: missing calls ref or callee number");
                throw error;
            }

            const url = new URL(this.portalURL + "calls/" + encodeURIComponent(activeCall.id) + "/blind-transfer");
            const headers = this.authService.getPostHeader();
            const reqData: { destination: any } = { destination: undefined };
            if (calleeNumber) {
                reqData.destination = calleeNumber;
            }
            else if (destination) {
                reqData.destination = destination;
            }
            const body = JSON.stringify(reqData);
            this.logger.info("[TelephonyServiceSipWise] blindTransferCall POST " + url);
            this.logger.info("[TelephonyServiceSipWise] blindTransferCall data: " + body);

            const response: Response = await fetch(url.toString(), { method: 'POST', headers, body });
            if (!response.ok) {
                throw (response);
            }

            this.logger.info("[TelephonyServiceSipWise] blindTransferCall success : " + " Call (" + activeCall + ")");
        }
        catch (error) {
            const errorInfo = await this.errorHelperService.getErrorInfo(error, 'blindTransferCall');
            this.logger.error(`[TelephonyServiceSipWise] ${errorInfo.message}`);
            if (errorInfo && errorInfo.error && errorInfo.error.errorDetailsCode === 400995) {
                this.mainService.showGlobalPopupMessage({
                    autoClose: false,
                    okLabel: "close",
                    popupTitle: "warning",
                    popupBody: "blindTransferNotPossibleForUser"
                });
            }
            throw errorInfo.error;
        }
    }


    /*************************************************************/
    /*                TRANSFER Routing  STUFF                   */
    /*************************************************************/
    /**
     * TRANSFER routing sipWise
     * Send the transfer routing service request to the server
     * @public
     * @async
     * @param {string} calleeId callee identifier
     * @param {string} addresseeId addressee identifier
     * @param {string} addresseePhoneNumber addressee phone number
     * @returns {Promise<any>} Promise resolved with the trasnfer routing data
     */
    public async transferRouting(calleeId: string, addresseeId: string, addresseePhoneNumber: string): Promise<any> {
        this.logger.info(`[TelephonyServiceSipWise] transfer-routing `);

        if (!calleeId || (!addresseeId && !addresseePhoneNumber)) {
            const error = "wrong parameters";
            const errorInfo = await this.errorHelperService.getErrorInfo(error, 'transferRouting');
            this.logger.error(`[telephonyBlindTransfer] ${errorInfo.message}`);
            throw errorInfo.error;
        }
        try {
            const url = new URL(this.portalURL + "transfer-routing");

            url.searchParams.set("calleeId", calleeId);
            if (addresseeId) {
                this.logger.info("[TelephonyServiceSipWise] transferRouting with addresseeId " + addresseeId);
                url.searchParams.set("addresseeId", addresseeId);
            }
            if (addresseePhoneNumber) {
                this.logger.info("[TelephonyServiceSipWise] transferRouting with addresseePhoneNumber " + addresseePhoneNumber);
                url.searchParams.set("addresseePhoneNumber", addresseePhoneNumber);
            }

            const headers = this.authService.getRequestHeader();
            this.logger.info("[TelephonyServiceSipWise] transfer-routing GET " + url);

            const response: Response = await fetch(url.toString(), { method: "GET", headers });
            if (!response.ok) {
                this.logger.debug(`[TelephonyServiceSipWise] transfer-routing -- FAIL -- `);
                const errorInfo = await this.errorHelperService.getErrorInfo(response, 'transfer-routing');
                return errorInfo;
            }
            const transferData = (await response.json()).data;
            this.logger.debug(`[TelephonyServiceSipWise] transfer-routing -- SUCCESS -- `);
            return transferData;
        }
        catch (error) {
            const errorInfo = await this.errorHelperService.getErrorInfo(error, 'transfer-routing');
            this.logger.error(`[TelephonyServiceSipWise] ${errorInfo.message}`);
            throw errorInfo.error;
        }
    }

