    /************************* Voicemail language *************************/
    /**
     * get list of supported voicemail audio languages: de, en, fr, nl, es, it, ro, ar, he...
     * @public
     * @function
     * @async
     * @returns {Promise<any[]>} Status promise resolved with the list of supported languages by voicemail
     */
    public async getVoicemailSupportedLanguages(): Promise<any[]> {

        this.logger.info("[TelephonyServiceSipWise] getVoicemailSupportedLanguages");

        try {
            const headers = this.authService.getRequestHeader();
            const reqUrl = this.portalURL + "messages/supported-languages";

            const response: Response = await fetch(reqUrl, { method: "GET", headers });
            if (!response.ok) {
                throw (response);
            }

            const responseBody: any = await response.json();
            return responseBody.data.sort(this.languageComparator.bind(this));
        }
        catch (error) {
            const errorInfo = await this.errorHelperService.getErrorInfo(error, 'getVoicemailSupportedLanguages');
            this.logger.error(`[TelephonyServiceSipWise] ${errorInfo.message}`);
            throw errorInfo.error;
        }
    }

    private languageComparator(language1: any, language2: any): number {
        const uiLanguages: any[] = this.settingsService.getAvailableLanguages();

        let indexLanguage1: number = uiLanguages.findIndex((uiLanguage: any) => { return uiLanguage.codeMoment === language1.code; });
        if (indexLanguage1 === -1) { indexLanguage1 = 100; }
        let indexLanguage2: number = uiLanguages.findIndex((uiLanguage: any) => { return uiLanguage.codeMoment === language2.code; });
        if (indexLanguage2 === -1) { indexLanguage2 = 100; }
        return indexLanguage1 - indexLanguage2;
    }

