/**
 * Webinar status
 */
export enum WebinarStatus {
    UPCOMING = 'upcoming',
    WAITING_ROOM = 'waitingRoom',
    PRACTICE_ROOM = 'practiceRoom',
    PRACTICE_WAITING_ROOM = 'practiceWaitingRoom',
    IN_PROGRESS = 'inProgress',
    TERMINATED = 'terminated'
}

export interface WebinarCodecs {
    audio?: string;
    video?: string;
    sharing?: string;
}
export class WebinarSessionParticipant {
    public id: string;
    public contact: Contact = null;
    public activeSpeaker: boolean = false;
    public mute: boolean = false;

    public onStage: boolean = false;
    public sharingOnStage: boolean = false;
    public searchString: string = null;
    public role: string = null;
    public raiseHand: boolean = false;
    public raiseHandDate?: Date;
    public raiseHandPosition?: number;
    public allowedToTalk: boolean = false;
    public invitedToTalk: boolean = false;

    public audioVideoSession: any = null;
    public originalAudioVideoStream: MediaStream = null;
    public audioVideoStream: MediaStream = null;
    public sharingSession: any = null;
    public sharingStream: any = null;

    public medias: any = { audio: false, video: false, sharing: false };

    public rxSubject: Subject<any> = new Subject<any>();
    public subStreamLevel: number = -1;
    public temporalLevel: number = -1;

    public static create(id: string) { return new WebinarSessionParticipant(id); }

    constructor(id: string) { this.id = id; }

    public getSessionType(sessionId: string): string | null {
        if (this.audioVideoSession && this.audioVideoSession.sid === sessionId) return 'audio+video';
        if (this.sharingSession && this.sharingSession.sid === sessionId) return 'sharing';
        return null;
    }

    public onHold(media: 'video' | 'sharing'): boolean {
        const session = this[media === 'video' ? 'audioVideoSession' : 'sharingSession'];
        if (session) return session.onHold;
        return false;
    }
}

export class WebinarSessionService {
    public sid?: string;
    public audioVideoSession?: JingleSession;
    public audioVideoStream?: MediaStream;
    public static create(id: string, name: string) { return new WebinarSessionService(id, name); }
    constructor(public id: string, public type: string) { }
}

export class WebinarSession {

    public jingleJid: string;
    public activeSpeakerId: string = null;
    public localParticipant: WebinarSessionParticipant = null;
    public speakerParticipants: WebinarSessionParticipant[] = [];
    public attendeeParticipants: WebinarSessionParticipant[] = [];
    public raiseHandAttendeeParticipants: WebinarSessionParticipant[] = [];
    public service?: WebinarSessionService;
    public connected: boolean = true;
    public masterMedia: string = null;
    public showMySharing: boolean = false;

    public static create() { return new WebinarSession(); }

    public getParticipantById(participantId: string): WebinarSessionParticipant {
        if (this.localParticipant && this.localParticipant.id === participantId) return this.localParticipant;

        const speakerParticipant = this.speakerParticipants.find((part: WebinarSessionParticipant) => { return part.id === participantId; });
        if (speakerParticipant) return speakerParticipant;

        const attendeeParticipant = this.attendeeParticipants.find((part: WebinarSessionParticipant) => { return part.id === participantId; });
        if (attendeeParticipant) return attendeeParticipant;

        return null;
    }

    public getSpeakerBySessionId(sessionId: string): WebinarSessionParticipant {
        return this.speakerParticipants.find((speaker: WebinarSessionParticipant) => {
            return speaker.getSessionType(sessionId) !== null;
        });
    }

    public addOrUpdateParticipant(participant: WebinarSessionParticipant, action?: string) {
        if (this.localParticipant && this.localParticipant.id === participant.id) {
            this.localParticipant.mute = participant.mute;
            this.localParticipant.role = participant.role;
            this.localParticipant.rxSubject.next(RBEvent.create('updateParticipant'));
            return;
        }

        const participants = participant.role === 'attendee' ? this.attendeeParticipants : this.speakerParticipants;
        const participantIndex = participants.findIndex((part: WebinarSessionParticipant) => { return part.id === participant.id; });
        if (participantIndex !== -1) {
            const existingParticipant = participants[participantIndex];
            existingParticipant.mute = participant.mute;
            existingParticipant.rxSubject.next(RBEvent.create('updateParticipant'));
        }
        else if (!action || action !== 'updateParticipant') { participants.push(participant); }
    }

    public removeParticipant(participantId: string) {
        const participantIndex = this.speakerParticipants.findIndex((part: WebinarSessionParticipant) => { return part.id === participantId; });
        if (participantIndex !== -1) { this.speakerParticipants.splice(participantIndex, 1); }
        if (this.localParticipant && this.localParticipant.id === participantId) { this.localParticipant = null; }
    }

    public addService(serviceId: string, serviceName: string): WebinarSessionService {
        this.service = WebinarSessionService.create(serviceId, serviceName);
        return this.service;
    }
}

export class WebinarParticipant {
    public email: string;
    public lastName: string;
    public firstName: string;
    public company: string;
    public jobTitle: string;
    public state: string;
    public userId: string;
    public lastAvatarUpdateDate: string;
    public country: string;

    public static create(): WebinarParticipant { return new WebinarParticipant(); }
    public static createFromData(data: any) {
        const participant = WebinarParticipant.create();
        if (data.email) participant.email = data.email;
        if (data.lastName) participant.lastName = data.lastName;
        if (data.firstName) participant.firstName = data.firstName;
        if (data.company) participant.company = data.company;
        if (data.jobTitle) participant.jobTitle = data.jobTitle;
        if (data.state) participant.state = data.state;
        if (data.userId) participant.userId = data.userId;
        if (data.lastAvatarUpdateDate) participant.lastAvatarUpdateDate = data.lastAvatarUpdateDate;
        if (data.country) participant.country = data.country;
        return participant;
    }

    public getData(): string {
        return JSON.stringify({
            email: this.email,
            userId: this.userId,
            lastName: this.lastName,
            firstName: this.firstName,
            company: this.company,
            jobTitle: this.jobTitle
        });
    }
}
