export class WebinarRB implements Webinar {

    private webinarService?: any;

    id: string = null;
    name: string = '';
    public subject: string = '';
    public webinarStartDate: string = null;
    public webinarEndDate: string = null;
    public webinarDuration: string = null;
    public webinarLastDateCheck: string = null;
    public waitingRoomStartDate: string = null;
    public timeZone: string = null;
    public roomId: string = null;
    public roomModeratorsChatId: string = null;
    public room: Bubble = null;
    public practiceRoom: Bubble = null;
    public organizers: any[] = [];
    public speakers: any[] = [];
    public participants: WebinarParticipant[] = [];
    public profileId: string = null;
    public pendingParticipantNumber: number = 0;
    public acceptedParticipantNumber: number = 0;
    public rejectedParticipantNumber: number = 0;
    public color: string = '';
    public creatorId: string = null;
    public creatorCompanyId: string = null;
    public isCreator: boolean = false;
    public isOrganizer: boolean = false;
    public isSpeaker: boolean = false;
    public isAttendee: boolean = true;
    public isGuestAttendee: boolean = true;
    public isGuest: boolean = true;
    public password: string = null;
    public approvalRegistrationMethod: string = 'automatic';
    public registrationUuid: string = null;
    public published: boolean = false;
    public moderatorsNotified: boolean = false;
    public status: WebinarStatus = WebinarStatus.UPCOMING;
    public webinarUrl: string = null;
    public rxSubject: Subject<any> = new Subject<any>();
    public rxAskStagingSubject: Subject<any> = new Subject<any>();
    public rxParticipantsSubject: Subject<any> = new Subject<any>();
    public rxServiceSubject: Subject<any> = new Subject<any>();
    public rxInfoSubject: Subject<any> = new Subject<any>();
    public isWebinarSync: boolean = true;
    public session: WebinarSession | null = null;
    public waitingRoomMultimediaURLs: string[] = [];
    public stageBackground: string = 'hop';
    public reminderDates: string[] = [];
    public subtitlesEnable: boolean = false;
    public blur: boolean = false;
    public bgReplaceUrl: string = null;
    public chatOption: string = 'participant';
    public chatOptionExpired: boolean = false;
    public chatOptionTimer: any = null;
    public recorded?: string;
    public hideRecordInfo: boolean = false;
    public recordFileId: string;
    public recordStatus: string;
    public action: string = null;
    public lastAvatarUpdate?: string;
    public lastActorsInfo?: any;
    public incomingStreamsDisabled: any = { video: false, sharing: false };

    private constructor() {
        this.webinarService = MainService.getInstance().inject<WebinarService>(WEBINAR_SVC);
    }

    public static create() { return new WebinarRB(); }

    public static createFromData(webinarData: any) {
        const webinar = new WebinarRB();
        webinar.updateFromData(webinarData);
        return webinar;
    }

    /**
     * Update existing webinar with server data
     * @param webinarData - server webinar data structure
     */
    public updateFromData(webinarData: any): void {

        // Fill data
        if (webinarData.name) { this.name = webinarData.name; }
        if (webinarData.subject || webinarData.subject === '') { this.subject = webinarData.subject; }
        if (webinarData.organizers) { this.organizers = webinarData.organizers; }
        if (webinarData.speakers) { this.speakers = webinarData.speakers; }
        if (webinarData.creatorId) { this.creatorId = webinarData.creatorId; }
        if (webinarData.creatorCompanyId) { this.creatorCompanyId = webinarData.creatorCompanyId; }
        if (webinarData.password) { this.password = webinarData.password; }
        if (webinarData.approvalRegistrationMethod) { this.approvalRegistrationMethod = webinarData.approvalRegistrationMethod; }
        if (webinarData.registrationUuid) { this.registrationUuid = webinarData.registrationUuid; }
        if (webinarData.waitingRoomMultimediaURL) { this.waitingRoomMultimediaURLs = webinarData.waitingRoomMultimediaURL; }
        if (webinarData.stageBackground) { this.stageBackground = webinarData.stageBackground; }
        if (webinarData.timeZone) { this.timeZone = webinarData.timeZone; }

        if (webinarData.id) { this.id = webinarData.id; }
        if (webinarData.webinarStartDate) { this.webinarStartDate = webinarData.webinarStartDate; }
        if (webinarData.webinarEndDate) { this.webinarEndDate = webinarData.webinarEndDate; }
        if (webinarData.waitingRoomStartDate) { this.waitingRoomStartDate = webinarData.waitingRoomStartDate; }
        if (webinarData.roomId) { this.roomId = webinarData.roomId; }
        if (webinarData.roomModeratorsChatId) { this.roomModeratorsChatId = webinarData.roomModeratorsChatId; }
        if (webinarData.participants) { this.participants = webinarData.participants.map((participant: any) => WebinarParticipant.createFromData(participant)); }
        if (webinarData.emailNotification) { this.published = webinarData.emailNotification; }
        if (webinarData.moderatorsSelectedAnNotified) { this.moderatorsNotified = webinarData.moderatorsSelectedAnNotified; }
        if (webinarData.reminderDates) { this.reminderDates = webinarData.reminderDates; }
        if (webinarData.profileId) { this.profileId = webinarData.profileId; }
        if (webinarData.chatOption) { this.chatOption = webinarData.chatOption; }
        if (webinarData.roomLastAvatarUpdateDate) { this.lastAvatarUpdate = webinarData.roomLastAvatarUpdateDate; }
        if (webinarData.recording !== undefined) { this.recorded = webinarData.recording === true ? 'true' : 'false'; }
        if (webinarData.lastDateVerification) { this.webinarLastDateCheck = webinarData.lastDateVerification; }
        if (webinarData.webinarRecording) {
            this.recordFileId = webinarData.webinarRecording.fileId;
            this.recordStatus = webinarData.webinarRecording.status;
        }

        // Handle status
        if (webinarData.isActive) { this.status = WebinarStatus.IN_PROGRESS; }
        if (webinarData.state !== undefined) {
            switch (webinarData.state) {
                case 'webinar': this.status = WebinarStatus.IN_PROGRESS; break;
                case 'waitingRoom': this.status = WebinarStatus.WAITING_ROOM; break;
                case 'practiceWaitingRoom': this.status = WebinarStatus.PRACTICE_WAITING_ROOM; break;
                case 'terminated': this.status = WebinarStatus.TERMINATED; break;
                default: this.status = WebinarStatus.UPCOMING; break;
            }
        }
        if (this.published && this.status === WebinarStatus.UPCOMING) {
            const nowDate = Date.now();
            const waitingRoomStartDate = new Date(this.waitingRoomStartDate);
            if (nowDate >= waitingRoomStartDate.getTime()) this.status = WebinarStatus.WAITING_ROOM;
        }

        // Handle moderators
        this.organizers.forEach((organizer: any) => { organizer.role = 'organizer'; });
        this.speakers.forEach((speaker: any) => { speaker.role = 'speaker'; });

        if (webinarData.guestSpeakers) {
            webinarData.guestSpeakers.forEach((guestSpeaker: any) => {
                this.speakers.push({ status: guestSpeaker.status, email: guestSpeaker.email, role: 'speaker' });
            });
        }

        this.updateAttendeeCounters();

        // Compute default color
        if (this.name.length) { this.color = this.webinarService?.computeWebinarColor(this.name); }

        // Compute webinarURLwebappWebinarRegistrationUrl
        if (config.webappWebinarRegistrationUrl) this.webinarUrl = `${config.webappWebinarRegistrationUrl.replace(".red", ".com")}${this.registrationUuid}`;
        else {
            this.webinarUrl = `${config.webservices.protocol}://webinar.${config.webservices.server.replace(".red", ".com")}/${this.registrationUuid}`;
            if (window.location.origin.indexOf("localhost") !== -1) { this.webinarUrl = `localhost:8000/#/webinar/${this.registrationUuid}`; }
            if (window.location.origin.indexOf("demo") !== -1) { this.webinarUrl = `https://web-demo.openrainbow.org/#/webinar/${this.registrationUuid}`; }
        }
    }

    public updateAttendeeCounters(): void {
        this.pendingParticipantNumber = 0;
        this.acceptedParticipantNumber = 0;
        this.rejectedParticipantNumber = 0;

        this.participants.forEach((participant: any) => {
            switch (participant.state) {
                case 'pending': this.pendingParticipantNumber++; break;
                case 'approved': this.acceptedParticipantNumber++; break;
                case 'rejected': this.rejectedParticipantNumber++; break;
                default: break;
            }
        });
    }

    public subscribe(handler: any): Subscription { return this.rxSubject.subscribe(handler); }

    public getData(): string {
        const data: any = { isOrganizer: true, passwordNeeded: false };
        if (this.name && this.name !== undefined) { data.name = this.name; }
        if (this.subject !== null && this.subject !== undefined) { data.subject = this.subject; }
        if (this.webinarStartDate && this.webinarStartDate !== undefined) { data.webinarStartDate = this.webinarStartDate; }
        if (this.webinarEndDate && this.webinarEndDate !== undefined) { data.webinarEndDate = this.webinarEndDate; }
        if (this.waitingRoomStartDate && this.waitingRoomStartDate !== undefined) { data.waitingRoomStartDate = this.waitingRoomStartDate; }
        if (this.timeZone && this.timeZone !== undefined) { data.timeZone = this.timeZone; }
        if (this.approvalRegistrationMethod && this.approvalRegistrationMethod !== undefined) { data.approvalRegistrationMethod = this.approvalRegistrationMethod; }
        if (this.waitingRoomMultimediaURLs && this.waitingRoomMultimediaURLs !== undefined && this.waitingRoomMultimediaURLs.length > 0) { data.waitingRoomMultimediaURL = this.waitingRoomMultimediaURLs; }
        if (this.stageBackground && this.stageBackground !== undefined) { data.stageBackground = this.stageBackground; }
        if (this.reminderDates && this.reminderDates.length > 0) { data.reminderDates = this.reminderDates; }
        if (this.profileId && this.profileId !== undefined) { data.profileId = this.profileId; }
        if (this.chatOption && this.chatOption !== undefined) { data.chatOption = this.chatOption; }
        if (this.webinarLastDateCheck && this.webinarLastDateCheck !== undefined) { data.lastDateVerification = this.webinarLastDateCheck; }
        if (this.recorded && this.recorded !== undefined) { data.recording = this.recorded === 'true'; }
        return JSON.stringify(data);
    }

    public updateRaiseHandParticipants(): void {
        if (this.session) {
            this.session.raiseHandAttendeeParticipants = this.session.attendeeParticipants.filter((participant: WebinarSessionParticipant) => { return participant.raiseHand; });
        }
    }

    public isTerminated(): boolean {
        return this.status === WebinarStatus.TERMINATED;
    }

    public isWaitingRoomStarted(): boolean {
        return isAfter(new Date(), subMinutes(new Date(this.webinarStartDate), 15));
    }

    /**
     * Asynchronous method to update webinar avatar on server
     * @param avatarImg - base64 encoded webinar avatar
     */
    public async updateAvatar(avatarSrc: string): Promise<Webinar> {
        return this.webinarService?.updateWebinarAvatar(this, avatarSrc);
    }

    /**
     * Asynchronous method to update webinar logo on server
     * @param logoSrc - base64 encoded webinar logo
     */
    public async updateLogo(logoSrc: string): Promise<Webinar> {
        return this.webinarService?.updateWebinarLogo(this, logoSrc);
    }

    /**
     * Allow a rainbow user to join the webinar
     */
    public async join(): Promise<void> {
        await this.webinarService?.conference.join(this);
    }

    /**
     * Allow a rainbow attendee to join the webinar room
     */
    public async joinAsRainbowAttendee(): Promise<void> {
        return this.webinarService?.participants.joinWebinarAsRainbowAttendee(this.id);
    }


}

