    public hasMediaPillarCallWithContactJid(jid: string): boolean {
        return Object.keys(this.calls).some((key) => {
            if (this.calls[key]) {
                const call = this.calls[key];

                if (call.callStatus !== CallStatus.ENDED && (call.localMedia & CallMedia.AUDIO) && call.isMediaPillarCall()) {
                    const mpContext: any = call.mediaPillarCall;
                    const telCalls: CallRB[] = mpContext?.telephonyCallRefs || [];
                    return telCalls.some((telCall: CallRB) => {
                        return telCall.contact && telCall.contact.jid === jid;
                    });
                }
            }
            return false;
        });
    }

