    /**
     * Ends all sharing calls related to a given contact
     * @param contact - The contact related to all calls
     */
    public endAllCallsForContact(contact: Contact) {
        if (!contact) {
            return;
        }

        this.logger.info("[webrtcP2PService] endAllCallsForContact " + contact.jid);

        Object.keys(this.calls).forEach((key) => {
            if (this.calls[key]) {
                const call = this.calls[key];

                if (call.callStatus !== CallStatus.ENDED && call.contact && call.contact.jid === contact.jid && !call.isWebRtcMediaPillar() && call.localMedia === CallMedia.SHARING) {
                    this.logger.info("[webrtcP2PService] endAllCallsForContact " + contact.jid + " release call (sharing): " + call);
                    this.releaseCall(call);
                }
            }
        });
    }

    //detect change on video input and update the current call
    private onVideoInputChangeEvent() {
        this.logger.info("[webrtcP2PService] MEDIA   | onVideoInputChangeEvent");

        Object.keys(this.calls).forEach((key) => {
            if (this.calls[key]) {
                const call = this.calls[key];
                const session:JingleSession = this.xmppService.connection.jingle.sessions[call.id];

                //check current call type
                if (session && call.localMedia && (call.localMedia & CallMedia.AUDIO) && (call.localMedia & CallMedia.VIDEO)) {
                    //audio + video
                    this.logger.info("[webrtcP2PService] MEDIA   | audio + video call, renegotiate the profile");
                    this.addVideoToCall(call, true);
                }
            }
        });
    }

    private async onAudioVideoInputDeviceChange() {
        if (this.audioProfileChanging) {
            //ignore
            this.logger.info("[webrtcP2PService] onAudioVideoInputDeviceChange -- ignore");
            return;
        }

        this.logger.info("[webrtcP2PService] onAudioVideoInputDeviceChange");
        const promises = [];
        this.audioProfileChanging = true;
        Object.keys(this.calls).forEach((key) => {
            if (this.calls[key]) {
                const call = this.calls[key];
                promises.push(this.updateLocalAudioStreamForCall(call));
            }
        });

        await allSettled(promises);
        this.audioProfileChanging = false;
    }

