    /**
     * Find and return a call by the distant contact's jid or full jid
     * @param contactJid - The jid of the contact that we want to find
     * @param fullJid - [optional] The full JID of the contact related to the call
     * @returns The call
     */
    public getCallByJid(contactJid: string, fullJid: string = ""): CallRB {
        let result: CallRB = null;
        if (!contactJid && !fullJid) return result;
        this.logger.info("[webrtcP2PService] getCallByJid " + contactJid);

        Object.keys(this.calls).forEach((key) => {
            if (this.calls[key]) {
                const call = this.calls[key];
                if (call.contact && call.contact.jid === contactJid) result = call;
            }
        });

        if (!result) {
            this.logger.info("[webrtcP2PService] getCallByJid fallback " + fullJid);
            Object.keys(this.calls).forEach((key) => {
                if (this.calls[key]) {
                    const call = this.calls[key];
                    if (call && call.fullJid === fullJid) result = call;
                }
            });
        }
        return result;
    }

