    public clearSrcObjectsFromElements() {
        if (Object.keys(this.xmppService.connection.jingle.sessions).length !== 0) {
            this.logger.info("[webrtcP2PService]  clearSrcObjectsFromElements -- ignored because not all calls are terminated");
            return;
        }

        this.RTC.clearMediaStream($("#largevideo"), null);
        this.RTC.clearMediaStream($("#globalAudioTagSharing"), null);
        this.RTC.clearMediaStream($("#globalAudioTag"), null);
    }

    public attachDistantMediaStreamsUnifiedPlan(call) {
        call.hasRemoteSharingWithAudio = false;
        const sess = this.xmppService.connection.jingle.sessions[call.id];
        if (!sess) {
            this.logger.warn("[webrtcP2PService] attachDistantMediaStreamsUnifiedPlan -- missing session " + call.id);
            return;
        }
        // audio
        if (sess.remoteStreamsObject["0"]) {
            this.logger.info("[webrtcP2PService] attachDistantMediaStreamsUnifiedPlan audio track for element globalAudioTag " + sess.remoteStreamsObject["0"].id);
            this.RTC.attachMediaStream($("#globalAudioTag"), sess.remoteStreamsObject["0"]);
        }

        // video & sharing
        if (sess.remoteStreamsObject["1"] && sess.remoteStreamsObject["2"]) {
            const largeVideoElem: any = $("#largevideo");
            this.RTC.attachMediaStreamIfNeeded(largeVideoElem, sess.remoteStreamsObject["2"], sess.remoteStreamsObject["2"].id);
            if (largeVideoElem[0]) {
                largeVideoElem[0].muted = true;
                largeVideoElem[0].volume = 0;
            }
        }
        // video
        else if (sess.remoteStreamsObject["1"]) {
            const largeVideoElem: any = $("#largevideo");
            this.RTC.attachMediaStreamIfNeeded(largeVideoElem, sess.remoteStreamsObject["1"], sess.remoteStreamsObject["1"].id);
            if (largeVideoElem[0]) {
                largeVideoElem[0].muted = true;
                largeVideoElem[0].volume = 0;
            }
        }
        // sharing
        else if (sess.remoteStreamsObject["2"]) {
            const largeVideoElem: any = $("#largevideo");
            this.RTC.attachMediaStreamIfNeeded(largeVideoElem, sess.remoteStreamsObject["2"], sess.remoteStreamsObject["2"].id);
            if (largeVideoElem[0]) {
                largeVideoElem[0].muted = true;
                largeVideoElem[0].volume = 0;
            }

            if (sess.remoteStreamsObject["2"]?.getAudioTracks().length) {
                call.hasRemoteSharingWithAudio = true;
                this.RTC.attachMediaStream($("#globalAudioTagSharing"), sess.remoteStreamsObject["2"]);
            }
        }
    }

    public attachDistantMediaStreams(attach, call) {
        if (attach) {
            if (this.alreadyAttaching) {
                return;
            }
            this.alreadyAttaching = true;
            this.attachDistantMediaStreamsUnifiedPlan(call);
            this.alreadyAttaching = false;
        }
        else {
            if (!this.isUserContactInCall()) {
                this.RTC.clearMediaStream($("#largevideo"), null);
                this.RTC.clearMediaStream($("#globalAudioTagSharing"), null);
                this.RTC.clearMediaStream($("#globalAudioTag"), null);
            }
        }
    }

    //NEW UI FUNCTIONS
    public attachLocalVideoOnlyStreamToElement(call, attach, element) {
        this.logger.info("[webrtcP2PService] attachLocalVideoOnlyStreamToElement " + attach);
        if (attach) {
            if (call.localStreams?.length) {
                call.localStreams.forEach((track) => {
                    //if audio/video track
                    if (track.getVideoTracks().length && track.getAudioTracks().length) {
                        //ignore
                    }
                    //if sharing track
                    else if (track.getVideoTracks().length) {
                        this.RTC.attachMediaStreamIfNeeded(element, track, track.id);
                    }
                });
            }

            //mute local videos -> bug Firefox
            if (element[0]) {
                element[0].volume = 0;
            }
        } else {
            this.RTC.clearMediaStream(element, null);
        }
    }
