/**
 * Description: Some bot or process needs a permanent authentication even though the account authentication changes.
 * Managing the full JWT authentication process is not relevant on low power devices (iOT,...).
 * In those cases, we can use API_KEYS instead;
 * This is the Interface of the SDK API Key
 */
export interface SdkApiKey {
    //The identifier of the API_KEY
    id?: string,

    //The scope of the API_KEY
    scope: string[],

    //The description of the API_KEY
    description: string,

    //Indicate if the API_KEY is active
    isActive: boolean,

    //The identifier of the API_KEY owner
    userId?: string,

    //The Email of the API_KEY owner
    loginEmail?: string

    //The expiration date of the API_KEY
    expirationDate: string
}

