    /**
    * Create a new SDK Api Key
    * @param description - the description of the key
    * @param expirationDate - the date of the expiration or null for never expires
    * Returns the list of the all SDK Api Keys
    */
    public async createSdkApiKey(description: string, expirationDate: Date|null): Promise<SdkApiKey[]> {
        try {
            if (!description) {
                this.logger.warn("[profileService] createSdkApiKey missing data");
                throw new Error('Missing data');
            }
            this.logger.info("[profileService] createSdkApiKey");
            const data = { description, scope: ['all'], isActive: true };
            if (expirationDate) data['expirationDate'] = expirationDate;

            const body = JSON.stringify(data);
            const url = `${config.restServerUrl}/api/rainbow/authentication/v1.0/apikeys`;
            const headers = this.authService.getPostHeader();
            const response = await fetch(url, { method: 'POST', headers, body });
            if (!response.ok) { throw response; }
            const responseData: any = await response.json();
            this.logger.info("[profileService] createSdkApiKey -- success");
            if (!this.sdkApiKeys) this.sdkApiKeys = [];
            this.sdkApiKeys.push(responseData.data);
            return this.sdkApiKeys;
        }
        catch (error) {
            let errorMessage = "createSdkApiKey from server failed -- no answer from server";
            if (error) { errorMessage = "createSdkApiKey from server failed -- " + JSON.stringify(error); }
            this.logger.error("[profileService] " + errorMessage);
            throw new Error(errorMessage);
        }
    }

    /**
    * Deletes a SDK Api Key
    * @param sdkApiKey - the key to delete
    * Returns the list of the remaining SDK Api Keys
    */
    public async deleteSdkApiKey(sdkApiKey: SdkApiKey): Promise<SdkApiKey[]> {
        try {
            if (!sdkApiKey?.id) {
                this.logger.warn("[profileService] deleteSdkApiKey missing data");
                throw new Error('Missing data');
            }
            this.logger.info("[profileService] deleteSdkApiKey");
            const url = `${config.restServerUrl}/api/rainbow/authentication/v1.0/apikeys/${sdkApiKey.id}`;
            const headers = this.authService.getRequestHeader();
            const response = await fetch(url, { method: 'DELETE', headers });
            if (!response.ok) { throw response; }
            const responseData: any = await response.json();
            this.logger.info("[profileService] deleteSdkApiKey -- success");
            if (!this.sdkApiKeys) {
                this.sdkApiKeys = (responseData?.data) ? responseData.data : [];
            }
            this.sdkApiKeys.forEach((app: SdkApiKey, index: number) => {
                if (app.id === sdkApiKey.id) { this.sdkApiKeys.splice(index, 1); }
            });
            return this.sdkApiKeys;
        }
        catch (error) {
            let errorMessage = "deleteSdkApiKey from server failed -- no answer from server";
            if (error) { errorMessage = "deleteSdkApiKey from server failed -- " + JSON.stringify(error); }
            this.logger.error("[profileService] " + errorMessage);
            throw new Error(errorMessage);
        }
    }

