    public async pickupCall(contact: Contact, callId?: string): Promise<void> {
        try {
            const url = new URL(`${this.portalURL}/calls/pickup`);

            const resource: string = this.xmppService.getResourceFromJid(this.contactService.userContact.fullJid);
            const body = {
                // eslint-disable-next-line @typescript-eslint/naming-convention
                jid_tel: contact.jidtel,
                supervisorResource: resource,
                callId
            };

            // a delay is sometimes useful between pickups so that hybrid system has the time to complete the answer to the right call (due to answer on webrtc mp call)
            if (this.lastPickupDate) {
                const now = new Date();
                const timeSinceLastPickup: number = now.getTime() - this.lastPickupDate.getTime();
                if (timeSinceLastPickup < 2000 && !this.telephonyService.getActiveCall()) {
                    const differDelay: number = 3000 - timeSinceLastPickup;
                    this.logger.info(`[SupervisionService] pickupCall delayed ${differDelay} milliseconds or active call detection`);
                    await this.waitActiveCall(differDelay);
                    await this.delay(500);
                    this.logger.info(`[SupervisionService] pickupCall after delay, ready to be executed`);
                }
            }
            this.lastPickupDate = new Date();

            this.logger.info(`[SupervisionService] pickupCall ${JSON.stringify(body)}`);

            const headers = this.authService.getPostHeader();
            const response: any = await fetch(url.toString(), { method: 'PUT', headers, body: JSON.stringify(body) });
            if (!response.ok) {
                throw (response);
            }
            this.logger.info(`[SupervisionService] pickupCall success`);
        }
        catch (error) {
            const errorInfo = await this.errorHelperService.getErrorInfo(error, 'pickupCall');
            this.logger.error(`[SupervisionService] pickupCall error ${errorInfo.message}`);
            throw errorInfo.error;
        }
    }

    private delay(milliseconds: number) {
        return new Promise(resolve => {
            setTimeout(resolve, milliseconds);
        });
    }

    private waitActiveCall(timeout: number = 3000, retryPeriod: number = 300): Promise<void> {
        const start = Date.now();
        this.logger.debug("[supervisionService] waitActiveCall start -- " + start);
        return new Promise(waitForActiveCall.bind(this));

        function waitForActiveCall(resolve, reject) {
            if (this.telephonyService.getActiveCall()) {
                this.logger.debug("[supervisionService] waitActiveCall active call found");
                resolve();
            } else if (timeout && (Date.now() - start) >= timeout) {
                this.logger.debug("[supervisionService] waitActiveCall timeout reached " + timeout);
                resolve();
            } else {
                this.logger.debug("[supervisionService] waitActiveCall no active call yet");
                setTimeout(waitForActiveCall.bind(this, resolve, reject), retryPeriod);
            }
        }
    }

