/**
 * Conversation public events
 * @eventProperty
 */
export enum ConversationEvents {

    /**
    * @eventProperty
    * This RBEvent is send when a new message is added in this conversation
    */
    ON_MESSAGE_ADDED = 'ON_MESSAGE_ADDED',

    /**
     * @eventProperty
     * This RBEvent is send when the replaced/deleted message is the last one
     */
    ON_MESSAGE_REPLACED = 'ON_MESSAGE_REPLACED',

    /**
     * @eventProperty
     * This RBEvent is send when a bookmark is set in this conversation
     */
    ON_MESSAGE_BOOKMARKED = 'ON_MESSAGE_BOOKMARKED',

    /**
    * @eventProperty
    * This RBEvent is send when a message is add in the "cache message".
    * This "cache message" is used to store messages which belongs to the conversation but not
    * already loaded. For example an old replied message.
    */
    ON_MESSAGE_CACHED = 'ON_MESSAGE_CACHED',

    /**
     * @eventProperty
     * This RBEvent is send when something occurs on conversation messages
     */
    ON_MESSAGES_UPDATED = 'ON_MESSAGES_UPDATED',

    /**
     * @eventProperty
     * This RBEvent is send when the missed message counter is updated
     */
    ON_MISSED_COUNTER_UPDATED = 'ON_MISSED_COUNTER_UPDATED',

    /**
    * @eventProperty
    * This RBEvent is send when the conversation status is changed
    * This status represent the user typing activity.
    * + ACTIVE
    * + INACTIVE
    * + COMPOSING
    * + PAUSED
    */
    ON_STATUS_CHANGED = 'ON_STATUS_CHANGED',

    /**
     * @eventProperty
     * This RBEvent is send when
     * In some situations when the call is "remotely picked" by another client and we update the tel call area (??)
     * In some situations to manage the mute / unmute / sharing buttons in tell call area;
     * This event is to be DELETED and replaced with something else;
     */
    RAINBOW_CONVERSATION_CALL_UPDATE = 'RAINBOW_CONVERSATION_CALL_UPDATE',

    /**
    * @eventProperty
    * @internal
    * This RBEvent is send when the contact is replced by a new one in the conversation :
    * It is used in the following usecases:
    * - PBX Hybride (OXO/OXE) conference call is "reverted" to single call
    * - temp contact replaced by a directory contact
    * As the conversation stays the same, we only modify the "contact" inside to adapt to the new situation.
    */
    ON_CONVERSATION_CALL_CONTACT_CHANGE = 'ON_CONVERSATION_CALL_CONTACT_CHANGE',

    // ************************************************** //
    // ** EVENTS TO REWORK : UCAAS SPECIFIC EVENTS     ** //
    // ************************************************** //

    /**
    * @eventProperty
    * @internal
    * This RBEvent is send when
    * FIXME : MCO GUI EVENT
    */
    RAINBOW_CONVERSATION_USER_UPDATED = 'RAINBOW_CONVERSATION_USER_UPDATED',

    /**
    * @eventProperty
    * @internal
    * This RBEvent is send when
    * FIXME : MCO GUI EVENT
    */
    RAINBOW_CONVERSATION_ROOM_UPDATED = 'RAINBOW_CONVERSATION_ROOM_UPDATED',

    /**
     * @eventProperty
     * @internal
     * This RBEvent is send when
     * FIXME : MCO WRONG PLACE : SFUCALLAREA SERVICE EVENT : GUI
     */
    RAINBOW_CONVERSATION_REQUEST_TRANSFERT_SHARING = 'RAINBOW_CONVERSATION_REQUEST_TRANSFERT_SHARING',

    /**
     * @eventProperty
     * @internal
     * This RBEvent is send when
     * FIXME : MCO WRONG PLACE : SFUCALLAREA SERVICE EVENT : GUI
     */
    RAINBOW_CONVERSATION_ACCEPT_TRANSFERT_SHARING = 'RAINBOW_CONVERSATION_ACCEPT_TRANSFERT_SHARING',

    /**
     * @eventProperty
     * @internal
     * This RBEvent is send when the conversation urgency level is reset
     * FIXME : MCO GUI EVENT
     */
    RAINBOW_CONVERSATION_RESET_MESSAGE_LEVEL = 'RAINBOW_CONVERSATION_RESET_MESSAGE_LEVEL',

    /**
     * @eventProperty
     * @internal
     * This RBEvent is send when
     * FIXME : MCO GUI EVENT
     */
    RAINBOW_CONVERSATION_INFO_VISIBLE = 'RAINBOW_CONVERSATION_INFO_VISIBLE'
}

/**
 * This enum is used to represent the type of the conversation
 */
export enum ConversationType {
    P2P = 'P2P',
    BUBBLE = 'BUBBLE',
    BOT = 'BOT'
}

/**
 * This enum is used to represent the status of the conversation
 */
export enum ConversationStatus {
    ACTIVE = 'active',
    INACTIVE = 'inactive',
    COMPOSING = 'composing',
    PAUSED = 'paused'
}

export interface DocumentMessageData {
    /**
     * The document name to be shown in the conversation
     */
    documentName?: string;

    /**
     * The Document to send ( in case of already existing document)
     */
    document?: Document;

    /**
     * The urgency of the message; Allowed values are (standard) 'std', (notify) 'low', (warning) 'middle', (emergency) 'high'; Default value is "std"
     */
    urgency?: Urgency;
}
export class ConversationLastMessage {
    /**
     * @internal
     */
    constructor() { }

    /**
     * The text of the last message received of the conversation
     * @readonly
     */
    text: string = '';

    /**
     * The content type of the last message received of the conversation
     * @readonly
     */
    contentType: string = '';

    /**
     * The ID of the user for the last message
     * @readonly
     */
    sender: string | null = null;

    /**
     * The Side of the Last message.
     * + LEFT
     * + RIGHT
     * + ADMIN
     * @readonly
     */
    side?: MessageSide;

    /**
     * The ID the last message replaced by
     * @readonly
     */
    messageId: string = '';

    /**
     * Allow to reset the lastMessage parameters
     */
    public reset() {
        this.text = '';
        this.contentType = '';
        this.sender = '';
        this.messageId = '';
        this.side = undefined;
    }
}

