export type MessageLevel = 'standard' | 'notify' | 'warning' | 'emergency';

/**
 * A conversation modelize an interaction between one or more Rainbow users.
 * In the Rainbow ecosystem we'll come across two types of conversations:
 * + The "peer-to-peer" (P2P) conversations : where two Rainbow users interact with each other.
 * + The "bubble" conversations : where several users interact all together.
 */
export interface Conversation {

    /**
     * The conversation ID
     * @readonly
     */
    id: string;

    /**
     * The database ID
     * @readonly
     */
    dbId?: string;

    /**
     * The conversation name
     * @readonly
     */
    name?: string;

    /**
     * The type of the conversation. Can be P2P (0), BUBBLE (1) or BOT (2)
     * @readonly
     */
    type?: ConversationType;

    /**
     * (P2P conversation only) The recipient of the conversation
     * @readonly
     */
    user?: User;

    /**
     * (Bubble conversation only) The conversation Bubble if any
     * @readonly
     */
    bubble?: Bubble;

    /**
     * The capabilities of the conversation
     * @readonly
     */
    capabilities?: ConversationCapabilities;

    /**
     * The name of the conversation (the display name of the recipient for P2P conversation or the room name for a BUBBLE conversation)
     * @readonly
     */
    filterName: string;

    /**
     * The number of instant messages not read
     * @readonly
     */
    missedCounter: number;

    /**
     * The list of messages downloaded for this conversation
     * @readonly
     */
    messages: Message[];

    /**
     * The status of the conversation
     * @readonly
     */
    status: ConversationStatus;

    /**
     * The date of the last modification of the conversation
     * @readonly
     */
    lastModification?: Date;

    /**
     * The date of the creation of the conversation
     * @readonly
     */
    creationDate?: Date;

    /**
     * The last message received of the conversation
     * @readonly
     */
    lastMessage: ConversationLastMessage;

    /**
     * If the last message that is forwarded is a file
     * @readonly
     */
    isForwardedMessageFile: boolean; // TODO : MCO ask Dobro WTF ?

    /**
     * The last message forwarded
     * @readonly
     */
    forwardedMessage: string;

    /**
     * TRUE if conversation favorite
     * @readonly
     */
    isFavorite: boolean;

    /**
     * The bookmarked message in the conversation
     */
    bookmark: ConversationBookmark;

    /**
     * True if this conversation is a webinar conversation
     * @readonly
     */
    isWebinarConversation: boolean;

    /**
     * The webinar associated to this conversation (if any)
     * @readonly
     */
    webinar?: Webinar;

    call: CallRB;


    /**
    * Subscribe to updates on the current conversation (all events are of RBEvent type);
    * @param handler - The call-back function that will be subscribed to the RxJS subject
    * @param filterEvent - a list of event names that the user wants to receive when subscribing (used a filter)
    */
    subscribe(handler: (event: RBEvent<ConversationEvents>) => any, filterEvent?: ConversationEvents | ConversationEvents[]): Subscription;

    /**
     * This method allows us to retrieve archived message pages.
     * By default, no message history is loaded, but this method will allow us to retrieve them page by page.
     * @param nbMessages - the number of messages to get in this page
     */
    getHistoryPage(nbMessages: number): Promise<void>;

    /**
     * Return all the already loaded messages
     */
    getMessages(): Message[];

    /**
    * Remove given message from the conversation (should be a message that the user has sent)
    * @param message - the message we want to delete
    */
    deleteMessage(message: Message): void;

    /**
    * Remove all message of the conversation
    */
    deleteAllMessages(): Promise<void>;

    /**
     * Return the message with the corresponding identifier
     * @param messId - the message identifier
     * @param searchInCache - if true this methods start to search in cacheMessage
     * @returns the search message if founded undefined else
     */
    getMessageById(messId: string, searchInCache?: boolean): Message | undefined;

    /**
     * This method permits to send a chat Message
     * @param messageText - the text to be send
     * @param messageData - the message data object
     * @returns the sent message (or undefined in case of an issue)
     */
    sendMessage(messageText: string, messageData?: SendMessageData): Message | undefined;

    /**
     * This method permits to send a file Message
     * @param messageData - The document message data to be send
     */
    sendFileMessage(messageData: SendFileMessageData): Promise<Message>;

    /**
     * This method permits to send a document message
     * @param messageData - The file message data to be send
     */
    sendDocumentMessage(messageData: DocumentMessageData): Promise<Message>;

    /**
     * Method to set or replace conversation bookmark
     * This API will provoque an update on the conversation object (event of type ConversationEvents.ON_MESSAGE_BOOKMARKED)
     * @param message - the message to bookmark
     */
    setBookmark(message: Message): Promise<void>;

    /**
     * Method to delete a conversation bookmark
     */
    deleteBookmark(): Promise<void>;

    /**
     * This API can be used to modify an already existing sent message; The user is allowed to modify the text of the message, the additional content and the mentions;
     * NB The new SendMessageData will replace the existing data, so all the existing informations (additionalContent or mentions) should also be added in the data otherwise they'll be removed
     * @param message - The Message we want to modify
     * @param newMessageText - The new text of the message
     * @param messageData - the updated send message data
     * @returns the updated message or undefined in case of issue
     */
    modifyMessage(message: Message, newMessageText?: string, messageData?: SendMessageData): Message;

    /**
     * This method permits to forward a Message to another conversation
     * @param destConv - conversation to which the Message is forwarded
     * @param message - the message to forward
     * @param anonymous - allow to specify if yes or not the message orioginbator has to be displayed (default: true)
     */
    forwardMessage(destConv: Conversation, message: Message, anonymous?: boolean): Promise<Message | undefined>;

    /**
     * This method permits to send a "typing" (or remove it) state to the distant party;
     * @param isTypingState - if the user is currently "typing" inside the conversation
     */
    sendIsTypingState(isTypingState: boolean): void;

    /**
     * This API permit to send the text content of the conversation at the connectUser e-mail address.
     */
    sendByEmail(): Promise<void>;

    /**
     * This method permits to send a ACK READ status for message to mark it as READ
     * @param message - the chat message to "ACK read"
     */
    ackReadMessage(message: Message): void;

    /**
     * This method permits to send a ACK READ all received messages inside the conversation
     */
    ackReadMessages(): boolean;

    /**
     * Method used to search for text in a given conversation P2P or bulle. The searched text length should be 3+ characters.
     * This API will return a SearchTextResult that contains the list of IDs of messages to be searched after that
     * @param searchedText - the text to be searched
     * @param limit - number of results to get; Default value is 20;
     */
    searchForText(searchedText: string, limit: number): Promise<SearchTextResult>;

    /**
     *  Method used to load the messages around a given timestamp. Can be used when we search for a message via API searchForTextInConversation
     * and then we want to load the message (or also the messages around it); This API will load the messages in the conversation list of messages and resolve once it's done;
     * @param timestamp - the timestamp of the message to be loaded
     * @param nbMessages - the number of messages to load before and after this one
     */
    loadHistoryMessagesAroundGivenMessage(timestamp: number, nbMessages: number): Promise<void>;

    /**
     * JSON serialisation of conversation for debug purpose
     */
    toJSON(): any;
}

/**
 * @internal
 * This class is used to represent a conversation
 */
export class ConversationRB implements Conversation {

    private static randomBase = crypto.randomUUID();
    private static messageId = 0;

    public static ChatstatesNS: string = 'http://jabber.org/protocol/chatstates';
    public static ReceiptNS: string = 'urn:xmpp:receipts';
    public static contentNS: string = 'urn:xmpp:content';
    public static AttentionNS: string = 'urn:xmpp:attention:0';
    public static FORWARDNS: string = 'urn:xmpp:forward:0';

    // ************************************************************ //
    // ** STATIC FACTORIES                                       ** //
    // ************************************************************ //
    public static createConversation(peer: Contact | BubbleRB): ConversationRB {

        // Peer is a Contact
        if (peer instanceof Contact) {
            const contact: Contact = (peer as Contact);
            const conversation = new ConversationRB(contact.id);
            conversation.contact = contact;
            conversation.type = contact.isBot ? ConversationType.BOT : ConversationType.P2P;
            conversation.infoVisible = contact.isBot;
            conversation.filterName = contact.displayName ? contact.displayName.toLowerCase().trim().normalize('NFD').replace(/[\u0300-\u036f]/g, '') : null;
            contact.conversation = conversation;
            return conversation;
        }

        // Peer is a bubble
        const bubble: BubbleRB = (peer as BubbleRB);
        const conversation = new ConversationRB(bubble.jid);
        conversation.type = ConversationType.BUBBLE;
        conversation.bubble = bubble;
        conversation.filterName = bubble.name.toLowerCase().trim().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
        conversation.infoVisible = true;
        return conversation;
    }

    public static getUniqueMessageId(): string {
        const messageToSendID = 'web_' + ConversationRB.randomBase + (ConversationRB.messageId++);
        return messageToSendID;
    }

    public id: string;
    public dbId?: string;
    public type?: ConversationType;
    public filterName: string = '';
    public contact: Contact | null = null;
    public bubble?: BubbleRB;
    public infoVisible: boolean = false;
    public capabilities?: ConversationCapabilities;
    public missedCounter: number = 0;
    public missedCalls: number = 0;
    public messages: Message[] = [];
    public participantStatuses: any = {}; // MCO missing statuses class
    public status: ConversationStatus = ConversationStatus.INACTIVE;
    public historyIndex: number = -1;
    public historyLastIndex: number = -1;
    public historyMessages: Message[] = [];
    public historyDefered = null;
    public historyAboveComplete: boolean = false;
    public historyBelowComplete: boolean = false;
    public currentHistoryIndex?: number;
    public lastModification?: Date;
    public creationDate?: Date;
    public lastMessage: ConversationLastMessage = new ConversationLastMessage();
    public forwardFrom: any = null; // MCO any
    public forwardedMessage: any = null; // MCO any
    public pip: boolean = true;
    public videoCall: CallRB | null = null;
    public audioCall: CallRB | null = null;
    public muted: boolean = false;
    public isMutedAudio: boolean = false;
    public largeInfoVisible: boolean = true;
    public selectedTabName: string = 'chat'; // MCO GUI????
    public isFavorite: boolean = false;
    public cacheMessages: Message[] = [];
    public msgLevelDraft: MessageLevel = 'standard';
    public msgAnswerDraft?: AnswerMessage;
    public innerHtml: string = ''; // MCO GUI????
    public mentionedMembersArray: Mention[] = [];
    public telephonyContacts: any = null; // MCO any
    public isWebinarConversation: boolean = false;
    public webinar?: Webinar;
    public lastCallInfo: any = null; // MCO ???
    public isForwardedMessageFile: boolean = false;
    public isGeoLoc?: boolean = false;
    public isDraft: boolean = false;
    public replyData: AnswerMessage = null;

    public lastEvent: any = null;

    private _callShift: boolean = false;
    private _bookmark: ConversationBookmark = null;
    private rxSubject: Subject<RBEvent<ConversationEvents>> = new Subject<RBEvent<ConversationEvents>>();

    public get getNameForLogs(): string {
        if (this.filterName) {
            return config?.debug ? this.filterName : this.filterName.charAt(0) + this.filterName.replace(/[^\s](?=.{1,}$)/g, "*").substr(1);
        }
        return '';
    }

    public get bookmark(): ConversationBookmark {
        return this._bookmark;
    }
    public set bookmark(value: ConversationBookmark) {
        if (this._bookmark !== value) {
            this._bookmark = value;
            this.rxSubject.next(RBEvent.create(ConversationEvents.ON_MESSAGE_BOOKMARKED));
        }
    }
    private _shouldRemoveBookMark: boolean = false;
    public get shouldRemoveBookMark(): boolean {
        return this._shouldRemoveBookMark;
    }
    public set shouldRemoveBookMark(value: boolean) {
        this._shouldRemoveBookMark = value;
        this.rxSubject.next(RBEvent.create(ConversationEvents.ON_MESSAGE_BOOKMARKED));
    }

    // Workaround to keep working conversation.room, but actually there's the conversation.bubble behind
    public get room(): BubbleRB { return this.bubble as BubbleRB; }
    public set room(value: BubbleRB) { this.bubble = value; }

    public set callShift(callShift: boolean) { if (this._callShift !== callShift) this._callShift = callShift; }
    public get callShift() { return this._callShift; }

    public get call(): CallRB {
        if (this.audioCall) return this.audioCall;
        if (this.videoCall) return this.videoCall;
        return null;
    }

    public get name(): string { return this.type === ConversationType.P2P ? this.user.displayName : this.bubble?.name; }
    public get user(): User { return this.contact; }

    private conversationService?: ConversationServiceRB;

    // ********************************************************************** //
    // ** PUBLIC METHODS IMPLEMENTATION                                    ** //
    // ********************************************************************** //

    public getHistoryPage(nbMessages: number = 30): Promise<void> {
        return this.conversationService.conversationServiceBulkHistoryHandler.getHistoryPage(this, nbMessages);
    }

    public getMessages(): Message[] {
        return this.messages;
    }

    public sendMessage(messageText: string, messageData?: SendMessageData): Message | undefined {
        return this.conversationService?.sendMessage(this, messageText, messageData);
    }

    public sendDocumentMessage(messageData: DocumentMessageData): Promise<Message> {
        const sendFileMessageData: SendFileMessageData = { fileName : messageData.documentName, document : messageData.document, urgency : messageData.urgency };
        return this.conversationService?.sendFileMessage(this, sendFileMessageData);
    }

    public sendFileMessage(messageData: SendFileMessageData): Promise<Message> {
        return this.conversationService?.sendFileMessage(this, messageData);
    }

    public deleteMessage(message: Message): void {
        return this.conversationService?.deleteMessage(this, message);
    }

    public deleteAllMessages(): Promise<void> {
        return this.conversationService?.removeAllMessages(this);
    }

    public setBookmark(message: Message): Promise<void> {
        return this.conversationService?.setConversationBookmark(this, message);
    }

    public deleteBookmark(): Promise<void> {
        return this.conversationService?.deleteConversationBookmark(this);
    }

    public modifyMessage(message: Message, newMessageText?: string, messageData?: SendMessageData): Message {
        return this.conversationService?.modifyMessage(this, message, newMessageText, messageData);
    }

    public forwardMessage(destConv: Conversation, message: Message, anonymous: boolean = true): Promise<Message | undefined> {
        return this.conversationService?.forwardMessage(this, destConv as ConversationRB, message, anonymous);
    }

    public sendIsTypingState(isTypingState: boolean): void {
        this.conversationService?.sendIsTypingState(this, isTypingState);
    }

    public sendByEmail(): Promise<void> {
        return this.conversationService?.sendConversationByEmail(this);
    }

    public ackReadMessage(message: Message): void {
        return this.conversationService?.sendAckReadMessage(this, message);
    }

    public ackReadMessages(): boolean {
        return this.conversationService?.sendAckReadMessages(this);
    }

    public searchForText(searchedText: string, limit: number = 20): Promise<SearchTextResult> {
        return this.conversationService?.searchForTextInConversation(this, searchedText, limit);
    }

    public loadHistoryMessagesAroundGivenMessage(timestamp: number, loadAround: number): Promise<void> {
        return this.conversationService?.loadHistoryMessagesAroundGivenMessage(this, timestamp, loadAround);
    }

    public constructor(conversationId: string) {
        this.conversationService = MainService.getInstance().inject<ConversationServiceRB>(CONVERSATION_SVC);
        this.id = conversationId;
        this.creationDate = new Date();
    }

    /**
     * Search in cache the message with the corresponding identifier
     * @param messId - the message identifier
     */
    private getMessageInCacheById(messId: string): Message | undefined {
        return this.cacheMessages.find((item: Message) => { return item.id === messId; });
    }

    public getMessageById(messId: string, searchInCache: boolean = false): Message {
        if (searchInCache) { const foundMsg = this.getMessageInCacheById(messId); if (foundMsg) return foundMsg; }
        return this.messages.find(item => item.id === messId);
    }

    /**
     * Search in history the message with the corresponding identifier
     * @param messId - the message identifier
     */
    public getMessageByIdInHistory(messId: string): Message {
        return this.historyMessages.find((item) => { return item.id === messId; });
    }

    /**
     * get a replaced message by identifier
     * @param messId - the message identifier
     */
    public getReplacedMessageById(messId: string): Message | null {
        let message = null;
        this.messages.forEach((msg) => { message = msg.replaceMsgs.find((replaceMsg) => { return replaceMsg.id === messId; }); });
        return message;
    }

    /**
     * Reset conversation instance
     */
    public reset(): void {
        this.messages = [];
        this.historyIndex = -1;
        this.historyLastIndex = -1;
        this.historyMessages = [];
        this.historyAboveComplete = false;
        this.historyBelowComplete = false;
        this.currentHistoryIndex = undefined;
        this.lastMessage.reset();
        this.sendEvent(ConversationEvents.ON_MESSAGES_UPDATED);
    }

    public resetHistoryInfo(): void {
        this.historyIndex = -1;
        this.historyLastIndex = -1;
        this.historyMessages = [];
        this.historyAboveComplete = false;
        this.historyBelowComplete = false;
        this.currentHistoryIndex = undefined;
    }

    public subscribe(handler: (event: RBEvent<ConversationEvents>) => any, eventNames?: ConversationEvents | ConversationEvents[]): Subscription {
        const observable = eventNames ? this.rxSubject.pipe(filter((event: RBEvent<ConversationEvents>) => {
            if (eventNames instanceof Array) return eventNames.indexOf(event.name) !== -1;
            return event.name === eventNames;
        })) : this.rxSubject;

        return observable.subscribe((event: RBEvent<ConversationEvents>) => {
            try { handler(event); }
            catch (error) { /*this.logger.error(`[Conversation] subscribe () -- error -- ${error.message}`);*/ }
        });
    }

    public sendEvent(name: ConversationEvents, data?: any): void {
        this.rxSubject.next(RBEvent.create(name, data));
    }

    /**
     * Subscribe to conversation change observable
     * @param missedCounter - the missed message value to set
     */
    public setMissedCounter(missedCounter: number): void {
        if (this.missedCounter !== missedCounter) {
            this.missedCounter = missedCounter;
            this.rxSubject.next(RBEvent.create(ConversationEvents.ON_MISSED_COUNTER_UPDATED, { missedCounter }));
        }
    }

    /**
     * Check if conversation has an incomming call
     */
    public isAudioCallIncomming(): boolean {
        return (this.audioCall?.callStatus &&
            (this.audioCall.callStatus === CallStatus.QUEUED_INCOMMING || this.audioCall.callStatus === CallStatus.RINGING_INCOMMING));
    }

    /**
     * Add message in history messages
     * @param message - the message
     */
    public addMessageInHistoryMessages(message: Message): void {
        if (!message) { return; }
        this.historyMessages.push(message);
    }

    /**
     * Add message in the cache (these are messages that are part of the conversation but often not in the right place, like in case
     * of some old reply or something like that, so the message is added in the cache and not in the list of messages, as it's separated)
     * @param message - the message
     */
    public addMessageInCacheMessages(message: Message): void {
        if (!message) { return; }
        const cacheMsg = this.getMessageInCacheById(message.id);
        if (cacheMsg) { return; }
        this.cacheMessages.push(message);
        this.sendEvent(ConversationEvents.ON_MESSAGE_CACHED, { message });
    }

    public ackReadAllSentMessages = function() {
        this.messages.forEach((message) => {
            if (message.side === MessageSide.RIGHT && (message.receiptStatus === MessageStatus.SENT || message.receiptStatus === MessageStatus.UNREAD)) {
                message.setReceiptStatus(MessageStatus.READ);
            }
        });
    };

    public ackReceivedAllSentMessages(): void {
        this.messages.forEach((message) => {
            if (message.side === MessageSide.RIGHT && message.receiptStatus === MessageStatus.SENT) {
                message.setReceiptStatus(MessageStatus.UNREAD);
            }
        });
    }

    /**
     * Marks all received messages as READ
     */
    public ackReadAllReceivedMessages(): boolean {
        let result = false;
        this.messages.forEach((message: Message) => {
            if (message.side !== MessageSide.RIGHT && (message.receiptStatus === MessageStatus.SENT || message.receiptStatus === MessageStatus.UNREAD)) {
                message.setReceiptStatus(MessageStatus.READ);
                result = true;
            }
        });

        return result;
    }

    public updateAfterReplaceEvent(message: Message): void {
        // Update conversation info if the replaced/deleted message is the last one
        const lastMsg = this.messages[this.messages.length - 1];
        if (lastMsg?.id === message.id) {
            this.lastModification = new Date();
            this.lastMessage.text = message.getLastTextModified();
            this.lastMessage.sender = message.from.id;
            this.lastMessage.messageId = lastMsg.id;
        }
        this.sendEvent(ConversationEvents.ON_MESSAGE_REPLACED, { message });
        message.sendUpdateEvent();
    }

    public toJSON(): any {
        const json: any = {
            id: this.dbId,
            jid: this.id,
            type: this.type,
            name: this.name
        };
        if (this.bookmark) json.bookmark = this.bookmark;

        if (this.call) {
            json.call = {};
            json.call.id = this.call?.id;
            json.call.callType = this.call?.callType;
            json.call.status = this.call?.status;
        }
        return json;
    }
}
